#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: start bit (0x01)
     * Byte 1: SGL/DIFF=1 (single) | D2 | D1 | D0, shifted left by 4
     * Byte 2: don't care (clocks out remaining data)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] (masked) + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Reading (MCP3008 CH0)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo != NULL) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("[%s] ADC Value: %d\n", timestamp, adc_value);
            } else {
                printf("ADC Value: %d\n", adc_value);
            }
            fflush(stdout);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    printf("\nShutting down...\n");
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

