/*
 * Raspberry Pi 4 Model B – MLX91219 Hall-Effect Current Sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX91219 VCC  -> 3.3 V (Pin 1)
 *   MLX91219 GND  -> GND   (Pin 6)
 *   MLX91219 OUT  -> ADS1115 AIN0 (Pin 4)
 *   ADS1115 VDD   -> 3.3 V (Pin 1)
 *   ADS1115 GND   -> GND   (Pin 6)
 *   ADS1115 SDA   -> GPIO2 (Pin 3, I2C bus 1)
 *   ADS1115 SCL   -> GPIO3 (Pin 5, I2C bus 1)
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *
 * Build:  gcc -O2 -Wall -o mlx91219_ads1115 mlx91219_ads1115.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bit fields */
#define ADS1115_CFG_OS_BEGIN    (1u << 15)   /* assert to start a conversion */
#define ADS1115_CFG_MUX_AIN0   (0x4000u)    /* single-ended, AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V (0x0200u)    /* ±4.096 V range */
#define ADS1115_CFG_MODE_SS    (0x0100u)    /* single-shot mode */
#define ADS1115_CFG_DR_128SPS  (0x0080u)    /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE  (0x0003u)    /* disable comparator */

#define SAMPLE_PERIOD_US 500000  /* 500 ms */
#define ADC_MAX_COUNT     32767  /* 16-bit signed, positive full-scale */
#define VREF_MV           4096.0f
#define SENSOR_SENSITIVITY 0.010f /* 10 mV/A (typical MLX91219) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);   /* ADS1115 is big-endian */
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    ssize_t n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];   /* big-endian */
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115 configuration                                               */
/* ------------------------------------------------------------------ */
static int ads1115_init(int fd)
{
    uint16_t cfg = ADS1115_CFG_OS_BEGIN
                 | ADS1115_CFG_MUX_AIN0
                 | ADS1115_CFG_PGA_4_096V
                 | ADS1115_CFG_MODE_SS
                 | ADS1115_CFG_DR_128SPS
                 | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* Wait for the first conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-shot conversion                                       */
/* ------------------------------------------------------------------ */
static int ads1115_read_conversion(int fd, int16_t *raw_out)
{
    uint16_t cfg = ADS1115_CFG_OS_BEGIN
                 | ADS1115_CFG_MUX_AIN0
                 | ADS1115_CFG_PGA_4_096V
                 | ADS1115_CFG_MODE_SS
                 | ADS1115_CFG_DR_128SPS
                 | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* 128 SPS -> ~7.8 ms; wait a bit longer for safety */
    usleep(10000);

    uint16_t raw;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *raw_out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ads1115_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91219 current sensor reading started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_conversion(g_i2c_fd, &raw) != 0) {
            fprintf(stderr, "ADS1115 read error – continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw signed 16-bit to amperes */
        float current = (float)raw * VREF_MV / (float)ADC_MAX_COUNT * SENSOR_SENSITIVITY;

        printf("Current: %.3f A\n", current);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

