#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define TEMP_THRESHOLD 60.0f
#define FLAME_DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] << 8 | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    return i2c_write_reg16(fd, ADS1115_REG_CONFIG, config);
}

static int ads1115_read_temp(int fd, float *temp_c) {
    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) return -1;
    int16_t signed_raw = (int16_t)raw;
    *temp_c = (signed_raw * 4.096f) / 32768.0f * 100.0f;
    return 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
        flame_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_cleanup();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    gpiod_init();
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("gpiod_chip_get_line flame");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input flame");
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line buzzer");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output buzzer");
        cleanup();
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    printf("Monitoring flame and temperature sensors. Press Ctrl+C to exit.\n");

    bool last_flame = false;
    struct timespec flame_ts = {0, 0};

    while (running) {
        int flame_val = gpiod_line_get_value(flame_line);
        if (flame_val < 0) {
            perror("gpiod_line_get_value flame");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - flame_ts.tv_sec) * 1000L +
                          (now.tv_nsec - flame_ts.tv_nsec) / 1000000L;

        bool flame_active = (flame_val == 1);
        if (flame_active && !last_flame) {
            if (elapsed_ms >= FLAME_DEBOUNCE_MS) {
                flame_ts = now;
            }
        } else if (!flame_active && last_flame) {
            flame_ts = now;
        }
        last_flame = flame_active;

        float temp_c = 0.0f;
        bool temp_ok = (ads1115_read_temp(i2c_fd, &temp_c) == 0);

        if (flame_active && temp_ok && temp_c > TEMP_THRESHOLD) {
            time_t rawtime;
            time(&rawtime);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s - Fire detected! Flame: ON, Temp: %.2f C\n", timestamp, temp_c);
            fflush(log_file);
            printf("%s - Fire detected! Flame: ON, Temp: %.2f C\n", timestamp, temp_c);

            gpiod_line_set_value(buzzer_line, 1);
            usleep(BUZZER_DURATION_MS * 1000);
            gpiod_line_set_value(buzzer_line, 0);
        } else if (flame_active && temp_ok) {
            time_t rawtime;
            time(&rawtime);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s - Flame detected! Temp: %.2f C\n", timestamp, temp_c);
            fflush(log_file);
            printf("%s - Flame detected! Temp: %.2f C\n", timestamp, temp_c);
        } else if (temp_ok && temp_c > TEMP_THRESHOLD) {
            time_t rawtime;
            time(&rawtime);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s - Temperature exceeded threshold! Temp: %.2f C\n", timestamp, temp_c);
            fflush(log_file);
            printf("%s - Temperature exceeded threshold! Temp: %.2f C\n", timestamp, temp_c);
        } else if (!temp_ok) {
            fprintf(stderr, "Error reading temperature from ADS1115\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

