{
    return (float)adc_value * 10.0f;
}

static void log_data(FILE *fp, float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
