#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* Simulated 16-bit ADC reading (raw CO resistance) */
#define RAW_MIN 0
#define RAW_MAX 65535

/* Calibration constants for MICS-4514 (example values) */
#define A 0.0001
#define B 0.01
#define C 1.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_raw_sensor_data(int handle, uint16_t *raw_value) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read failed (expected 2 bytes, got %d)\n", bytes_read);
        return -1;
    }
    *raw_value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static double convert_to_ppm(uint16_t raw_value) {
    double resistance = (double)raw_value;
    double ppm = A * resistance * resistance + B * resistance + C;
    return ppm;
}

static int log_data(FILE *fp, double ppm) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm) < 0) {
        fprintf(stderr, "Error: fprintf() failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CO sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t raw_value = 0;
        if (read_raw_sensor_data(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
        } else {
            double ppm = convert_to_ppm(raw_value);
            if (log_data(log_file, ppm) != 0) {
                fprintf(stderr, "Warning: log write failed\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

