#define I2C_BUS 1
#define I2C_ADDR 0x28
#define CO_THRESHOLD 25.0f
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mics4514(int handle, float *co_ppm) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes, expected 4)\n", bytes_read);
        return -1;
    }

    uint16_t ox_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t red_raw = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    *co_ppm = (float)ox_raw / 100.0f;
    return 0;
}

static int log_co_value(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening " LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (!fp) {
        perror("Error opening " ALERT_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ALERT: CO exceeds %.1f ppm (current: %.2f ppm)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, CO_THRESHOLD, co_ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: I2C open failed (code %d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Industrial Air Quality Monitoring System started.\n");
    printf("Logging CO values to %s every %d seconds.\n", LOG_FILE, READ_INTERVAL_SEC);
    printf("Alerts for CO >= %.1f ppm will be logged to %s.\n", CO_THRESHOLD, ALERT_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float co_ppm = 0.0f;

        if (read_mics4514(handle, &co_ppm) != 0) {
            fprintf(stderr, "Warning: sensor read failed, retrying in %d seconds...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        if (log_co_value(co_ppm) != 0) {
            fprintf(stderr, "Warning: failed to log CO value\n");
        }

        if (co_ppm >= CO_THRESHOLD) {
            if (log_alert(co_ppm) != 0) {
                fprintf(stderr, "Warning: failed to log alert\n");
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

