#define ERROR_VALUE -999.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int handle, uint8_t *data) {
    if (i2cWriteByte(handle, 0x00) < 0) return -1;
    int b = i2cReadByte(handle);
    if (b < 0) return -1;
    *data = (uint8_t)b;
    return 0;
}

static float read_microphone(int handle) {
    uint8_t raw;
    if (i2c_read_byte(handle, &raw) < 0) {
        fprintf(stderr, "Error reading microphone data from handle %d\n", handle);
        return ERROR_VALUE;
    }
    return (float)raw;
}

static float calculate_average(float m1, float m2) {
    if (m1 == ERROR_VALUE || m2 == ERROR_VALUE) return ERROR_VALUE;
    return (m1 + m2) / 2.0f;
}

static void log_data(float average) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("Error opening audio_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, average);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle1 = i2cOpen(I2C_BUS, 0x20, 0);
    int handle2 = i2cOpen(I2C_BUS, 0x21, 0);
    if (handle1 < 0 || handle2 < 0) {
        fprintf(stderr, "Error opening I2C handles: %d, %d\n", handle1, handle2);
        if (handle1 >= 0) i2cClose(handle1);
        if (handle2 >= 0) i2cClose(handle2);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float m1 = read_microphone(handle1);
        float m2 = read_microphone(handle2);
        float avg = calculate_average(m1, m2);
        log_data(avg);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return 0;
}

