#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LED_GPIO 27
#define HIGH_LEVEL_THRESHOLD 100.0
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_US 1000
#define LED_ON_DURATION_MS 500
#define NUM_SAMPLES (SAMPLE_WINDOW_MS * 1000 / SAMPLE_INTERVAL_US)

static volatile sig_atomic_t running = 1;
static int spi_handle_0 = -1;
static int spi_handle_1 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / num_samples);
}

static void log_audio_event(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    } else {
        fflush(log_file);
    }
}

static void trigger_led(int duration_ms) {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(LED_GPIO, 0);
}

static void cleanup(void) {
    if (spi_handle_0 >= 0) {
        spiClose(spi_handle_0);
        spi_handle_0 = -1;
    }
    if (spi_handle_1 >= 0) {
        spiClose(spi_handle_1);
        spi_handle_1 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    int samples1[NUM_SAMPLES];
    int samples2[NUM_SAMPLES];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle_0 = spiOpen(SPI_CHANNEL_0, SPI_SPEED, SPI_FLAGS);
    if (spi_handle_0 < 0) {
        fprintf(stderr, "Failed to open SPI channel 0 (CE0): %d\n", spi_handle_0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, SPI_FLAGS);
    if (spi_handle_1 < 0) {
        fprintf(stderr, "Failed to open SPI channel 1 (CE1): %d\n", spi_handle_1);
        spiClose(spi_handle_0);
        spi_handle_0 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int read_error = 0;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            int v1 = read_mcp3008(spi_handle_0, 0);
            if (v1 < 0) {
                read_error = 1;
                break;
            }
            samples1[i] = v1;

            int v2 = read_mcp3008(spi_handle_1, 0);
            if (v2 < 0) {
                read_error = 1;
                break;
            }
            samples2[i] = v2;

            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (read_error) {
            fprintf(stderr, "Error reading ADC samples, retrying...\n");
            gpioDelay(10000);
            continue;
        }

        double mic1_rms = calculate_rms(samples1, NUM_SAMPLES);
        double mic2_rms = calculate_rms(samples2, NUM_SAMPLES);

        log_audio_event(mic1_rms, mic2_rms);

        if (mic1_rms > HIGH_LEVEL_THRESHOLD || mic2_rms > HIGH_LEVEL_THRESHOLD) {
