#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define THRESHOLD 50.0
#define VREF 4.096
#define RSENSE 0.001
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

static volatile sig_atomic_t running = 1;
static double current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_A0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    gpioDelay(10000);
    uint16_t cfg;
    for (int i = 0; i < 10; i++) {
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0) {
            return -1;
        }
        if (cfg & 0x8000) {
            break;
        }
        gpioDelay(1000);
    }
    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) < 0) {
        return -1;
    }
    *raw = (int16_t)conv;
    return 0;
}

static double raw_to_current(int16_t raw) {
    double voltage = (double)raw * VREF / 32768.0;
    return voltage / RSENSE;
}

static void add_to_buffer(double current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static double calculate_average(void) {
    if (buffer_count == 0) {
        return 0.0;
    }
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

static void control_led(double average_current) {
    if (average_current > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t raw;
    double current;
    double average_current;

    while (running) {
        if (ads1115_read_conversion(i2c_handle, &raw) < 0) {
            fprintf(stderr, "Error: Failed to read ADS1115 conversion.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        current = raw_to_current(raw);
        add_to_buffer(current);
        average_current = calculate_average();
        control_led(average_current);
        printf("Current: %.3f A, Average: %.3f A\n", current, average_current);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

