#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define CSV_FILENAME   "color_log.csv"
#define MAX_CONSECUTIVE_ERRORS 3
#define SAMPLE_INTERVAL_US 1000000  /* 1 second in microseconds */

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ID_VALUE    0x44

typedef struct {
    unsigned int clear;
    unsigned int red;
    unsigned int green;
    unsigned int blue;
} color_data_t;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_csv_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_csv_file != NULL) {
        fflush(g_csv_file);
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0)
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cReadWordData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int tcs34725_init(int handle)
{
    int id = i2cReadByteData(handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error: failed to read ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Error: unexpected ID 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);  /* power-on wait */

    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) < 0)
        return -1;  /* 2.4 ms integration time */

    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    return 0;
}

static int tcs34725_read_color(int handle, color_data_t *data)
{
    uint16_t c, r, g, b;

    if (i2c_read_word(handle, TCS34725_CDATA, &c) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, &r) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, &g) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, &b) < 0) return -1;

    data->clear = c;
    data->red   = r;
    data->green = g;
    data->blue  = b;
    return 0;
}

static int log_data(FILE *fp, const color_data_t *data)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Warning: localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Warning: strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u,%u,%u,%u\n", ts, data->clear, data->red, data->green, data->blue) < 0) {
        fprintf(stderr, "Warning: fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
