#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define LED_GPIO       17
#define PRESSURE_THRESHOLD 105.0f

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

#define ADS1115_CONFIG_OS_BEGIN (1u << 15)
#define ADS1115_CONFIG_MUX_AIN0 (0x4000u)  /* AIN0 single-ended */
#define ADS1115_CONFIG_MUX_AIN1 (0x5000u)  /* AIN1 single-ended */
#define ADS1115_CONFIG_PGA_4_096V (0x0200u)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100u)
#define ADS1115_CONFIG_DR_128SPS (0x0080u)
#define ADS1115_CONFIG_CQUE_NONE (0x0003u)

#define ADC_MAX_COUNT 32767.0f
#define VREF 4.096f
#define PRESSURE_SCALE 100.0f
#define TEMP_SCALE 100.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int16_t read_ads1115(int handle, uint16_t mux) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | mux | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;

    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) != 3) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < 10; i++) {
        char reg = ADS1115_REG_CONFIG;
        if (i2cWriteDevice(handle, &reg, 1) != 1) {
            fprintf(stderr, "Error selecting config register: %s\n", strerror(errno));
            return -1;
        }
        char buf[2];
        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "Error reading config register: %s\n", strerror(errno));
            return -1;
        }
        uint16_t cfg_val = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
        if (cfg_val & 0x8000) break;
        usleep(10000);
    }

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting conversion register: %s\n", strerror(errno));
        return -1;
