#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SPI_SPEED_HZ    1000000
#define ADC_CHANNEL     0
#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_PERIOD_S 1
#define ADC_MAX         4095
#define ADC_VREF        3.3
#define TMP36_MIN_C     -40.0
#define TMP36_MAX_C     125.0
#define GPIO_CHIP       "gpiochip4"
#define GPIO_CE0        8
#define GPIO_SCLK       11
#define GPIO_MOSI       10
#define GPIO_MISO       9

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_ce_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_ce_line = gpiod_chip_get_line(g_chip, GPIO_CE0);
    if (!g_ce_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", GPIO_CE0, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_ce_line, "tmp36-mcp3208", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output(CE0): %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_ce_line = NULL;
        return -1;
    }

    return 0;
}

static int read_adc(int channel, int *out_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (gpiod_line_set_value(g_ce_line, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(CE0 low): %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(g_ce_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_ce_line, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(CE0 high): %s\n", strerror(errno));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_celsius(int adc_value) {
    float voltage = (float)adc_value * ADC_VREF / (float)(ADC_MAX + 1);
    return (voltage - 0.5f) * 100.0f;
}

static int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_ce_line) {
        gpiod_line_release(g_ce_line);
        g_ce_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (gpio_init() < 0) {
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }

    printf("Starting TMP36 temperature logging on %s (CH%d)...\n", SPI_DEVICE, ADC_CHANNEL);

    while (g_running) {
        int adc_value = 0;
        if (read_adc(ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d s\n", SAMPLE_PERIOD_S);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < TMP36_MIN_C || temperature > TMP36_MAX_C) {
            fprintf(stderr, "Temperature out of range: %.2f C (ADC: %d)\n", temperature, adc_value);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("Temperature: %.2f C (ADC: %d)\n", temperature, adc_value);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

