    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_ce_line) {
        gpiod_line_release(g_ce_line);
        g_ce_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (gpio_init() < 0) {
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }

    printf("Starting TMP36 temperature logging on %s (CH%d)...\n", SPI_DEVICE, ADC_CHANNEL);

    while (g_running) {
        int adc_value = 0;
        if (read_adc(ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d s\n", SAMPLE_PERIOD_S);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < TMP36_MIN_C || temperature > TMP36_MAX_C) {
            fprintf(stderr, "Temperature out of range: %.2f C (ADC: %d)\n", temperature, adc_value);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("Temperature: %.2f C (ADC: %d)\n", temperature, adc_value);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

