#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define IMPACT_THRESHOLD 500
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define LOG_FILE "impact_log.txt"
#define CS_PIN 8

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buf[3] = { 0 };

    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1);

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | (uint8_t)rx_buf[2];
}

static int detect_impact(int x, int y, int z) {
    return (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD);
}

static void log_data(int x, int y, int z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

static void log_impact_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CS_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(CS_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADXL335 impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int x = read_adc_channel(ADC_CHANNEL_X);
        int y = read_adc_channel(ADC_CHANNEL_Y);
        int z = read_adc_channel(ADC_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading ADC values, skipping sample\n");
        } else if (detect_impact(x, y, z)) {
            log_data(x, y, z);
            log_impact_event();
            printf("Impact detected!\n");
        } else {
            log_data(x, y, z);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

