#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define MIN_FLOW_RATE  0.0
#define MAX_FLOW_RATE  5.0
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

static int read_adc(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static double convert_to_flow_rate(int adc_value)
{
    return (double)adc_value * (MAX_FLOW_RATE / 1023.0);
}

static int validate_flow_rate(double flow_rate)
{
    if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
        fprintf(stderr, "Flow rate out of range: %.2f L/min\n", flow_rate);
        return -1;
    }
    return 0;
}

static int log_flow_rate(FILE *fp, double flow_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# flow_log.csv started\n");
    fflush(g_log_file);

    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d) - sensor absent or disconnected\n",
                    adc_value);
        }

        double flow_rate = convert_to_flow_rate(adc_value);

        if (validate_flow_rate(flow_rate) != 0) {
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_flow_rate(g_log_file, flow_rate) != 0) {
            fprintf(stderr, "Error logging flow rate\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

