#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ICP10125_ADDR 0x50
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

/* ICP-10125 high-precision measurement command */
static const uint8_t CMD_MEASURE[2] = {0x36, 0x00};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 2-byte command to the ICP-10125 */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

/* Read exactly `len` bytes from the ICP-10125 */
static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("I2C read failed");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
