#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0

#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

#define SAMPLE_RATE 44100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(0, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int apply_gain(int sample, int gain) {
    if (gain < 0 || gain > 100) {
        fprintf(stderr, "Invalid gain value: %d\n", gain);
        return 0;
    }
    return sample * (100 + gain) / 100;
}

static void print_csv(int sample1, int sample2) {
    printf("%d,%d\n", sample1, sample2);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int gain1 = atoi(argv[1]);
    int gain2 = atoi(argv[2]);

    if (gain1 < 0 || gain1 > 100 || gain2 < 0 || gain2 > 100) {
        fprintf(stderr, "Gain values must be between 0 and 100\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio sampling started. Press Ctrl+C to stop.\n");
    printf("Sample rate: %d Hz, SPI: channel %d, speed %d Hz\n",
           SAMPLE_RATE, SPI_CHANNEL, SPI_SPEED);
    printf("Gain 1: %d%%, Gain 2: %d%%\n", gain1, gain2);

    while (running) {
        int sample1 = read_mcp3008(MCP3008_CHANNEL_0);
        if (sample1 < 0) {
            fprintf(stderr, "Error reading channel 0\n");
            break;
        }

        int sample2 = read_mcp3008(MCP3008_CHANNEL_1);
        if (sample2 < 0) {
            fprintf(stderr, "Error reading channel 1\n");
            break;
        }

        int processed_sample1 = apply_gain(sample1, gain1);
        int processed_sample2 = apply_gain(sample2, gain2);

        print_csv(processed_sample1, processed_sample2);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nAudio sampling stopped.\n");
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

