#define LOG_FILE       "moisture_log.txt"
#define ADC_MAX        1023      /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out), -1 on error.
 */
static int read_mcp3008(int spi_handle, int channel, int *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining data bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    if (value < 0 || value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }

    *out = value;
    return 0;
}

static int log_data(const char *filename, int adc_value)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        perror("gmtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, adc_value) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void)
    {
        struct sigaction sa;
        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = signal_handler;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;

        if (sigaction(SIGINT, &sa, NULL) != 0) {
            perror("sigaction(SIGINT)");
            return EXIT_FAILURE;
        }
        if (sigaction(SIGTERM, &sa, NULL) != 0) {
            perror("sigaction(SIGTERM)");
            return EXIT_FAILURE;
        }

        if (gpioInitialise() < 0) {
            fprintf(stderr, "pigpio initialisation failed\n");
            return EXIT_FAILURE;
        }

        int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        if (spi_handle < 0) {
            fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Soil moisture monitoring started. Logging to %s every %d s.\n",
               LOG_FILE, SAMPLE_PERIOD);
        printf("Press Ctrl+C to exit.\n");

        while (g_running) {
            int adc_value = 0;

            if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc_value) != 0) {
                fprintf(stderr, "ADC read failed; skipping sample.\n");
            } else {
                if (log_data(LOG_FILE, adc_value) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                } else {
                    printf("ADC value: %d\n", adc_value);
                }
            }

            /* Sleep in 1-second increments so signals are caught promptly. */
            for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
                sleep(1);
            }
        }

        printf("\nShutting down...\n");
        if (spiClose(spi_handle) != 0) {
            fprintf(stderr, "spiClose failed\n");
        }
        gpioTerminate();
        printf("Cleanup complete.\n");
        return EXIT_SUCCESS;
    }

