#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define BUZZER_GPIO 18
#define FLAME_SENSOR_CHANNEL 0
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(float *temp) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open ambient temp file: %s\n", strerror(errno));
        *temp = 25.0f;
        return -1;
    }
    if (fscanf(fp, "%f", temp) != 1) {
        fprintf(stderr, "Warning: invalid ambient temp data\n");
        *temp = 25.0f;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float compensate_voltage(int raw_adc, float ambient_temp) {
    float v_ref = 3.3f;
    float v_sensor = (float)raw_adc * v_ref / 1023.0f;
    float v_comp = v_sensor + (ambient_temp - 25.0f) * 0.005f;
    if (v_comp < 0.0f) v_comp = 0.0f;
    return v_comp;
}

static void log_data(int raw_adc, float voltage, float compensated_voltage, float ambient_temp, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_fp, "%s,%d,%.3f,%.3f,%.2f,%d\n",
            timestamp, raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            raw_adc = read_mcp3008(FLAME_SENSOR_CHANNEL);
            if (raw_adc >= 0 && raw_adc <= 1023) break;
            retries++;
            usleep(10000);
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Error: failed to read ADC after %d retries\n", MAX_RETRIES);
            if (log_fp) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                fprintf(log_fp, "%s,ERROR,ADC_READ_FAILURE\n", timestamp);
                fflush(log_fp);
            }
            if (log_fp) fclose(log_fp);
            close(spi_fd);
            return 1;
        }

        float ambient_temp = 25.0f;
        if (read_ambient_temperature(&ambient_temp) != 0) {
            fprintf(stderr, "Warning: using default ambient temperature 25.0°C\n");
        }

        float voltage = (float)raw_adc * 3.3f / 1023.0f;
        float compensated_voltage = compensate_voltage(raw_adc, ambient_temp);

        int flame_detected = (compensated_voltage > 2.0f) ? 1 : 0;

        log_data(raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);

        if (flame_detected) {
            printf("Flame detected! Buzzer ON\n");
        } else {
            printf("No flame. Buzzer OFF\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

