    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float adc_to_percentage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * 100.0f;
}

static void log_json(float percentage)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    long ms = (long)(now - (long)tm_buf.tm_sec * 3600L -
                     (long)tm_buf.tm_min * 60L - tm_buf.tm_hour);
    snprintf(ts + strlen(ts), sizeof(ts) - strlen(ts), ".%03ld", ms);

    if (fprintf(g_json_file, "  {\"timestamp\": \"%s\", \"water_level\": %.2f}\n", ts, percentage) < 0) {
        perror("fprintf to JSON file failed");
    }
    fflush(g_json_file);
}

static void control_led(float percentage)
{
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1);
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0);
    }
    /* Between thresholds: keep current LED state (hysteresis) */
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_json_file = fopen(JSON_FILE, "a");
    if (g_json_file == NULL) {
        perror("Failed to open JSON file");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write JSON array header if file is empty */
    if (ftell(g_json_file) == 0) {
        fprintf(g_json_file, "[\n");
        fflush(g_json_file);
    } else {
        /* If not empty, ensure we are at the end so we can append correctly */
        fseek(g_json_file, 0, SEEK_END);
    }

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float percentage = adc_to_percentage(adc_value);
        log_json(percentage);
        control_led(percentage);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    fprintf(g_json_file, "]\n");
    fflush(g_json_file);
    fclose(g_json_file);
    g_json_file = NULL;

    spiClose(g_spi_handle);
    g_spi_handle = -1;

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

