#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIBRATION 200
#define DEFAULT_MAX_CALIBRATION 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_LOG_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/etc/msmtp.conf"

#define SPI_SPEED 500000
#define SPI_FLAGS 0

static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_calibration = DEFAULT_MIN_CALIBRATION;
static int max_calibration = DEFAULT_MAX_CALIBRATION;
static int threshold = DEFAULT_THRESHOLD;
static int log_interval = DEFAULT_LOG_INTERVAL;
static char *email_recipient = DEFAULT_EMAIL_RECIPIENT;
static char *msmtp_config_file = DEFAULT_MSMTP_CONFIG_FILE;

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d): %s\n", ret, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value, int min_cal, int max_cal) {
    if (max_cal <= min_cal) {
        fprintf(stderr, "Error: Invalid calibration range (min=%d, max=%d)\n", min_cal, max_cal);
        return -1.0f;
    }
    return ((float)(adc_value - min_cal) / (float)(max_cal - min_cal)) * 100.0f;
}

static void log_data(float moisture, const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open %s for writing: %s\n", filename, strerror(errno));
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
}

static void send_email_alert(float moisture, const char *recipient, const char *config_file) {
    char command[512];
    char body[256];

    snprintf(body, sizeof(body),
             "Subject: Plant Moisture Alert\n\n"
             "The plant moisture level is below the threshold.\n"
             "Moisture level: %.2f%%\n", moisture);

    snprintf(command, sizeof(command),
             "echo '%s' | msmtp -t -f %s %s",
             body, config_file, recipient);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command: %s\n", strerror(errno));
        return;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
    } else {
        printf("Email alert sent successfully.\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "c:a:m:M:t:i:e:f:h")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_calibration = atoi(optarg); break;
            case 'M': max_calibration = atoi(optarg); break;
            case 't': threshold = atoi(optarg); break;
            case 'i': log_interval = atoi(optarg); break;
            case 'e': email_recipient = optarg; break;
            case 'f': msmtp_config_file = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-M max_calibration] [-t threshold] [-i log_interval] [-e email_recipient] [-f msmtp_config_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d: %s\n", spi_channel, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(spi_handle, adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", log_interval);
            sleep(log_interval);
            continue;
        }

        float moisture = calculate_moisture(adc_value, min_calibration, max_calibration);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error: Invalid moisture calculation, retrying in %d seconds...\n", log_interval);
            sleep(log_interval);
            continue;
        }

        log_data(moisture, "plant_data.txt");

        if (moisture < (float)threshold) {
            send_email_alert(moisture, email_recipient, msmtp_config_file);
        }

        sleep(log_interval);
    }

    cleanup();
    printf("Plant monitoring stopped.\n");
    return EXIT_SUCCESS;
}

