    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90823 pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC reads 0 - sensor may be absent or disconnected\n");
        } else if (adc_value >= ADC_MAX) {
            fprintf(stderr, "Warning: ADC saturated at %d - sensor may be disconnected or at max pressure\n", adc_value);
        }

        float pressure = adc_to_pressure(adc_value);
        log_pressure(pressure);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

