static int log_data(FILE *fp, const float voltages[NUM_SENSORS])
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s", timestamp) < 0) {
        fprintf(stderr, "Error writing timestamp: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fprintf(fp, ",%.3f", voltages[i]) < 0) {
