        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_fp, "Timestamp") < 0) {
        fprintf(stderr, "Error writing header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fprintf(g_log_fp, ",Sensor%d", i + 1) < 0) {
            fprintf(stderr, "Error writing header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }
    if (fputc('\n', g_log_fp) == EOF) {
        fprintf(stderr, "Error writing newline: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float voltages[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(g_spi_fd, i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
                error = 1;
                voltages[i] = -1.0f;
            } else {
