#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define MCP3008_CHANNEL 0
#define PUMP_GPIO      17
#define LOW_THRESHOLD  300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE    20
#define SAMPLE_INTERVAL 5

#define SPI_READ_ERROR -1

typedef struct {
    time_t timestamp;
    int    moisture_level;
    bool   pump_state;
} MoistureData;

static MoistureData moisture_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return SPI_READ_ERROR;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(0, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return SPI_READ_ERROR;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void control_pump(int moisture_level) {
    static bool pump_on = false;

    if (moisture_level < LOW_THRESHOLD && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = true;
            printf("Pump ON\n");
        } else {
            fprintf(stderr, "Failed to turn pump ON\n");
        }
    } else if (moisture_level > HIGH_THRESHOLD && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = false;
            printf("Pump OFF\n");
        } else {
            fprintf(stderr, "Failed to turn pump OFF\n");
        }
    }
}

static void add_to_buffer(time_t ts, int level, bool state) {
    moisture_buffer[buffer_index].timestamp   = ts;
    moisture_buffer[buffer_index].moisture_level = level;
    moisture_buffer[buffer_index].pump_state   = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Moisture Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char tmb[32];
        struct tm *tm_info = localtime(&moisture_buffer[idx].timestamp);
        if (tm_info) {
            strftime(tmb, sizeof(tmb), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(tmb, sizeof(tmb), "unknown");
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               tmb, moisture_buffer[idx].moisture_level,
               moisture_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("-----------------------\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring System started.\n");
    printf("SPI channel %d, speed %d, MCP3008 channel %d, pump GPIO %d\n",
           SPI_CHANNEL, SPI_SPEED, MCP3008_CHANNEL, PUMP_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);

        if (moisture_level == SPI_READ_ERROR) {
            fprintf(stderr, "Error reading moisture level. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        control_pump(moisture_level);
        add_to_buffer(now, moisture_level, pump_on);

        printf("Moisture Level: %d\n", moisture_level);
        print_buffer();

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

