    moisture_buffer[buffer_index].moisture_level = level;
    moisture_buffer[buffer_index].pump_state   = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Moisture Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char tmb[32];
        struct tm *tm_info = localtime(&moisture_buffer[idx].timestamp);
        if (tm_info) {
            strftime(tmb, sizeof(tmb), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(tmb, sizeof(tmb), "unknown");
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               tmb, moisture_buffer[idx].moisture_level,
               moisture_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("-----------------------\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring System started.\n");
    printf("SPI channel %d, speed %d, MCP3008 channel %d, pump GPIO %d\n",
           SPI_CHANNEL, SPI_SPEED, MCP3008_CHANNEL, PUMP_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);

        if (moisture_level == SPI_READ_ERROR) {
            fprintf(stderr, "Error reading moisture level. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        control_pump(moisture_level);
        add_to_buffer(now, moisture_level, pump_on);

        printf("Moisture Level: %d\n", moisture_level);
        print_buffer();

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

