#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define LOG_FILE "health_log.txt"

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVF_COUNTER 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x05
#define REG_FIFO_CONFIG 0x06
#define REG_MODE_CONFIG 0x07
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define PART_ID_EXPECTED 0x15

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id;
    if (read_reg(REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_EXPECTED);
        return -1;
    }

    if (write_reg(REG_MODE_CONFIG, 0x40) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (write_reg(REG_FIFO_WR_PTR, 0x00) < 0) return -1;
    if (write_reg(REG_OVF_COUNTER, 0x00) < 0) return -1;
    if (write_reg(REG_FIFO_RD_PTR, 0x00) < 0) return -1;
    if (write_reg(REG_FIFO_CONFIG, 0x4F) < 0) return -1;
    if (write_reg(REG_MODE_CONFIG, 0x03) < 0) return -1;
    if (write_reg(REG_SPO2_CONFIG, 0x27) < 0) return -1;
    if (write_reg(REG_LED1_PA, 0x24) < 0) return -1;
    if (write_reg(REG_LED2_PA, 0x24) < 0) return -1;

    return 0;
}

static int read_fifo(uint32_t *red, uint32_t *ir) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }
    *red = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    *ir  = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];
    return 0;
}

static int calculate_heart_rate(uint32_t *red, uint32_t *ir) {
    int hr = 0;
    if (*red > 0 && *ir > 0) {
        hr = (int)((float)(*red - *ir) / (*ir - *red) * 100.0f);
    }
    return hr;
}

static int calculate_spo2(uint32_t *red, uint32_t *ir) {
    int spo2 = 0;
    if (*red > 0 && *ir > 0) {
        spo2 = (int)((float)(*red - *ir) / (*ir - *red) * 100.0f);
    }
    return spo2;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, MAX30102_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring MAX30102 on I2C bus %d, addr 0x%02X...\n", I2C_BUS, MAX30102_ADDR);

    while (running) {
        uint32_t red, ir;
        if (read_fifo(&red, &ir) == 0) {
            int hr = calculate_heart_rate(&red, &ir);
            int spo2 = calculate_spo2(&red, &ir);

            if (spo2 < 95 || hr > 100) {
                char msg[128];
                snprintf(msg, sizeof(msg), "SpO2: %d%%, Heart Rate: %dBPM", spo2, hr);
                log_event(msg);
            }
        } else {
            log_event("Error reading sensor data");
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

