#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define BUZZER_PIN  24
#define THRESHOLD   500
#define SAMPLE_US   500000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
