    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure buzzer pin as output and ensure it is OFF --- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d to LOW\n", BUZZER_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

