#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

#define RELAY_GPIO     17
#define DOOR_SENSOR_GPIO 27

#define THRESHOLD_DISTANCE 50
#define LOG_FILE        "/var/log/door_events.log"
#define SAMPLE_DELAY_MS 50
#define CALIBRATION_SAMPLES 10
#define RELAY_PULSE_MS 3000
#define LOOP_DELAY_MS  200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000; /* OS=1, MUX=000 (A0 vs GND), PGA=001 (4.096V), MODE=1 (single), DR=100 (128 SPS) */
    return i2c_write_reg16(fd, ADS1115_REG_CONFIG, config);
}

static int ads1115_read_raw(int fd, int16_t *raw) {
    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONV, &val) < 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

static int ads1115_read_distance(int fd, int *distance) {
    int16_t raw;
    if (ads1115_read_raw(fd, &raw) < 0) return -1;
    *distance = (int)raw;
    return 0;
}

static int calibrate_sensor(int fd, int *threshold) {
    int sum = 0;
    int samples = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int dist;
        if (ads1115_read_distance(fd, &dist) < 0) {
            fprintf(stderr, "Calibration sample %d failed: %s\n", i, strerror(errno));
            return -1;
        }
        sum += dist;
        usleep(SAMPLE_DELAY_MS * 1000);
    }
    *threshold = sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Baseline distance: %d\n", *threshold);
    return 0;
}

static int log_event(const char *event) {
    if (!log_fp) return -1;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_fp, "%s.%03ld: %s\n", time_buf, ts.tv_nsec / 1000000, event);
    fflush(log_fp);
    return 0;
}

static int control_relay(int gpio, int state) {
    FILE *gpio_path = fopen("/sys/class/gpio/export", "w");
    if (!gpio_path) {
        fprintf(stderr, "Failed to open /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    fprintf(gpio_path, "%d", gpio);
    fclose(gpio_path);
    usleep(100000);

    gpio_path = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (!gpio_path) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
        return -1;
    }
    fprintf(gpio_path, "out");
    fclose(gpio_path);

    gpio_path = fopen("/sys/class/gpio/gpio17/value", "w");
    if (!gpio_path) {
        fprintf(stderr, "Failed to set value: %s\n", strerror(errno));
        return -1;
    }
    fprintf(gpio_path, "%d", state);
    fclose(gpio_path);
    return 0;
}

static int read_door_sensor(int gpio) {
    FILE *gpio_path = fopen("/sys/class/gpio/gpio27/value", "r");
    if (!gpio_path) {
        fprintf(stderr, "Failed to open door sensor value: %s\n", strerror(errno));
        return -1;
    }
    int val = fgetc(gpio_path);
    fclose(gpio_path);
    return (val == '0') ? 0 : 1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    int threshold;
    if (calibrate_sensor(i2c_fd, &threshold) < 0) {
        fprintf(stderr, "Sensor calibration failed\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring distance sensor. Press Ctrl+C to exit.\n");

    while (running) {
        int distance;
        if (ads1115_read_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        printf("Distance: %d\n", distance);

        if (distance < threshold) {
            printf("Distance below threshold! Activating relay.\n");
            if (control_relay(RELAY_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to activate relay\n");
            } else {
                log_event("Door lock released");
            }

            usleep(RELAY_PULSE_MS * 1000);

            if (control_relay(RELAY_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to deactivate relay\n");
            }

            int door_open = read_door_sensor(DOOR_SENSOR_GPIO);
            if (door_open < 0) {
                fprintf(stderr, "Failed to read door sensor\n");
            } else {
                log_event(door_open ? "door opened" : "door not opened");
            }
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    control_relay(RELAY_GPIO, 0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

