        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_cs_lines[i]) {
            gpiod_line_set_value(g_cs_lines[i], 1);
            gpiod_line_release(g_cs_lines[i]);
            g_cs_lines[i] = NULL;
        }
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

