        fflush(fp);
    }

    while (g_running) {
        int s1 = read_mcp3008(0);
        int s2 = read_mcp3008(1);
        int s3 = read_mcp3008(2);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    fclose(fp);
    cleanup();
    return EXIT_SUCCESS;
}

