#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define PUMP_GPIO        18
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION  10
#define DEFAULT_SLEEP     60
#define LOG_FILE         "irrigation.log"
#define MAX_RETRIES      3
#define ADC_MAX          1023.0
#define ADC_VREF         3.3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(10000);
        }
    }
    return -1;
}

static double adc_to_percentage(int adc_value) {
    return (adc_value / ADC_MAX) * 100.0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void log_reading(double moisture) {
    char buf[128];
    snprintf(buf, sizeof(buf), "Moisture level: %.2f%%", moisture);
    log_message(buf);
}

static void log_pump_action(int on) {
    char buf[128];
    snprintf(buf, sizeof(buf), "Pump %s", on ? "activated" : "deactivated");
    log_message(buf);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:h")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0 || threshold > 100.0) {
                    fprintf(stderr, "Threshold must be between 0 and 100\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'd':
                duration = atoi(optarg);
                if (duration <= 0) {
                    fprintf(stderr, "Duration must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            log_message("Error reading ADC, skipping cycle");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }

        double moisture = adc_to_percentage(adc);
        log_reading(moisture);

        if (moisture < threshold) {
            if (gpioWrite(PUMP_GPIO, 1) != 0) {
                log_message("Error activating pump");
            } else {
                log_pump_action(1);
                gpioDelay(duration * 1000000);
                if (gpioWrite(PUMP_GPIO, 0) != 0) {
                    log_message("Error deactivating pump");
                } else {
                    log_pump_action(0);
                }
            }
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            gpioDelay(1000000);
        }
    }

    log_message("Irrigation system shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

