                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            log_message("Error reading ADC, skipping cycle");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }

        double moisture = adc_to_percentage(adc);
        log_reading(moisture);

        if (moisture < threshold) {
            if (gpioWrite(PUMP_GPIO, 1) != 0) {
                log_message("Error activating pump");
            } else {
                log_pump_action(1);
                gpioDelay(duration * 1000000);
                if (gpioWrite(PUMP_GPIO, 0) != 0) {
                    log_message("Error deactivating pump");
                } else {
                    log_pump_action(0);
                }
            }
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            gpioDelay(1000000);
        }
    }

    log_message("Irrigation system shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

