#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define PCF8591_CTRL   0x40   /* enable analog output on AOUT, channel 0 */
#define SAMPLE_PERIOD  100000 /* microseconds */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_sigint() != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Dummy write to select control byte register (PCF8591 auto-increments
     * the register pointer on a write, so writing one byte points to the
     * control register). */
    uint8_t ctrl = PCF8591_CTRL;
    if (write(fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Error writing control byte: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Dummy read: the PCF8591 returns the result of the *previous* conversion
     * when the control register is read, so discard the first byte. */
    uint8_t dummy;
    if (read(fd, &dummy, 1) != 1) {
        fprintf(stderr, "Error reading dummy byte: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        uint8_t value;
        ssize_t n = read(fd, &value, 1);
        if (n != 1) {
            fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("%u\n", value);
        fflush(stdout);
        usleep(SAMPLE_PERIOD);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

