#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define CONFIG_OS_SINGLE 0x8000
#define CONFIG_MUX_AIN0_GND 0x4000
#define CONFIG_PGA_4_096V 0x0200
#define CONFIG_MODE_SINGLE 0x0100
#define CONFIG_DR_128SPS 0x0080
#define CONFIG_CQUE_NONE 0x0003
#define CONFIG_DEFAULT (CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_CQUE_NONE)
#define GPIO_SHUTDOWN 27
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL_US 1000000
#define VOLTAGE_MIN 0.0f
#define VOLTAGE_MAX 3.3f
#define THRESHOLD_GAUSS 500.0f
#define SLOPE 0.001f
#define INTERCEPT -0.0005f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (CONFIG_DEFAULT >> 8) & 0xFF;
    config[2] = CONFIG_DEFAULT & 0xFF;
    if (i2cWriteDevice(handle, config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config");
        return -1;
    }
    gpioDelay(10000);
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        syslog(LOG_ERR, "Failed to set ADS1115 conversion register");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion");
        return -1;
    }
    return (int16_t)((data[0] << 8) | data[1]);
}

static float voltage_to_gauss(float voltage) {
    return SLOPE * voltage + INTERCEPT;
}

static void buffer_add(float *buf, int *idx, float val) {
    buf[*idx] = val;
    *idx = (*idx + 1) % BUFFER_SIZE;
}

static float buffer_avg(const float *buf, int count) {
    float sum = 0.0f;
    for (int i = 0; i < count; i++) sum += buf[i];
    return sum / count;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting Hall sensor monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X", ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_SHUTDOWN);
        cleanup();
        return 1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    float buffer[BUFFER_SIZE] = {0.0f};
    int buf_idx = 0;
    int consecutive_errors = 0;

    while (running) {
        int16_t raw = read_ads1115(i2c_handle);
        if (raw < 0) {
            syslog(LOG_ERR, "ADC read error, skipping sample");
            consecutive_errors++;
            if (consecutive_errors > 10) {
                syslog(LOG_ERR, "Too many consecutive ADC errors, aborting");
                break;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        consecutive_errors = 0;

        float voltage = (float)raw * 4.096f / 32768.0f;
        if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
            syslog(LOG_WARNING, "Voltage out of range: %.3f V", voltage);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        buffer_add(buffer, &buf_idx, gauss);
        float avg = buffer_avg(buffer, BUFFER_SIZE);

        syslog(LOG_INFO, "Voltage: %.3f V, Gauss: %.2f, Avg: %.2f", voltage, gauss, avg);

        if (gauss > THRESHOLD_GAUSS) {
            syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss", gauss);
            gpioWrite(GPIO_SHUTDOWN, 1);
        } else {
            gpioWrite(GPIO_SHUTDOWN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

