#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define ADC_CHANNEL 0
#define VREF        3.3
#define ADC_MAX     1023
#define SAMPLE_US   1000000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit ADC value in *adc_value;
 * returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel, uint16_t *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] contains the two most-significant bits, rx[2] the least 8 bits.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *adc_value = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)(uint8_t)rx[2];
    return 0;
}

/*
 * Map the raw ADC value to a rainfall intensity level.
 * Returns 0 for no rain, 1 for light rain, 2 for moderate rain, 3 for heavy rain.
 */
static int calculate_rainfall_intensity(uint16_t adc_value) {
    if (adc_value < 200) return 0;
    if (adc_value < 500) return 1;
    if (adc_value < 800) return 2;
    return 3;
}

static void log_rainfall_data(uint16_t adc_value, int intensity) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - ADC: %u, Rainfall Intensity: %d\n", timestamp, adc_value, intensity);
    fflush(stdout);
}

int main(void) {
    int spi_handle = -1;
    int rc = EXIT_FAILURE;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        goto cleanup_gpio;
    }

    /* --- Install SIGINT handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Rain sensor monitoring started. Press Ctrl-C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample\n");
        } else {
            int intensity = calculate_rainfall_intensity(adc_value);
            log_rainfall_data(adc_value, intensity);
        }

        /* Sleep 1 second (microseconds) */
        gpioDelay(SAMPLE_US);
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

cleanup_gpio:
    gpioTerminate();
    return rc;
}

