#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define PWM_GPIO       18
#define PWM_FREQUENCY  1000
#define PWM_RANGE      1023
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: bits 9..0 in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static int set_motor_speed(int pwm_gpio, int pwm_value)
{
    if (pwm_value < 0 || pwm_value > PWM_RANGE) {
        fprintf(stderr, "PWM value %d out of range [0, %d]\n", pwm_value, PWM_RANGE);
        return -1;
    }

    if (gpioPWM(pwm_gpio, pwm_value) < 0) {
        fprintf(stderr, "gpioPWM failed for GPIO %d\n", pwm_gpio);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on GPIO18 --- */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Reading MCP3008 channel 0 on SPI0 CE0, setting PWM on GPIO18.\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing after delay.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        int pwm_value = adc_value;  /* direct mapping 0..1023 */

        if (set_motor_speed(PWM_GPIO, pwm_value) < 0) {
            fprintf(stderr, "PWM set error; continuing after delay.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, pwm_value);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(PWM_GPIO, 0);   /* stop motor */
    spiClose(spi_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

