/*
 * Raspberry Pi 4 Model B – Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor (VOUT) -> ADS1115 AIN0
 *   - ADS1115 ADC on I2C bus 1, address 0x48 (ADDR pin to GND)
 *   - LED on GPIO17 (BCM) with appropriate current-limiting resistor
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lgpiod
 *
 * Usage:
 *   ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <getopt.h>

#include <gpiod.h>

/* ---- ADS1115 constants (I2C address 0x48, ADDR -> GND) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bit fields */
#define ADS1115_CFG_OS_BEGIN    (1u << 15)
#define ADS1115_CFG_MUX_AIN0   (0x4000u)   /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096V (0x0200u)   /* PGA = 4.096 V */
#define ADS1115_CFG_MODE_SS    (0x0100u)   /* Single-shot */
#define ADS1115_CFG_DR_128SPS  (0x0080u)   /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE  (0x0003u)   /* Disable comparator */

#define ADS1115_PGA_4_096V_VREF 4.096f
#define ADS1115_MAX_COUNT       32767.0f   /* 16-bit signed, single-ended positive */

/* ---- Application constants ---- */
#define LED_GPIO_LINE   17
#define BLINK_ON_MS     50
#define BLINK_OFF_MS    50
#define BLINK_TOTAL_MS  1000
#define SAMPLE_PERIOD_MS 100

#define DEFAULT_THRESHOLD_GAUSS 100.0f

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip   = NULL;
static struct gpiod_line  *g_led    = NULL;
static struct gpiod_line  *g_led_off = NULL;   /* line to drive LOW */
static int                 g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (MSB first).            */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (MSB first).           */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion and read the raw result.          */
static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096V
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t cfg_read = 0;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg_read) != 0)
        return -1;

    if (!(cfg_read & ADS1115_CFG_OS_BEGIN)) {
        fprintf(stderr, "ADS1115 conversion not complete\n");
        return -1;
    }

    uint16_t raw = 0;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *raw_out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC count to magnetic field strength in Gauss.         */
/* The SS49E output is linear: B = (VOUT / VREF) * 1000 Gauss.        */
static float raw_to_gauss(int16_t raw)
{
    float voltage = (float)raw / ADS1115_MAX_COUNT * ADS1115_PGA_4_096V;
    return voltage * 1000.0f;
}

/* ------------------------------------------------------------------ */
static void blink_led(int duration_ms)
{
    int half_ms = BLINK_ON_MS / 2;
    int remaining = duration_ms;

    while (remaining > 0 && g_running) {
        if (gpiod_line_set_value(g_led, 1) < 0) {
            fprintf(stderr, "Failed to set LED HIGH: %s\n", strerror(errno));
            return;
        }
        usleep(half_ms * 1000);
        if (gpiod_line_set_value(g_led, 0) < 0) {
            fprintf(stderr, "Failed to set LED LOW: %s\n", strerror(errno));
            return;
        }
        usleep(half_ms * 1000);
        remaining -= BLINK_ON_MS;
    }
    gpiod_line_set_value(g_led, 0);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_led_off) {
        gpiod_line_release(g_led_off);
        g_led_off = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD_GAUSS;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            threshold = (float)atof(optarg);
            if (threshold < 0.0f) {
                fprintf(stderr, "Threshold must be non-negative\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fallback for older kernels */
        g_chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (!g_chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "hall_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led_off = g_led;   /* same line; we just drive it HIGH/LOW */

    printf("Monitoring SS49E Hall sensor via ADS1115 (I2C 0x%02X) on %s\n",
           ADS1115_ADDR, I2C_BUS);
    printf("Threshold: %.2f Gauss | LED on GPIO%d | Press Ctrl+C to exit\n",
           threshold, LED_GPIO_LINE);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t raw = 0;
        if (ads1115_read_raw(g_i2c_fd, &raw) != 0) {
            fprintf(stderr, "ADC read error – continuing\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for %d ms...\n",
                   BLINK_TOTAL_MS);
            blink_led(BLINK_TOTAL_MS);
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nExiting cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

