#include <pigpio.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_THRESHOLD 30
#define MOISTURE_HYSTERESIS 35
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_BROKER "localhost"
#define SAMPLE_INTERVAL 60
#define ADC_MAX 1023
#define ADC_MIN 0
#define MOISTURE_MIN 0.0
#define MOISTURE_MAX 100.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pump_state = 0;
static int last_published = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < ADC_MIN) adc_value = ADC_MIN;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;
    return (float)(ADC_MAX - adc_value) / (float)(ADC_MAX - ADC_MIN) * (MOISTURE_MAX - MOISTURE_MIN) + MOISTURE_MIN;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d: %s", PUMP_GPIO, strerror(errno));
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

static void publish_moisture(float moisture) {
    char payload[32];
    int len = snprintf(payload, sizeof(payload), "%.2f", moisture);
    if (len < 0 || len >= (int)sizeof(payload)) {
        syslog(LOG_ERR, "Payload formatting failed");
        return;
    }
    if (mosquitto_publish(NULL, NULL, MQTT_TOPIC, (int)len, payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", strerror(errno));
    } else {
        syslog(LOG_INFO, "Published moisture: %.2f", moisture);
    }
}

static void on_connect(void *userdata, int result, int flags) {
    (void)userdata;
    (void)flags;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(NULL, NULL, MQTT_CONTROL_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s: %s", MQTT_CONTROL_TOPIC, strerror(errno));
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_message(void *userdata, const struct mosquitto_message *message) {
    (void)userdata;
    if (message->payloadlen > 0 && message->payload != NULL) {
        if (strcmp((char *)message->payload, "pump_on") == 0) {
            syslog(LOG_INFO, "Received pump_on command");
            control_pump(1);
        } else if (strcmp((char *)message->payload, "pump_off") == 0) {
            syslog(LOG_INFO, "Received pump_off command");
            control_pump(0);
        } else {
            syslog(LOG_WARNING, "Unknown command: %s", (char *)message->payload);
        }
    }
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosquitto_message_callback_set(NULL, on_message);
    mosquitto_connect_callback_set(NULL, on_connect);

    struct mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, 1883, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            syslog(LOG_ERR, "ADC read failed, retrying in 5 seconds");
            sleep(5);
            continue;
        }

        float moisture = adc_to_moisture(adc);
        if (moisture < 0.0 || moisture > 100.0) {
            syslog(LOG_ERR, "Moisture out of range: %.2f", moisture);
            sleep(5);
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD && pump_state == 0) {
            control_pump(1);
        } else if (moisture > MOISTURE_HYSTERESIS && pump_state == 1) {
            control_pump(0);
        }

        if (time(NULL) - last_published >= SAMPLE_INTERVAL) {
            publish_moisture(moisture);
            last_published = time(NULL);
        }

        sleep(5);
    }

    syslog(LOG_INFO, "Shutting down");
    control_pump(0);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();
    closelog();
    return 0;
}

