#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define PUMP_GPIO        17
#define MOISTURE_THRESHOLD 30.0
#define SAMPLE_INTERVAL  60
#define MAX_RETRIES      3
#define ADC_MAX          1023
#define ADC_VREF         3.3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_percentage(int adc_value) {
    return ((double)adc_value / (double)ADC_MAX) * 100.0;
}

static void control_pump(bool on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Failed to write pump GPIO\n");
    }
}

static void cleanup(void) {
    control_pump(false);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    control_pump(false);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "ADC read failed (attempt %d/%d), retrying...\n",
                        retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed after %d attempts, skipping cycle\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        double moisture = adc_to_percentage(adc_value);
        printf("Moisture: %.2f%% (ADC: %d)\n", moisture, adc_value);

        if (moisture < MOISTURE_THRESHOLD) {
            control_pump(true);
            printf("Moisture below threshold (%.1f%% < %.1f%%), pump ON\n",
                   moisture, MOISTURE_THRESHOLD);
        } else {
            control_pump(false);
            printf("Moisture above threshold, pump OFF\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

