#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CO2_THRESHOLD 700
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_co2_ppm(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    float voltage = (float)adc_value / 1023.0f * 3.3f;
    float co2_ppm = 100.0f * (voltage - 0.5f) / 0.5f;

    if (co2_ppm < 0.0f) co2_ppm = 0.0f;
    if (co2_ppm > 10000.0f) co2_ppm = 10000.0f;

    return (int)co2_ppm;
}

static void control_fan(int co2_ppm) {
    int state = (co2_ppm > CO2_THRESHOLD) ? 1 : 0;
    if (gpioWrite(FAN_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write fan GPIO\n");
    }
}

static void log_data(int co2_ppm, int fan_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, co2_ppm, fan_state);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FAN_GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int co2_ppm = calculate_co2_ppm(adc_value);
        if (co2_ppm < 0) {
            fprintf(stderr, "Error calculating CO2 ppm, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        control_fan(co2_ppm);
        int fan_state = gpioRead(FAN_GPIO);
        if (fan_state < 0) {
            fprintf(stderr, "Failed to read fan GPIO state\n");
        }

        log_data(co2_ppm, fan_state);
        printf("CO2: %d ppm, Fan: %s\n", co2_ppm, fan_state ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

