#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define VALVE_GPIO     17
#define PWM_FREQUENCY  100
#define PWM_RANGE      100
#define SAMPLE_COUNT   3
#define SAMPLE_DELAY_US 100000
#define LOG_INTERVAL_S  5
#define LOG_FILE_NAME   "irrigation.log"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then don't-care */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_average(int samples[], int count)
{
    int sum = 0;
    int valid = 0;
    for (int i = 0; i < count; i++) {
        if (samples[i] >= 0) {
            sum += samples[i];
            valid++;
        }
    }
    if (valid == 0) return -1;
    return sum / valid;
}

static int set_valve_position(int position)
{
    if (position < 0) position = 0;
    if (position > PWM_RANGE) position = PWM_RANGE;
    if (gpioPWM(VALVE_GPIO, position) != 0) {
        fprintf(stderr, "gpioPWM failed for position %d\n", position);
        return -1;
    }
    return 0;
}

static void log_data(int samples[], int average, int position)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Sample1: %d, Sample2: %d, Sample3: %d, Average: %d, Valve: %d\n",
            timestamp, samples[0], samples[1], samples[2], average, position);
    fflush(g_log_file);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    int samples[SAMPLE_COUNT];
    int average;
    int position;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Initial gpioPWM(0) failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation controller started. Logging to %s every %d seconds.\n",
           LOG_FILE_NAME, LOG_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int read_failed = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            samples[i] = read_mcp3008(i);
            if (samples[i] < 0) {
                fprintf(stderr, "Failed to read sample %d\n", i + 1);
                read_failed = 1;
            }
            gpioDelay(SAMPLE_DELAY_US);
        }

        if (read_failed) {
            fprintf(stderr, "Skipping cycle due to read failure.\n");
            sleep(1);
            continue;
        }

        average = calculate_average(samples, SAMPLE_COUNT);
        if (average < 0) {
            fprintf(stderr, "All samples failed; skipping cycle.\n");
            sleep(1);
            continue;
        }

        position = average;
        if (set_valve_position(position) != 0) {
            fprintf(stderr, "Failed to set valve position.\n");
        }

        log_data(samples, average, position);
        printf("Average: %d, Valve: %d\n", average, position);

        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    set_valve_position(0);
    cleanup();
    printf("Irrigation controller stopped.\n");
    return EXIT_SUCCESS;
}

