#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/pwm.h>

#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 1000000
#define PWM_DUTY_NS 500000

#define TRIGGER_PIN 23
#define ECHO_PIN 24

#define CONFIG_FILE "theremin_config.txt"

#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define MAX_VOLUME 1023
#define MIN_VOLUME 0

#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int pwm_fd = -1;
static int last_valid_distance = 0;
static int last_valid_volume = 0;

typedef struct {
    float min_distance;
    float max_distance;
    float min_volume;
    float max_volume;
} CalibrationData;

static CalibrationData calibration;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_adc(int channel) {
    if (spi_fd < 0) return -1;

    unsigned char tx[3] = {0x01, (0x08 | (channel & 0x07)) << 4, 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int pwm_init(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to export PWM");
        return -1;
    }
    fprintf(fp, "0");
    fclose(fp);

    usleep(100000);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/period", PWM_CHIP);
    fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to set PWM period");
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        FILE *unfp = fopen(path, "w");
        if (unfp) fclose(unfp);
        return -1;
    }
    fprintf(fp, "%d", PWM_PERIOD_NS);
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/duty_cycle", PWM_CHIP);
    fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to set PWM duty cycle");
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        FILE *unfp = fopen(path, "w");
        if (unfp) fclose(unfp);
        return -1;
    }
    fprintf(fp, "%d", 0);
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/enable", PWM_CHIP);
    fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to enable PWM");
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        FILE *unfp = fopen(path, "w");
        if (unfp) fclose(unfp);
        return -1;
    }
    fprintf(fp, "1");
    fclose(fp);

    pwm_fd = open(path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM enable file");
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        FILE *unfp = fopen(path, "w");
        if (unfp) fclose(unfp);
        return -1;
    }

    return 0;
}

static void pwm_set_duty(int duty_ns) {
    if (pwm_fd < 0) return;
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", duty_ns);
    if (write(pwm_fd, buf, strlen(buf)) < 0) {
        perror("Failed to write duty cycle");
    }
}

static void pwm_cleanup(void) {
    if (pwm_fd >= 0) {
        close(pwm_fd);
        pwm_fd = -1;
    }
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/enable", PWM_CHIP);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
    fp = fopen(path, "w");
    if (fp) fclose(fp);
}

static int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to open GPIO value file");
        return -1;
    }
    fprintf(fp, "%d", value);
    fclose(fp);
    return 0;
}

static int gpio_export(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to open GPIO export");
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    usleep(100000);
    return 0;
}

static int gpio_unexport(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to open GPIO unexport");
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

static int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to open GPIO direction");
        return -1;
    }
    fprintf(fp, "%s", direction);
    fclose(fp);
    return 0;
}

static int read_distance(void) {
    if (gpio_write(TRIGGER_PIN, 1) < 0) return -1;
    usleep(10);
    if (gpio_write(TRIGGER_PIN, 0) < 0) return -1;

    struct timespec start, end;
    int timeout = 0;

    while (gpio_write(ECHO_PIN, 1) < 0) {
        usleep(10);
        timeout++;
        if (timeout > TIMEOUT_US) return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    timeout = 0;
    while (gpio_write(ECHO_PIN, 0) < 0) {
        usleep(10);
        timeout++;
        if (timeout > TIMEOUT_US) return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    if (elapsed_us < 0 || elapsed_us > TIMEOUT_US) return -1;

    float distance = (elapsed_us / 1000.0) * 34300.0 / 2.0;
    if (distance < 0 || distance > MAX_DISTANCE) return -1;

    return (int)distance;
}

static int read_volume(void) {
    int adc_value = spi_read_adc(0);
    if (adc_value < 0) return -1;
    return adc_value;
}

static float map_value(float x, float in_min, float in_max, float out_min, float out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

static void cleanup(void) {
    pwm_cleanup();
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpio_unexport(TRIGGER_PIN);
    gpio_unexport(ECHO_PIN);
}

static int load_calibration(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "No config file found, using defaults.\n");
        return -1;
    }

    if (fscanf(fp, "%f %f %f %f", &calibration.min_distance, &calibration.max_distance, &calibration.min_volume, &calibration.max_volume) != 4) {
        fprintf(stderr, "Invalid config file format.\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration loaded: min_d=%.2f, max_d=%.2f, min_v=%.2f, max_v=%.2f\n",
           calibration.min_distance, calibration.max_distance, calibration.min_volume, calibration.max_volume);
    return 0;
}

static int save_calibration(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        perror("Failed to save config");
        return -1;
    }
    fprintf(fp, "%.2f %.2f %.2f %.2f\n", calibration.min_distance, calibration.max_distance, calibration.min_volume, calibration.max_volume);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpio_export(TRIGGER_PIN) < 0 || gpio_export(ECHO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO pins.\n");
        return 1;
    }

    if (gpio_set_direction(TRIGGER_PIN, "out") < 0 || gpio_set_direction(ECHO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO directions.\n");
        cleanup();
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        cleanup();
        return 1;
    }

    if (pwm_init() < 0) {
        fprintf(stderr, "PWM initialization failed.\n");
        cleanup();
        return 1;
    }

    if (load_calibration() < 0) {
        calibration.min_distance = MIN_DISTANCE;
        calibration.max_distance = MAX_DISTANCE;
        calibration.min_volume = MIN_VOLUME;
        calibration.max_volume = MAX_VOLUME;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        int volume = read_volume();

        if (distance < 0) {
            fprintf(stderr, "Error reading distance, using last valid value.\n");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        if (volume < 0) {
            fprintf(stderr, "Error reading volume, using last valid value.\n");
            volume = last_valid_volume;
        } else {
            last_valid_volume = volume;
        }

        float frequency = map_value((float)distance, calibration.min_distance, calibration.max_distance, 200.0, 1000.0);
        float duty_cycle = map_value((float)volume, calibration.min_volume, calibration.max_volume, 0.0, 1.0) * PWM_PERIOD_NS;

        pwm_set_duty((int)duty_cycle);

        printf("Distance: %d cm, Volume: %d, Frequency: %.2f Hz\n", distance, volume, frequency);

        usleep(50000);
    }

    printf("\nCleaning up...\n");
    cleanup();
    return 0;
}

