    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_SPI_RETRIES && running) {
            adc_value = read_mcp3008(MQ135_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_SPI_RETRIES) {
                fprintf(stderr, "SPI read failed, retry %d/%d\n", retries, MAX_SPI_RETRIES);
                gpioDelay(SPI_RETRY_DELAY_US);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MQ135 after %d retries, re-initializing SPI...\n", MAX_SPI_RETRIES);
            spiClose(spi_handle);
            spi_handle = -1;
            gpioDelay(SPI_RETRY_DELAY_US);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-initialization failed: %d\n", spi_handle);
                break;
            }
            continue;
        }

        float aqi = calculate_aqi(adc_value);
        log_data(aqi);

        if (aqi > AQI_THRESHOLD) {
            control_fan(1);
        } else {
            control_fan(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

