#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define LOG_FILE       "alcohol_log.txt"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000
#define SENSOR_ABSENT_THRESHOLD 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d): %s\n", ret, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static const char *classify_alcohol_level(int adc_value) {
    if (adc_value < 0) return "Error: Invalid ADC value";
    if (adc_value == 0 || adc_value == 1023) return "Sensor absent or disconnected.";
    if (adc_value > 50) return "Alcohol detected! Limit exceeded.";
    if (adc_value < 20) return "Sobriety confirmed.";
    return "Alcohol level within acceptable range.";
}

static int log_data(int adc_value, const char *classification) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, ADC: %d, Classification: %s\n", timestamp, adc_value, classification) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d): %s\n", spi_handle, strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Alcohol monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(ADC_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Warning: ADC read failed (attempt %d/%d), retrying...\n", retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed after %d attempts, skipping sample.\n", MAX_RETRIES);
        } else {
            const char *classification = classify_alcohol_level(adc_value);
            if (log_data(adc_value, classification) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            } else {
                printf("ADC: %d, Classification: %s\n", adc_value, classification);
            }
        }

        if (running) {
            sleep(SAMPLE_INTERVAL);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

