#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* Motor 1 */
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

/* Motor 2 */
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

/* SPI */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

/* Acceleration/deceleration time (microseconds) */
#define ACCEL_TIME 1000000
#define DECEL_TIME 1000000

/* Constant speed duration (seconds) */
#define CONST_SPEED_SEC 2

/* Pause between cycles (seconds) */
#define PAUSE_SEC 5

/* Acceleration/deceleration steps */
#define ACCEL_STEPS 100
#define DECEL_STEPS 100

/* PWM range */
#define PWM_RANGE 255

/* Error sentinel for potentiometer readings */
#define POT_ERROR -1

/* Global flag for graceful shutdown */
static volatile sig_atomic_t running = 1;

/* Signal handler for SIGINT and SIGTERM */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a single-ended channel from the MCP3008 via SPI */
static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return POT_ERROR;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (returned %d)\n", channel, bytes);
        return POT_ERROR;
    }

    /* 10-bit result: lower 2 bits of rx[1] + rx[2] */
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* Accelerate a motor from 0 to target speed over ACCEL_TIME microseconds */
static void accelerate_motor(int enable_pin, int direction_pin, int target_speed) {
    int step_delay = ACCEL_TIME / ACCEL_STEPS;
    int step = 0;
    while (step < ACCEL_STEPS && running) {
        int speed = (target_speed * step) / ACCEL_STEPS;
        if (gpioPWM(enable_pin, speed) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", enable_pin);
            return;
        }
        if (gpioWrite(direction_pin, 1) < 0) {
            fprintf(stderr, "Failed to set direction on GPIO %d\n", direction_pin);
            return;
        }
        gpioDelay(step_delay);
        step++;
    }
}

/* Decelerate a motor from current speed to 0 over DECEL_TIME microseconds */
static void decelerate_motor(int enable_pin, int direction_pin, int current_speed) {
    int step_delay = DECEL_TIME / DECEL_STEPS;
    int step = 0;
    while (step < DECEL_STEPS && running) {
        int speed = (current_speed * (DECEL_STEPS - step)) / DECEL_STEPS;
        if (gpioPWM(enable_pin, speed) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", enable_pin);
            return;
        }
        if (gpioWrite(direction_pin, 1) < 0) {
            fprintf(stderr, "Failed to set direction on GPIO %d\n", direction_pin);
            return;
        }
        gpioDelay(step_delay);
        step++;
    }
    /* Ensure motor is stopped */
    gpioPWM(enable_pin, 0);
}

/* Run a full cycle: accelerate, constant speed, decelerate, pause, reverse */
static void run_cycle(int m1_en, int m1_dir, int m2_en, int m2_dir,
                      int pot1, int pot2) {
    /* Accelerate both motors forward */
    accelerate_motor(m1_en, m1_dir, pot1);
    accelerate_motor(m2_en, m2_dir, pot2);

    /* Constant speed phase */
    if (running) {
        printf("Constant speed for %d seconds...\n", CONST_SPEED_SEC);
        sleep(CONST_SPEED_SEC);
    }

    /* Decelerate both motors */
    decelerate_motor(m1_en, m1_dir, pot1);
    decelerate_motor(m2_en, m2_dir, pot2);

    /* Pause between cycles */
    if (running) {
        printf("Pausing for %d seconds...\n", PAUSE_SEC);
        sleep(PAUSE_SEC);
    }

    /* Reverse: Motor 1 forward, Motor 2 backward */
    if (running) {
        printf("Reversing direction...\n");
        if (gpioWrite(m1_dir, 1) < 0) {
            fprintf(stderr, "Failed to set Motor 1 direction\n");
        }
        if (gpioWrite(m2_dir, 0) < 0) {
            fprintf(stderr, "Failed to set Motor 2 direction\n");
        }
        gpioDelay(100000); /* short delay to allow direction change */
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range */
    if (gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (running) {
        int pot1 = read_mcp3008(spi_handle, 0);
        int pot2 = read_mcp3008(spi_handle, 1);

        if (pot1 == POT_ERROR || pot2 == POT_ERROR) {
            fprintf(stderr, "Error reading potentiometer(s). Skipping cycle.\n");
            if (running) {
                sleep(PAUSE_SEC);
            }
            continue;
        }

        /* Map 0-1023 to 0-255 */
        int speed1 = (pot1 * PWM_RANGE) / 1023;
        int speed2 = (pot2 * PWM_RANGE) / 1023;

        printf("Pot1: %d, Pot2: %d, Speed1: %d, Speed2: %d\n", pot1, pot2, speed1, speed2);

        run_cycle(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION,
                  speed1, speed2);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

