#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_DURATION 5
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_ambient_level(void) {
    long sum = 0;
    int valid_samples = 0;

    printf("Calibrating ambient noise level for %d seconds...\n", CALIBRATION_DURATION);

    for (int i = 0; i < CALIBRATION_DURATION * 100; i++) {
        int level = read_mcp3008(MCP3008_CHANNEL);
        if (level >= 0) {
            sum += level;
            valid_samples++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1;
    }

    return (int)(sum / valid_samples);
}

static void control_led(int level, int ambient_level) {
    static int led_state = 0;
    static uint32_t last_toggle_tick = 0;

    if (level > ambient_level) {
        if (led_state == 0) {
            if (gpioTick() - last_toggle_tick > DEBOUNCE_DELAY_US) {
                gpioWrite(LED_GPIO, 1);
                led_state = 1;
                last_toggle_tick = gpioTick();
            }
        }
    } else {
        if (led_state == 1) {
            if (gpioTick() - last_toggle_tick > DEBOUNCE_DELAY_US) {
                gpioWrite(LED_GPIO, 0);
                led_state = 0;
                last_toggle_tick = gpioTick();
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int ambient_level = calibrate_ambient_level();
    if (ambient_level < 0) {
        fprintf(stderr, "Calibration failed\n");
        gpioWrite(LED_GPIO, 0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ambient noise level: %d\n", ambient_level);

    while (running) {
        int level = read_mcp3008(MCP3008_CHANNEL);
        if (level >= 0) {
            control_led(level, ambient_level);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return EXIT_SUCCESS;
}

