#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_GPIO_LINE    8          /* BCM 8  -> CE0  (physical pin 24) */
#define SPI_SPEED_HZ    1000000    /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_open(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int gpio_request_cs(struct gpiod_line *cs_line)
{
    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(0): %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(1): %s\n", strerror(errno));
        return -1;
    }

    /* rx[1] contains the two high bits of the result in its lower nibble;
     * rx[2] contains the low 8 bits. */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_sample(FILE *fp, long timestamp_ns, int adc_value)
{
    if (fprintf(fp, "%ld|%d\n", timestamp_ns, adc_value) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) == EOF) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
