#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define VREF 3.3
#define ADC_RESOLUTION 1023.0
#define SAMPLE_RATE_HZ 10
#define LOOP_DELAY_US (1000000 / SAMPLE_RATE_HZ)

#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

#define ADC_MAX_VALUE 1023.0

#define Q 0.01
#define R 0.1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double kalman_filter(double measurement, double *state, double *P) {
    double Q = 0.01;
    double R = 0.1;

    double P_pred = *P + Q;
    double K = P_pred / (P_pred + R);
    *state = *state + K * (measurement - *state);
    *P = (1.0 - K) * P_pred;
    return *state;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double x_state = 0.0, y_state = 0.0, z_state = 0.0;
    double x_P = 1.0, y_P = 1.0, z_P = 1.0;

    while (running) {
        int x_raw = read_mcp3008(spi_handle, X_CHANNEL);
        int y_raw = read_mcp3008(spi_handle, Y_CHANNEL);
        int z_raw = read_mcp3008(spi_handle, Z_CHANNEL);

        if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double x_voltage = (double)x_raw / ADC_RESOLUTION * VREF;
        double y_voltage = (double)y_raw / ADC_RESOLUTION * VREF;
        double z_voltage = (double)z_raw / ADC_RESOLUTION * VREF;

        double x_g = (x_voltage - 1.5) / 0.3;
        double y_g = (y_voltage - 1.5) / 0.3;
        double z_g = (z_voltage - 1.5) / 0.3;

        x_state = kalman_filter(x_g, &x_state, &x_P);
        y_state = kalman_filter(y_g, &y_state, &y_P);
        z_state = kalman_filter(z_g, &z_state, &z_P);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_state, y_state, z_state);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

