    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double x_state = 0.0, y_state = 0.0, z_state = 0.0;
    double x_P = 1.0, y_P = 1.0, z_P = 1.0;

    while (running) {
        int x_raw = read_mcp3008(spi_handle, X_CHANNEL);
        int y_raw = read_mcp3008(spi_handle, Y_CHANNEL);
        int z_raw = read_mcp3008(spi_handle, Z_CHANNEL);

        if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double x_voltage = (double)x_raw / ADC_RESOLUTION * VREF;
        double y_voltage = (double)y_raw / ADC_RESOLUTION * VREF;
        double z_voltage = (double)z_raw / ADC_RESOLUTION * VREF;

        double x_g = (x_voltage - 1.5) / 0.3;
        double y_g = (y_voltage - 1.5) / 0.3;
        double z_g = (z_voltage - 1.5) / 0.3;

        x_state = kalman_filter(x_g, &x_state, &x_P);
        y_state = kalman_filter(y_g, &y_state, &y_P);
        z_state = kalman_filter(z_g, &z_state, &z_P);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_state, y_state, z_state);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

