#define VOLTAGE_LOW 0.0
#define ADC_RESOLUTION 1024.0
#define MAX_MAGNETIC_FIELD 100.0
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR3_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d\n", gpio_pin);
        return -1;
    }
    return value;
}

static double convert_to_magnetic_field(int sensor_value) {
    double voltage = (sensor_value == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    double adc_value = (voltage - VOLTAGE_LOW) / (VOLTAGE_HIGH - VOLTAGE_LOW) * ADC_RESOLUTION;
    double magnetic_field = adc_value / 1000.0;
    return magnetic_field;
}

static int log_data(double sensor1_mT, double sensor2_mT, double sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT) < 0) {
