    }
    if (sensor2_mT < -MAX_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD) {
        fprintf(stderr, "Warning: sensor2_mT out of range: %.2f\n", sensor2_mT);
    }
    if (sensor3_mT < -MAX_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
        fprintf(stderr, "Warning: sensor3_mT out of range: %.2f\n", sensor3_mT);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Magnetic field logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error: GPIO read failure, skipping logging\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double sensor1_mT = convert_to_magnetic_field(sensor1_value);
        double sensor2_mT = convert_to_magnetic_field(sensor2_value);
        double sensor3_mT = convert_to_magnetic_field(sensor3_value);

        check_magnetic_field_range(sensor1_mT, sensor2_mT, sensor3_mT);

        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error: failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nMagnetic field logging stopped.\n");
    return 0;
}

