#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <errno.h>
#include <syslog.h>
#include <pigpio.h>

#define MQTT_BROKER_ADDRESS "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define MAX_PAYLOAD_SIZE 512

#define JSON_KEY_LED_STATE "led_state"

typedef struct {
    char payload[MAX_PAYLOAD_SIZE];
    size_t payload_len;
} mqtt_message_t;

typedef struct {
    int gpio_pin;
    int pigpio_handle;
    bool led_state;
} led_driver_t;

static volatile sig_atomic_t program_running = 1;
static int mqtt_connection_id = -1;
static led_driver_t led_driver = {LED_GPIO, -1, false};

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "[%s] %s", timestamp, message);
}

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void mqtt_connect_callback(void *userdata, int result_code) {
    (void)userdata;
    if (result_code == 0) {
        log_message("Connected to MQTT broker.");
    } else {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "MQTT connection failed with code %d.", result_code);
        syslog(LOG_ERR, "%s", error_message);
    }
}

static void mqtt_disconnect_callback(void *userdata, int result_code) {
    (void)userdata;
    if (result_code != 0) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "MQTT disconnection failed with code %d.", result_code);
        syslog(LOG_ERR, "%s", error_message);
    }
}

static void mqtt_message_callback(void *userdata, char *topic, int topic_len, char *message, int message_len) {
    (void)userdata;
    (void)topic;
    (void)topic_len;

    if (message_len <= 0 || message_len >= MAX_PAYLOAD_SIZE) {
        syslog(LOG_ERR, "Invalid message length: %d", message_len);
        return;
    }

    mqtt_message_t msg;
    memcpy(msg.payload, message, message_len);
    msg.payload_len = (size_t)message_len;
    msg.payload[msg.payload_len] = '\0';

    char json_key[64];
    char json_value[64];
    int key_len = 0, value_len = 0;

    if (json_get_key_value(msg.payload, msg.payload_len, JSON_KEY_LED_STATE, json_key, sizeof(json_key), &key_len, json_value, sizeof(json_value), &value_len) != 0) {
        syslog(LOG_ERR, "Failed to parse JSON payload.");
        return;
    }

    if (key_len != (int)strlen(JSON_KEY_LED_STATE)) {
        syslog(LOG_ERR, "Unexpected key in JSON payload: %s", json_key);
        return;
    }

    if (value_len != 4) {
        syslog(LOG_ERR, "Invalid value length for led_state.");
        return;
    }

    if (strncmp(json_value, "true", 4) == 0) {
        led_driver.led_state = true;
    } else if (strncmp(json_value, "false", 5) == 0) {
        led_driver.led_state = false;
    } else {
        syslog(LOG_ERR, "Invalid led_state value: %s", json_value);
        return;
    }

    if (led_driver.pigpio_handle >= 0) {
        if (gpioWrite(led_driver.gpio_pin, led_driver.led_state ? 1 : 0) != 0) {
            syslog(LOG_ERR, "Failed to write to GPIO %d.", led_driver.gpio_pin);
        } else {
            syslog(LOG_INFO, "LED state set to %s.", led_driver.led_state ? "ON" : "OFF");
        }
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed.");
        return -1;
    }

    led_driver.pigpio_handle = gpioInitialise();
    if (led_driver.pigpio_handle < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio.");
        return -1;
    }

    if (gpioSetMode(led_driver.gpio_pin, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output.", led_driver.gpio_pin);
        return -1;
    }

    if (gpioWrite(led_driver.gpio_pin, 0) != 0) {
        syslog(LOG_ERR, "Failed to set initial state of GPIO %d.", led_driver.gpio_pin);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (led_driver.pigpio_handle >= 0) {
        gpioWrite(led_driver.gpio_pin, 0);
        gpioTerminate();
        led_driver.pigpio_handle = -1;
    }
}

static int connect_to_mqtt(void) {
    int result = mosquitto_connect(mqtt_connection_id, MQTT_BROKER_ADDRESS, MQTT_PORT, 60);
    if (result != MOSQ_ERR_SUCCESS) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "MQTT connect failed with code %d.", result);
        syslog(LOG_ERR, "%s", error_message);
        return -1;
    }
    return 0;
}

static void disconnect_from_mqtt(void) {
    if (mqtt_connection_id >= 0) {
        mosquitto_disconnect(mqtt_connection_id);
    }
}

static int subscribe_to_mqtt(void) {
    int result = mosquitto_subscribe(mqtt_connection_id, NULL, MQTT_TOPIC, MQTT_QOS);
    if (result != MOSQ_ERR_SUCCESS) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "MQTT subscribe failed with code %d.", result);
        syslog(LOG_ERR, "%s", error_message);
        return -1;
    }
    return 0;
}

static void handle_mqtt_error(int result_code) {
    char error_message[128];
    snprintf(error_message, sizeof(error_message), "MQTT error occurred with code %d.", result_code);
    syslog(LOG_ERR, "%s", error_message);
}

int main(void) {
    openlog("led_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up signal handlers.");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    mosquitto_lib_init();

    mqtt_connection_id = mosquitto_connect_callback_set(NULL, mqtt_connect_callback);
    if (mqtt_connection_id < 0) {
        syslog(LOG_ERR, "Failed to set MQTT connect callback.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mqtt_connection_id = mosquitto_disconnect_callback_set(mqtt_connection_id, mqtt_disconnect_callback);
    if (mqtt_connection_id < 0) {
        syslog(LOG_ERR, "Failed to set MQTT disconnect callback.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mqtt_connection_id = mosquitto_message_callback_set(mqtt_connection_id, mqtt_message_callback);
    if (mqtt_connection_id < 0) {
        syslog(LOG_ERR, "Failed to set MQTT message callback.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    if (connect_to_mqtt() != 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    if (subscribe_to_mqtt() != 0) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic.");
        disconnect_from_mqtt();
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    int reconnect_delay = 1;
    while (program_running) {
        int result = mosquitto_loop(mqtt_connection_id, -1, 1);
        if (result != MOSQ_ERR_SUCCESS) {
            handle_mqtt_error(result);
            disconnect_from_mqtt();
            if (reconnect_delay < MAX_RECONNECT_DELAY) {
                reconnect_delay *= 2;
            } else {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
            syslog(LOG_INFO, "Reconnecting in %d seconds...", reconnect_delay);
            sleep(reconnect_delay);
            if (connect_to_mqtt() != 0) {
                syslog(LOG_ERR, "Failed to reconnect to MQTT broker.");
            } else {
                if (subscribe_to_mqtt() != 0) {
                    syslog(LOG_ERR, "Failed to resubscribe to MQTT topic.");
                }
            }
        } else {
            reconnect_delay = 1;
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    disconnect_from_mqtt();
    cleanup_gpio();
    mosquitto_lib_cleanup();
    closelog();
    return 0;
}

