    }
}

static int connect_to_mqtt(void) {
    int result = mosquitto_connect(mqtt_connection_id, MQTT_BROKER_ADDRESS, MQTT_PORT, 60);
    if (result != MOSQ_ERR_SUCCESS) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "MQTT connect failed with code %d.", result);
        syslog(LOG_ERR, "%s", error_message);
        return -1;
    }
    return 0;
}

static void disconnect_from_mqtt(void) {
    if (mqtt_connection_id >= 0) {
        mosquitto_disconnect(mqtt_connection_id);
    }
}

static int subscribe_to_mqtt(void) {
    int result = mosquitto_subscribe(mqtt_connection_id, NULL, MQTT_TOPIC, MQTT_QOS);
    if (result != MOSQ_ERR_SUCCESS) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "MQTT subscribe failed with code %d.", result);
        syslog(LOG_ERR, "%s", error_message);
        return -1;
    }
    return 0;
}

static void handle_mqtt_error(int result_code) {
    char error_message[128];
    snprintf(error_message, sizeof(error_message), "MQTT error occurred with code %d.", result_code);
    syslog(LOG_ERR, "%s", error_message);
}

int main(void) {
    openlog("led_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up signal handlers.");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    mosquitto_lib_init();

    mqtt_connection_id = mosquitto_connect_callback_set(NULL, mqtt_connect_callback);
    if (mqtt_connection_id < 0) {
        syslog(LOG_ERR, "Failed to set MQTT connect callback.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mqtt_connection_id = mosquitto_disconnect_callback_set(mqtt_connection_id, mqtt_disconnect_callback);
    if (mqtt_connection_id < 0) {
        syslog(LOG_ERR, "Failed to set MQTT disconnect callback.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mqtt_connection_id = mosquitto_message_callback_set(mqtt_connection_id, mqtt_message_callback);
    if (mqtt_connection_id < 0) {
        syslog(LOG_ERR, "Failed to set MQTT message callback.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    if (connect_to_mqtt() != 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker.");
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    if (subscribe_to_mqtt() != 0) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic.");
        disconnect_from_mqtt();
        cleanup_gpio();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    int reconnect_delay = 1;
    while (program_running) {
        int result = mosquitto_loop(mqtt_connection_id, -1, 1);
        if (result != MOSQ_ERR_SUCCESS) {
            handle_mqtt_error(result);
            disconnect_from_mqtt();
            if (reconnect_delay < MAX_RECONNECT_DELAY) {
                reconnect_delay *= 2;
            } else {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
            syslog(LOG_INFO, "Reconnecting in %d seconds...", reconnect_delay);
            sleep(reconnect_delay);
            if (connect_to_mqtt() != 0) {
                syslog(LOG_ERR, "Failed to reconnect to MQTT broker.");
            } else {
                if (subscribe_to_mqtt() != 0) {
                    syslog(LOG_ERR, "Failed to resubscribe to MQTT topic.");
                }
            }
        } else {
            reconnect_delay = 1;
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    disconnect_from_mqtt();
    cleanup_gpio();
    mosquitto_lib_cleanup();
    closelog();
    return 0;
}

