typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    return 0;
}

static int read_calibration(int handle, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2c_read_reg(handle, BMP280_REG_CALIB, buf, 24) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    cal->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    cal->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    cal->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    cal->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int read_raw(int handle, int32_t *temp, int32_t *press) {
    uint8_t buf[6];
    if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, buf, 6) < 0) return -1;
    *press = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *temp = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static double compensate_temp(int32_t raw, const bmp280_calib_t *c, double *t_fine) {
    double v1 = ((double)raw / 16384.0 - (double)c->dig_T1 / 1024.0) * (double)c->dig_T2;
    double v2 = (((double)raw / 131072.0 - (double)c->dig_T1 / 8192.0) *
                 ((double)raw / 131072.0 - (double)c->dig_T1 / 8192.0)) * (double)c->dig_T3;
    *t_fine = v1 + v2;
    return *t_fine / 5120.0;
}

static double compensate_press(int32_t raw, const bmp280_calib_t *c, double t_fine) {
    double v1 = (t_fine / 2.0) - 64000.0;
    double v2 = v1 * v1 * (double)c->dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)c->dig_P5 * 2.0;
    v2 = (v2 / 4.0) + ((double)c->dig_P4 * 65536.0);
    v1 = ((double)c->dig_P3 * v1 * v1 / 524288.0 + (double)c->dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)c->dig_P1;
    if (v1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw;
    p = (p - (v2 / 4096.0)) * 6250.0 / v1;
    v1 = (double)c->dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)c->dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)c->dig_P7) / 16.0;
    return p;
}

static double calc_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
}

