#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL_US 5000000
#define LOG_FILE "temp_log.dat"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_temperature(int adc_value) {
    return (float)adc_value * 0.0625f;
}

static void add_to_buffer(float temperature, float *buffer, int *index) {
    buffer[*index] = temperature;
    *index = (*index + 1) % BUFFER_SIZE;
}

static void print_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
    fflush(stdout);
}

static int write_buffer_to_file(const float *buffer, int size, const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(buffer, sizeof(float), size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int spi_handle = -1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping sample.\n");
        } else {
            float temperature = adc_to_temperature(adc_value);
            add_to_buffer(temperature, temperature_buffer, &buffer_index);
            print_temperature(temperature);

            if (write_buffer_to_file(temperature_buffer, BUFFER_SIZE, LOG_FILE) != 0) {
                fprintf(stderr, "Failed to write buffer to file.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

