#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define I2C_DEVICE      "/dev/i2c-1"
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR    0x48
#define DAC_RESOLUTION  4095.0f
#define DAC_VREF        3.3f
#define LOG_FILE        "temperature_log.txt"
#define SAMPLE_INTERVAL 0.5
#define MAX_RETRIES     3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint32_t speed = 500000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd); i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(uint8_t channel, uint16_t *adc_value) {
    if (channel > 7) return -1;

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 500000,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int write_mcp4725(uint16_t dac_value) {
    if (dac_value > 4095) return -1;

    uint8_t buf[3];
    buf[0] = 0x40;
    buf[1] = (uint8_t)((dac_value >> 4) & 0xFF);
    buf[2] = (uint8_t)((dac_value << 4) & 0xF0);

    if (write(i2c_fd, buf, 3) != 3) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

static float adc_to_celsius(uint16_t adc_value) {
    return (float)(adc_value - 512) * 0.01f;
}

static float celsius_to_dac_voltage(float temp_c) {
    return temp_c * 10.0f;
}

static float dac_voltage_to_dac_value(float voltage) {
    return (voltage / DAC_VREF) * DAC_RESOLUTION;
}

static int log_data(uint16_t adc_value, float temp_c, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_fp, "%s, ADC: %u, Temp: %.2f C, DAC: %.2f V\n",
                ts, adc_value, temp_c, dac_voltage) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) { close(spi_fd); spi_fd = -1; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (spi_init() < 0) return 1;
    if (i2c_init() < 0) { cleanup(); return 1; }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t adc_value = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_mcp3008(MCP3008_CHANNEL, &adc_value) == 0) {
                ok = 1;
                break;
            }
            usleep(10000);
        }

        if (!ok) {
            fprintf(stderr, "Error: failed to read ADC after %d retries.\n", MAX_RETRIES);
            log_data(0, 0.0f, 0.0f);
            sleep(1);
            continue;
        }

        float temp_c = adc_to_celsius(adc_value);
        float dac_voltage = celsius_to_dac_voltage(temp_c);
        uint16_t dac_value = (uint16_t)dac_voltage_to_dac_value(dac_voltage);

        if (write_mcp4725(dac_value) < 0) {
            fprintf(stderr, "Warning: DAC write failed.\n");
        }

        if (log_data(adc_value, temp_c, dac_voltage) < 0) {
            fprintf(stderr, "Warning: log write failed.\n");
        }

        printf("ADC: %u, Temp: %.2f C, DAC: %.2f V\n", adc_value, temp_c, dac_voltage);

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

