#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define RELAY_ON 1
#define RELAY_OFF 0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int deactivate_all_relays(void) {
    int rc = 0;
    rc |= safe_write(RELAY1_PIN, RELAY_OFF);
    rc |= safe_write(RELAY2_PIN, RELAY_OFF);
    rc |= safe_write(RELAY3_PIN, RELAY_OFF);
    rc |= safe_write(RELAY4_PIN, RELAY_OFF);
    return rc;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (deactivate_all_relays() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (safe_write(RELAY1_PIN, RELAY_ON) != 0) break;
        sleep(1);
        if (safe_write(RELAY1_PIN, RELAY_OFF) != 0) break;
        sleep(1);

        if (safe_write(RELAY2_PIN, RELAY_ON) != 0) break;
        sleep(1);
        if (safe_write(RELAY2_PIN, RELAY_OFF) != 0) break;
        sleep(1);

        if (safe_write(RELAY3_PIN, RELAY_ON) != 0) break;
        sleep(1);
        if (safe_write(RELAY3_PIN, RELAY_OFF) != 0) break;
        sleep(1);

        if (safe_write(RELAY4_PIN, RELAY_ON) != 0) break;
        sleep(1);
        if (safe_write(RELAY4_PIN, RELAY_OFF) != 0) break;
        sleep(1);
    }

    deactivate_all_relays();
    gpioTerminate();
    return EXIT_SUCCESS;
}

