/*
 * rain.c — Raspberry Pi 3 Model B+
 *
 * Reads a Seeed Studio Grove Rain Sensor via an MCP3008 ADC on SPI0,
 * logs rain levels to rain_log.txt, and drives an L298N motor to
 * simulate window control based on a threshold.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V, VREF -> 3.3 V, AGND/DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Grove Rain Sensor analog out
 *   L298N IN1    -> GPIO17 (BCM)
 *   L298N IN2    -> GPIO18 (BCM)
 *   L298N ENA    -> GPIO27 (BCM, PWM0)
 *
 * Build: gcc -o rain rain.c -lrt -lpthread
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        0
#define SPI_BITS        8

#define MOTOR_IN1       17
#define MOTOR_IN2       18
#define MOTOR_ENA       27

#define RAIN_THRESHOLD  5
#define MOTOR_DURATION  3          /* seconds */
#define PWM_RANGE       255
#define PWM_DUTY        150

#define LOG_FILE        "rain_log.txt"
#define POLL_INTERVAL   1          /* seconds */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static FILE    *g_log_fp   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI                                                                 */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * 3-byte transfer: [0x01] [SGL|D2|D1|D0 | 0x00] [0x00]
 * Result: ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(uint8_t channel)
{
    if (g_spi_fd < 0)
        return -1;

    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static int motor_init(void)
{
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(MOTOR_IN1): %s\n", pigpio_error(0));
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(MOTOR_IN2): %s\n", pigpio_error(0));
        return -1;
    }
    if (gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(MOTOR_ENA): %s\n", pigpio_error(0));
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_ENA, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange: %s\n", pigpio_error(0));
        return -1;
    }

    /* Ensure motor is stopped at startup */
    if (gpioWrite(MOTOR_IN1, 0) < 0) {
        fprintf(stderr, "gpioWrite(MOTOR_IN1): %s\n", pigpio_error(0));
        return -1;
    }
    if (gpioWrite(MOTOR_IN2, 0) < 0) {
        fprintf(stderr, "gpioWrite(MOTOR_IN2): %s\n", pigpio_error(0));
        return -1;
    }
    if (gpioPWM(MOTOR_ENA, 0) < 0) {
        fprintf(stderr, "gpioPWM(MOTOR_ENA): %s\n", pigpio_error(0));
        return -1;
    }

    return 0;
}

static void motor_forward(void)
{
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

static void motor_reverse(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_rain_level(int rain_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize motor control */
    if (motor_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    int window_open = 1;

    while (g_running) {
        int rain_level = mcp3008_read(0);

        if (rain_level < 0) {
            fprintf(stderr, "SPI read error; continuing\n");
        } else {
            log_rain_level(rain_level);

            if (rain_level > RAIN_THRESHOLD) {
                printf("Rain detected! Closing window.\n");
                motor_forward();
                sleep(MOTOR_DURATION);
                motor_stop();
                window_open = 0;
            } else {
                if (!window_open) {
                    printf("Rain level low. Opening window.\n");
                    motor_reverse();
                    sleep(MOTOR_DURATION);
                    motor_stop();
                    window_open = 1;
                }
            }
        }

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

