#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_ADC_PIN 26
#define LED_PIN 16
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000
#define ADC_MAX_VALUE 1023

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int pin) {
    int value = 0;
    for (int i = 0; i < 10; i++) {
        if (gpioWrite(pin, 1) < 0) return -1;
        gpioDelay(1);
        value = (value << 1) | gpioRead(pin);
        if (gpioWrite(pin, 0) < 0) return -1;
        gpioDelay(1);
    }
    return value;
}

static bool detect_clap(int adc_value) {
    return adc_value > 500;
}

static void control_led(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error: Failed to write to LED pin %d\n", pin);
    }
}

static void log_event(int pin, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected on GPIO%d, ADC value: %d\n", timestamp, pin, adc_value);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_ADC_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set MIC_ADC_PIN %d as output\n", MIC_ADC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED_PIN %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize LED_PIN %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

