#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define DISTANCE_THRESHOLD_MM 200
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_gpio_value(void) {
    char path[64];
    FILE *fp;
    int value;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_LINE);
    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Error reading GPIO value\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return value;
}

static void log_distance(int distance_mm) {
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[20];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time\n");
        return;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance_mm);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    int ret;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = system("echo 17 > /sys/class/gpio/export");
    if (ret == -1) {
        fprintf(stderr, "Error exporting GPIO17: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = system("echo in > /sys/class/gpio/gpio17/direction");
    if (ret == -1) {
        fprintf(stderr, "Error setting GPIO17 direction: %s\n", strerror(errno));
        system("echo 17 > /sys/class/gpio/unexport");
        return EXIT_FAILURE;
    }

    printf("Distance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_gpio_value();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying in %d second(s)...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD_MM) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    system("echo 17 > /sys/class/gpio/unexport");
    return EXIT_SUCCESS;
}

