        float moisture = adc_to_moisture(adc_value);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error converting ADC value to moisture percentage.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD) {
            if (!pump_status) {
                if (gpiod_line_set_value(pump_line, 1) < 0) {
                    perror("Failed to activate pump");
                } else {
                    pump_status = 1;
                    printf("Pump activated. Moisture: %.2f%%\n", moisture);
                }
            }
        } else {
            if (pump_status) {
                if (gpiod_line_set_value(pump_line, 0) < 0) {
                    perror("Failed to deactivate pump");
                } else {
                    pump_status = 0;
                    printf("Pump deactivated. Moisture: %.2f%%\n", moisture);
                }
            }
        }

        log_data(moisture, pump_status);
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

