#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0
#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_PERIOD_MS 500
#define GPIO_CHIP       "gpiochip0"
#define CS_LINE_OFFSET  8
#define VREF_MV         3300
#define ADC_MAX         1023

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    return raw;
}

static int calculate_magnetic_field(int raw, float *b_out)
{
    if (raw < 0 || raw > ADC_MAX) {
        fprintf(stderr, "ADC raw value out of range: %d\n", raw);
        return -1;
    }

    float v = (float)raw * VREF_MV / (float)(ADC_MAX + 1);
    if (v < 0.0f || v > VREF_MV) {
        fprintf(stderr, "Voltage out of range: %.2f mV\n", v);
        return -1;
    }

    /* DRV5055-A1: 0.5 mV/mT sensitivity, 1.65 V offset at 0 T */
    float b = (v - 1650.0f) / 0.5f;
    *b_out = b;
    return 0;
}

static int log_data(FILE *fp, float b)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    if (fprintf(fp, "%ld,%.2f\n", (long)now, b) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Starting magnetic field logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        int raw = read_mcp3008(spi_fd, cs_line, ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        float b;
        if (calculate_magnetic_field(raw, &b) != 0) {
            fprintf(stderr, "Magnetic field calculation failed; skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if (log_data(log_fp, b) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("Magnetic Field: %.2f mT\n", b);
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) fclose(log_fp);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    return ret;
}

