#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17
#define ADC_CHANNEL     0
#define LOG_FILE        "current_log.txt"
#define SAMPLE_INTERVAL 1
#define ADC_MAX         1023
#define ADC_VREF        3.3
#define SENSOR_VOUT     0.05   /* 50 mV/A typical */
#define ADC_ERROR_VALUE -1

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static int  g_gpio_fd  = -1;
static FILE *g_log_fp  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void)
{
    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    uint32_t offset = GPIO_LINE;
    if (ioctl(fd, GPIO_GET_LINE_IOCTL, &offset) < 0) {
        fprintf(stderr, "Error getting GPIO line %u: %s\n", GPIO_LINE, strerror(errno));
        close(fd);
        return -1;
    }

    /* Request the line as output, initially low (sensor disabled) */
    struct gpio_line_request req;
    memset(&req, 0, sizeof(req));
    req.offset = offset;
    req.consumer = "mlx91209_current";

    if (ioctl(fd, GPIO_LINE_REQUEST, &req) < 0) {
        fprintf(stderr, "Error requesting GPIO line %u: %s\n", GPIO_LINE, strerror(errno));
        close(fd);
        return -1;
    }

    /* Set line value low to power down the sensor */
    if (ioctl(fd, GPIO_LINE_SET_VALUE, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line %u low: %s\n", GPIO_LINE, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return ADC_ERROR_VALUE;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return ADC_ERROR_VALUE;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static double adc_to_current(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX) {
        return 0.0;
    }
    double voltage = (double)adc_value * ADC_VREF / ADC_MAX;
    return voltage / SENSOR_VOUT;
}

static int log_current(FILE *fp, double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%.4f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_gpio_fd >= 0) {
        /* Power down the sensor by setting GPIO low */
        if (ioctl(g_gpio_fd, GPIO_LINE_SET_VALUE, 0) < 0) {
            fprintf(stderr, "Warning: failed to power down sensor: %s\n", strerror(errno));
        }
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    g_gpio_fd = gpio_init();
    if (g_gpio_fd < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting current monitoring. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = read_adc(g_spi_fd, ADC_CHANNEL);
        if (adc_value == ADC_ERROR_VALUE) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
        } else {
            double current = adc_to_current(adc_value);
            if (log_current(g_log_fp, current) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

