#define LOG_FILE    "current_log.txt"
#define SAMPLE_US   100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, then 1 dummy byte */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static double adc_to_current(int adc_value) {
    double voltage = ((double)adc_value / (double)ADC_MAX) * VREF;
    return voltage / 0.18;
}

static int log_current(FILE *fp, double current) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s %.2f A\n", timestamp, current) < 0) {
        perror("fprintf to log file failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush on log file failed");
        return -1;
    }
    return 0;
}

int main(void) {
    int spi_handle = -1;
    FILE *fp = NULL;
    int exit_code = 0;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return 1;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel 0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ") failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting current monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = adc_to_current(adc_value);

        if (current < 0.0 || current > 5.0) {
            fprintf(stderr, "Current out of range: %.2f A (ADC %d)\n", current, adc_value);
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_current(fp, current) != 0) {
            fprintf(stderr, "Logging failed, exiting\n");
            exit_code = 1;
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    /* Clean up resources */
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return exit_code;
}

