#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_debounced(int gpio) {
    int count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int v = gpioRead(gpio);
        if (v < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d)\n", gpio, v);
            return -1;
        }
        if (v == 0) count++;
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (count >= DEBOUNCE_READINGS / 2) ? 0 : 1;
}

static void log_sensor_data(int s1, int s2) {
    printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);
    fflush(stdout);
}

static void check_alert(int s1, int s2) {
    if (s1 == 0 && s2 == 0) {
        printf("ALERT: Both sensors detect object\n");
        fflush(stdout);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sensors on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);
    fflush(stdout);

    while (running) {
        int s1 = read_sensor_debounced(SENSOR_1_GPIO);
        if (s1 < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        int s2 = read_sensor_debounced(SENSOR_2_GPIO);
        if (s2 < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        log_sensor_data(s1, s2);
        check_alert(s1, s2);
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

