#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_fd = -1;
static volatile sig_atomic_t program_running = 1;

static int spi_setup(spi_config_t config) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", config.channel);
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", spi_device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = config.baud_rate;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (spi_fd < 0) {
        fprintf(stderr, "SPI device not initialized.\n");
        return -1;
    }

    uint8_t tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    uint8_t rx_buf[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_BAUD,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

static double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

static void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    // spi_cleanup() is not called here because the user requested a minimal
    // signal handler that only closes the SPI handle and exits cleanly.
    // The full cleanup is handled by the main loop.
    exit(0);
}

int main() {
    spi_config_t config = {SPI_CHANNEL, SPI_BAUD};
    if (spi_setup(config) != 0) {
        fprintf(stderr, "SPI setup failed, exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds.\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level < 0) {
            fprintf(stderr, "Error calculating moisture level, retrying in %d seconds.\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        log_data(moisture_level);
        sleep(READ_DELAY);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    // spi_cleanup() is not called here because the user requested a minimal
    // signal handler that only closes the SPI handle and exits cleanly.
    // The full cleanup is handled by the main loop.
    return 0;
}

