#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define PIR_PIN          17
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_MS      200
#define CAPTURE_DIR      "/home/pi/security_cam"
#define MAX_FILENAME_LEN 256
#define MAX_CMD_LEN      512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir('%s'): %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        char *argv[] = {
            "libcamera-still",
            "-o", (char *)filename,
            "--timeout", "1000",
            "--nopreview",
            NULL
        };
        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp(libcamera-still): %s", strerror(errno));
        _exit(127);
    }

    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR)
            continue;
        syslog(LOG_ERR, "waitpid: %s", strerror(errno));
        return -1;
    }

    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still failed (status=0x%04x)", status);
        return -1;
    }
    return 0;
}

static void log_motion(const char *filename)
{
    syslog(LOG_INFO, "Motion detected, captured to %s", filename);
}

int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

