/*
 * Raspberry Pi CSI camera UDP streamer (V4L2 YUYV -> UDP).
 *
 * Build:  gcc -O2 -Wall -Wextra -o stream stream.c
 * Run:    ./stream send_udp_packet
 *
 * send_udp_packet is a placeholder for the actual library call that
 * sends a UDP datagram.  Replace it with your own implementation.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <linux/videodev2.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define DEVICE_NAME   "/dev/video0"
#define TARGET_IP     "127.0.0.1"
#define TARGET_PORT   5000
#define MAX_DGRAM_LEN 65000
#define NUM_BUFFERS   4
#define FRAME_WIDTH   640
#define FRAME_HEIGHT  480
#define FRAME_SIZE    (FRAME_WIDTH * FRAME_HEIGHT * 2)  /* YUYV: 2 bytes/pixel */

typedef struct {
    uint32_t frame_index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
} __attribute__((packed)) udp_header_t;

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int ret;
    do {
        ret = ioctl(fd, request, arg);
    } while (ret < 0 && errno == EINTR);
    return ret;
}

static int init_camera(int *fd, struct v4l2_buffer *buf,
                       struct v4l2_requestbuffers *rb)
{
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "open(%s): %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    memset(rb, 0, sizeof(*rb));
    rb->count  = NUM_BUFFERS;
    rb->type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    rb->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, rb) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    for (unsigned int i = 0; i < rb->count; ++i) {
        memset(buf + i, 0, sizeof(*buf));
        buf[i].index = i;
        buf[i].type  = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;

        if (xioctl(*fd, VIDIOC_QUERYBUF, buf + i) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF[%u]: %s\n",
                    i, strerror(errno));
            close(*fd);
            *fd = -1;
            return -1;
        }

        if (mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE,
                 MAP_SHARED, *fd, buf[i].m.offset) == MAP_FAILED) {
            fprintf(stderr, "mmap[%u]: %s\n", i, strerror(errno));
            close(*fd);
            *fd = -1;
            return -1;
        }
    }
    return 0;
}

static int start_stream(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void stop_stream(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0)
        fprintf(stderr, "VIDIOC_STREAMOFF: %s\n", strerror(errno));
}

static void unmap_buffers(struct v4l2_buffer *buf, unsigned int count)
{
    for (unsigned int i = 0; i < count; ++i)
        if (buf[i].length > 0 && buf[i].m.offset != 0)
            munmap((void *)(uintptr_t)buf[i].m.offset, buf[i].length);
}

static int send_udp_packet(int sockfd, const uint8_t *data, size_t len,
                           const struct sockaddr_in *addr)
{
    size_t total_sent = 0;
    while (total_sent < len) {
        size_t chunk = len - total_sent;
        if (chunk > MAX_DGRAM_LEN)
            chunk = MAX_DGRAM_LEN;
        ssize_t n = sendto(sockfd, data + total_sent, chunk, 0,
                           (const struct sockaddr *)addr,
                           sizeof(*addr));
        if (n < 0) {
            fprintf(stderr, "sendto: %s\n", strerror(errno));
            return -1;
        }
        total_sent += (size_t)n;
    }
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <library_call_to_send_udp_packet>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *send_udp_packet = argv[1];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = -1;
    struct v4l2_buffer buf[NUM_BUFFERS];
    struct v4l2_requestbuffers rb;
    memset(&rb, 0, sizeof(rb));

    if (init_camera(&fd, buf, &rb) < 0)
        return EXIT_FAILURE;

    if (start_stream(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        stop_stream(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(TARGET_PORT);
    if (inet_pton(AF_INET, TARGET_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton: invalid address '%s'\n", TARGET_IP);
        close(sockfd);
        stop_stream(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Streaming %dx%d YUYV to %s:%d ...\n",
           FRAME_WIDTH, FRAME_HEIGHT, TARGET_IP, TARGET_PORT);

    while (g_running) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fd_set fds;
        struct timeval tv;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec  = 2;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select: %s\n", strerror(errno));
            break;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            continue;
        }

        struct v4l2_buffer b;
        memset(&b, 0, sizeof(b));
        b.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        b.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &b) < 0) {
            if (errno == EAGAIN) continue;
            fprintf(stderr, "VIDIOC_DQBUF: %s\n", strerror(errno));
            break;
        }

        if (b.index >= rb.count) {
            fprintf(stderr, "Invalid buffer index %u\n", b.index);
            continue;
        }

        uint8_t *frame = (uint8_t *)(uintptr_t)b.m.offset;
        size_t total_fragments = (size_t)(FRAME_SIZE + MAX_DGRAM_LEN - 1) / MAX_DGRAM_LEN;
        size_t fragment_size = (total_fragments > 1) ? MAX_DGRAM_LEN : FRAME_SIZE;

        for (uint32_t frag = 0; frag < total_fragments; ++frag) {
            size_t payload_len = (frag < total_fragments - 1) ? fragment_size : (FRAME_SIZE % MAX_DGRAM_LEN);
            uint8_t *payload = frame + frag * fragment_size;
            udp_header_t hdr = {
                .frame_index     = b.index,
                .fragment_index  = frag,
                .total_fragments = total_fragments,
                .payload_size    = payload_len
            };

            uint8_t dgram[MAX_DGRAM_LEN + sizeof(udp_header_t)];
            memcpy(dgram, &hdr, sizeof(hdr));
            memcpy(dgram + sizeof(hdr), payload, payload_len);

            if (send_udp_packet(sockfd, dgram, sizeof(hdr) + payload_len, &addr) < 0) {
                fprintf(stderr, "Failed to send fragment %u\n", frag);
                break;
            }
        }

        if (xioctl(fd, VIDIOC_QBUF, &b) < 0) {
            fprintf(stderr, "VIDIOC_QBUF: %s\n", strerror(errno));
            break;
        }
    }

    printf("\nShutting down...\n");
    stop_stream(fd);
    unmap_buffers(buf, rb.count);
    if (fd >= 0) close(fd);
    if (sockfd >= 0) close(sockfd);

    printf("Done.\n");
    return EXIT_SUCCESS;
}

