#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define TILT_UP_BUTTON     6
#define TILT_DOWN_BUTTON   7
#define PAN_LEFT_BUTTON    8
#define PAN_RIGHT_BUTTON   9

#define PWM_FREQUENCY      50
#define PWM_RANGE          1000
#define MIN_DUTY           50
#define MAX_DUTY           100
#define SERVO_MID_DUTY     75
#define MIN_POSITION       25
#define MAX_POSITION       125
#define STEP_SIZE          5
#define POLL_DELAY_US      50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_position(int pin, int position)
{
    if (position < MIN_POSITION || position > MAX_POSITION) {
        fprintf(stderr, "Error: position %d out of range [%d, %d]\n",
                position, MIN_POSITION, MAX_POSITION);
        return -1;
    }

    int duty = MIN_DUTY + (int)(((float)(position - MIN_POSITION) /
                                 (MAX_POSITION - MIN_POSITION)) *
                                (MAX_DUTY - MIN_DUTY));
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (duty %d)\n", pin, duty);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan servo pin %d\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt servo pin %d\n",
                TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_UP_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt-up button pin %d\n",
                TILT_UP_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt-down button pin %d\n",
                TILT_DOWN_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan-left button pin %d\n",
                PAN_LEFT_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan-right button pin %d\n",
                PAN_RIGHT_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for tilt-up button\n");
        gpioTerminate();
        return EXIT_FAILURE;
