#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void print_resolution(const struct v4l2_frmsize_discrete *s) {
    printf("  Resolution: %ux%u\n", s->width, s->height);
}

static void print_frame_interval(const struct v4l2_frmival_stepwise *i) {
    if (i->type == V4L2_FRMIVAL_TYPE_DISCRETE) {
        printf("    Frame rate: %u/%u fps\n", i->discrete.numerator, i->discrete.denominator);
    } else if (i->type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
        printf("    Frame rate: %u.%u fps (continuous)\n",
               i->stepwise.numerator / i->stepwise.denominator,
               i->stepwise.numerator % i->stepwise.denominator * 1000 / i->stepwise.denominator);
    } else if (i->type == V4L2_FRMIVAL_TYPE_STEPWISE) {
        printf("    Frame rate: %u.%u fps (stepwise, min/max: %u.%u/%u.%u fps)\n",
               i->stepwise.numerator / i->stepwise.denominator,
               i->stepwise.numerator % i->stepwise.denominator * 1000 / i->stepwise.denominator,
               i->stepwise.min.numerator / i->stepwise.min.denominator,
               i->stepwise.min.numerator % i->stepwise.min.denominator * 1000 / i->stepwise.min.denominator,
               i->stepwise.max.numerator / i->stepwise.max.denominator,
               i->stepwise.max.numerator % i->stepwise.max.denominator * 1000 / i->stepwise.max.denominator);
    }
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl qctrl;
    int autofocus_supported = 0;
    int has_frame_size = 0;
    int has_frame_interval = 0;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_ENUM_FRAMESIZES)) {
        fprintf(stderr, "%s does not support frame size enumeration\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_ENUM_FRAMEINTERVALS)) {
        fprintf(stderr, "%s does not support frame interval enumeration\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("CSI Camera: %s\n", DEVICE_NAME);
    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.pixel_format = V4L2_PIX_FMT_MJPEG;

    for (frmsize.index = 0; ; frmsize.index++) {
        if (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == -1) {
            if (errno == EINVAL) break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            has_frame_size = 1;
            printf("Supported resolutions:\n");
            print_resolution(&frmsize.discrete);
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            has_frame_size = 1;
            printf("Supported resolutions (stepwise, min/max %ux%u to %ux%u):\n",
                   frmsize.stepwise.min.width, frmsize.stepwise.min.height,
                   frmsize.stepwise.max.width, frmsize.stepwise.max.height);
        } else {
            break;
        }
    }

    if (!has_frame_size) {
        fprintf(stderr, "No frame sizes found for %s\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&frmival, 0, sizeof(frmival));
    frmival.pixel_format = V4L2_PIX_FMT_MJPEG;

    for (frmival.index = 0; ; frmival.index++) {
        if (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == -1) {
            if (errno == EINVAL) break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            has_frame_interval = 1;
            printf("  Frame rates:\n");
            print_frame_interval(&frmival.discrete);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
            has_frame_interval = 1;
            printf("  Frame rates:\n");
            print_frame_interval(&frmival.stepwise);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            has_frame_interval = 1;
            printf("  Frame rates:\n");
            print_frame_interval(&frmival.stepwise);
        } else {
            break;
        }
    }

    if (!has_frame_interval) {
        fprintf(stderr, "No frame intervals found for %s\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&qctrl, 0, sizeof(qctrl));
    qctrl.id = V4L2_CID_FOCUS_AUTO;

    if (xioctl(fd, VIDIOC_QUERYCTRL, &qctrl) == -1) {
        if (errno == EINVAL) {
            fprintf(stderr, "Autofocus control not supported by %s\n", DEVICE_NAME);
        } else {
            fprintf(stderr, "VIDIOC_QUERYCTRL failed: %s\n", strerror(errno));
        }
        close(fd);
        return EXIT_FAILURE;
    }

    if (qctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        fprintf(stderr, "Autofocus is disabled on %s\n", DEVICE_NAME);
    } else {
        autofocus_supported = 1;
        printf("Autofocus: %s\n", qctrl.name);
    }

    close(fd);
    return EXIT_SUCCESS;
}

