#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define UP_BUTTON_PIN      6
#define DOWN_BUTTON_PIN    7
#define LEFT_BUTTON_PIN    8
#define RIGHT_BUTTON_PIN   9

#define MIN_PULSE_WIDTH    1000
#define MAX_PULSE_WIDTH    2000
#define CENTER_PULSE_WIDTH 1500
#define STEP_SIZE          10
#define LOOP_DELAY_US      50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp_pulse(int pulse)
{
    if (pulse < MIN_PULSE_WIDTH) return MIN_PULSE_WIDTH;
    if (pulse > MAX_PULSE_WIDTH) return MAX_PULSE_WIDTH;
    return pulse;
}

static int set_servo_pulse(int pin, int pulse)
{
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", pin, pulse);
        return -1;
    }
    return 0;
}

static int adjust_pan(int delta)
{
    static int pan = CENTER_PULSE_WIDTH;
    pan += delta;
    pan = clamp_pulse(pan);
    if (set_servo_pulse(PAN_SERVO_PIN, pan) < 0) return -1;
    printf("Pan: %d us\n", pan);
    return 0;
}

static int adjust_tilt(int delta)
{
    static int tilt = CENTER_PULSE_WIDTH;
    tilt += delta;
    tilt = clamp_pulse(tilt);
    if (set_servo_pulse(TILT_SERVO_PIN, tilt) < 0) return -1;
    printf("Tilt: %d us\n", tilt);
    return 0;
}

static void cleanup(void)
{
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    if (set_servo_pulse(PAN_SERVO_PIN, CENTER_PULSE_WIDTH) < 0 ||
        set_servo_pulse(TILT_SERVO_PIN, CENTER_PULSE_WIDTH) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Pan-Tilt Control Program\n");
    printf("Pan:   GPIO%d\n", PAN_SERVO_PIN);
    printf("Tilt:  GPIO%d\n", TILT_SERVO_PIN);
    printf("Up:    GPIO%d\n", UP_BUTTON_PIN);
    printf("Down:  GPIO%d\n", DOWN_BUTTON_PIN);
    printf("Left:  GPIO%d\n", LEFT_BUTTON_PIN);
    printf("Right: GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("Center: %d us\n", CENTER_PULSE_WIDTH);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(UP_BUTTON_PIN) == 0) {
            adjust_tilt(-STEP_SIZE);
        }
        if (gpioRead(DOWN_BUTTON_PIN) == 0) {
            adjust_tilt(STEP_SIZE);
        }
        if (gpioRead(LEFT_BUTTON_PIN) == 0) {
            adjust_pan(-STEP_SIZE);
        }
        if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
            adjust_pan(STEP_SIZE);
        }
        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

