#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <gpiod.h>

#define PIR_GPIO_LINE	17
#define DEBOUNCE_MS		50
#define CAPTURE_TIMEOUT_MS	2000
#define IMAGE_DIR	"/home/pi/images"
#define LOG_FILE	"/home/pi/motion_capture.log"
#define CONSUMER	"motion_capture"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
	(void)sig;
	running = 0;
}

static void log_event(const char *msg)
{
	FILE *fp = fopen(LOG_FILE, "a");
	if (!fp) {
		fprintf(stderr, "log open failed: %s\n", strerror(errno));
		return;
	}
	time_t t = time(NULL);
	struct tm tm;
	if (localtime_r(&t, &tm)) {
		char ts[64];
		strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
		fprintf(fp, "%s: %s\n", ts, msg);
	}
	fclose(fp);
}

static int capture_image(void)
{
	char cmd[512];
	char ts[32];
	time_t t = time(NULL);
	struct tm tm;
	if (!localtime_r(&t, &tm)) {
		log_event("Failed to get local time for filename");
		return -1;
	}
	strftime(ts, sizeof(ts), "%Y%m%d_%H%M%S", &tm);

	char filename[256];
	snprintf(filename, sizeof(filename), "%s/%s_%03d.jpg",
		 IMAGE_DIR, ts, (int)(t * 1000) % 1000);

	snprintf(cmd, sizeof(cmd),
		 "raspistill -o %s --width 640 --height 480 -q 85 --timeout %d --nopreview",
		 filename, CAPTURE_TIMEOUT_MS);

	int status = system(cmd);
	if (status == -1) {
		log_event("system() failed to launch raspistill");
		return -1;
	}
	if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
		char m[256];
		snprintf(m, sizeof(m), "raspistill failed (status=%d)", status);
		log_event(m);
		return -1;
	}
	return 0;
}

int main(void)
{
	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = sig_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
		fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
		return 1;
	}

	struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
	if (!chip) {
		fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
		return 1;
	}

	struct gpiod_line *line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
	if (!line) {
		fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
			PIR_GPIO_LINE, strerror(errno));
		gpiod_chip_close(chip);
		return 1;
	}

	if (gpiod_line_request_falling_edge_events(line, CONSUMER) < 0) {
		fprintf(stderr, "gpiod_line_request_falling_edge_events failed: %s\n",
			strerror(errno));
		gpiod_chip_close(chip);
		return 1;
	}

	log_event("Motion capture service started");

	while (running) {
		struct timespec ts = { 0, 100 * 1000 * 1000 }; /* 100 ms poll */
		int ret = gpiod_line_event_wait(line, &ts);
		if (ret < 0) {
			if (errno == EINTR) continue;
			log_event("gpiod_line_event_wait error");
			break;
		}
		if (ret == 0) continue; /* timeout, loop and re-check running */

		struct gpiod_line_event ev;
		if (gpiod_line_event_read(line, &ev) < 0) {
			log_event("gpiod_line_event_read error");
			continue;
		}
		if (ev.event_type != GPIOD_LINE_EVENT_FALLING_EDGE)
			continue;

		/* Debounce: wait for the line to stay low for DEBOUNCE_MS */
		struct timespec debounce_ts = { 0, DEBOUNCE_MS * 1000 * 1000 };
		int val = gpiod_line_get_value(line);
		if (val < 0) {
			log_event("gpiod_line_get_value error during debounce");
			continue;
		}
		if (val != 0) continue;

		/* Wait for line to rise or timeout */
		int edge_wait = 0;
		while (running && edge_wait < DEBOUNCE_MS) {
			struct timespec poll_ts = { 0, 100 * 1000 * 1000 };
			ret = gpiod_line_event_wait(line, &poll_ts);
			if (ret < 0) {
				if (errno == EINTR) break;
				log_event("gpiod_line_event_wait error during debounce");
				edge_wait = DEBOUNCE_MS;
				break;
			}
			if (ret == 0) {
				edge_wait++;
				continue;
			}
			struct gpiod_line_event ev2;
			if (gpiod_line_event_read(line, &ev2) < 0) {
				log_event("gpiod_line_event_read error during debounce");
				edge_wait = DEBOUNCE_MS;
				break;
			}
			if (ev2.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
				edge_wait = DEBOUNCE_MS;
				break;
			}
		}

		if (!running) break;
		if (edge_wait >= DEBOUNCE_MS) {
			log_event("Motion detected");
			if (capture_image() == 0)
				log_event("Image captured successfully");
		}
	}

	gpiod_line_release(line);
	gpiod_chip_close(chip);
	log_event("Motion capture service stopped");
	return 0;
}

