#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define SERVO_FREQ 50
#define SERVO_RANGE 180
#define SERVO_NEUTRAL 90
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        fprintf(stderr, "Error: Angle %d out of range (0-%d).\n", angle, SERVO_RANGE);
        return -1;
    }
    int pulse_width = (int)(angle * 1000.0 / SERVO_RANGE);
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler.\n");
    }

    if (set_servo_angle(PAN_SERVO_PIN, SERVO_NEUTRAL) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, SERVO_NEUTRAL) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Arrow keys (WASD) to move pan/tilt. Press 'q' or Ctrl+C to quit.\n");

    while (running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }

        int pan_angle = SERVO_NEUTRAL;
        int tilt_angle = SERVO_NEUTRAL;

        switch (c) {
            case 'w': case 'W': pan_angle -= STEP_SIZE; break;
            case 's': case 'S': pan_angle += STEP_SIZE; break;
            case 'a': case 'A': tilt_angle -= STEP_SIZE; break;
            case 'd': case 'D': tilt_angle += STEP_SIZE; break;
            case 'q': case 'Q': running = 0; break;
            default: continue;
        }

        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
            set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
            break;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_SERVO_PIN, SERVO_NEUTRAL);
    set_servo_angle(TILT_SERVO_PIN, SERVO_NEUTRAL);
    gpioTerminate();
    printf("\nClean exit.\n");
    return 0;
}

