#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define OLED_I2C_ADDR 0x3C
#define I2C_BUS "/dev/i2c-1"

#define SSD1306_SET_DISPLAY_CLOCK_DIV 0xA0
#define SSD1306_SET_MULTIPLEX 0xA1
#define SSD1306_SET_DISPLAY_OFFSET 0xA2
#define SSD1306_SET_START_LINE 0xA4
#define SSD1306_SET_CHARGE_PUMP 0x8D
#define SSD1306_SET_MEMORY_MODE 0x20
#define SSD1306_SET_COLUMN_RANGE 0x21
#define SSD1306_SET_CONTRAST 0x81
#define SSD1306_SET_ALL_ON_RESUME 0xA4
#define SSD1306_NORMAL_DISPLAY 0xA6
#define SSD1306_INVERT_DISPLAY 0xA7
#define SSD1306_DISPLAY_ON 0xAF
#define SSD1306_DISPLAY_OFF 0xAE
#define SSD1306_SET_PAGE_ADDR 0xB0
#define SSD1306_SET_SEGMENT_REMAP 0xA0
#define SSD1306_SET_COM_SCAN_DIR 0xC0
#define SSD1306_SET_COM_PINS 0xDA
#define SSD1306_SET_PRECHARGE 0xD9
#define SSD1306_SET_VCOMDETECT 0xDB
#define SSD1306_SET_DISPLAY_CLOCK 0xD5
#define SSD1306_SET_GPIO 0x8A
#define SSD1306_SET_POWER_SOURCE 0x82
#define SSD1306_SET_OLED_CMD 0x00
#define SSD1306_SET_OLED_DATA 0x40

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(uint8_t cmd) {
    uint8_t buf[2] = {SSD1306_SET_OLED_CMD, cmd};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_write_data(const uint8_t *data, size_t len) {
    uint8_t buf[1 + 64];
    if (len > 64) {
        fprintf(stderr, "Data length %zu exceeds 64\n", len);
        return -1;
    }
    buf[0] = SSD1306_SET_OLED_DATA;
    memcpy(buf + 1, data, len);
    if (write(i2c_fd, buf, len + 1) != (ssize_t)(len + 1)) {
        perror("I2C write data failed");
        return -1;
    }
    return 0;
}

static int oled_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, OLED_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (i2c_write_cmd(0xAE) < 0) return -1;
    if (i2c_write_cmd(0xD5) < 0) return -1;
    if (i2c_write_cmd(0x80) < 0) return -1;
    if (i2c_write_cmd(0xA8) < 0) return -1;
    if (i2c_write_cmd(0x3F) < 0) return -1;
    if (i2c_write_cmd(0xD3) < 0) return -1;
    if (i2c_write_cmd(0x00) < 0) return -1;
    if (i2c_write_cmd(0x40) < 0) return -1;
    if (i2c_write_cmd(0x8D) < 0) return -1;
    if (i2c_write_cmd(0x14) < 0) return -1;
    if (i2c_write_cmd(0x20) < 0) return -1;
    if (i2c_write_cmd(0x00) < 0) return -1;
    if (i2c_write_cmd(0xA1) < 0) return -1;
    if (i2c_write_cmd(0xC8) < 0) return -1;
    if (i2c_write_cmd(0xDA) < 0) return -1;
    if (i2c_write_cmd(0x12) < 0) return -1;
    if (i2c_write_cmd(0x81) < 0) return -1;
    if (i2c_write_cmd(0xCF) < 0) return -1;
    if (i2c_write_cmd(0xD9) < 0) return -1;
    if (i2c_write_cmd(0xF1) < 0) return -1;
    if (i2c_write_cmd(0xDB) < 0) return -1;
    if (i2c_write_cmd(0x40) < 0) return -1;
    if (i2c_write_cmd(0xA4) < 0) return -1;
    if (i2c_write_cmd(0xA6) < 0) return -1;
    if (i2c_write_cmd(0xAF) < 0) return -1;
    return 0;
}

static int oled_clear(void) {
    uint8_t blank[OLED_WIDTH];
    memset(blank, 0x00, sizeof(blank));
    for (int page = 0; page < OLED_HEIGHT / 8; page++) {
        if (i2c_write_cmd(0xB0 + page) < 0) return -1;
        if (i2c_write_cmd(0x00) < 0) return -1;
        if (i2c_write_cmd(0x10) < 0) return -1;
        if (i2c_write_data(blank, sizeof(blank)) < 0) return -1;
    }
    return 0;
}

static int oled_display_string(int x, int y, const char *text) {
    if (x < 0) x = 0;
