#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_ENTRY_MODE 0x06
#define LCD_CLEAR 0x01
#define LCD_HOME 0x02
#define LCD_4BITMODE 0x30
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00
#define LCD_INIT 0x33
#define LCD_INIT2 0x32
#define LCD_INIT3 0x28
#define LCD_INIT4 0x0C
#define LCD_INIT5 0x06
#define LCD_INIT6 0x01

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static double total_volume = 0.0;
static double flow_rate = 0.0;
static time_t last_log_time = 0;
static time_t last_lcd_update_time = 0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static void update_flow_rate(void) {
    time_t now = time(NULL);
    double elapsed = difftime(now, last_log_time);
    if (elapsed > 0.0) {
        flow_rate = (double)pulse_count / elapsed;
        pulse_count = 0;
    }
}

static void update_total_volume(void) {
    time_t now = time(NULL);
    double elapsed = difftime(now, last_log_time);
    if (elapsed > 0.0) {
        total_volume += (double)pulse_count / elapsed;
        pulse_count = 0;
    }
}

static void log_data(void) {
    time_t now = time(NULL);
    double elapsed = difftime(now, last_log_time);
    if (elapsed > 0.0) {
        flow_rate = (double)pulse_count / elapsed;
        pulse_count = 0;
        last_log_time = now;
        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
    }
}

static void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    char buf[2] = {0x00, (char)(data | ENABLE)};
    i2cWriteDevice(i2c_handle, buf, 2);
    gpioDelay(1);
    buf[1] = (char)(data & ~ENABLE);
    i2cWriteDevice(i2c_handle, buf, 2);
    gpioDelay(100);
}

static void lcd_byte(int bits, int mode) {
    if (i2c_handle < 0) return;
    char buf[2] = {0x00, (char)(bits & 0xF0) | LCD_BACKLIGHT | mode};
    i2cWriteDevice(i2c_handle, buf, 2);
    lcd_strobe(bits);
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_byte(LCD_INIT, LCD_CMD);
    gpioDelay(5000);
    lcd_byte(LCD_INIT2, LCD_CMD);
    gpioDelay(2000);
    lcd_byte(LCD_4BITMODE, LCD_CMD);
    gpioDelay(2000);
    lcd_byte(LCD_INIT3, LCD_CMD);
    gpioDelay(2000);
    lcd_byte(LCD_INIT4, LCD_CMD);
    gpioDelay(2000);
    lcd_byte(LCD_INIT5, LCD_CMD);
    gpioDelay(2000);
    lcd_byte(LCD_INIT6, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_clear(void) {
    if (i2c_handle < 0) return;
    lcd_byte(LCD_CLEAR, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_set_cursor(int row, int col) {
    if (i2c_handle < 0) return;
    int addr = (row == 0) ? LCD_LINE_1 : LCD_LINE_2;
    lcd_byte(addr + col, LCD_CMD);
}

static void lcd_print(const char *str) {
    if (i2c_handle < 0) return;
    while (*str) {
        lcd_byte((uint8_t)*str++, LCD_CHR);
    }
}

static void update_lcd(void) {
    time_t now = time(NULL);
    double elapsed = difftime(now, last_lcd_update_time);
    if (elapsed > 0.0) {
        lcd_clear();
        char line1[17];
        char line2[17];
        snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
        snprintf(line2, sizeof(line2), "Vol: %.2f L", total_volume);
        lcd_set_cursor(0, 0);
        lcd_print(line1);
        lcd_set_cursor(1, 0);
        lcd_print(line2);
        last_lcd_update_time = now;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d\n", LCD_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();
    lcd_clear();

    while (running) {
        update_flow_rate();
        update_total_volume();
        log_data();
        update_lcd();
        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

