#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define ANEMOMETER_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define SPI_BUS 0
#define SPI_CS 0
#define SPI_SPEED 1000000
#define WIND_DIRECTION_CHANNEL 0
#define SAMPLE_WINDOW_MS 500
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        pulse_count++;
    }
}

static int spi_init(void) {
    char spi_dev[32];
    snprintf(spi_dev, sizeof(spi_dev), "/dev/spidev%d.%d", SPI_BUS, SPI_CS);
    spi_fd = open(spi_dev, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", spi_dev, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int i2c_init(void) {
    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", i2c_dev, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(i2c_fd); i2c_fd = -1; return -1;
    }
    return 0;
}

static int lcd_init(void) {
    uint8_t init_cmds[] = {0x33, 0x32, 0x28, 0x0C, 0x06, 0x01};
    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        uint8_t buf[4] = {0x00, 0x00, init_cmds[i], 0x00};
        if (write(i2c_fd, buf, 4) != 4) {
            fprintf(stderr, "Error sending LCD init command 0x%02X: %s\n", init_cmds[i], strerror(errno));
            return -1;
        }
        usleep(5000);
    }
    return 0;
}

static int lcd_write(uint8_t data) {
    uint8_t buf[4] = {0x00, 0x00, data, 0x00};
    if (write(i2c_fd, buf, 4) != 4) {
        fprintf(stderr, "Error writing to LCD: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_clear(void) {
    if (lcd_write(0x01) < 0) return -1;
    usleep(2000);
    return 0;
}

static int lcd_set_cursor(int row, int col) {
    uint8_t addr = (row == 0) ? 0x80 : 0xC0;
    addr += col;
    return lcd_write(addr);
}

static int lcd_print(const char *str) {
    for (size_t i = 0; str[i] != '\0' && i < LCD_WIDTH; i++) {
        if (lcd_write((uint8_t)str[i]) < 0) return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error reading MCP3008: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) return 1;
    if (i2c_init() < 0) { cleanup(); return 1; }
