#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_CLEAR 0x01
#define LCD_HOME 0x02
#define LCD_ENTRY_MODE 0x06
#define LCD_DISPLAY_ON 0x0C
#define LCD_FUNCTION_SET 0x28
#define FLOW_SENSOR_PULSES_PER_LITER 7.5
#define FLOW_SENSOR_TIMEOUT_SEC 10
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    char buf[2] = { (char)(data | LCD_ENABLE | LCD_BACKLIGHT), (char)(data & ~LCD_ENABLE | LCD_BACKLIGHT) };
    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) {
        fprintf(stderr, "Error: I2C write failed during strobe.\n");
    }
}

static void lcd_byte(int bits, int mode) {
    if (i2c_handle < 0) return;
    int high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    lcd_strobe(high);
    lcd_strobe(low);
}

static void lcd_string(const char *s) {
    if (i2c_handle < 0) return;
    while (*s) {
        lcd_byte((uint8_t)*s++, LCD_CHR);
    }
}

static void lcd_clear(void) {
    if (i2c_handle < 0) return;
    lcd_byte(LCD_CLEAR, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(void) {
    if (i2c_handle < 0) return;
    gpioDelay(50000);
    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(LCD_FUNCTION_SET, LCD_CMD);
    lcd_byte(LCD_DISPLAY_ON, LCD_CMD);
    lcd_byte(LCD_ENTRY_MODE, LCD_CMD);
    lcd_clear();
}

static void lcd_set_cursor(int row, int col) {
    if (i2c_handle < 0) return;
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_byte(addr, LCD_CMD);
}

static void lcd_print_line(int row, const char *text) {
    if (i2c_handle < 0) return;
    lcd_set_cursor(row, 0);
    lcd_string(text);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear();
        lcd_print_line(0, "Shutting down...");
        gpioDelay(1000000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, LCD_ADDR);
        return -1;
    }
    lcd_init();
    return 0;
}

static double calculate_flow_rate(int pulses) {
    return ((double)pulses / FLOW_SENSOR_PULSES_PER_LITER) * 60.0;
}

static void display_flow_rate(double flow_rate) {
    char line2[LCD_WIDTH + 1];
    snprintf(line2, sizeof(line2), "Flow Rate: %.2f L/min", flow_rate);
    lcd_print_line(0, "Flow Rate:");
    lcd_print_line(1, line2);
}

static void display_error(const char *message) {
    lcd_clear();
    lcd_print_line(0, "Error:");
    lcd_print_line(1, message);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t last_pulse_time = time(NULL);
    int pulse_count = 0;
    bool sensor_absent = false;

    while (running) {
        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            display_error("Time retrieval failed.");
            gpioDelay(1000000);
            continue;
        }

        if (gpioRead(FLOW_SENSOR_GPIO) == 1) {
            pulse_count++;
            last_pulse_time = current_time;
            sensor_absent = false;
        }

        if (difftime(current_time, last_pulse_time) > FLOW_SENSOR_TIMEOUT_SEC) {
            if (!sensor_absent) {
                sensor_absent = true;
                display_error("Sensor absent or disconnected.");
            }
        } else {
            sensor_absent = false;
        }

        double flow_rate = calculate_flow_rate(pulse_count);
        display_flow_rate(flow_rate);

        pulse_count = 0;
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

