        for (int i = 0; i < NUM_COLS; i++) {
            frame[i] = (frame[i] << 1) | (frame[i + NUM_COLS] >> 7);
            frame[i + NUM_COLS] = (frame[i + NUM_COLS] << 1) | (frame[i] >> 7);
        }
        if (display_frame(frame) != 0) {
            cleanup();
            return 1;
        }
    }

    cleanup();
    return 0;
}

