/*
 * 8x8 Common-Anode LED Matrix Wave Animation
 * Board: Raspberry Pi (any model with BCM GPIO)
 * Wiring:
 *   Rows (anodes): GPIO 2, 3, 4, 17, 27, 22, 10, 9
 *   Cols (cathodes): GPIO 14, 15, 18, 23, 24, 25, 8, 7
 *   Each column cathode is through a 220 ohm resistor to GND.
 *   A column lights when its cathode is LOW and all row anodes are HIGH.
 *
 * Build: gcc -O2 -Wall -Wextra -o matrix_wave matrix_wave.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>

#define NUM_ROWS 8
#define NUM_COLS 8

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_set_value(row_lines[i], 0);
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_set_value(col_lines[i], 1);
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "matrix-wave", 0) < 0) {
            perror("gpiod_line_request_output (row)");
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "matrix-wave", 1) < 0) {
            perror("gpiod_line_request_output (col)");
            return -1;
        }
    }
    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            perror("gpiod_line_set_value (row clear)");
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpiod_line_set_value(col_lines[i], 1) < 0) {
            perror("gpiod_line_set_value (col clear)");
        }
    }
}

static void display_column(int col, const int *pattern) {
    if (gpiod_line_set_value(col_lines[col], 0) < 0) {
        perror("gpiod_line_set_value (col select)");
        return;
    }
    for (int r = 0; r < NUM_ROWS; r++) {
        if (gpiod_line_set_value(row_lines[r], pattern[r]) < 0) {
            perror("gpiod_line_set_value (row set)");
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int pattern[NUM_ROWS];
    for (int i = 0; i < NUM_ROWS; i++) {
        pattern[i] = (i == 0 || i == 7) ? 1 : 0;
    }

    while (running) {
        clear_matrix();
        usleep(150000);

        for (int col = 0; col < NUM_COLS && running; col++) {
            display_column(col, pattern);
            usleep(150000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

