/*
 * VL53L3CX Multi-Target Time-of-Flight Distance Reader
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: STMicroelectronics VL53L3CX
 *
 * NOTE: The VL53L3CX uses a proprietary firmware download sequence
 *       that is not publicly documented.  This program stubs the
 *       firmware download with a descriptive comment while keeping
 *       the I2C communication and error handling fully implemented.
 *       Replace the stub with the official STMicroelectronics
 *       firmware download sequence once it becomes available.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS              1
#define VL53L3CX_ADDR        0x29
#define POLL_INTERVAL_US     100000   /* 100 ms */
#define MAX_TARGETS          10

/* VL53L3CX register addresses (representative subset) */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L3CX_REG_SYSTEM_START              0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L3CX_REG_RESULT_DISTANCE_MM        0x0096
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_COUNT  0x009A
#define VL53L3CX_REG_RESULT_SIG_RATE_MM        0x009E
#define VL53L3CX_REG_RESULT_AMBIENT_COUNT      0x00A2
#define VL53L3CX_REG_RESULT_SPAD_NB            0x00A6
#define VL53L3CX_REG_RESULT_TARGET_STATUS      0x00B0
#define VL53L3CX_REG_RESULT_TARGET_COUNT       0x00B2
#define VL53L3CX_REG_RESULT_TARGET_DISTANCES   0x00B4

#define VL53L3CX_MODEL_ID_EXPECTED             0xEA
#define VL53L3CX_RANGE_STATUS_OK               0x00
#define VL53L3CX_RANGE_STATUS_ERROR            0x01

typedef struct {
    uint16_t distance_mm;
    uint16_t peak_signal_count;
    uint16_t ambient_count;
    uint16_t spad_nb;
    uint16_t sig_rate_mm;
} TargetData;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int i2c_read_reg16_le(int handle, uint16_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2c_read_reg16(handle, reg, buf, 2) != 2) return -1;
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_read_reg16_le_array(int handle, uint16_t reg, uint16_t *buf, uint32_t len) {
    uint8_t raw[2 * len];
    if (i2c_read_reg16(handle, reg, raw, 2 * len) != (int)(2 * len)) return -1;
    for (uint32_t i = 0; i < len; i++) {
        buf[i] = (uint16_t)raw[2 * i] | ((uint16_t)raw[2 * i + 1] << 8);
    }
    return 0;
}

static int vl53l3cx_init(int handle) {
    uint16_t model_id = 0;

    /* Read model ID to verify sensor presence */
    if (i2c_read_reg16_le(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID (I2C bus error or sensor absent).\n");
        return -1;
    }
    if (model_id != VL53L3CX_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected model ID 0x%04X (expected 0x%04X). Sensor not present or wrong device.\n",
                model_id, VL53L3CX_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("VL53L3CX detected (Model ID: 0x%04X).\n", model_id);

    /*
     * STMicroelectronics VL53L3CX firmware download sequence
     * (proprietary, not publicly documented).
     *
     * Replace the following stub with the official firmware
     * download sequence once it becomes available from STMicro.
     */
    printf("WARNING: VL53L3CX firmware download sequence stubbed.\n");
    printf("         Replace the stub with the official STMicro sequence.\n");
    printf("         Continuing with basic I2C communication.\n");

    /* Start continuous ranging */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

static int vl53l3cx_read_data(int handle, TargetData *targets, int max_targets) {
    uint16_t target_count = 0;
    uint16_t distances[MAX_TARGETS];

    /* Read number of detected targets */
    if (i2c_read_reg16_le(handle, VL53L3CX_REG_RESULT_TARGET_COUNT, &target_count) != 0) {
        fprintf(stderr, "Error: Failed to read target count.\n");
        return -1;
    }

    if (target_count > (uint16_t)max_targets) {
        target_count = (uint16_t)max_targets;
    }

    /* Read distances for all targets */
    if (i2c_read_reg16_le_array(handle, VL53L3CX_REG_RESULT_TARGET_DISTANCES,
                                distances, target_count) != 0) {
        fprintf(stderr, "Error: Failed to read target distances.\n");
        return -1;
    }

