#define POLL_INTERVAL_US     100000   /* 100 ms */
#define MAX_TARGETS          10

/* VL53L3CX register addresses (representative subset) */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L3CX_REG_SYSTEM_START              0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L3CX_REG_RESULT_DISTANCE_MM        0x0096
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_COUNT  0x009A
#define VL53L3CX_REG_RESULT_SIG_RATE_MM        0x009E
#define VL53L3CX_REG_RESULT_AMBIENT_COUNT      0x00A2
#define VL53L3CX_REG_RESULT_SPAD_NB            0x00A6
#define VL53L3CX_REG_RESULT_TARGET_STATUS      0x00B0
#define VL53L3CX_REG_RESULT_TARGET_COUNT       0x00B2
#define VL53L3CX_REG_RESULT_TARGET_DISTANCES   0x00B4

