#define VL53L3CX_RANGE_STATUS_ERROR            0x01

typedef struct {
    uint16_t distance_mm;
    uint16_t peak_signal_count;
    uint16_t ambient_count;
    uint16_t spad_nb;
    uint16_t sig_rate_mm;
} TargetData;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int i2c_read_reg16_le(int handle, uint16_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2c_read_reg16(handle, reg, buf, 2) != 2) return -1;
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_read_reg16_le_array(int handle, uint16_t reg, uint16_t *buf, uint32_t len) {
    uint8_t raw[2 * len];
    if (i2c_read_reg16(handle, reg, raw, 2 * len) != (int)(2 * len)) return -1;
    for (uint32_t i = 0; i < len; i++) {
        buf[i] = (uint16_t)raw[2 * i] | ((uint16_t)raw[2 * i + 1] << 8);
    }
    return 0;
}

static int vl53l3cx_init(int handle) {
    uint16_t model_id = 0;

    /* Read model ID to verify sensor presence */
    if (i2c_read_reg16_le(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID (I2C bus error or sensor absent).\n");
        return -1;
    }
    if (model_id != VL53L3CX_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected model ID 0x%04X (expected 0x%04X). Sensor not present or wrong device.\n",
                model_id, VL53L3CX_MODEL_ID_EXPECTED);
        return -1;
    }
