#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75031_ADDR  0x24
#define LOG_FILE       "depth_log.csv"
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;
    usleep(10000);

    /* Set measurement mode */
    if (i2c_write_reg8(fd, 0x01, 0x01) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_distance(int fd, int16_t *distance)
{
    uint16_t raw;
    if (i2c_read_reg16(fd, 0x02, &raw) < 0) return -1;
    *distance = (int16_t)raw;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

static int log_data(FILE *fp, const char *timestamp, int16_t distance)
{
    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX75031_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Distance\n");
        fflush(fp);
    }

    printf("Starting depth logging to %s (Ctrl+C to stop)...\n", LOG_FILE);

    while (g_running) {
        int16_t distance;
        if (read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Read failed; logging -1 and attempting re-open.\n");
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (log_data(fp, ts, -1) < 0) {
                fprintf(stderr, "Log write failed; aborting.\n");
                break;
            }
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(1000000);
            if (g_i2c_fd < 0) {
                g_i2c_fd = open(I2C_BUS, O_RDWR);
                if (g_i2c_fd < 0) {
                    fprintf(stderr, "Re-open failed: %s\n", strerror(errno));
                    break;
                }
                if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
                    fprintf(stderr, "Re-set address failed: %s\n", strerror(errno));
                    close(g_i2c_fd);
                    g_i2c_fd = -1;
                    break;
                }
                if (init_sensor(g_i2c_fd) < 0) {
                    fprintf(stderr, "Re-init failed.\n");
                    close(g_i2c_fd);
                    g_i2c_fd = -1;
                    break;
                }
            }
            continue;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        if (log_data(fp, ts, distance) < 0) {
            fprintf(stderr, "Log write failed; aborting.\n");
            break;
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (fp) {
        fclose(fp);
    }
    return 0;
}

