    while (g_running) {
        int16_t distance;
        if (read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Read failed; logging -1 and attempting re-open.\n");
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (log_data(fp, ts, -1) < 0) {
