#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1145_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000  /* 500 ms */

/* Si1145 register addresses */
#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0    0x26
#define SI1145_REG_PS1_DATA1    0x27

#define SI1145_PART_ID          0x45
#define SI1145_HW_KEY_VAL       0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int si1145_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int si1145_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int si1145_init(void)
{
    uint8_t part_id = 0;

    if (si1145_read_reg(SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (si1145_write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0)
        return -1;

    /* Measurement rate: 0x08 0x00 -> ~100 ms; enable ALS_VIS and PS1 */
    if (si1145_write_reg(SI1145_REG_MEAS_RATE0, 0x08) != 0)
        return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(uint16_t *prox, uint16_t *light)
{
    uint8_t p0, p1, l0, l1;

    if (si1145_read_reg(SI1145_REG_PS1_DATA0, &p0) != 0) return -1;
    if (si1145_read_reg(SI1145_REG_PS1_DATA1, &p1) != 0) return -1;
    if (si1145_read_reg(SI1145_REG_ALS_VIS_DATA0, &l0) != 0) return -1;
    if (si1145_read_reg(SI1145_REG_ALS_VIS_DATA1, &l1) != 0) return -1;

    *prox = (uint16_t)((p1 << 8) | p0);
    *light = (uint16_t)((l1 << 8) | l0);
    return 0;
}

static void log_data(uint16_t prox, uint16_t light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Light: %u\n", timestamp, prox, light);
    fflush(log_file);
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox, light;

        if (read_sensor_data(&prox, &light) == 0) {
            log_data(prox, light);
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

