#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_US 100000
#define LED_BLINK_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        return -1;
    }
    return 0;
}

static int log_detection(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int blink_led(void) {
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error turning LED on: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(LED_BLINK_US);
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error turning LED off: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int ret = EXIT_FAILURE;
    int pigpio_initialized = 0;
    int gpio_chip_opened = 0;
    int sensor_line = -1;
    int led_line = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    /*
     * Open the default GPIO chip first (gpiochip0 on Pi 5).
     * If that fails, fall back to the library's default chip name.
     */
    sensor_line = gpioGetLineHandle(0, SENSOR_PIN);
    if (sensor_line < 0) {
        fprintf(stderr, "Failed to get sensor line handle: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpioSetLineFunction(sensor_line, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpioSetPullUpDown(sensor_line, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on sensor line: %s\n", strerror(errno));
        goto cleanup;
    }

    led_line = gpioGetLineHandle(0, LED_PIN);
    if (led_line < 0) {
        fprintf(stderr, "Failed to get LED line handle: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpioSetLineFunction(led_line, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpioWrite(led_line, 0) < 0) {
        fprintf(stderr, "Failed to initialise LED to OFF: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state = 1; /* Assume no object initially (HIGH) */
    int first_detection = 1;

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            break;
        }

        if (level == 0 && last_state == 1 && first_detection) {
            char timestamp[32];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_detection(timestamp) == 0) {
                    if (blink_led() == 0) {
                        printf("Object detected at %s\n", timestamp);
                    }
                }
            } else {
                fprintf(stderr, "Failed to generate timestamp\n");
            }
            first_detection = 0;
        }

        last_state = level;
        gpioDelay(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line >= 0) {
        gpioWrite(led_line, 0);
    }
    if (sensor_line >= 0) {
        gpioSetLineFunction(sensor_line, PI_INPUT);
    }
    if (pigpio_initialized) {
        gpioTerminate();
    }
    printf("Proximity sensor monitoring stopped.\n");
    return ret;
}

