        fprintf(stderr, "Failed to initialise LED to OFF: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state = 1; /* Assume no object initially (HIGH) */
    int first_detection = 1;

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            break;
        }

        if (level == 0 && last_state == 1 && first_detection) {
            char timestamp[32];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_detection(timestamp) == 0) {
                    if (blink_led() == 0) {
                        printf("Object detected at %s\n", timestamp);
                    }
                }
            } else {
                fprintf(stderr, "Failed to generate timestamp\n");
            }
            first_detection = 0;
        }

        last_state = level;
        gpioDelay(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line >= 0) {
        gpioWrite(led_line, 0);
    }
    if (sensor_line >= 0) {
        gpioSetLineFunction(sensor_line, PI_INPUT);
    }
    if (pigpio_initialized) {
        gpioTerminate();
    }
    printf("Proximity sensor monitoring stopped.\n");
    return ret;
}

