#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x1A

#define SI1145_PART_ID 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int si1145_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int si1145_read(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_init(void) {
    uint8_t part_id = 0;
    if (si1145_read(SI1145_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (si1145_write(SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (si1145_write(SI1145_REG_MEAS_RATE0, 0x0A) < 0) return -1;
    return 0;
}

static int si1145_read_proximity(uint16_t *proximity) {
    uint8_t low, high;
    if (si1145_read(SI1145_REG_PS1_DATA0, &low) < 0) return -1;
    if (si1145_read(SI1145_REG_PS1_DATA0 + 1, &high) < 0) return -1;
    *proximity = (uint16_t)((high << 8) | low);
    return 0;
