    while (!terminate) {
        uint16_t proximity = 0, ambient_light = 0;
        if (si1145_read_proximity(&proximity) < 0) {
            fprintf(stderr, "Proximity read error, retrying...\n");
            sleep(1);
            continue;
        }
        if (si1145_read_ambient_light(&ambient_light) < 0) {
            fprintf(stderr, "Ambient light read error, retrying...\n");
            sleep(1);
            continue;
        }
        log_data(proximity, ambient_light);
        sleep(1);
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

