#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define LOG_FILE    "distance_log.txt"
#define WATER_THRESHOLD_CM 15.0f
#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000
#define LOG_INTERVAL_S 60

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
}

static void log_message(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (log_file) {
        fprintf(log_file, "%s: %s\n", ts, msg);
        fflush(log_file);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

static void log_distance(float distance) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (log_file) {
        fprintf(log_file, "%s: Distance: %.2f cm\n", ts, distance);
        fflush(log_file);
    }
    fprintf(stderr, "%s: Distance: %.2f cm\n", ts, distance);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        return -1;
    }
    gpioDelay(50000);
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    trigger_sensor();

    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            return -2.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width / 58.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -3.0f;
    }
    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    log_message("Program started");

    time_t last_log_time = time(NULL);

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            if (distance == -1.0f) {
                log_message("Error: Echo signal timeout (sensor absent or not responding)");
            } else if (distance == -2.0f) {
                log_message("Error: Echo pulse timeout (sensor stuck or out of range)");
            } else {
                log_message("Error: Distance out of valid range");
            }
        } else {
            log_distance(distance);
            if (distance < WATER_THRESHOLD_CM) {
                log_message("Time to water the plant!");
            }
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) >= LOG_INTERVAL_S) {
            last_log_time = current_time;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    log_message("Program exiting");
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

