#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x29
#define GPIO_TRIGGER   17
#define LOG_FILE       "distance_log.txt"
#define POLL_TIMEOUT_MS 100

/* VL53L0X register addresses */
#define REG_IDENTIFICATION_MODEL_ID       0x010F
#define REG_SYSTEM_INTERRUPT_CLEAR        0x0086
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO  0x0084
#define REG_SYSTEM_RANGE_START            0x0000
#define REG_RESULT_INTERRUPT_STATUS       0x0044
#define REG_RESULT_RANGE_STATUS           0x0089
#define REG_RESULT_DISTANCE               0x0096

#define EXPECTED_MODEL_ID                 0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write16 to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t reg_buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg addr) 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read8(int fd, uint16_t reg)
{
    uint8_t buf[1];
    if (i2c_read16(fd, reg, buf, 1) < 0)
        return -1;
    return buf[0];
}

static int i2c_read16_be(int fd, uint16_t reg)
{
    uint8_t buf[2];
    if (i2c_read16(fd, reg, buf, 2) < 0)
        return -1;
    return (buf[0] << 8) | buf[1];
}

static int init_vl53l0x(int fd)
{
    int model_id = i2c_read8(fd, REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Failed to read MODEL_ID (sensor absent or bus error)\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected MODEL_ID: 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (MODEL_ID=0x%02X)\n", model_id);

    /* Clear any pending interrupt */
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Configure GPIO interrupt: falling edge, active low */
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x01) < 0)
        return -1;

    /* Start continuous ranging (0x00 = continuous) */
    if (i2c_write16(fd, REG_SYSTEM_RANGE_START, 0x00) < 0)
        return -1;

    return 0;
}

static int wait_for_data_ready(int fd, int timeout_ms)
{
    for (int i = 0; i < timeout_ms; i++) {
        int status = i2c_read8(fd, REG_RESULT_INTERRUPT_STATUS);
        if (status < 0)
            return -1;
        if (status & 0x01)  /* new sample ready */
            return 0;
        usleep(1000);
    }
    return -1;  /* timeout */
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    if (wait_for_data_ready(fd, POLL_TIMEOUT_MS) < 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    int range_status = i2c_read8(fd, REG_RESULT_RANGE_STATUS);
    if (range_status < 0)
        return -1;
    if ((range_status & 0x1F) != 0x00) {
        fprintf(stderr, "Range status error: 0x%02X\n", range_status);
        return -1;
    }

    int dist = i2c_read16_be(fd, REG_RESULT_DISTANCE);
    if (dist < 0)
        return -1;

    *distance_mm = (uint16_t)dist;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (init_vl53l0x(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Monitoring distance on GPIO %d (BCM). Press Ctrl+C to exit.\n", GPIO_TRIGGER);

    while (g_running) {
        /* Simulate falling-edge trigger by waiting for a falling edge on GPIO 17 */
        /* In a real production system this would be handled by a hardware interrupt */
        /* Here we simply wait for the VL53L0X data-ready interrupt as the trigger */
        /* (the falling edge on GPIO 17 is the sensor's data-ready signal) */
        if (wait_for_data_ready(g_i2c_fd, POLL_TIMEOUT_MS) < 0) {
            fprintf(stderr, "No data ready within timeout\n");
            usleep(100000);
            continue;
        }

        uint16_t distance_mm;
        if (read_distance(g_i2c_fd, &distance_mm) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        log_distance(g_log_fp, distance_mm);
        printf("Distance: %u mm\n", distance_mm);

        /* Clear interrupt so next measurement can be triggered */
        if (i2c_write16(g_i2c_fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt\n");
        }
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

