    while (g_running) {
        /* Simulate falling-edge trigger by waiting for a falling edge on GPIO 17 */
        /* In a real production system this would be handled by a hardware interrupt */
        /* Here we simply wait for the VL53L0X data-ready interrupt as the trigger */
        /* (the falling edge on GPIO 17 is the sensor's data-ready signal) */
        if (wait_for_data_ready(g_i2c_fd, POLL_TIMEOUT_MS) < 0) {
            fprintf(stderr, "No data ready within timeout\n");
            usleep(100000);
            continue;
        }

        uint16_t distance_mm;
        if (read_distance(g_i2c_fd, &distance_mm) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        log_distance(g_log_fp, distance_mm);
        printf("Distance: %u mm\n", distance_mm);

        /* Clear interrupt so next measurement can be triggered */
        if (i2c_write16(g_i2c_fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt\n");
        }
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

