#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x24
#define TRIGGER_REG    0x00
#define DISTANCE_REG   0x02
#define SAMPLE_US      200000   /* 200 ms between samples */
#define TRIGGER_US     50000    /* 50 ms after trigger */
#define LOG_FILE       "distance_log.txt"
#define TIMESTAMP_LEN  32

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void)
{
    char buf[1] = { TRIGGER_REG };
    int rc = i2cWriteDevice(g_i2c_handle, buf, 1);
    if (rc < 0) {
        fprintf(stderr, "Error writing trigger register: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_mm)
{
    char reg = DISTANCE_REG;
    char data[2];
    int rc;

    rc = i2cWriteDevice(g_i2c_handle, &reg, 1);
    if (rc < 0) {
        fprintf(stderr, "Error writing distance register address: %d\n", rc);
        return -1;
    }

    rc = i2cReadDevice(g_i2c_handle, data, 2);
    if (rc < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Short read: got %d bytes, expected 2\n", rc);
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[TIMESTAMP_LEN];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    printf("%s, %u\n", timestamp, distance_mm);
    return 0;
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (trigger_sensor() != 0) {
            gpioDelay(TRIGGER_US);
            continue;
        }

        gpioDelay(TRIGGER_US);

        uint16_t distance_mm;
        if (read_distance(&distance_mm) != 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_distance(distance_mm) != 0) {
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

