static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)((uint8_t)data_buf[0] | ((uint8_t)data_buf[1] << 8));
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t product_id = 0;
    if (i2c_read_reg8(handle, ICU20201_REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "Failed to read product ID\n");
        return -1;
    }
    if (product_id != 0x20) {
        fprintf(stderr, "Unexpected product ID: 0x%02X (expected 0x20)\n", product_id);
        return -1;
    }

    if (i2c_write_reg8(handle, ICU20201_REG_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg8(handle, ICU20201_REG_SYSTEM_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, ICU20201_REG_RANGE_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, ICU20201_REG_AGC_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, ICU20201_REG_PHASE_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, ICU20201_REG_CLOCK_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, ICU20201_REG_GPIO_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, ICU20201_REG_I2C_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, ICU20201_REG_BOOT_CONFIG, 0x01) != 0) return -1;

    return 0;
}

static int read_distance_mm(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    if (i2c_read_reg8(handle, ICU20201_REG_STATUS, &status) != 0) return -1;
    if ((status & 0x01) == 0) {
        return 1;
    }

    if (i2c_read_reg16(handle, ICU20201_REG_DISTANCE_MM, distance_mm) != 0) return -1;
    return 0;
}

static void log_distance(FILE *fp, float distance_cm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", timestamp, distance_cm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n", I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_LED);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance monitoring (threshold %.1f cm)...\n", DISTANCE_THRESHOLD_CM);

    while (running) {
        uint16_t distance_mm = 0;
        int ret = read_distance_mm(i2c_handle, &distance_mm);
        if (ret == 0) {
            float distance_cm = (float)distance_mm / 10.0f;
            log_distance(fp, distance_cm);
            gpioWrite(GPIO_LED, (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0);
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance\n");
            gpioWrite(GPIO_LED, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

