#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

/* Si1182 register addresses */
#define REG_PART_ID 0x00
#define REG_REV_ID 0x01
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x24
#define REG_PS1_DATA1 0x25

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_si1182(void) {
    uint8_t part_id, rev_id;

    if (read_reg(REG_PART_ID, &part_id) < 0) return -1;
    if (read_reg(REG_REV_ID, &rev_id) < 0) return -1;

    printf("Si1182 detected: Part ID=0x%02X, Rev ID=0x%02X\n", part_id, rev_id);

    if (write_reg(REG_HW_KEY, 0x17) < 0) return -1;
    if (write_reg(REG_MEAS_RATE0, 0x0A) < 0) return -1;
    if (write_reg(REG_MEAS_RATE1, 0x00) < 0) return -1;

    return 0;
}

static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    uint8_t prox_l, prox_h, als_l, als_h;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_reg(REG_PS1_DATA0, &prox_l) < 0) { retries++; continue; }
        if (read_reg(REG_PS1_DATA1, &prox_h) < 0) { retries++; continue; }
        if (read_reg(REG_ALS_VIS_DATA0, &als_l) < 0) { retries++; continue; }
        if (read_reg(REG_ALS_VIS_DATA1, &als_h) < 0) { retries++; continue; }

        *proximity = (uint16_t)((prox_h << 8) | prox_l);
        *ambient_light = (uint16_t)((als_h << 8) | als_l);
        return 0;
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t proximity, ambient_light;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialization failed. Check wiring and sensor presence.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Logging data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

