/*
 * ICU-20201 Ultrasonic ToF Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: TDK InvenSense ICU-20201
 * LED:    GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o tof_monitor tof_monitor.c -lgpiod
 * Run:    ./tof_monitor [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- ICU-20201 constants (from datasheet) ---- */
#define I2C_BUS          "/dev/i2c-1"
#define ICU20201_ADDR    0x24
#define WHO_AM_I_REG     0x00
#define WHO_AM_I_VAL     0x20
#define DISTANCE_REG     0x04
#define EXPECTED_LEN     2

/* ---- Defaults ---- */
#define DEFAULT_THRESHOLD 100
#define DEFAULT_LOG_FILE  "tof_log.txt"
#define POLL_MS           50

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[EXPECTED_LEN];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, EXPECTED_LEN) != EXPECTED_LEN) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ICU20201_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICU20201_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    uint16_t who;
    if (i2c_read_reg16(fd, WHO_AM_I_REG, &who) < 0) {
        fprintf(stderr, "Sensor not responding on 0x%02X\n", ICU20201_ADDR);
        close(fd);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who, WHO_AM_I_VAL);
        close(fd);
        return -1;
    }

    g_i2c_fd = fd;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance(uint16_t *distance_mm)
{
    return i2c_read_reg16(g_i2c_fd, DISTANCE_REG, distance_mm);
}

/* ------------------------------------------------------------------ */
static void log_reading(uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(g_log_fp, "%s Distance: %u mm\n", ts, distance_mm);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Threshold must be positive\n");
            return EXIT_FAILURE;
        }
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup (libgpiod) ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fall back to gpiochip0 on older kernels */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, 17);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line 17: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "icu20201_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO 17 as output: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(DEFAULT_LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", DEFAULT_LOG_FILE,
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring ICU-20201 (addr 0x%02X) on %s. "
           "Threshold: %d mm. Press Ctrl+C to exit.\n",
           ICU20201_ADDR, I2C_BUS, threshold);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t dist;

        if (read_distance(&dist) < 0) {
            /* Bus error: turn LED off for safety, keep running */
            gpiod_line_set_value(g_led, 0);
            usleep(POLL_MS * 1000);
            continue;
        }

        if (dist < threshold) {
            gpiod_line_set_value(g_led, 1);
        } else {
            gpiod_line_set_value(g_led, 0);
        }

        log_reading(dist);
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

