#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x50
#define LOG_FILE       "intrusion_log.txt"
#define DISTANCE_THRESHOLD 1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_US 100000
#define MEAS_DELAY_US  10000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int request_measurement(int fd)
{
    uint8_t cmd[4] = {0x01, 0x02, 0x03, 0x04};
    return i2c_write_cmd(fd, cmd, sizeof(cmd));
}

static int read_distance(int fd, uint16_t *distance)
{
    uint8_t buf[15];
    if (i2c_read_data(fd, buf, sizeof(buf)) != 0)
        return -1;

    if (buf[0] != 0x01) {
        fprintf(stderr, "Unexpected header byte: 0x%02X\n", buf[0]);
        return -1;
    }

    *distance = ((uint16_t)buf[11] << 8) | buf[12];
    return 0;
}

static double calculate_average_distance(int fd)
{
    double sum = 0.0;
    int valid = 0;

