#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x24
#define DIST_REG       0x00
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;

    if (install_signal_handlers() != 0)
        return 1;

    fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        return 1;

    printf("MLX75030 sensor initialized on %s (addr 0x%02X).\n", I2C_BUS, MLX75030_ADDR);
    fflush(stdout);

    while (g_running) {
        uint8_t dist = 0;
        if (i2c_read_reg8(fd, DIST_REG, &dist) == 0) {
            printf("Distance: %u mm\n", dist);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }
        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    if (fd >= 0)
        close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

