/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W
 *
 * Reads distance and ambient light data from the OPT3101 on I2C bus 1
 * every 500 ms, logging to stdout.  Handles I2C errors and SIGINT
 * gracefully.
 *
 * Wiring:
 *   OPT3101 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   OPT3101 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   OPT3101 VDD  -> 3.3 V
 *   OPT3101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3101_reader opt3101_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3101 I2C address (7-bit) ---- */
#define OPT3101_ADDR 0x29

/* ---- OPT3101 register addresses ---- */
#define REG_RESULT_DISTANCE 0x00
#define REG_RESULT_AMBIENT  0x02
#define REG_ERROR_FLAGS     0x04
#define REG_SYSTEM_CONFIG   0x08
#define REG_SYSTEM_STATUS   0x0A
#define REG_SYSTEM_RESET    0x0B

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (big-endian on the bus).  */
static int opt3101_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register (big-endian on the bus). */
static int opt3101_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register. */
static int opt3101_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[1];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint8_t)data[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the OPT3101 and wait for the device to acknowledge. */
static int opt3101_reset(int handle)
{
    if (opt3101_write_reg16(handle, REG_SYSTEM_RESET, 0x0001) != 0)
        return -1;

    /* Allow the device to reset and re-initialise. */
    gpioDelay(10000); /* 10 ms */

    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (opt3101_read_reg8(handle, REG_SYSTEM_STATUS, &status) != 0)
            return -1;
        if ((status & 0x01) == 0) /* STATUS_BUSY cleared */
            return 0;
        gpioDelay(5000); /* 5 ms */
    }

    fprintf(stderr, "OPT3101 reset timed out (status=0x%02X)\n", status);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialise the OPT3101: reset, verify address, configure channels. */
static int opt3101_init(int handle)
{
    if (opt3101_reset(handle) != 0) {
        fprintf(stderr, "OPT3101 reset failed\n");
        return -1;
    }

    /* Verify the device is present by reading the system status. */
    uint8_t status = 0;
    if (opt3101_read_reg8(handle, REG_SYSTEM_STATUS, &status) != 0) {
        fprintf(stderr, "OPT3101 not responding on address 0x%02X\n",
                OPT3101_ADDR);
        return -1;
    }

    /* Configure channel 0: enable distance and ambient measurements. */
    if (opt3101_write_reg16(handle, REG_SYSTEM_CONFIG, 0x0001) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialise pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the OPT3101 address. */
    g_i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n",
                OPT3101_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor. */
    if (opt3101_init(g_i2c_handle) != 0) {
        fprintf(stderr, "OPT3101 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3101 initialised. Reading every 500 ms (Ctrl-C to exit).\n");

    /* Main loop: read and log every 500 ms. */
    while (g_running) {
        uint16_t distance = 0;
        uint16_t ambient  = 0;
        uint8_t  error_flags = 0;

        if (opt3101_read_reg16(g_i2c_handle, REG_RESULT_DISTANCE, &distance) != 0 ||
            opt3101_read_reg16(g_i2c_handle, REG_RESULT_AMBIENT,  &ambient)  != 0 ||
            opt3101_read_reg8(g_i2c_handle, REG_ERROR_FLAGS, &error_flags)  != 0) {
            fprintf(stderr, "Read error; continuing after 500 ms.\n");
        } else {
            printf("Distance: %u, Ambient: %u, Error Flags: 0x%02X\n",
                   distance, ambient, error_flags);
        }

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

