    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register. */
static int opt3101_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[1];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint8_t)data[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the OPT3101 and wait for the device to acknowledge. */
static int opt3101_reset(int handle)
{
    if (opt3101_write_reg16(handle, REG_SYSTEM_RESET, 0x0001) != 0)
        return -1;

    /* Allow the device to reset and re-initialise. */
    gpioDelay(10000); /* 10 ms */

    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (opt3101_read_reg8(handle, REG_SYSTEM_STATUS, &status) != 0)
            return -1;
        if ((status & 0x01) == 0) /* STATUS_BUSY cleared */
            return 0;
        gpioDelay(5000); /* 5 ms */
    }

    fprintf(stderr, "OPT3101 reset timed out (status=0x%02X)\n", status);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialise the OPT3101: reset, verify address, configure channels. */
static int opt3101_init(int handle)
{
    if (opt3101_reset(handle) != 0) {
        fprintf(stderr, "OPT3101 reset failed\n");
        return -1;
    }

    /* Verify the device is present by reading the system status. */
    uint8_t status = 0;
    if (opt3101_read_reg8(handle, REG_SYSTEM_STATUS, &status) != 0) {
        fprintf(stderr, "OPT3101 not responding on address 0x%02X\n",
                OPT3101_ADDR);
        return -1;
    }

    /* Configure channel 0: enable distance and ambient measurements. */
    if (opt3101_write_reg16(handle, REG_SYSTEM_CONFIG, 0x0001) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialise pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the OPT3101 address. */
    g_i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n",
                OPT3101_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor. */
    if (opt3101_init(g_i2c_handle) != 0) {
        fprintf(stderr, "OPT3101 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3101 initialised. Reading every 500 ms (Ctrl-C to exit).\n");

    /* Main loop: read and log every 500 ms. */
    while (g_running) {
        uint16_t distance = 0;
        uint16_t ambient  = 0;
        uint8_t  error_flags = 0;

        if (opt3101_read_reg16(g_i2c_handle, REG_RESULT_DISTANCE, &distance) != 0 ||
            opt3101_read_reg16(g_i2c_handle, REG_RESULT_AMBIENT,  &ambient)  != 0 ||
            opt3101_read_reg8(g_i2c_handle, REG_ERROR_FLAGS, &error_flags)  != 0) {
            fprintf(stderr, "Read error; continuing after 500 ms.\n");
        } else {
            printf("Distance: %u, Ambient: %u, Error Flags: 0x%02X\n",
                   distance, ambient, error_flags);
        }

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * HC-SR04 ultrasonic distance reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VCC  -> 5 V (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO17 (BCM 17, pin 11)
 *   ECHO -> GPIO18 (BCM 18, pin 12)  [via 1 kOhm resistor]
 *
 * The HC-SR04 operates at 5 V; the Pi GPIO is only 3.3 V tolerant.
 * A 1 kOhm resistor must be placed between the HC-SR04 ECHO pin and
 * the Pi GPIO18 pin within the libgpiod API call() that drives the
 * line, to ensure the HC-SR04 sees a valid 5 V supply and the Pi
 * input is clamped to a safe 3.3 V level.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN    17
#define ECHO_PIN       18
#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   200000   /* 200 ms max echo wait */
#define MAX_PULSE_US      38000    /* 38 ms = ~2 m, HC-SR04 max range */
#define SAMPLE_PERIOD_S   1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/*
 * Issue a 10 us trigger pulse on the trigger line.
 * Returns 0 on success, -1 on error.
 */
static int trigger_sensor(struct gpiod_line *trig)
{
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig high)");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig low)");
        return -1;
    }
    return 0;
}

/*
 * Wait for the echo line to reach the requested level with a timeout.
 * Returns 0 on success, -1 on timeout or error.
 */
static int wait_for_level(struct gpiod_line *echo, int level, uint32_t timeout_us)
{
    uint32_t elapsed = 0;
    while (elapsed < timeout_us) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            return -1;
        }
        if (val == level)
            return 0;
        usleep(10);
        elapsed += 10;
    }
    return -1;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in microseconds, or -1 on error/timeout.
 */
static long measure_pulse(struct gpiod_line *echo)
{
    if (wait_for_level(echo, 1, ECHO_TIMEOUT_US) < 0)
        return -1;

    uint32_t start = (uint32_t)gpiod_line_get_value(echo);
    if (start == 0) {
        /* Should not happen, but guard anyway */
        return -1;
    }

    uint32_t elapsed = 0;
    while (elapsed < ECHO_TIMEOUT_US) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            return -1;
        }
        if (val == 0) {
            uint32_t end = elapsed + 10;
            return (long)end;
        }
        usleep(10);
        elapsed += 10;
    }
    return -1;
}

/*
 * Convert pulse width (microseconds) to distance (cm).
 * Speed of sound ~343 m/s = 0.0343 cm/us.
 * HC-SR04 rounds to 0.5 cm resolution.
 */
static float pulse_to_cm(long pulse_us)
{
    return (float)pulse_us * 0.0343f / 2.0f;
}

int main(void)
{
    install_signal_handlers();

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trig)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_sensor(trig) < 0)
            break;

        long pulse = measure_pulse(echo);
        if (pulse < 0) {
            fprintf(stderr, "Error: echo pulse measurement failed or timed out.\n");
            break;
        }

        if (pulse <= 0 || pulse > MAX_PULSE_US) {
            fprintf(stderr, "Warning: invalid pulse width %ld us (out of range).\n", pulse);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float distance = pulse_to_cm(pulse);

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        if (t)
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        else
            snprintf(ts, sizeof(ts), "unknown-time");

        printf("[%s] Distance: %.2f cm (pulse: %ld us)\n", ts, distance, pulse);
        fflush(stdout);

        sleep(SAMPLE_PERIOD_S);
    }

cleanup:
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

