#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_PORT "/dev/serial0"
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define LOG_FILE "intrusion_log.csv"
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define NUM_DISTANCE_BINS 64
#define ALERT_DURATION_MS 2000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(int fd, uint8_t *magic) {
    uint8_t byte;
    int idx = 0;
    while (running) {
        ssize_t n = read(fd, &byte, 1);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        if (byte == magic[idx]) {
            magic[idx] = byte;
            idx++;
            if (idx == MAGIC_WORD_SIZE) return 0;
        } else {
            idx = 0;
            magic[0] = byte;
        }
    }
    return -1;
}

static int read_range_profile(int fd, uint8_t *profile) {
    return read_exact(fd, profile, RANGE_PROFILE_SIZE);
}

static int decode_range_profile(const uint8_t *profile, float *distances) {
    for (int i = 0; i < NUM_DISTANCE_BINS; i++) {
        uint16_t raw = (uint16_t)profile[i * 2] | ((uint16_t)profile[i * 2 + 1] << 8);
        distances[i] = (float)raw / 100.0f;
    }
    return 0;
}

static int is_target_detected(const float *distances, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (distances[i] <= threshold) return 1;
    }
    return 0;
}

static int log_intrusion(FILE *fp, float distance) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void trigger_alert(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error turning on LED: %s\n", strerror(errno));
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error turning off LED: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", GPIO_LED, strerror(errno));
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_PORT);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t magic[MAGIC_WORD_SIZE] = {0};
    uint8_t profile[RANGE_PROFILE_SIZE];
    float distances[NUM_DISTANCE_BINS];

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (find_magic_word(uart_fd, magic) < 0) {
            fprintf(stderr, "Error finding magic word or sensor absent.\n");
            break;
        }

        if (read_range_profile(uart_fd, profile) < 0) {
            fprintf(stderr, "Error reading range profile.\n");
            break;
        }

        decode_range_profile(profile, distances);

        if (is_target_detected(distances, NUM_DISTANCE_BINS, DISTANCE_THRESHOLD)) {
            float min_distance = 1e9f;
            for (int i = 0; i < NUM_DISTANCE_BINS; i++) {
                if (distances[i] <= DISTANCE_THRESHOLD && distances[i] < min_distance) {
                    min_distance = distances[i];
                }
