/*
 * Parking assistance system using STMicroelectronics VL53L1X ToF sensor.
 *
 * Board : Raspberry Pi 3 Model B+
 * Bus   : I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: VL53L1X on I2C address 0x29
 * Log   : distance_log.csv  (timestamp,distance_mm)
 *
 * Build: gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lpigpio -lrt
 * Run  : sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"
#define POLL_DELAY_US  100000          /* 100 ms */
#define STOP_THRESHOLD 300             /* mm */
#define SLOW_THRESHOLD 600             /* mm */
#define CLEAR_THRESHOLD 1200           /* mm */

/* ---- VL53L1X register map (16-bit addresses, big-endian on the bus) ---- */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_START              0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS       0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0 0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR    0x0086

#define VL53L1X_MODEL_ID_EXPECTED             0xEA

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit VL53L1X register address.                 */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit VL53L1X register address.                */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    char data[1];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(addr reg=0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }
    *out = (uint8_t)data[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from a 16-bit VL53L1X register.       */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16_be(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(addr reg=0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor.                                       */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    if (vl53l1x_read_reg8(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Start continuous ranging mode. */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_START, 0x00) != 0)
        return -1;
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single distance measurement in millimetres.                  */
/* Returns 0 on success and stores distance in *out; -1 on error.      */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *out)
{
    uint8_t  status = 0;
    uint16_t dist  = 0;

    if (vl53l1x_read_reg8(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;
    if (status == 0x01) {
        /* Data not ready yet. */
        return 1;
    }
    if (status != 0x00) {
        fprintf(stderr, "[WARN] Range status 0x%02X (non-zero)\n", status);
        return -1;
    }

    if (vl53l1x_read_reg16_be(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0, &dist) != 0)
        return -1;

    *out = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the CSV log.               */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", ts, (unsigned)distance_mm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush log failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void print_guidance(uint16_t distance_mm)
{
    if (distance_mm < STOP_THRESHOLD)
        printf("PARKING GUIDANCE: STOP\n");
    else if (distance_mm < SLOW_THRESHOLD)
        printf("PARKING GUIDANCE: APPROACH\n");
    else if (distance_mm < CLEAR_THRESHOLD)
        printf("PARKING GUIDANCE: SLOW\n");
    else
        printf("PARKING GUIDANCE: CLEAR\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file; write header only if the file does not yet exist. */
    int file_exists = (access(LOG_FILE, F_OK) == 0);
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        if (fprintf(g_log_file, "timestamp,distance_mm\n") < 0 || fflush(g_log_file) != 0) {
            perror("[ERROR] writing CSV header");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Parking assistance started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        uint16_t distance = 0;
        int      rc       = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            if (log_distance(g_log_file, distance) != 0)
                fprintf(stderr, "[WARN] Logging failed for this sample\n");
            print_guidance(distance);
        } else if (rc < 0) {
            fprintf(stderr, "[ERROR] Sensor read failure; continuing\n");
        }
        /* rc == 1 means data not ready — just wait and retry. */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

