 *   gcc -O2 -Wall -Wextra -o ch201_led ch201_led.c -lgpiod
 *
 * The CH201 exposes a register map over I2C.  This program reads the
 * distance register (0x00) and maps the raw value to a distance in mm.
 * The LED blink frequency is proportional to the inverse of the distance
 * (closer → faster blink).  Each iteration performs one half-cycle of the
 * blink so the LED stays smooth across samples.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS_NAME      "i2c-1"
#define I2C_ADDR          0x29          /* CH201 default 7-bit address */
#define DISTANCE_REG      0x00          /* Raw distance register */
#define LED_PIN           18            /* BCM 18 */
#define LED_CONSUMER      "ch201-led"
#define SAMPLE_PERIOD_MS  100
#define I2C_RETRIES       3
#define I2C_RETRY_DELAY_MS 10
#define MIN_DISTANCE_MM   100           /* Valid min range (mm) */
#define MAX_DISTANCE_MM   4000          /* Valid max range (mm) */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int                   g_i2c_fd = -1;
static struct gpiod_chip    *g_chip   = NULL;
static struct gpiod_line    *g_led    = NULL;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------- I2C helpers ----------------------------- */

/*
 * Read a 16-bit little-endian register from the CH201.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int ch201_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "[I2C] write reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "[I2C] read reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }

    return -1;
}

/*
 * Read distance in mm from the CH201.
 * Returns 0 on success and stores the distance in *out; -1 on failure.
 */
static int ch201_read_distance(int fd, uint16_t *out)
{
    return ch201_read_reg16(fd, DISTANCE_REG, out);
}

/* ------------------------------- GPIO helpers ---------------------------- */

static int led_init(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fall back to gpiochip0 on older kernels */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "[GPIO] open chip failed: %s\n", strerror(errno));
        return -1;
    }

    g_led = gpiod_chip_get_line(g_chip, LED_PIN);
    if (!g_led) {
        fprintf(stderr, "[GPIO] get line %d failed: %s\n", LED_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(g_led, LED_CONSUMER, 0) < 0) {
        fprintf(stderr, "[GPIO] request output failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void led_set(int value)
{
    if (g_led)
        gpiod_line_set_value(g_led, value);
}

static void led_cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------- Main loop -------------------------------- */

int main(void)
{
    uint16_t distance_mm = 0;
    int      led_state   = 0;          /* 0 = off, 1 = on */
    int      led_half    = 0;          /* 0 = next half-cycle on, 1 = off */
    int      led_period  = 1000;       /* ms per full blink cycle */
    int      led_half_ms = led_period / 2;

    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_NAME, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[I2C] open %s failed: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "[I2C] ioctl I2C_SLAVE 0x%02X failed: %s\n",
                I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize LED */
    if (led_init() < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("CH201 ultrasonic ToF reader started.  I2C addr 0x%02X, LED on GPIO %d.\n",
           I2C_ADDR, LED_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (ch201_read_distance(g_i2c_fd, &distance_mm) < 0) {
            fprintf(stderr, "[I2C] sensor read failed – continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if (distance_mm < MIN_DISTANCE_MM || distance_mm > MAX_DISTANCE_MM) {
            fprintf(stderr, "[WARN] distance out of range: %u mm – skipping.\n",
                    distance_mm);
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        /* Map distance to blink period: closer → faster → shorter period */
        led_period = (int)(1000.0f - (float)distance_mm * 0.25f);
        if (led_period < 10) led_period = 10;
        if (led_period > 1000) led_period = 1000;

        led_half_ms = led_period / 2;

        /* One half-cycle of the LED blink */
        led_set(led_state);
        led_state = !led_state;

