        while (g_running && elapsed < SAMPLE_PERIOD_MS) {
            int remaining = SAMPLE_PERIOD_MS - elapsed;
            usleep((useconds_t)remaining * 1000);
            elapsed = SAMPLE_PERIOD_MS;
        }
    }

    /* --------------------------- Graceful shutdown ------------------------ */
    printf("\nShutting down...\n");

    led_cleanup();

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Done.\n");
    return EXIT_SUCCESS;
}

