#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x28
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, int *distance_cm) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByte(handle, 0x01);
        if (result < 0) {
            fprintf(stderr, "Error: I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            gpioDelay(1000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            *distance_cm = (buf[0] << 8) | buf[1];
            return 0;
        }

        fprintf(stderr, "Error: I2C read failed (attempt %d): %s\n", attempt + 1, strerror(errno));
        gpioDelay(1000);
    }

    return -1;
}

static int log_data(const char *filename, int distance_cm) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d\n", timestamp, distance_cm);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d: %s\n",
                MLX75030_ADDR, I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not set signal handlers: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (running) {
        int distance_cm = -1;

        if (read_distance(i2c_handle, &distance_cm) == 0) {
            if (log_data(LOG_FILE, distance_cm) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

