/*
 * VL53L4CX distance reader for Raspberry Pi Zero W
 * I2C bus 1, interrupt-driven distance polling every 500 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l4cx_reader vl53l4cx_reader.c
 * Run:    ./vl53l4cx_reader
 *
 * NOTE: The VL53L4CX is a time-of-flight sensor that requires a dedicated
 *       microcontroller (e.g., ST's VL53L4CX breakout) to drive the I2C
 *       interface and manage the sensor's internal state machine.  This
 *       program assumes the sensor is already configured and ready to
 *       report distance measurements on the I2C bus.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- VL53L4CX register definitions (I2C address 0x29) ---- */
#define VL53L4CX_I2C_ADDR          0x29

#define VL53L4CX_REG_SYSTEM_STATUS 0x000B
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_DISTANCE  0x0096
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0046
#define VL53L4CX_REG_SYSTEM_INTERRUPT_MODE_GPIO 0x0044
#define VL53L4CX_REG_SYSTEM_INTERRUPT_POLARITY_GPIO 0x0045
#define VL53L4CX_REG_SYSTEM_INTERRUPT_THRESHOLD 0x0047
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086

/* ---- Application constants ---- */
#define I2C_BUS              1
#define POLL_INTERVAL_US     500000   /* 500 ms */
#define MAX_POLL_ATTEMPTS    100      /* ~50 s worst-case timeout */
#define MAX_RETRIES          3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "i2cReadDevice(reg=0x%04X, len=%u) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    /*
     * The VL53L4CX requires a dedicated microcontroller to drive its
     * I2C interface and manage the sensor's internal state machine.
     * This program assumes the sensor is already configured and ready
     * to report distance measurements.
     *
     * If you are using an ST STU31 breakout, the sensor is pre-configured
     * and ready to report on the I2C bus.
     */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance reading                                                   */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status_buf[2];
    uint8_t data_buf[2];

    /* Poll the interrupt status register for a new measurement */
    if (i2c_read_reg16(handle, VL53L4CX_REG_SYSTEM_STATUS, status_buf, 2) != 0)
        return -1;

    uint16_t status = ((uint16_t)status_buf[0] << 8) | status_buf[1];

    if ((status & 0x01) == 0) {
        /* No new data available yet */
        return 1;
    }

    /* Read the 16-bit distance result */
    if (i2c_read_reg16(handle, VL53L4CX_REG_RESULT_DISTANCE, data_buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)data_buf[0] << 8) | data_buf[1];

    /* Clear the interrupt so the next measurement can be reported */
    if (i2c_write_reg16(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "Timestamp: UNKNOWN");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    snprintf(buf, len, "Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld",
             tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
             tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
             ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t distance_mm;
    char timestamp[40];
    int consecutive_errors = 0;

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, VL53L4CX_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l4cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L4CX distance reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int rc = vl53l4cx_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            printf("%s, Distance: %u mm\n", timestamp, distance_mm);
            fflush(stdout);
            consecutive_errors = 0;
        } else if (rc == 1) {
            /* No new data yet — normal condition, skip this cycle */
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading distance (consecutive: %d)\n",
                    consecutive_errors);

            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive errors reached. Aborting.\n");
                break;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

