#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 500000

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_VHV_CONFIG 0x0001
#define VL53L1X_REG_PHASECAL_CONFIG 0x0002
#define VL53L1X_REG_SYSTEM_MODE 0x0000
#define VL53L1X_REG_RANGE_CONFIG 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = ((uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_VHV_CONFIG, 0x0000) < 0) return -1;
    if (vl53l1x_write16(handle, VL53L1X_REG_PHASECAL_CONFIG, 0x0000) < 0) return -1;
