#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_ANGLE        -90.0f
#define MAX_ANGLE        90.0f
#define TIMEOUT_US       50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    200000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_distance(float distance)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        perror("fopen(sensor_data.log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    }
    fclose(fp);
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        return -1;
    }
    return 0;
}

static float get_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1.0f;
    }

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width / 58.0f;
    return distance;
}

static float map_distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    float angle = MIN_ANGLE + (distance - MIN_DISTANCE_CM) *
                  (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return angle;
}

static int set_servo_angle(float angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulse_width = (int)(angle + 90.0f) * 1000 / 180;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void)
{
    gpioServo(SERVO_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    while (g_running) {
        float distance = get_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read failed, skipping cycle\n");
        } else {
            float angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Servo set failed\n");
            } else {
                log_distance(distance);
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup_gpio();
    return 0;
}

