/*
 * Parking sensor with HC-SR04 ultrasonic sensor and buzzer alarm.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring (BCM numbering):
 *   GPIO 17 -> HC-SR04 TRIG
 *   GPIO 27 -> HC-SR04 ECHO
 *   GPIO 22 -> Buzzer
 *
 * Build:  gcc -Wall -Wextra -O2 -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:    sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define DISTANCE_THRESHOLD_CM  30.0f
#define MIN_VALID_DISTANCE_CM  2.0f
#define MAX_VALID_DISTANCE_CM  400.0f

#define TRIGGER_PULSE_US      10          /* HC-SR04 requires >= 10 us HIGH   */
#define ECHO_TIMEOUT_US       30000       /* 30 ms max echo wait               */
#define LOOP_DELAY_US         100000      /* 100 ms between measurements       */
#define BUZZER_ON_DELAY_US    100000      /* 100 ms buzzer on/off cycle        */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* Echo measurement state (accessed from both main and ISR contexts) */
static volatile uint32_t g_echo_start_tick = 0;
static volatile uint32_t g_echo_end_tick   = 0;
static volatile bool     g_echo_received    = false;
static volatile bool     g_echo_timeout     = false;

/* --------------------------- Function prototypes ------------------------- */

static void signal_handler(int sig);
static void echo_callback(int gpio, int level, uint32_t tick);
static void trigger_sensor(void);
static float measure_distance_cm(void);
static void control_buzzer(float distance_cm);
static void cleanup(void);

/* ------------------------------- Signal handler -------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Echo ISR (level 0) -------------------------- */

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_echo_start_tick = tick;
        g_echo_received   = false;
        g_echo_timeout    = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_echo_end_tick   = tick;
        g_echo_received   = true;
    }
    /* level == 2 indicates a watchdog timeout; pigpio reports it here */
    if (level == 2) {
        g_echo_timeout = true;
    }
}

/* --------------------------- Trigger sensor ------------------------------ */

static void trigger_sensor(void)
{
    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(TRIGGER, 0) failed\n");
        return;
    }
    gpioDelay(5);                       /* settle */

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);        /* 10 us HIGH pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(TRIGGER, 0) failed\n");
    }
}

/* ------------------------- Measure distance (cm) ------------------------- */

static float measure_distance_cm(void)
{
    g_echo_received   = false;
    g_echo_timeout    = false;
    g_echo_start_tick = 0;
    g_echo_end_tick   = 0;

    trigger_sensor();

    /* Wait for echo with timeout */
    uint32_t elapsed = 0;
    while (!g_echo_received && !g_echo_timeout) {
        gpioDelay(100);                 /* 100 us poll interval */
        elapsed += 100;
        if (elapsed >= ECHO_TIMEOUT_US) {
            g_echo_timeout = true;
            break;
        }
    }

    if (g_echo_timeout) {
        fprintf(stderr, "Error: echo timeout (sensor absent or not responding)\n");
        return -1.0f;
    }
    if (!g_echo_received) {
        fprintf(stderr, "Error: echo not received (sensor absent or wiring fault)\n");
        return -1.0f;
    }

    /*
     * pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min.
     * Handle the 32-bit wraparound correctly.
     */
    uint32_t diff = g_echo_end_tick - g_echo_start_tick;

    /* Speed of sound ~343 m/s => 34300 cm/s; round-trip time in us */
    float distance_cm = (float)diff / 58.0f;

    if (distance_cm < MIN_VALID_DISTANCE_CM || distance_cm > MAX_VALID_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f-%.0f]\n",
                distance_cm, MIN_VALID_DISTANCE_CM, MAX_VALID_DISTANCE_CM);
        return -1.0f;
    }

    return distance_cm;
}

/* --------------------------- Buzzer control ------------------------------ */

static void control_buzzer(float distance_cm)
{
    if (distance_cm < DISTANCE_THRESHOLD_CM) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            fprintf(stderr, "Warning: gpioWrite(BUZZER, 1) failed\n");
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite(BUZZER, 0) failed\n");
        }
    }
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Ensure buzzer is off */
    gpioWrite(BUZZER_PIN, 0);

    /* Deregister ISR */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL) != 0) {
        fprintf(stderr, "Warning: gpioSetISRFuncEx deregister failed\n");
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Fatal: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Fatal: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Fatal: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Fatal: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register ISR on echo pin (both edges) */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Fatal: gpioSetISRFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor running. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | Buzzer: GPIO %d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.0f cm | Loop: %d ms\n\n",
           DISTANCE_THRESHOLD_CM, LOOP_DELAY_US / 1000);

    /* Main measurement loop */
    while (g_running) {
        float distance = measure_distance_cm();

        if (distance < 0.0f) {
            /* Sensor error: turn buzzer off for safety */
            gpioWrite(BUZZER_PIN, 0);
        } else {
            control_buzzer(distance);
            printf("Distance: %.2f cm\n", distance);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

