/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TRIG -> GPIO23 (physical pin 16, BCM)
 *   ECHO -> GPIO24 (physical pin 18, BCM)  [NOTE: HC-SR04 ECHO is 5 V;
 *                                            use a voltage divider or
 *                                            logic-level converter so
 *                                            the Pi's 3.3 V GPIO are not
 *                                            overdriven.]
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 *
 * Run:    ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_PIN    23
#define ECHO_PIN    24

#define TRIG_PULSE_US   10
#define SAMPLE_PERIOD_US 200000   /* 5 Hz */
#define ECHO_TIMEOUT_US  60000    /* 60 ms */
#define MIN_PULSE_US     100
#define MAX_PULSE_US     30000
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Monotonic microseconds; handles 32-bit tick wraparound (~72 min). */
static unsigned long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (unsigned long long)ts.tv_sec * 1000000ULL
         + (unsigned long long)ts.tv_nsec / 1000ULL;
}

static void log_distance(FILE *fp, double distance)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    printf("%s Distance: %.2f cm\n", ts, distance);
    if (fp) {
        fprintf(fp, "%s Distance: %.2f cm\n", ts, distance);
        fflush(fp);
    }
}

static void echo_alert(struct gpiod_line *line, unsigned int ts,
                       const struct gpiod_line_event *event)
{
    static unsigned long long rising_tick = 0;
    static int have_rising = 0;

    if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        rising_tick = now_us();
        have_rising = 1;
    } else if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (!have_rising) {
            /* Spurious falling edge with no rising edge yet. */
            return;
        }
        unsigned long long dur = ts - rising_tick; /* handles wraparound */
        if (dur >= MIN_PULSE_US && dur <= MAX_PULSE_US) {
            double dist = (double)dur * 34300.0 / 2000000.0;
            log_distance(NULL, dist);
        } else {
            fprintf(stderr,
                    "Warning: pulse %llu us out of range [100, 30000] us\n",
                    (unsigned long long)dur);
        }
        have_rising = 0;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the first chip found (RPi 4/5). */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(TRIG)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(ECHO)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(TRIG)");
        goto cleanup;
    }

    if (gpiod_line_request_both_edges_events(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_both_edges_events(ECHO)");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(TRIG high)");
            break;
        }
        usleep(TRIG_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(TRIG low)");
            break;
        }

        unsigned long long start = now_us();
        unsigned long long last_seen = start;

        while (g_running) {
            unsigned long long now = now_us();
            if (now - last_seen > ECHO_TIMEOUT_US) {
                fprintf(stderr,
                        "Warning: echo timeout (%llu us > %d us)\n",
                        (unsigned long long)(now - start),
                        ECHO_TIMEOUT_US);
                break;
            }
            last_seen = now;

            struct gpiod_line_event ev;
            int rc = gpiod_line_event_wait(echo, NULL); /* poll */
            if (rc < 0) {
                if (errno == EINTR) continue;
                perror("gpiod_line_event_wait");
                break;
            }
            if (rc == 0) continue; /* timeout (should not happen with NULL) */

            if (gpiod_line_event_read(echo, &ev) < 0) {
                if (errno == EINTR) continue;
                perror("gpiod_line_event_read");
                break;
            }
            echo_alert(echo, ev.ts.tv_sec * 1000000ULL
                        + ev.ts.tv_nsec / 1000ULL, &ev);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (trig) {
        gpiod_line_release(trig);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

