#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_MODEL_ID 0xEA

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != len) return -1;
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read model ID from VL53L1X.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: Incorrect model ID 0x%02X (expected 0x%02X). Sensor not present or wrong device.\n", model_id, VL53L1X_MODEL_ID);
        return -1;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set VL53L1X to standby mode.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    uint8_t status = 0;
    int timeout = 100;
    do {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
