            return -1;
        }
        gpioDelay(1000);
        timeout--;
    } while ((status & 0x01) == 0 && timeout > 0);
    if (timeout == 0) {
        fprintf(stderr, "Error: Ranging timeout.\n");
        return -1;
    }
    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }
    *distance = (dist_buf[0] << 8) | dist_buf[1];
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "Warning: Failed to stop ranging.\n");
    }
    return 0;
}

static void control_servo(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = 1000 + (int)(angle * 1000.0 / 180.0);
    gpioServo(SERVO_PIN, pulse_width);
