    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioSetPullUpDown(INT_PIN, PI_PUD_DOWN);
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int gate_state = 0;
    int distance = 0;
    while (running) {
        if (gpioRead(INT_PIN) == 1) {
            gpioDelay(10000);
            if (gpioRead(INT_PIN) == 1) {
                if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
                    if (distance > 0 && distance < 1000) {
                        if (distance < DISTANCE_THRESHOLD && gate_state == 0) {
                            control_servo(90);
                            gate_state = 1;
                            log_event(distance, gate_state);
                        } else if (distance > DISTANCE_HYSTERESIS && gate_state == 1) {
                            control_servo(0);
                            gate_state = 0;
                            log_event(distance, gate_state);
                        }
                    }
                }
            }
        }
        gpioDelay(100000);
    }
    control_servo(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

