#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "gate_events.log"
#define POLL_INTERVAL_US 500000

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE 0x0000
#define VL53L1X_REG_RANGE_START 0x0000
#define VL53L1X_REG_RESULT_DISTANCE 0x0014
#define VL53L1X_REG_RESULT_STATUS 0x001E

#define VL53L1X_SYSTEM_MODE_SINGLE 0x00
#define VL53L1X_SYSTEM_MODE_STOP 0x01
#define VL53L1X_SYSTEM_MODE_START 0x02

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s %s\n", ts, event);
    fflush(log_file);
}

static int vl53l1x_write16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE, VL53L1X_SYSTEM_MODE_STOP) < 0) return -1;
    return 0;
}

static int vl53l1x_start_ranging(int handle) {
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE, VL53L1X_SYSTEM_MODE_START) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_stop_ranging(int handle) {
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE, VL53L1X_SYSTEM_MODE_STOP) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint16_t status = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_STATUS, &status) < 0) return -1;
    if ((status & 0x01) == 0) return 1;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, distance) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        vl53l1x_stop_ranging(i2c_handle);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing VL53L1X sensor\n");
        cleanup();
        return 1;
    }

    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_open = 0;

    while (!terminate) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);
        if (ret == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                if (!gate_open) {
                    gpioWrite(GPIO_OPEN, 1);
                    gpioWrite(GPIO_CLOSE, 0);
                    gate_open = 1;
                    log_event("Gate opened");
                }
            } else {
                if (gate_open) {
                    gpioWrite(GPIO_OPEN, 0);
                    gpioWrite(GPIO_CLOSE, 1);
                    gate_open = 0;
                    log_event("Gate closed");
                }
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance\n");
            log_event("Error reading distance");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

