    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing VL53L1X sensor\n");
        cleanup();
        return 1;
    }

    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_open = 0;

    while (!terminate) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);
        if (ret == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                if (!gate_open) {
                    gpioWrite(GPIO_OPEN, 1);
                    gpioWrite(GPIO_CLOSE, 0);
                    gate_open = 1;
                    log_event("Gate opened");
                }
            } else {
                if (gate_open) {
                    gpioWrite(GPIO_OPEN, 0);
                    gpioWrite(GPIO_CLOSE, 1);
                    gate_open = 0;
                    log_event("Gate closed");
                }
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance\n");
            log_event("Error reading distance");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

