#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define MOTOR_FWD_PIN  17
#define MOTOR_BWD_PIN  18
#define TRIGGER_PIN    24

#define DIST_NEAR      100
#define DIST_FAR       300

#define VL53L1X_REG_SOFT_RESET       0x0003
#define VL53L1X_REG_SYSTEM_START     0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "I2C write to reg 0x%04X failed (rc=%d)\n", reg, rc);
    }
    return rc;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    int rc = i2cWriteDevice(handle, reg_buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write (reg select) for 0x%04X failed (rc=%d)\n", reg, rc);
        return rc;
    }
    rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read from reg 0x%04X failed (rc=%d)\n", reg, rc);
    }
    return rc;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status_buf[1];
    uint8_t dist_buf[2];

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) return -1;

    int timeout = 100;
    while (timeout-- > 0) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 1) < 0) return -1;
        if ((status_buf[0] & 0x01) != 0) break;
        gpioDelay(1000);
    }
    if (timeout < 0) {
        fprintf(stderr, "VL53L1X data-ready timeout\n");
        return -1;
    }

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void motor_forward(void) {
    gpioWrite(MOTOR_BWD_PIN, 0);
    gpioWrite(MOTOR_FWD_PIN, 1);
    printf("Motor: FORWARD\n");
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FWD_PIN, 0);
    gpioWrite(MOTOR_BWD_PIN, 1);
    printf("Motor: BACKWARD\n");
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FWD_PIN, 0);
    gpioWrite(MOTOR_BWD_PIN, 0);
    printf("Motor: STOP\n");
}

static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;
    if (level != 1) return;

    uint16_t distance = 0;
    if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        if (distance < DIST_NEAR) {
            motor_forward();
        } else if (distance > DIST_FAR) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Failed to read distance; stopping motor.\n");
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n", I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR_FWD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BWD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", TRIGGER_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance-based motor control running. Press Ctrl+C to exit.\n");

    while (g_running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    motor_stop();
    if (g_i2c_handle >= 0) {
        i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_START, 0x00);
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

