#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5C
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.txt"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_SOFTRESET 0x80

#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL, NULL, NULL, NULL};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    uint8_t whoami;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &whoami) < 0) return -1;
    if (whoami != 0x41) {
        fprintf(stderr, "MPR121 not responding (WHO_AM_I=0x%02X, expected 0x41)\n", whoami);
        return -1;
    }
    if (i2c_write_reg8(fd, MPR121_ELECONFIG, 0x0C) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }
    int led_pins[4] = {LED_PIN_0, LED_PIN_1, LED_PIN_2, LED_PIN_3};
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_led", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 proximity-based LED installation running. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t lo, hi;
        if (i2c_read_reg8(i2c_fd, MPR121_TOUCHSTATUS_L, &lo) < 0 ||
            i2c_read_reg8(i2c_fd, MPR121_TOUCHSTATUS_H, &hi) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(100000);
            continue;
        }
        uint16_t touch_status = ((uint16_t)hi << 8) | lo;
        int any_proximity = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                any_proximity = 1;
                break;
            }
        }
        if (any_proximity) {
            int pattern = touch_status & 0x0F;
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(led_lines[i], (pattern >> i) & 1);
            }
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_fp, "%s - Proximity detected (pattern: 0x%X)\n", ts, pattern);
            fflush(log_fp);
        } else {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(led_lines[i], 0);
            }
        }
        usleep(50000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

