 * Returns >= 0 on success, -1.0 on timeout or sensor-absent (echo never rises),
 * -2.0 on reading outside the valid range.
 */
static double measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_LOW_US);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo signal timeout (sensor absent or not responding)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 30 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo signal timeout (no falling edge)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_width_us = (double)(end_tick - start_tick);
    double distance_cm = (pulse_width_us / 1000000.0) * SPEED_OF_SOUND * 100.0 / 2.0;

    if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance %.2f cm out of range [%.0f-%.0f]\n",
                distance_cm, MIN_DISTANCE, MAX_DISTANCE);
        return -2.0;
    }

    return distance_cm;
}

static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger is low at start */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed during init\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: Measurement failed, skipping log entry.\n");
        } else {
            log_distance(distance);
        }

        /* Sleep 1 s, but wake early on signal */
        uint32_t remaining = LOOP_DELAY_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");

    if (g_log != NULL) {
        if (fclose(g_log) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        g_log = NULL;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

