#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 1000000
#define ECHO_TIMEOUT_US  30000
#define MIN_PULSE_US     58
#define MAX_PULSE_US     25000
#define SPEED_OF_SOUND   34300.0
#define LOG_FILE         "distance_log.txt"

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_done  = false;
static volatile bool     g_echo_error = false;
static volatile bool     g_running    = true;

static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_done  = false;
        g_echo_error = false;
    } else if (level == 0) {
        if (g_start_tick != 0) {
            g_end_tick = tick;
            g_echo_done = true;
        }
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t start_tick, uint32_t end_tick)
{
    uint32_t diff = end_tick - start_tick;
    double time_s = (double)diff / 1000000.0;
    return (time_s * SPEED_OF_SOUND) / 2.0;
}

static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f meters\n", timestamp, distance);
    fflush(g_log_fp);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set ISR on ECHO_PIN.\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    while (g_running) {
        g_echo_done  = false;
        g_echo_error = false;
        g_start_tick = 0;
        g_end_tick   = 0;

        trigger_sensor();

        uint32_t elapsed = 0;
        while (!g_echo_done && !g_echo_error && elapsed < ECHO_TIMEOUT_US) {
            gpioDelay(100);
            elapsed += 100;
        }

        if (g_echo_error) {
            fprintf(stderr, "Warning: echo timeout or sensor absent.\n");
        } else if (g_echo_done && g_start_tick != 0 && g_end_tick != 0) {
            uint32_t diff = g_end_tick - g_start_tick;
            if (diff >= MIN_PULSE_US && diff <= MAX_PULSE_US) {
                double distance = calculate_distance(g_start_tick, g_end_tick);
                log_distance(distance);
            } else {
                fprintf(stderr, "Warning: pulse width out of range (%u us).\n", diff);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    fclose(g_log_fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

