#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x29
#define XSHUT_PIN        27
#define POLL_DELAY_MS    100

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET       0x0003
#define VL53L1X_REG_VHV_CONFIG       0x0001
#define VL53L1X_REG_PHASECAL_CONFIG  0x0002
#define VL53L1X_REG_SYSTEM_START     0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096

#define VL53L1X_SOFT_RESET_VALUE     0x00
#define VL53L1X_SYSTEM_START_VALUE   0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_xshut_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write16 to 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write (reg select) 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        syslog(LOG_ERR, "I2C read from 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", VL53L1X_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Soft reset */
    if (i2c_write16(g_i2c_fd, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VALUE) < 0) {
        syslog(LOG_ERR, "VL53L1X soft reset failed");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    usleep(10000); /* 10 ms */

    /* Enable XSHUT via GPIO27 (active-low) */
    if (gpiod_line_set_value(g_xshut_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set XSHUT high: %s", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    usleep(10000); /* 10 ms for sensor to power up */

    /* Start ranging */
    if (i2c_write16(g_i2c_fd, VL53L1X_REG_SYSTEM_START, VL53L1X_SYSTEM_START_VALUE) < 0) {
        syslog(LOG_ERR, "VL53L1X start ranging failed");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    usleep(10000); /* 10 ms for first measurement */

    syslog(LOG_INFO, "VL53L1X initialized successfully");
    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t status_buf[1];
    uint8_t dist_buf[2];

    /* Read range status (bit 0 = data ready) */
    if (i2c_read16(g_i2c_fd, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 1) < 0)
        return -1;

    if ((status_buf[0] & 0x01) == 0) {
        syslog(LOG_ERR, "VL53L1X data not ready");
        return -1;
    }

    /* Read 16-bit distance */
    if (i2c_read16(g_i2c_fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void cleanup(void)
{
    if (g_xshut_line) {
        gpiod_line_set_value(g_xshut_line, 0); /* XSHUT low to power down */
        gpiod_line_release(g_xshut_line);
        g_xshut_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    closelog();
}

int main(void)
{
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        syslog(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    g_xshut_line = gpiod_chip_get_line(g_chip, XSHUT_PIN);
    if (!g_xshut_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", XSHUT_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_xshut_line, "vl53l1x_xshut", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %d as output: %s", XSHUT_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init() < 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Starting distance readings every %d ms", POLL_DELAY_MS);

    while (g_running) {
        uint16_t distance_mm = 0;
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];

        if (localtime_r(&now, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown");
        }

        if (vl53l1x_read_distance(&distance_mm) == 0) {
            syslog(LOG_INFO, "%s Distance: %u mm", ts, distance_mm);
        } else {
            syslog(LOG_ERR, "%s Failed to read distance", ts);
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

