#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_INTERVAL_US 100000
#define LOG_FILE "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != len) return -1;
    return 0;
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        log_message("Error: Failed to read model ID from VL53L1X.");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: Unexpected model ID 0x%02X (expected 0xEA).", model_id);
        log_message(msg);
        return -1;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x00) != 0) {
        log_message("Error: Failed to stop VL53L1X during init.");
        return -1;
    }
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm) {
    uint8_t status = 0, dist_raw = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
        log_message("Error: Failed to read range status.");
        return -1;
    }
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist_raw, 2) != 0) {
        log_message("Error: Failed to read distance data.");
        return -1;
    }
    uint16_t dist_mm = (dist_raw >> 8) | (dist_raw << 8);
    *distance_cm = (float)dist_mm / 10.0f;
    return 0;
}

static void control_gate(int state) {
    gpioWrite(GATE_GPIO, state);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed.\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    control_gate(0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started.");

    int gate_state = 0;
    while (!terminate) {
        float distance_cm = 0.0f;
        if (read_distance_cm(i2c_handle, &distance_cm) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_message(msg);

            if (distance_cm < DISTANCE_THRESHOLD_CM) {
                if (gate_state == 0) {
                    control_gate(1);
                    gate_state = 1;
                    log_message("Gate opened.");
                }
            } else {
                if (gate_state == 1) {
                    control_gate(0);
                    gate_state = 0;
                    log_message("Gate closed.");
                }
            }
        } else {
            log_message("Error reading distance.");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

