#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define SERVO_MIN_US     500
#define SERVO_MAX_US     2500
#define SERVO_CENTER_US  1500
#define SERVO_ANGLE      90
#define MAX_DISTANCE_CM  400.0
#define MIN_DISTANCE_CM  2.0
#define MOVING_AVG_SIZE  5

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_width = 0;
static volatile uint32_t new_pulse = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle %d\n", angle);
        return -1;
    }
    int pulse_us = SERVO_MIN_US + (int)((float)angle / 180.0 * (SERVO_MAX_US - SERVO_MIN_US));
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        uint32_t start_tick = tick;
        while (gpioRead(ECHO_PIN) == 1) {
            if (new_pulse) {
                pulse_width = 0;
                new_pulse = 0;
                return;
            }
            if ((tick - start_tick) > ECHO_TIMEOUT_US) {
                pulse_width = 0;
                new_pulse = 0;
                return;
            }
        }
        uint32_t end_tick = tick;
        pulse_width = end_tick - start_tick;
        new_pulse = 1;
    }
}

static float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) return -1.0f;
    float distance = (float)pulse_width * 0.0343f / 2.0f;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f;
    }
    return distance;
}

static float moving_average(float new_distance, float *buffer, int *index, int size) {
    buffer[*index] = new_distance;
    *index = (*index + 1) % size;
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / size;
}

static int log_data(float distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize trigger pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
