#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define SERVO_MIN_US     500
#define SERVO_MAX_US     2500
#define SERVO_CENTER_US  1500
#define SERVO_ANGLE      90
#define MAX_DISTANCE_CM  400.0
#define MIN_DISTANCE_CM  2.0
#define MOVING_AVG_SIZE  5

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_width = 0;
static volatile uint32_t new_pulse = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle %d\n", angle);
        return -1;
    }
    int pulse_us = SERVO_MIN_US + (int)((float)angle / 180.0 * (SERVO_MAX_US - SERVO_MIN_US));
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        uint32_t start_tick = tick;
        while (gpioRead(ECHO_PIN) == 1) {
            if (new_pulse) {
                pulse_width = 0;
                new_pulse = 0;
                return;
            }
            if ((tick - start_tick) > ECHO_TIMEOUT_US) {
                pulse_width = 0;
                new_pulse = 0;
                return;
            }
        }
        uint32_t end_tick = tick;
        pulse_width = end_tick - start_tick;
        new_pulse = 1;
    }
}

static float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) return -1.0f;
    float distance = (float)pulse_width * 0.0343f / 2.0f;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f;
    }
    return distance;
}

static float moving_average(float new_distance, float *buffer, int *index, int size) {
    buffer[*index] = new_distance;
    *index = (*index + 1) % size;
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / size;
}

