#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define GPIO_LED       17
#define THRESHOLD_MM   200
#define BUFFER_SIZE    10
#define POLL_DELAY_US  50000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0003
#define REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x000E
#define REG_PHASECAL_CONFIG_TIMEOUT_MACROP  0x0010
#define REG_RANGE_CONFIG_A           0x001E
#define REG_RANGE_CONFIG_B           0x0020
#define REG_INTERMEASUREMENT_MS      0x0024
#define REG_SYSTEM_INTERMEASUREMENT  0x0026
#define REG_SYSTEM_INTERRUPT_CONFIG  0x0028
#define REG_SYSTEM_INTERRUPT_CLEAR   0x002A
#define REG_RESULT_INTERRUPT_STATUS  0x0044
#define REG_RESULT_RANGE_STATUS      0x0046
#define REG_RESULT_DISTANCE          0x0066

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then a single byte value. */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then read one byte. */
static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed at reg 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "I2C read failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then read two bytes (big-endian). */
static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed at reg 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read (word) failed at reg 0x%04X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000); /* 10 ms */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);

    /* Default config */
    if (vl53l1x_write_byte(handle, REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND, 0x09) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_PHASECAL_CONFIG_TIMEOUT_MACROP, 0x09) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_RANGE_CONFIG_A, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_RANGE_CONFIG_B, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_INTERMEASUREMENT_MS, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERMEASUREMENT, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERRUPT_CONFIG, 0x04) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;

    /* Start ranging */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x00) != 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    uint16_t dist;

    if (vl53l1x_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
        return -1;

    if (!(status & 0x01)) {
        /* No new data yet */
        return 1;
    }

    if (vl53l1x_read_word(handle, REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear interrupt so next measurement can signal */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

int main(void)
{
    uint16_t distance;
    uint16_t buffer[BUFFER_SIZE];
    int      idx = 0;
    int      i;

    for (i = 0; i < BUFFER_SIZE; i++)
        buffer[i] = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            buffer[idx] = distance;
            idx = (idx + 1) % BUFFER_SIZE;

            if (distance < THRESHOLD_MM) {
                gpioWrite(GPIO_LED, 1);
                printf("Distance: %u mm (below threshold)\n", distance);
            } else {
                gpioWrite(GPIO_LED, 0);
                printf("Distance: %u mm\n", distance);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Read error, continuing...\n");
        }
        /* rc == 1: no new data, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(GPIO_LED, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

