/*
 * Theremin-like instrument using an HC-SR04 ultrasonic sensor and a PWM-driven
 * 8-ohm speaker on a Raspberry Pi Zero W.
 *
 * Hardware connections (BCM numbering):
 *   - HC-SR04 TRIG -> GPIO23 (physical pin 16)
 *   - HC-SR04 ECHO -> GPIO24 (physical pin 18)
 *   - Speaker +    -> GPIO18 (physical pin 12, hardware PWM0)
 *   - Speaker -    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define TRIGGER_PIN      23          /* BCM 23 - HC-SR04 TRIG  */
#define ECHO_PIN         24          /* BCM 24 - HC-SR04 ECHO  */
#define PWM_PIN          18          /* BCM 18 - hardware PWM0 */

#define MIN_DISTANCE_CM  2.0f        /* HC-SR04 minimum range   */
#define MAX_DISTANCE_CM  200.0f      /* HC-SR04 maximum range   */
#define MIN_FREQUENCY_HZ 200.0f      /* lowest tone            */
#define MAX_FREQUENCY_HZ 2000.0f     /* highest tone           */
#define ECHO_TIMEOUT_US  200000      /* 200 ms timeout          */
#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse     */
#define SAMPLE_PERIOD_US 50000       /* 50 ms between samples   */
#define PWM_DUTY_50PCT   128         /* 50 % of 255 range       */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* --------------------------- HC-SR04 sensor ------------------------------ */

/*
 * Measure the distance to the nearest object in centimetres.
 * Returns -1.0 on timeout or out-of-range.
 */
static float read_distance_cm(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);                       /* settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline   = gpioTick() + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t elapsed_us = end_tick - start_tick;

    /* distance = elapsed_us * 34300 cm/s / 2 */
    float distance = (float)elapsed_us * 0.01715f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm out of range [%.0f-%.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }
    return distance;
}

/* --------------------------- Frequency mapping --------------------------- */

static float map_distance_to_frequency(float distance_cm)
{
    float freq = MIN_FREQUENCY_HZ +
                 (distance_cm - MIN_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
    return freq;
}

/* --------------------------- PWM tone generation ------------------------- */

static int set_tone(float frequency_hz)
{
    if (frequency_hz <= 0.0f) {
        if (gpioPWM(PWM_PIN, 0) != 0) {
            fprintf(stderr, "gpioPWM(PWM_PIN, 0) failed\n");
            return -1;
        }
        return 0;
    }

    /* pigpio hardware PWM: range 0-255, duty 0-255 */
    int duty = PWM_DUTY_50PCT;

    if (gpioSetPWMfrequency(PWM_PIN, (int)frequency_hz) != 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d) failed\n", (int)frequency_hz);
        return -1;
    }
    if (gpioPWM(PWM_PIN, duty) != 0) {
        fprintf(stderr, "gpioPWM(PWM_PIN, %d) failed\n", duty);
        return -1;
    }
    return 0;
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger as output, echo as input */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PWM_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 for 50 % duty cycle */
    if (gpioSetPWMrange(PWM_PIN, 255) != 0) {
        fprintf(stderr, "gpioSetPWMrange(PWM_PIN, 255) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin ready.  Distance (cm) -> frequency (Hz)\n");
    printf("  %.0f cm .. %.0f cm  ->  %.0f Hz .. %.0f Hz\n",
           MIN_DISTANCE_CM, MAX_DISTANCE_CM,
           MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
    printf("Press Ctrl+C to exit.\n");

    float previous_frequency = 0.0f;

    while (g_running) {
        float distance = read_distance_cm();

        if (distance < 0.0f) {
            /* Error or out-of-range: keep previous frequency */
            if (previous_frequency > 0.0f) {
                set_tone(previous_frequency);
            }
        } else {
            float frequency = map_distance_to_frequency(distance);
            if (frequency != previous_frequency) {
                if (set_tone(frequency) == 0) {
                    previous_frequency = frequency;
                }
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --------------------------- Cleanup --------------------------------- */
    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);   /* stop PWM */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

