/*
 * Theremin-like instrument using an HC-SR04 ultrasonic sensor and a piezo buzzer.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   - HC-SR04 trigger  -> GPIO23 (BCM)
 *   - HC-SR04 echo     -> GPIO24 (BCM) with pull-down
 *   - Piezo buzzer     -> PWM0 on GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o theremin theremin.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN    23
#define ECHO_PIN       24
#define BUZZER_PIN     18

#define MIN_DISTANCE_CM 5.0f
#define MAX_DISTANCE_CM 50.0f
#define MIN_FREQUENCY   200.0f
#define MAX_FREQUENCY   2000.0f

#define ECHO_TIMEOUT_US 100000   /* 100 ms */
#define LOOP_DELAY_MS   10
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **trig,
                     struct gpiod_line **echo, struct gpiod_line **buzzer)
{
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    *trig = gpiod_chip_get_line(*chip, TRIGGER_PIN);
    *echo = gpiod_chip_get_line(*chip, ECHO_PIN);
    *buzzer = gpiod_chip_get_line(*chip, BUZZER_PIN);
    if (!*trig || !*echo || !*buzzer) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(*trig, "theremin", 0) < 0) {
        fprintf(stderr, "Failed to request trigger as output: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(*echo, "theremin") < 0) {
        fprintf(stderr, "Failed to request echo as input: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(*buzzer, "theremin", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip,
                         struct gpiod_line *trig,
                         struct gpiod_line *echo,
                         struct gpiod_line *buzzer)
{
    if (buzzer) {
        gpiod_line_set_value(buzzer, 0);
        gpiod_line_release(buzzer);
    }
    if (trig) {
        gpiod_line_set_value(trig, 0);
        gpiod_line_release(trig);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int trigger_sensor(struct gpiod_line *trig)
{
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(5);
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int measure_echo_us(struct gpiod_line *echo, long long *start_us,
                           long long *end_us)
{
    long long deadline = now_us() + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() > deadline) {
            return -1; /* timeout */
        }
    }
    *start_us = now_us();

    /* Wait for echo falling edge */
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() > deadline) {
            return -1; /* timeout */
        }
    }
    *end_us = now_us();

    return 0;
}

static float distance_cm(long long pulse_us)
{
    /* distance = (pulse_us * speed_of_sound) / 2 / 1000000 */
    return (float)pulse_us * 0.01715f;
}

static float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float norm = (distance - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return MIN_FREQUENCY + norm * (MAX_FREQUENCY - MIN_FREQUENCY);
}

static int set_buzzer_frequency(struct gpiod_line *buzzer, float frequency)
{
    if (frequency < 20.0f || frequency > 20000.0f) {
        fprintf(stderr, "Invalid frequency %.2f Hz\n", frequency);
        return -1;
    }
    if (gpiod_line_set_value(buzzer, 1) < 0) {
        fprintf(stderr, "Failed to set buzzer high: %s\n", strerror(errno));
        return -1;
    }
    usleep(1000000 / (int)(frequency * 2));
    if (gpiod_line_set_value(buzzer, 0) < 0) {
        fprintf(stderr, "Failed to set buzzer low: %s\n", strerror(errno));
        return -1;
    }
    usleep(1000000 / (int)(frequency * 2));
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    struct gpiod_line *buzzer = NULL;
    float last_valid_freq = 500.0f;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio(&chip, &trig, &echo, &buzzer) != 0) {
        cleanup_gpio(chip, trig, echo, buzzer);
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_sensor(trig) != 0) {
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        long long start_us = 0, end_us = 0;
        if (measure_echo_us(echo, &start_us, &end_us) != 0) {
            fprintf(stderr, "Echo timeout (sensor absent or out of range)\n");
            if (set_buzzer_frequency(buzzer, last_valid_freq) != 0) {
                fprintf(stderr, "Failed to set buzzer frequency\n");
            }
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        long long pulse_us = end_us - start_us;
        float distance = distance_cm(pulse_us);
        float frequency = map_distance_to_frequency(distance);

        if (set_buzzer_frequency(buzzer, frequency) != 0) {
            fprintf(stderr, "Failed to set buzzer frequency\n");
        }

        last_valid_freq = frequency;
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
