#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 50000
#define LOOP_DELAY_US 500000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static long measure_echo(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    /* Wait for echo to go high */
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static double calculate_distance(long pulse_duration_us) {
    if (pulse_duration_us < 0) {
        return -1.0;
    }
    return (double)pulse_duration_us * SPEED_OF_SOUND / 2000000.0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse_duration = measure_echo();
        double distance = calculate_distance(pulse_duration);

        if (distance < 0.0) {
            printf("Error: echo measurement timeout\n");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < 10.0) {
                printf("Too close!\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

