#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* mode 0, active-low CE0 on GPIO8 */
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_DELAY_US 100000  /* 100 ms */
#define MAX_RETRIES    3

/* ICU-20201 SPI commands (16-bit, big-endian on wire) */
#define CMD_READ_DIST  0x0001
#define CMD_RESET      0x0000
#define CMD_START      0x0002
#define CMD_STOP       0x0003

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit command to the sensor (MSB first) */
static int spi_write_cmd(uint16_t cmd)
{
    char tx[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    char rx[2] = { 0, 0 };
    int rc = spiXfer(spi_handle, tx, rx, 2);
    if (rc != 2) {
        fprintf(stderr, "SPI write failed (cmd 0x%04X): rc=%d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* Read distance from sensor; returns distance in mm on success, -1 on error */
static int read_distance(void)
{
    if (spi_write_cmd(CMD_READ_DIST) != 0)
        return -1;

    /* Small delay for measurement conversion */
    gpioDelay(1000);

    char tx[2] = { 0x00, 0x00 };
    char rx[2] = { 0, 0 };
    int rc = spiXfer(spi_handle, tx, rx, 2);
    if (rc != 2) {
        fprintf(stderr, "SPI read failed: rc=%d\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    /* Distance range: 200 mm to 5000 mm */
    if (raw < 200 || raw > 5000) {
        fprintf(stderr, "Distance out of range: %u mm\n", raw);
        return -1;
    }
    return (int)raw;
}

static void log_distance(int distance_mm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%d\n", ts, distance_mm);
    fflush(log_file);
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Reset and start sensor */
    if (spi_write_cmd(CMD_RESET) != 0) {
        fprintf(stderr, "Sensor reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms reset settling */
    if (spi_write_cmd(CMD_START) != 0) {
        fprintf(stderr, "Sensor start failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ICU-20201 distance logging to %s\n", LOG_FILE);

    while (!terminate) {
        int distance = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            distance = read_distance();
            if (distance >= 0)
                break;
            gpioDelay(10000); /* 10 ms backoff */
        }

        if (distance < 0) {
            fprintf(stderr, "Failed to read distance after %d attempts\n", MAX_RETRIES);
        } else {
            log_distance(distance);
            printf("Distance: %d mm\n", distance);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

