    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%d\n", ts, distance_mm);
    fflush(log_file);
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Reset and start sensor */
    if (spi_write_cmd(CMD_RESET) != 0) {
        fprintf(stderr, "Sensor reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms reset settling */
    if (spi_write_cmd(CMD_START) != 0) {
        fprintf(stderr, "Sensor start failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ICU-20201 distance logging to %s\n", LOG_FILE);

    while (!terminate) {
        int distance = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            distance = read_distance();
            if (distance >= 0)
                break;
            gpioDelay(10000); /* 10 ms backoff */
        }

        if (distance < 0) {
            fprintf(stderr, "Failed to read distance after %d attempts\n", MAX_RETRIES);
        } else {
            log_distance(distance);
            printf("Distance: %d mm\n", distance);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

