        if (result == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int si1120_reset(int handle) {
    if (i2c_write_byte(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to send reset command to Si1120.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int si1120_init(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_byte(handle, SI1120_REG_PART_ID, &part_id) != 0) {
