#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define DISTANCE_THRESHOLD_CM 20.0
#define SOUND_SPEED_CM_PER_US 0.0343
#define TRIGGER_PULSE_US      10
#define SAMPLE_INTERVAL_S     1

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_ready      = false;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = false;
    } else if (level == 0) {
        g_end_tick   = tick;
        g_echo_seen  = true;
    }
}

static double calculate_distance_cm(uint32_t start_tick, uint32_t end_tick)
{
    uint32_t diff = end_tick - start_tick;
    return (double)diff * SOUND_SPEED_CM_PER_US / 2.0;
}

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set alert function on echo pin %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin %d low\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin %d low\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ultrasonic sensor monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        g_ready = false;
        g_echo_seen = false;

        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error: failed to set trigger high\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to set trigger low\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000);

        if (g_echo_seen && g_ready) {
            double distance = calculate_distance_cm(g_start_tick, g_end_tick);
            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD_CM) {
                if (gpioWrite(BUZZER_PIN, 1) < 0) {
                    fprintf(stderr, "Error: failed to activate buzzer\n");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) < 0) {
                    fprintf(stderr, "Error: failed to deactivate buzzer\n");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
        } else {
            fprintf(stderr, "Warning: no valid echo received this cycle\n");
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

