#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define MIN_DISTANCE_CM 20.0
#define MAX_DISTANCE_CM 200.0

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode.\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        return -1;
    }
    return 0;
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1.0;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    int      timeout    = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        start_tick = gpioTick();
        if ((int)(start_tick - timeout) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout.\n");
            return -1.0;
        }
        timeout = start_tick;
    }

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if ((int)(end_tick - timeout) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout.\n");
            return -1.0;
        }
        timeout = end_tick;
    }

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (double)pulse_width / 58.0;
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = SERVO_MIN_PULSE + (int)((double)angle / 180.0 *
                                              (double)(SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: failed to set servo pulse width.\n");
        return -1;
    }
    return 0;
}

static int calculate_servo_angle(double distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    double fraction = (MAX_DISTANCE_CM - distance) /
                      (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(fraction * 180.0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Sensor error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int servo_angle = calculate_servo_angle(distance);
        if (set_servo_angle(servo_angle) < 0) {
            fprintf(stderr, "Servo error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        printf("Distance: %.2f cm, Servo Angle: %d degrees\n",
               distance, servo_angle);
        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

