/*
 * Si7005 Humidity & Temperature Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7005 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si7005 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si7005 VDD  -> 3.3 V (pin 1)
 *   Si7005 GND  -> GND  (pin 6)
 *
 * I2C address: 0x40 (Si7005 default 7-bit address)
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7005_reader si7005_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define I2C_BUS_NAME      "i2c-1"
#define SI7005_ADDR       0x40

/* Si7005 register addresses */
#define SI7005_REG_CONFIG  0x01
#define SI7005_REG_HUMID   0x02
#define SI7005_REG_TEMP    0x03

/* Configuration register bits */
#define SI7005_CONFIG_SD50 0x00  /* 50 %RH resolution */
#define SI7005_CONFIG_SD12 0x01  /* 12.5 %RH resolution */
#define SI7005_CONFIG_SD1  0x02  /* 1 %RH resolution */
#define SI7005_CONFIG_SD0_5 0x03 /* 0.5 %RH resolution */

#define SAMPLE_INTERVAL_S  2
#define CONVERSION_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Write a single byte to a Si7005 register.
 * Returns 0 on success, -1 on error.
 */
static int si7005_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si7005 register.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int si7005_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t val;
    ret = read(fd, &val, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = val;
    return 0;
}

/*
 * Read temperature and humidity from the Si7005.
 * Returns 0 on success, -1 on error.
 */
static int si7005_read(int fd, float *temperature, float *humidity)
{
    uint8_t config = SI7005_CONFIG_SD50; /* 50 %RH resolution */
    if (si7005_write_reg(fd, SI7005_REG_CONFIG, config) != 0)
        return -1;

    sleep_ms(CONVERSION_DELAY_MS);

    uint8_t reg = SI7005_REG_HUMID;
    if (si7005_read_reg(fd, reg, &reg) != 0)
        return -1;

    uint8_t hum_low, hum_high;
    if (si7005_read_reg(fd, reg, &hum_low) != 0)
        return -1;
    if (si7005_read_reg(fd, reg, &hum_high) != 0)
        return -1;

    uint16_t hum_raw = ((uint16_t)hum_high << 8) | hum_low;
    *humidity = ((float)hum_raw / 16383.0f) * 100.0f;

    if (si7005_write_reg(fd, SI7005_REG_CONFIG, 0x00) != 0)
        return -1;

    sleep_ms(CONVERSION_DELAY_MS);

    reg = SI7005_REG_TEMP;
    if (si7005_read_reg(fd, reg, &reg) != 0)
        return -1;

    uint8_t temp_low, temp_high;
    if (si7005_read_reg(fd, reg, &temp_low) != 0)
        return -1;
    if (si7005_read_reg(fd, reg, &temp_high) != 0)
        return -1;

    uint16_t temp_raw = ((uint16_t)temp_high << 8) | temp_low;
    *temperature = ((float)temp_raw / 16383.0f) * 165.0f - 40.0f;

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sda  = NULL;
    struct gpiod_line *scl  = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus using gpiod's internal I2C helpers */
    chip = gpiod_chip_open_by_name(I2C_BUS_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n",
                I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    sda = gpiod_chip_get_line(chip, 2);  /* GPIO2 = SDA */
    scl = gpiod_chip_get_line(chip, 3);  /* GPIO3 = SCL */
    if (!sda || !scl) {
        fprintf(stderr, "Failed to get I2C GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request the lines as output for I2C control (we use gpiod's internal
     * I2C helpers, so explicit line requests are not strictly required, but
     * we do it for clarity and to ensure the lines are configured correctly. */
    if (gpiod_line_request_output(sda, "si7005-sda", 0) != 0) {
        fprintf(stderr, "Failed to request SDA line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(scl, "si7005-scl", 0) != 0) {
        fprintf(stderr, "Failed to request SCL line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open the I2C device using the gpiod internal I2C helper */
    g_i2c_fd = gpiod_i2c_open(chip, SI7005_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                SI7005_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si7005 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (si7005_read(g_i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Read failed; re-opening I2C bus.\n");
            gpiod_i2c_close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep_ms(100);

            g_i2c_fd = gpiod_i2c_open(chip, SI7005_ADDR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %s\n",
                        strerror(errno));
                goto cleanup;
            }
        }

        sleep_ms(SAMPLE_INTERVAL_S * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (g_i2c_fd >= 0)
        gpiod_i2c_close(g_i2c_fd);
    if (sda)
        gpiod_line_release(sda);
    if (scl)
        gpiod_line_release(scl);
    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return ret;
}

