 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3)
 * Build: gcc -O2 -Wall -o mpu6050 mpu6050.c -li2c
 *
 * Reads the 14-byte block starting at 0x3B (ACCEL_XOUT_H) every 100 ms.
 * The MPU-6050 sends big-endian int16 values for each axis.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <i2c.h>

#define I2C_BUS        1
#define MPU6050_ADDR   0x68
#define WHO_AM_I       0x75
#define WHO_AM_I_VAL   0x68
#define PWR_MGMT_1     0x6B
#define ACCEL_XOUT_H   0x3B
#define DATA_LEN       14

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    i2c_fd = i2c_open(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify sensor identity */
    int who = i2c_read_byte_data(i2c_fd, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        goto cleanup;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        goto cleanup;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2c_write_byte_data(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(100000); /* allow oscillator to stabilize */

    printf("MPU-6050 initialized on I2C bus %d, addr 0x%02X.\n", I2C_BUS, MPU6050_ADDR);
    printf("Logging raw data every 100 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t buf[DATA_LEN];
        int n = i2c_read_i2c_block_data(i2c_fd, ACCEL_XOUT_H, DATA_LEN, buf);
        if (n != DATA_LEN) {
            fprintf(stderr, "I2C read error (got %d bytes, expected %d): %s\n",
                    n, DATA_LEN, strerror(errno));
            usleep(100000);
            continue;
        }

        int16_t accel_x = (int16_t)((buf[0]  << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2]  << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4]  << 8) | buf[5]);
        /* buf[6..7] = temperature (skipped) */
        int16_t gyro_x  = (int16_t)((buf[8]  << 8) | buf[9]);
        int16_t gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
        int16_t gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

        printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        usleep(100000); /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0)
        i2c_close(i2c_fd);
    return rc;
}

