#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR        0x49
#define SHT40_CMD_MEAS_HR 0x2C
#define SHT40_CMD_SOFT_RST 0x30
#define SHT40_MEAS_DELAY_US 10000
#define SAMPLE_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t sht40_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht40_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_CMD_MEAS_HR;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to SHT40.\n");
        return -1;
    }

    gpioDelay(SHT40_MEAS_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from SHT40.\n");
        return -1;
    }

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                sht40_crc8(&buf[0], 2), buf[2]);
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                sht40_crc8(&buf[3], 2), buf[5]);
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X.\n", SHT40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteDevice(handle, (char *)&SHT40_CMD_SOFT_RST, 1) != 0) {
        fprintf(stderr, "Warning: soft-reset write failed; continuing anyway.\n");
    }

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: sensor read failed; re-opening I2C bus.\n");
            i2cClose(handle);
            handle = -1;
            gpioDelay(1000000);
            handle = i2cOpen(1, SHT40_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "Error: failed to re-open I2C bus.\n");
                break;
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    if (handle >= 0)
        i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

