#define SHT40_ADDR 0x45
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sht40_read(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x2C, 0x06};
    if (write(fd, cmd, 2) != 2) {
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t buf[6];
    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
