#define MAX_RETRIES    3
#define MEAS_DELAY_US  1000     /* 1 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as per Sensirion datasheet */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int sdp31_trigger(int handle)
{
    uint8_t cmd[2] = { 0x36, 0x2F };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

static int sdp31_read(int handle, float *pressure, float *temperature)
{
    uint8_t buf[6];
    int n = i2cReadDevice(handle, (char *)buf, 6);
    if (n != 6)
