    if (crc8(&buf[0], 2) != buf[2]) return -1;
    if (crc8(&buf[3], 2) != buf[5]) return -1;

    int16_t dp_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t t_raw  = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)dp_raw / 2048.0f;   /* Pa */
    *temperature = (float)t_raw  / 2048.0f;   /* °C */
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

