#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_TIMEOUT_MS 20

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7015(int handle, uint8_t cmd, uint16_t *value) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "Error writing command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }

    gpioDelay(MEASUREMENT_TIMEOUT_MS * 1000);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading data for command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)(buf[1] & 0xFF);
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint16_t raw;
    if (read_si7015(handle, 0xE3, &raw) < 0) return -1;
    *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *humidity) {
    uint16_t raw;
    if (read_si7015(handle, 0xE5, &raw) < 0) return -1;
    *humidity = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(fp);
    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main(void) {
    float temperature, humidity;
    FILE *fp;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        fclose(fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_temperature(i2c_handle, &temperature) < 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (read_humidity(i2c_handle, &humidity) < 0) {
            fprintf(stderr, "Error reading humidity, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        log_data(fp, temperature, humidity);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

