/*
 * SDP800-500Pa differential-pressure logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x2000 (16-bit, big-endian on the bus)
 * Continuous-measurement trigger: 0x362F
 * Pressure / temperature data: 9 bytes (3 words, each with CRC-8)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x2000          /* 16-bit address, big-endian on bus */
#define TRIGGER_CMD    0x362F          /* continuous measurement */
#define MEAS_DELAY_MS  45              /* conversion time */
#define LOOP_DELAY_MS  100             /* logging interval */
#define LOG_FILE       "airflow_data.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c write(0x%04X) failed: %s (wrote %zd bytes)\n",
                cmd, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "i2c read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "i2c read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature)
{
    if (i2c_write_cmd(fd, TRIGGER_CMD) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t data[9];
    if (i2c_read_n(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);
    int16_t raw_scale    = (int16_t)((data[6] << 8) | data[7]);

    if (raw_scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)raw_scale;
    *temperature = (float)raw_temp / 200.0f;

    return 0;
}

static int log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%04X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is new/empty */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        if (!fp) {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
                fclose(fp);
            }
        } else {
            fclose(fp);
        }
    }

    printf("SDP800 logger started. Logging to %s every %d ms. Ctrl+C to stop.\n",
           LOG_FILE, LOOP_DELAY_MS);

    while (g_running) {
        float pressure, temperature;
        if (read_sdp800(fd, &pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) < 0)
                fprintf(stderr, "Logging failed\n");
            else
                printf("%s  P=%.2f Pa  T=%.2f C\n",
                       "data", pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

