#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD_ON  28.0f
#define TEMP_THRESHOLD_OFF 27.0f
#define BUFFER_SIZE    60
#define READ_INTERVAL  2
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000
#define FAN_SETTLE_US  10000

#define CMD_TEMP_NO_HOLD  0xE3
#define CMD_RESET        0xFE

typedef struct {
    time_t timestamp;
    float  temperature;
} SensorData;

static SensorData  buffer[BUFFER_SIZE];
static int         buffer_index = 0;
static int         buffer_count = 0;
static int         i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature)
{
    char cmd = CMD_TEMP_NO_HOLD;
    char data[2];
    int  result;

    for (int attempt = 0; attempt < RETRY_COUNT; ++attempt) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            gpioDelay(20000);
            result = i2cReadDevice(i2c_handle, data, 2);
            if (result == 2) {
                uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
                *temperature = -46.85f + 175.72f * (float)raw / 65536.0f;
                return 0;
            }
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d, result=%d)\n",
                attempt + 1, RETRY_COUNT, result);
        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static void add_to_buffer(float temperature)
{
    buffer[buffer_index].timestamp  = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static void print_buffer(void)
{
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; ++i) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temperature: %.2f C\n", ts, buffer[idx].temperature);
    }
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    bool fan_on = false;

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            printf("Temperature: %.2f C\n", temperature);

            if (temperature > TEMP_THRESHOLD_ON && !fan_on) {
                if (gpioWrite(FAN_GPIO, 1) == 0) {
                    fan_on = true;
                    printf("Fan ON\n");
                } else {
                    fprintf(stderr, "Failed to turn fan ON\n");
                }
            } else if (temperature < TEMP_THRESHOLD_OFF && fan_on) {
                if (gpioWrite(FAN_GPIO, 0) == 0) {
                    fan_on = false;
                    printf("Fan OFF\n");
                } else {
                    fprintf(stderr, "Failed to turn fan OFF\n");
                }
            }
        } else {
            fprintf(stderr, "Sensor read failed; sensor may be absent\n");
        }

        print_buffer();
        sleep(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

