#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 5
#define SCD40_START_PERIODIC_MEASUREMENT 0x0010
#define SCD40_READ_MEASUREMENT 0x0202
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x0103
#define SCD40_GET_DATA_READY 0x0200
#define SCD40_DATA_READY_BIT 0x01
#define SCD40_MEASUREMENT_DELAY_SEC 1
#define SCD40_MEASUREMENT_DELAY_US 0
#define SCD40_READ_MEASUREMENT_DELAY_US 10000
#define SCD40_DATA_READY_DELAY_US 10000
#define SCD40_MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int scd40_write_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write command 0x%04X to SCD40.\n", command);
        return -1;
    }
    return 0;
}

static int scd40_read_data(int handle, uint8_t *data, int len) {
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: Failed to read %d bytes from SCD40.\n", len);
        return -1;
    }
    return 0;
}

static int scd40_start_periodic_measurement(int handle) {
    return scd40_write_command(handle, SCD40_START_PERIODIC_MEASUREMENT);
}

static int scd40_stop_periodic_measurement(int handle) {
    return scd40_write_command(handle, SCD40_STOP_PERIODIC_MEASUREMENT);
}

static int scd40_data_ready(int handle) {
    if (scd40_write_command(handle, SCD40_GET_DATA_READY) != 0) {
        return -1;
    }
    gpioDelay(SCD40_DATA_READY_DELAY_US);
    uint8_t data[3];
    if (scd40_read_data(handle, data, 3) != 0) {
        return -1;
    }
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: CRC check failed for data-ready response.\n");
        return -1;
    }
    uint16_t word = (data[0] << 8) | data[1];
    return (word & SCD40_DATA_READY_BIT) ? 1 : 0;
}

static int scd40_read_measurement(int handle, uint16_t *co2, float *temperature, float *humidity) {
    if (scd40_write_command(handle, SCD40_READ_MEASUREMENT) != 0) {
        return -1;
    }
    gpioDelay(SCD40_READ_MEASUREMENT_DELAY_US);
    uint8_t data[9];
    if (scd40_read_data(handle, data, 9) != 0) {
        return -1;
    }
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: CRC check failed for CO2 word.\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: CRC check failed for temperature word.\n");
        return -1;
    }
    if (crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "Error: CRC check failed for humidity word.\n");
        return -1;
    }
    *co2 = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static int log_data(FILE *fp, uint16_t co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp, co2, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device on bus %d, address 0x%02X.\n", I2C_BUS, SCD40_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    if (scd40_start_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement.\n");
        fclose(fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioDelay(SCD40_MEASUREMENT_DELAY_SEC * 1000000 + SCD40_MEASUREMENT_DELAY_US);

    while (!terminate) {
        int ready = scd40_data_ready(i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Error: Failed to check data-ready status.\n");
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }
        if (ready) {
            uint16_t co2;
            float temperature, humidity;
            if (scd40_read_measurement(i2c_handle, &co2, &temperature, &humidity) == 0) {
                if (log_data(fp, co2, temperature, humidity) != 0) {
                    fprintf(stderr, "Error: Logging failed.\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to read measurement data.\n");
            }
        }
        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    fprintf(stderr, "Shutting down gracefully...\n");
    if (scd40_stop_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Warning: Failed to stop periodic measurement.\n");
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    return 0;
}

