/*
 * SCD40 CO2 sensor reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   LED anode -> GPIO17 (pin 11) via 330 ohm resistor
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_reader scd40_reader.c -lpigpio -lrt
 * Run:    sudo ./scd40_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SCD40_I2C_ADDR       0x62
#define GPIO_LED             17
#define CO2_THRESHOLD        1000
#define BUFFER_SIZE          20
#define SAMPLE_INTERVAL_SEC  5

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC   0x364D
#define CMD_STOP_PERIODIC    0xB098
#define CMD_READ_MEASUREMENT 0xEC05

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
    time_t   timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void buffer_init(circular_buffer_t *buf)
{
    buf->head  = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_print(const circular_buffer_t *buf)
{
    printf("\n--- Circular Buffer (%d entries) ---\n", buf->count);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        sensor_data_t *d = &buf->data[idx];
        char ts[32];
        struct tm tmv;
        localtime_r(&d->timestamp, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("[%s] CO2=%u ppm  T=%.2f C  RH=%.2f %%\n",
               ts, d->co2, d->temperature, d->humidity);
    }
    printf("--- End of buffer ---\n");
}

/*
 * Send a 16-bit command to the SCD40.
 * Returns 0 on success, -1 on I2C error.
 */
static int scd40_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[SCD40] I2C write failed (cmd 0x%04X)\n", cmd);
        return -1;
    }
    return 0;
}

/*
 * Read one 9-byte measurement frame and validate CRC on each 2-byte word.
 * Returns 0 on success, -1 on I2C error, -2 on sensor not ready.
 */
static int scd40_read_measurement(int handle, sensor_data_t *out)
{
    uint8_t buf[9];
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[SCD40] I2C read failed (got %d bytes, expected 9)\n", n);
        return -1;
    }

    /* Word 0: CO2 (MSB first) */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[SCD40] CO2 CRC mismatch\n");
        return -1;
    }
    /* Word 1: Temperature (MSB first) */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[SCD40] Temperature CRC mismatch\n");
        return -1;
    }
    /* Word 2: Humidity (MSB first) */
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[SCD40] Humidity CRC mismatch\n");
        return -1;
    }

    out->co2          = (uint16_t)((buf[0] << 8) | buf[1]);
    out->temperature  = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    out->humidity     = (float)((buf[6] << 8) | buf[7]) / 100.0f;
    out->timestamp    = time(NULL);
    return 0;
}

static int scd40_init(int handle)
{
    if (scd40_write_cmd(handle, CMD_START_PERIODIC) != 0)
        return -1;
    /* Datasheet: first measurement is ready after ~5 s */
    time_sleep(5.0);
    return 0;
}

static void scd40_stop(int handle)
{
    (void)scd40_write_cmd(handle, CMD_STOP_PERIODIC);
}

int main(void)
{
    circular_buffer_t buf;
    buffer_init(&buf);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
