#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define EDGE_TIMEOUT_US 50000
#define MAX_CONSECUTIVE_ERRORS 3
#define MIN_TEMP_C -40.0f
#define MAX_TEMP_C 150.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_temperature(FILE *fp, float temperature, const char *status) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (temperature > MIN_TEMP_C && temperature < MAX_TEMP_C) {
        fprintf(fp, "%s, Temperature: %.2f C, Status: %s\n", timestamp, temperature, status);
    } else {
        fprintf(fp, "%s, Temperature: %.2f C, Status: %s\n", timestamp, temperature, status);
    }
    fflush(fp);
}

static float calculate_temperature(unsigned int high_us, unsigned int low_us) {
    if (low_us == 0) {
        return -999.0f;
    }
    return ((float)high_us / (float)low_us) * 100.0f - 25.0f;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(line, "tmp05_temp") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup_chip;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        goto cleanup_line;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        unsigned int high_us = 0, low_us = 0;
        int level = gpiod_line_get_value(line);
        if (level < 0) {
            perror("gpiod_line_get_value (initial)");
            log_temperature(log_fp, -999.0f, "ERROR: GPIO read failed");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        struct timespec start, now;
        int last_level = level;

        while (program_running) {
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("clock_gettime");
                log_temperature(log_fp, -999.0f, "ERROR: clock_gettime");
                break;
            }

            int current_level = gpiod_line_get_value(line);
            if (current_level < 0) {
                perror("gpiod_line_get_value (edge loop)");
                log_temperature(log_fp, -999.0f, "ERROR: GPIO read failed");
                break;
            }

            if (current_level != last_level) {
                last_level = current_level;
                if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
                    perror("clock_gettime");
                    log_temperature(log_fp, -999.0f, "ERROR: clock_gettime");
                    break;
                }
            }

            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("clock_gettime");
                log_temperature(log_fp, -999.0f, "ERROR: clock_gettime");
                break;
            }

            double elapsed_us = (now.tv_sec - start.tv_sec) * 1000000.0 +
                                (now.tv_nsec - start.tv_nsec) / 1000.0;

            if (current_level == 1 && last_level == 0) {
                high_us = (unsigned int)elapsed_us;
            } else if (current_level == 0 && last_level == 1) {
                low_us = (unsigned int)elapsed_us;
                break;
            }

            if (elapsed_us > EDGE_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for edge transition.\n");
                log_temperature(log_fp, -999.0f, "ERROR: Edge timeout");
                break;
            }
        }

        if (!program_running) {
            break;
        }

        if (high_us > 0 && low_us > 0) {
            float temperature = calculate_temperature(high_us, low_us);
            log_temperature(log_fp, temperature, "OK");
            printf("Temperature: %.2f C\n", temperature);
        } else {
            log_temperature(log_fp, -999.0f, "ERROR: Invalid pulse width");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup_line:
    if (line) {
        gpiod_line_release(line);
    }
cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    printf("Temperature monitoring stopped.\n");
    return ret;
}

