#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT35_ADDR             0x45
#define SHT35_MEASURE_HIGHREP  0x2400
#define SHT35_MEASURE_CMD_LEN  2
#define SHT35_READ_LEN         6
#define SHT35_MEAS_DELAY_US    15000
#define RETRY_COUNT            3
#define RETRY_DELAY_US         1000000
#define LOG_FILE               "environmental_data.txt"
#define GREENHOUSE_TEMP_AMPL   2.0
#define GREENHOUSE_HUM_AMPL    5.0
#define GREENHOUSE_PERIOD_S    3600
#define SAMPLE_INTERVAL_S      5

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[SHT35_MEASURE_CMD_LEN] = {
        (uint8_t)((SHT35_MEASURE_HIGHREP >> 8) & 0xFF),
        (uint8_t)(SHT35_MEASURE_HIGHREP & 0xFF)
    };
    uint8_t data[SHT35_READ_LEN];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, SHT35_MEASURE_CMD_LEN);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed: %d\n", rc);
        return -1;
    }

    gpioDelay(SHT35_MEAS_DELAY_US);

    rc = i2cReadDevice(handle, (char *)data, SHT35_READ_LEN);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", rc);
        return -1;
    }
