            if (log_data(pressure, temperature) < 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

