/*
 * SHT35-DIS-B temperature/humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT35 VDD  -> Pi 3V3  (pin 1)
 *   SHT35 GND  -> Pi GND  (pin 9)
 *   SHT35 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   SHT35 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c
 *
 * The SHT35-DIS-B is a single-wire, I2C sensor from Sensirion.
 * It supports clock-stretching (SCL low time up to 15.4 ms) and
 * the single-shot high-repeatability measurement command.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT35_ADDR     0x45
#define CSV_FILENAME   "environment.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_DELAY_MS  20         /* SHT35 high-rep measurement ~15 ms */

/* SHT35 single-shot, clock-stretching disabled, high repeatability */
#define CMD_MSB        0x2C
#define CMD_LSB        0x06

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sht_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Issue the single-shot measurement command, wait, then read 6 bytes.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int sht35_read(int fd, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { CMD_MSB, CMD_LSB };
    ssize_t w = write(fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[6];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    if (sht_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -2;
    }
    if (sht_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity)
{
    int need_header = 0;
    FILE *check = fopen(filename, "r");
    if (!check) {
        need_header = 1;
    } else {
        fseek(check, 0, SEEK_END);
        if (ftell(check) == 0)
            need_header = 1;
        fclose(check);
    }

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SHT35_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started on %s (addr 0x%02X). Press Ctrl+C to stop.\n", I2C_BUS, SHT35_ADDR);

    while (g_running) {
        float temperature, humidity;
        int rc = sht35_read(fd, &temperature, &humidity);
        if (rc == 0) {
            printf("T=%.2f C  H=%.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else if (rc == -1) {
            fprintf(stderr, "Sensor read error; will retry next cycle.\n");
        } else {
            fprintf(stderr, "CRC error; will retry next cycle.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    close(fd);
    return EXIT_SUCCESS;
}

