#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

/* Si7021 commands */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUMID_HOLD  0xE5
#define CMD_RESET               0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00, no reflection, no final XOR)     */
/* Si7021 datasheet: CRC-8, polynomial x^8 + x^5 + x^4 + 1 (0x31)      */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c_read_bytes: read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: short read (%zd of %zu bytes)\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read with timeout                                            */
/* ------------------------------------------------------------------ */
static int read_measurement(int fd, uint8_t cmd, uint16_t *raw)
{
    uint8_t buf[3];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    /* Si7021 conversion time: ~11 ms for temperature, ~11 ms for humidity */
    struct timespec ts_start, ts_now;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    ts_start.tv_sec += 12; /* 12 ms margin */

    while (1) {
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;

        struct timespec ts_now;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long elapsed_ms = (ts_now.tv_sec - ts_start.tv_sec) * 1000L
                        + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000L;

        if (elapsed_ms > POLL_TIMEOUT_MS) {
            fprintf(stderr, "read_measurement: timeout waiting for data (cmd 0x%02X)\n", cmd);
            return -1;
        }

        if (crc8(buf, 2) == buf[2])
            break;

        /* NACK or bad CRC — keep polling */
    }

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Temperature                                                         */
/* ------------------------------------------------------------------ */
static int read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_TEMP_HOLD, &raw) < 0)
        return -1;

    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Humidity                                                            */
/* ------------------------------------------------------------------ */
static int read_humidity(int fd, float *rh)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_HUMID_HOLD, &raw) < 0)
        return -1;

    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("log_data: fopen failed");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    } else {
        fprintf(fp, "1970-01-01T00:00:00,%.2f,%.2f\n", temp_c, rh);
    }

    fclose(fp);
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("log_error: fopen failed");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    } else {
        fprintf(fp, "1970-01-01T00:00:00,ERROR,%s\n", msg);
    }
    fclose(fp);
    fprintf(stderr, "ERROR: %s\n", msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0)
            perror("cleanup: ioctl I2C_SLAVE failed");
        else
            i2c_write_cmd(g_i2c_fd, CMD_RESET);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence with a reset command */
    if (i2c_write_cmd(g_i2c_fd, CMD_RESET) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", SI7021_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(15000); /* reset takes ~15 ms */

    /* Write CSV header if file is new/empty */
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    printf("Greenhouse monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh;

        if (read_temperature(g_i2c_fd, &temp_c) < 0) {
            log_error("temperature read failed");
        } else if (read_humidity(g_i2c_fd, &rh) < 0) {
            log_error("humidity read failed");
        } else {
            log_data(temp_c, rh);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

