/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x260 (10-bit, 0x26 on the bus)
 * Continuous measurement command: 0x362F
 * Conversion time: 45 ms
 * Data format: 9 bytes = 3 words + 3 CRC bytes
 * CRC-8 polynomial: 0x31, init: 0xFF
 *
 * Build: gcc -O2 -Wall -o pressure_logger pressure_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS_NAME      "i2c-1"
#define I2C_ADDR_10BIT    0x260
#define I2C_ADDR_8BIT     0x26
#define CONT_MEAS_CMD     0x362F
#define CONVERSION_MS     45
#define LOG_INTERVAL_S    5
#define LOG_FILE          "pressure_log.txt"
#define MAX_RETRIES       3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as documented by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure)
{
    if (i2c_write_cmd(fd, CONT_MEAS_CMD) < 0)
        return -1;

    usleep(CONVERSION_MS * 1000);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *pressure = (float)raw / 100.0f;
    return 0;
}

static void log_pressure(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f Pa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        fclose(g_log);
        return EXIT_FAILURE;
    }

    struct gpiod_line *sda = gpiod_chip_get_line(chip, 2);
    struct gpiod_line *scl = gpiod_chip_get_line(chip, 3);
    if (!sda || !scl) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sda, "sdp800", 0) < 0 ||
        gpiod_line_request_output(scl, "sdp800", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS_NAME, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR_10BIT) < 0) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDR_8BIT) < 0) {
            perror("ioctl I2C_SLAVE");
            close(fd);
            gpiod_line_release(sda);
            gpiod_line_release(scl);
            gpiod_chip_close(chip);
            fclose(g_log);
            return EXIT_FAILURE;
        }
    }

    printf("SDP800 logger started. Logging to %s every %d s.\n",
           LOG_FILE, LOG_INTERVAL_S);

    while (g_running) {
        float pressure = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_pressure(fd, &pressure) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed.\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                usleep(100000);
        }

        if (ok) {
            log_pressure(g_log, pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts.\n", MAX_RETRIES);
        }

        for (int s = 0; s < LOG_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    close(fd);
    gpiod_line_release(sda);
    gpiod_line_release(scl);
    gpiod_chip_close(chip);
    fclose(g_log);
    return EXIT_SUCCESS;
}

