#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

#define HAFBLF0100A2AX5_REG_STATUS 0x00
#define HAFBLF0100A2AX5_REG_PRESSURE 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(int handle, float *pressure) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, HAFBLF0100A2AX5_REG_PRESSURE, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw * 0.01f;
    return 0;
}

static float calculate_flow_rate(float pressure) {
    return pressure * 0.1f;
}

static void control_fan(float flow_rate) {
    int duty = (int)(flow_rate * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_data(FILE *fp, float pressure) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);
    gpioPWM(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        float pressure;
        if (read_pressure(i2c_handle, &pressure) != 0) {
            fprintf(stderr, "Sensor read failed; continuing\n");
        } else {
            float flow_rate = calculate_flow_rate(pressure);
            control_fan(flow_rate);
            log_data(log_file, pressure);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

