#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0xB4
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s\n", ts, msg);
        fflush(log_file);
    }
}

static int init_lps33hw(void) {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus 1 at address 0xB4");
        return -1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who < 0) {
        log_error("Failed to read WHO_AM_I register");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x84) < 0) {
        log_error("Failed to write CTRL_REG1");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        log_error("Failed to write CTRL_REG2");
        return -1;
    }
    return 0;
}

static int read_lps33hw(float *pressure, float *temperature) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buf, 6) != 6) {
        log_error("Failed to read pressure/temperature block");
        return -1;
    }

    int32_t raw_p = (int32_t)((uint8_t)buf[2] << 16) |
                   (int32_t)((uint8_t)buf[1] << 8)  |
                   (int32_t)((uint8_t)buf[0]);
    int16_t raw_t = (int16_t)((uint8_t)buf[5] << 8) |
                    (int16_t)((uint8_t)buf[4]);

    *pressure = (float)raw_p / 100.0f;
    *temperature = (float)raw_t / 100.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", ts, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open environmental_data.txt");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_lps33hw() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    float pressure, temperature;
    while (running) {
        if (read_lps33hw(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        }
        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

