        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_lps33hw() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    float pressure, temperature;
    while (running) {
        if (read_lps33hw(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        }
        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

