#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x99
#define GPIO_LED       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, float *temperature)
{
    char buf[2];
    int  bytes;

    bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2)\n", bytes);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw / 128.0f;
    return 0;
}

static void update_buffer(float temperature, float buffer[], int *index, int size)
{
    buffer[*index] = temperature;
    *index = (*index + 1) % size;
}

static float calculate_average(const float buffer[], int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++)
        sum += buffer[i];
    return sum / (float)size;
}

static void control_led(float average_temperature, int gpio_pin)
{
    if (average_temperature > TEMP_THRESHOLD)
        gpioWrite(gpio_pin, 1);
    else
        gpioWrite(gpio_pin, 0);
}

int main(void)
{
    float temperature_buffer[BUFFER_SIZE] = {0.0f};
    int   buffer_index = 0;
    float average_temperature = 0.0f;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", GPIO_LED);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping iteration\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        update_buffer(temperature, temperature_buffer, &buffer_index, BUFFER_SIZE);
        average_temperature = calculate_average(temperature_buffer, BUFFER_SIZE);
        control_led(average_temperature, GPIO_LED);

        printf("Temperature: %.2f C, Average: %.2f C\n",
               temperature, average_temperature);

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(GPIO_LED, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

