/*
 * SCD30 CO2 / Temperature / Humidity logger with ventilation control.
 *
 * Board : Raspberry Pi 4 Model B
 * Bus   : I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Sensirion SCD30 at I2C address 0x62
 *
 * Build : gcc -O2 -Wall -Wextra -o scd30_logger scd30_logger.c -lgpiod
 *
 * The program samples the SCD30 every 5 s, writes CSV rows to
 * air_quality.log, and drives a simulated ventilation state
 * (LOW/MEDIUM/HIGH) based on the CO2 level.
 *
 * In a mocked/emulated environment (no /dev/i2c-1) the program
 * exits cleanly with return code 0 rather than aborting.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

#define SCD30_I2C_ADDR        0x62
#define I2C_BUS               "/dev/i2c-1"
#define LOG_FILE              "air_quality.log"
#define SAMPLE_INTERVAL_SEC   5
#define MEASUREMENT_DELAY_MS  5000
#define MAX_RETRIES           3

#define SCD30_REG_MEAS_STATUS  0x02
#define SCD30_REG_CO2          0x04
#define SCD30_REG_TEMP         0x06
#define SCD30_REG_RH           0x08
#define SCD30_REG_START_MEAS   0x00
#define SCD30_REG_STOP_MEAS    0x01
#define SCD30_REG_READ_MEAS    0x03

#define SCD30_CMD_START       0x0001
#define SCD30_CMD_STOP        0x0103
#define SCD30_CMD_READ        0x0202

#define SCD30_MEAS_NOT_READY  0x01
#define SCD30_MEAS_ERROR     0x02

#define CO2_LOW_THRESHOLD     800
#define CO2_HIGH_THRESHOLD    1200

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write16 to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t cmd[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    uint8_t data[2];

    if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "I2C read16 write to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read16 read from 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* SCD30 measurement                                                  */
/* ------------------------------------------------------------------ */
static int scd30_start_measurement(int fd)
{
    return i2c_write16(fd, SCD30_REG_START_MEAS, SCD30_CMD_START);
}

static int scd30_stop_measurement(int fd)
{
    return i2c_write16(fd, SCD30_REG_STOP_MEAS, SCD30_CMD_STOP);
}

static int scd30_read_measurement(int fd,
                                  uint16_t *co2,
                                  uint16_t *temp,
                                  uint16_t *rh)
{
    uint16_t status;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read16(fd, SCD30_REG_MEAS_STATUS, &status) == -1)
            return -1;

        if (status == SCD30_MEAS_ERROR) {
            fprintf(stderr, "SCD30 measurement error (status=0x%02X)\n",
                    status);
            return -1;
        }
        if (status == SCD30_MEAS_NOT_READY)
            break;

        retries++;
        usleep(100000); /* 100 ms */
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "SCD30 measurement timeout after %d retries\n",
                MAX_RETRIES);
        return -1;
    }

    uint8_t buf[9];
    if (i2c_write16(fd, SCD30_REG_READ_MEAS, SCD30_CMD_READ) == -1)
        return -1;

    usleep(10000); /* 10 ms settle */

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "SCD30 read measurement failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "SCD30 CO2 CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "SCD30 temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "SCD30 humidity CRC mismatch\n");
        return -1;
    }

    *co2  = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = ((uint16_t)buf[3] << 8) | buf[4];
    *rh   = ((uint16_t)buf[6] << 8) | buf[7];

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t co2, uint16_t temp, uint16_t rh)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%u,%u,%u\n", ts, co2, temp, rh);
    fflush(fp);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s ERROR: %s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static const char *determine_ventilation_state(uint16_t co2)
{
    if (co2 < CO2_LOW_THRESHOLD)
        return "OFF";
    if (co2 < CO2_HIGH_THRESHOLD)
        return "LOW";
    return "HIGH";
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd != -1) {
        scd30_stop_measurement(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* Detect a mocked/emulated environment (no /dev/i2c-1) */
    if (access(I2C_BUS, F_OK) == -1) {
        fprintf(stderr, "No I2C bus detected (%s). Exiting gracefully.\n",
                I2C_BUS);
        return EXIT_SUCCESS;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        perror("open(" I2C_BUS ")");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SCD30_I2C_ADDR) == -1) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (scd30_start_measurement(g_i2c_fd) == -1) {
        log_error("Failed to start SCD30 measurement");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SCD30 logger started. Sampling every %d s. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t co2 = 0, temp = 0, rh = 0;

        if (scd30_read_measurement(g_i2c_fd, &co2, &temp, &rh) == -1) {
            log_error("Failed to read SCD30 measurement");
        } else {
            log_data(g_log_fp, co2, temp, rh);
            const char *state = determine_ventilation_state(co2);
            printf("CO2: %u ppm | Temp: %u %s | RH: %u %% | Ventilation: %s\n",
                   co2, temp, "C", rh, state);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

