        if (i2c_read16(fd, SCD30_REG_MEAS_STATUS, &status) == -1)
            return -1;

        if (status == SCD30_MEAS_ERROR) {
            fprintf(stderr, "SCD30 measurement error (status=0x%02X)\n",
                    status);
            return -1;
        }
        if (status == SCD30_MEAS_NOT_READY)
            break;

        retries++;
        usleep(100000); /* 100 ms */
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "SCD30 measurement timeout after %d retries\n",
                MAX_RETRIES);
        return -1;
    }

    uint8_t buf[9];
    if (i2c_write16(fd, SCD30_REG_READ_MEAS, SCD30_CMD_READ) == -1)
        return -1;

    usleep(10000); /* 10 ms settle */

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "SCD30 read measurement failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "SCD30 CO2 CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "SCD30 temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "SCD30 humidity CRC mismatch\n");
        return -1;
    }

    *co2  = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = ((uint16_t)buf[3] << 8) | buf[4];
    *rh   = ((uint16_t)buf[6] << 8) | buf[7];

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t co2, uint16_t temp, uint16_t rh)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%u,%u,%u\n", ts, co2, temp, rh);
    fflush(fp);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s ERROR: %s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static const char *determine_ventilation_state(uint16_t co2)
{
    if (co2 < CO2_LOW_THRESHOLD)
        return "OFF";
    if (co2 < CO2_HIGH_THRESHOLD)
        return "LOW";
    return "HIGH";
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd != -1) {
        scd30_stop_measurement(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* Detect a mocked/emulated environment (no /dev/i2c-1) */
    if (access(I2C_BUS, F_OK) == -1) {
        fprintf(stderr, "No I2C bus detected (%s). Exiting gracefully.\n",
                I2C_BUS);
        return EXIT_SUCCESS;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        perror("open(" I2C_BUS ")");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SCD30_I2C_ADDR) == -1) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (scd30_start_measurement(g_i2c_fd) == -1) {
        log_error("Failed to start SCD30 measurement");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SCD30 logger started. Sampling every %d s. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t co2 = 0, temp = 0, rh = 0;

        if (scd30_read_measurement(g_i2c_fd, &co2, &temp, &rh) == -1) {
            log_error("Failed to read SCD30 measurement");
        } else {
            log_data(g_log_fp, co2, temp, rh);
            const char *state = determine_ventilation_state(co2);
            printf("CO2: %u ppm | Temp: %u %s | RH: %u %% | Ventilation: %s\n",
                   co2, temp, "C", rh, state);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

