#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR 0x20
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp32(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) return -1;

    gpioDelay(20000);

    rc = i2cReadDevice(handle, (char *)buf, 9);
    if (rc < 0) return -1;
    if (rc != 9) return -2;

    if (crc8(&buf[0], 2) != buf[2]) return -3;
    if (crc8(&buf[3], 2) != buf[5]) return -3;
    if (crc8(&buf[6], 2) != buf[8]) return -3;

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t raw_scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (raw_scale_factor == 0) return -4;

    *pressure = (float)raw_pressure / (float)raw_scale_factor;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;
    float pressure, temperature;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval. Using default: %d ms\n", DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SDP32_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int consecutive_errors = 0;

    while (running) {
        int result = -1;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            result = read_sdp32(i2c_handle, &pressure, &temperature);
            if (result == 0) break;
            gpioDelay(100000);
        }

        if (result == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C\n", ts, pressure, temperature);
            fflush(stdout);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive I2C errors reached. Exiting.\n");
                break;
            }
            if (running) {
                fprintf(stderr, "I2C read error (code %d). Retrying...\n", result);
            }
        }

        if (running) {
            gpioDelay(interval_ms * 1000);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

