/*
 * SDP810-125Pa differential pressure reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -li2c
 *
 * The SDP810 is a Sensirion differential pressure sensor that returns
 * 9 bytes on a single read:  pressure(2)+crc, temperature(2)+crc,
 * pressure_scale(2)+crc, temperature_scale(2)+crc.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <i2c/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x200   /* 10-bit address: 0x20 << 1 */
#define READ_LEN       9
#define CONV_DELAY_MS  45
#define POLL_INTERVAL  1      /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int sdp_read(int fd, float *pressure, float *temperature)
{
    uint8_t buf[READ_LEN];

    ssize_t n = i2c_read(fd, buf, READ_LEN);
    if (n != READ_LEN) {
        if (n < 0)
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C short read: %zd of %d bytes\n", n, READ_LEN);
        return -1;
    }

    /* Validate CRC on each 3-byte word */
    for (int i = 0; i < 4; i++) {
        if (sdp_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_p = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t scale_t = (int16_t)((buf[8] << 8) | buf[9]);

    if (scale_p == 0 || scale_t == 0) {
        fprintf(stderr, "Invalid scale factor (p=%d, t=%d)\n", scale_p, scale_t);
        return -1;
    }

    *pressure    = (float)raw_p / (float)scale_p;
    *temperature = (float)raw_t / (float)scale_t;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = i2c_open(I2C_BUS, SDP810_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s at 0x%03X: %s\n",
                I2C_BUS, SDP810_ADDR, strerror(errno));
        return EXIT_FAILURE;
    }

    printf("SDP810 reader started on %s (addr 0x%03X). Press Ctrl+C to exit.\n",
           I2C_BUS, SDP810_ADDR);

    while (g_running) {
        float pressure, temperature;

        if (sdp_read(fd, &pressure, &temperature) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("[%s] Pressure: %.2f Pa, Temperature: %.2f C\n",
                   ts, pressure, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    if (i2c_close(fd) < 0)
        perror("i2c_close");
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

