#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define SI7051_TEMP_REG 0x00
#define SI7051_MEASUREMENT_CMD 0xE3
#define SI7051_READ_TEMP_CMD 0xE0
#define SI7051_READ_ID_CMD 0xFA
#define SI7051_READ_ID_LEN 8
#define SI7051_CHIP_ID 0x7051
#define SI7051_MEASUREMENT_DELAY_US 10000
#define SAMPLE_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_id(int handle, uint16_t *chip_id) {
    char cmd = SI7051_READ_ID_CMD;
    char buf[SI7051_READ_ID_LEN];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write sensor ID read command: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, SI7051_READ_ID_LEN) != SI7051_READ_ID_LEN) {
        fprintf(stderr, "Error: Failed to read sensor ID: %s\n", strerror(errno));
        return -1;
    }

    uint16_t id = ((uint16_t)(buf[1] & 0x0F) << 8) | (uint8_t)buf[0];
    if (id != SI7051_CHIP_ID) {
        fprintf(stderr, "Error: Unexpected sensor ID 0x%04X (expected 0x%04X)\n", id, SI7051_CHIP_ID);
        return -1;
    }

    *chip_id = id;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    char cmd = SI7051_MEASUREMENT_CMD;
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write temperature measurement command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(SI7051_MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *temperature = -46.85 + 175.72 * (float)raw / 65536.0;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SI7051_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t chip_id = 0;
    if (read_sensor_id(i2c_handle, &chip_id) != 0) {
        fprintf(stderr, "Error: Sensor not detected or incorrect ID\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7051 detected (ID: 0x%04X). Starting temperature readings every 5 seconds...\n", chip_id);

    while (running) {
        float temperature = 0.0f;

        if (read_temperature(i2c_handle, &temperature) == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "Warning: Failed to read temperature. Retrying next cycle.\n");
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

