    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, READ_LEN);
    if (result != READ_LEN) {
        fprintf(stderr, "Error reading pressure data: expected %d bytes, got %d (errno: %s)\n",
                READ_LEN, result, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw / 100.0f;
    return 0;
}

