#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define MEASURE_CMD    0x10
#define READ_CMD       0x00
#define MEASURE_DELAY  7000   /* microseconds */
#define LOOP_DELAY     5000000 /* microseconds (5 s) */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(buf, len, "UNKNOWN");
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length read to confirm the sensor is present. */
    int probe = i2cReadByte(g_i2c_handle);
    if (probe < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (probe failed)\n", I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 sensor detected at 0x%02X. Starting periodic reads.\n", I2C_ADDR);
    fflush(stdout);

    while (g_running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        int rc = i2cWriteByte(g_i2c_handle, MEASURE_CMD);
        if (rc < 0) {
            fprintf(stderr, "%s - I2C write error (cmd 0x%02X): %d\n", ts, MEASURE_CMD, rc);
            gpioDelay(LOOP_DELAY);
            continue;
        }

        gpioDelay(MEASURE_DELAY);

        char data[6];
        int n = i2cReadDevice(g_i2c_handle, data, 6);
        if (n != 6) {
            fprintf(stderr, "%s - I2C read error: expected 6 bytes, got %d\n", ts, n);
            gpioDelay(LOOP_DELAY);
            continue;
        }

        /* Check for sensor-absent / bus error: all bytes 0xFF or 0x00. */
        int all_ff = 1, all_00 = 1;
        for (int i = 0; i < 6; i++) {
            if (data[i] != 0xFF) all_ff = 0;
            if (data[i] != 0x00) all_00 = 0;
        }
        if (all_ff || all_00) {
            fprintf(stderr, "%s - Sensor absent or bus error (data: %02X %02X %02X %02X %02X %02X)\n",
                    ts, data[0], data[1], data[2], data[3], data[4], data[5]);
            gpioDelay(LOOP_DELAY);
            continue;
        }

        /* Parse: 2 bytes temperature (MSB first), 2 bytes pressure (MSB first). */
        uint16_t raw_t = ((uint16_t)(data[0] & 0xFF) << 8) | (uint16_t)(data[1] & 0xFF);
        uint16_t raw_p = ((uint16_t)(data[2] & 0xFF) << 8) | (uint16_t)(data[3] & 0xFF);

        float temperature = (float)raw_t / 100.0f;
        float pressure    = (float)raw_p / 100.0f;

        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temperature, pressure);
        fflush(stdout);

        gpioDelay(LOOP_DELAY);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

