#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX90819_ADDR 0x50
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(int fd, float *pressure) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadDevice(fd, buf, 2);
        if (result == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *pressure = (float)raw / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (returned %d): %s\n",
                attempt + 1, result, strerror(errno));
        gpioDelay(10000);
    }
    return -1;
}

static void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = i2cOpen(I2C_BUS, MLX90819_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, MLX90819_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float pressure;
        if (read_pressure(i2c_fd, &pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure after %d attempts\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

