/*
 * HVAC airflow monitor using Sensirion SDP800-500Pa differential pressure sensor.
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   Sensor SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   Sensor SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   Sensor VDD  -> 3.3 V
 *   Sensor GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_monitor airflow_monitor.c -li2c
 *
 * NOTE: On many Raspberry Pi models the I2C bus is /dev/i2c-1.  If your
 * system uses a different bus path (e.g. /dev/i2c-2 on a Pi 4) adjust
 * the I2C_BUS_PATH macro accordingly.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_PATH "/dev/i2c-1"
#define SDP800_I2C_ADDRESS 0x2000  /* 16-bit address, big-endian on the bus */

#define LOG_FILE_NAME "pressure_log.txt"
#define SAMPLE_INTERVAL_US 45000   /* 45 ms measurement + conversion time */
#define MEASUREMENT_DELAY_US 45000 /* 45 ms per datasheet */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */

static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write16(int fd, uint16_t addr)
{
    uint8_t buf[2] = { (uint8_t)(addr >> 8), (uint8_t)(addr & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write16 failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */

/*
 * Trigger a measurement and read 9 bytes:
 *   word0: differential pressure (Pa)  [CRC byte follows]
 *   word1: temperature (°C)             [CRC byte follows]
 *   word2: scale factor                 [CRC byte follows]
 */
static int read_sdp800(int fd, float *pressure_pa, float *temperature_c)
{
    uint8_t data[9];

    if (i2c_write16(fd, SDP800_I2C_ADDRESS) < 0)
        return -1;

    usleep(MEASUREMENT_DELAY_US);

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    /* Scale factors from datasheet */
    *pressure_pa   = (float)raw_pressure / 200.0f;
    *temperature_c = (float)raw_temp / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, float pressure_pa, float temperature_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS_PATH, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_PATH, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%04X: %s\n",
                SDP800_I2C_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HVAC airflow monitor started. Logging to %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure_pa, temperature_c;

        if (read_sdp800(g_i2c_fd, &pressure_pa, &temperature_c) == 0) {
            log_data(g_log_file, pressure_pa, temperature_c);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure_pa, temperature_c);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

