#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDR 0x200
#define LOG_FILE "airflow_log.csv"
#define MEASUREMENT_DELAY_MS 8
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t data[3];

    if (i2c_write(fd, cmd, sizeof(cmd)) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read(fd, data, sizeof(data)) < 0) {
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        return -2;
    }

    int16_t raw = (data[0] << 8) | data[1];
    *pressure = (float)raw / 100.0f;
    return 0;
}

static int log_data(const char *filename, float pressure) {
    int needs_header = (access(filename, F_OK) == -1);
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        return -1;
    }

    if (needs_header) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure);

    if (fclose(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_I2C_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP800-500Pa airflow monitor started. Logging to %s\n", LOG_FILE);

    while (running) {
        float pressure;
        int rc = read_sdp800(fd, &pressure);

        if (rc == 0) {
            if (log_data(LOG_FILE, pressure) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            } else {
                printf("Pressure: %.2f Pa\n", pressure);
            }
        } else if (rc == -1) {
            fprintf(stderr, "I2C communication error: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "CRC mismatch - sensor may be absent or bus error\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

