#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90821_ADDR  0x50
#define LOG_FILE       "pressure_log.csv"
#define SAFE_MIN_KPA   200.0f
#define SAFE_MAX_KPA   250.0f
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3

/* MLX90821 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE_MSB  0x00
#define REG_PRESSURE_LSB  0x01
#define REG_TEMP_MSB      0x02
#define REG_TEMP_LSB      0x03
#define REG_CONFIG        0x04

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    ssize_t n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int init_sensor(int fd)
{
    /* Verify sensor presence by reading the configuration register */
    uint16_t cfg = 0;
    if (i2c_read_reg16(fd, REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", MLX90821_ADDR);
        return -1;
    }
    printf("MLX90821 detected (config=0x%04X)\n", cfg);
    return 0;
}

static int read_pressure(int fd, float *pressure_kPa)
{
    uint16_t raw = 0;
    if (i2c_read_reg16(fd, REG_PRESSURE_MSB, &raw) != 0)
        return -1;

    /* Convert raw 16-bit value to kPa (example scaling; adjust per datasheet) */
    int32_t signed_raw = (int32_t)raw;
    *pressure_kPa = (float)signed_raw * 0.1f;
    return 0;
}

static void log_pressure(FILE *fp, float pressure_kPa)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure_kPa);
    fflush(fp);
}

static void check_pressure_range(float pressure_kPa)
{
    if (pressure_kPa < SAFE_MIN_KPA || pressure_kPa > SAFE_MAX_KPA) {
        fprintf(stderr,
                "WARNING: Pressure %.2f kPa is outside safe range [%.1f, %.1f] kPa\n",
                pressure_kPa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX90821_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MLX90821_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_log_fp);
    if (pos == 0) {
        fprintf(g_log_fp, "timestamp,pressure_kPa\n");
        fflush(g_log_fp);
    }

    printf("Logging pressure to %s every %d second(s). Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float pressure = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_pressure(g_i2c_fd, &pressure) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; re-opening I2C bus.\n",
                    attempt + 1, MAX_RETRIES);
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            g_i2c_fd = open(I2C_BUS, O_RDWR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-open failed: %s\n", strerror(errno));
                break;
            }
            if (ioctl(g_i2c_fd, I2C_SLAVE, MLX90821_ADDR) < 0) {
                fprintf(stderr, "Re-set slave failed: %s\n", strerror(errno));
                break;
            }
        }

        if (!ok) {
            fprintf(stderr, "All %d read attempts failed; aborting.\n", MAX_RETRIES);
            break;
        }

        log_pressure(g_log_fp, pressure);
        check_pressure_range(pressure);
        sleep(SAMPLE_PERIOD);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

