#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define MEASUREMENT_INTERVAL 5
#define HIH6130_MEASUREMENT_DELAY_US 40000
#define HIH6130_STATUS_ERROR 0x01
#define HIH6130_STATUS_BUSY 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

static int roll_log_file(void) {
    if (log_file == NULL) {
        return 0;
    }

    if (ftruncate(fileno(log_file), 0) != 0) {
        perror("Error truncating log file");
        return -1;
    }

    if (rewind(log_file) != 0) {
        perror("Error rewinding log file");
        return -1;
    }

    return 0;
}

static int read_hih6130(float *temperature, float *humidity) {
    char buf[4];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    uint16_t raw_humidity = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_temperature = ((uint16_t)buf[2] << 8) | (uint8_t)buf[3];

    if (raw_humidity & HIH6130_STATUS_ERROR) {
        fprintf(stderr, "Sensor error detected\n");
        return -1;
    }

    if (raw_humidity & HIH6130_STATUS_BUSY) {
        fprintf(stderr, "Sensor busy, skipping reading\n");
        return -1;
    }

    *humidity = ((float)raw_humidity / 16383.0f) * 100.0f;
    *temperature = ((float)raw_temperature / 16383.0f) * 165.0f - 40.0f;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (read_hih6130(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        if (fseek(log_file, 0, SEEK_END) != 0) {
            perror("Error seeking in log file");
        } else {
            long file_size = ftell(log_file);
            if (file_size > LOG_FILE_SIZE_LIMIT) {
                if (roll_log_file() != 0) {
