#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO 4
#define LOG_FILE "pressure_log.txt"
#define SENT_TICK_US 3
#define SENT_SYNC_TICKS 56
#define SENT_MIN_TICKS 12
#define SENT_MAX_TICKS 271
#define SENT_TIMEOUT_US 1000000
#define SENT_ERROR_VALUE -1.0f

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(SENT_GPIO, PI_INPUT);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_sent_nibble(int *nibble) {
    uint32_t start_tick, end_tick;
    int level;
    int ticks = 0;
    int timeout = 0;

    /* Wait for falling edge (start of sync pulse) */
    while (gpioRead(SENT_GPIO) == 1) {
        if (timeout++ > SENT_TIMEOUT_US / SENT_TICK_US) {
            return -1;
        }
        gpioDelay(SENT_TICK_US);
    }
    start_tick = gpioTick();

    /* Measure sync pulse low time */
    while (gpioRead(SENT_GPIO) == 0) {
        if (timeout++ > SENT_TIMEOUT_US / SENT_TICK_US) {
            return -1;
        }
        gpioDelay(SENT_TICK_US);
    }
    end_tick = gpioTick();
    ticks = (int)(end_tick - start_tick) / SENT_TICK_US;

    if (ticks < SENT_SYNC_TICKS - 5 || ticks > SENT_SYNC_TICKS + 5) {
        return -2;
    }

    /* Wait for rising edge (start of data nibble) */
    while (gpioRead(SENT_GPIO) == 0) {
        if (timeout++ > SENT_TIMEOUT_US / SENT_TICK_US) {
            return -1;
        }
        gpioDelay(SENT_TICK_US);
    }
    start_tick = gpioTick();

    /* Measure data pulse high time */
    while (gpioRead(SENT_GPIO) == 1) {
        if (timeout++ > SENT_TIMEOUT_US / SENT_TICK_US) {
            return -1;
        }
        gpioDelay(SENT_TICK_US);
    }
    end_tick = gpioTick();
    ticks = (int)(end_tick - start_tick) / SENT_TICK_US;

    if (ticks < SENT_MIN_TICKS || ticks > SENT_MAX_TICKS) {
        return -3;
    }

    *nibble = ticks;
    return 0;
}

static float calculate_pressure(int nibble) {
    return (float)(nibble - 12) * 0.5f;
}

static int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    int status_nibble, data_nibble1, data_nibble2, data_nibble3, checksum_nibble;
    int i;
    float pressure;
    int error_code;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Starting SENT pressure sensor reading on GPIO%d...\n", SENT_GPIO);

    while (running) {
        error_code = 0;

        for (i = 0; i < 5; i++) {
            error_code = read_sent_nibble((i == 0) ? &status_nibble :
                                          (i == 1) ? &data_nibble1 :
                                          (i == 2) ? &data_nibble2 :
                                          (i == 3) ? &data_nibble3 :
                                          &checksum_nibble);
            if (error_code != 0) {
                break;
            }
        }

        if (error_code != 0) {
            if (error_code == -1) {
                fprintf(stderr, "Error: Sensor absent or bus timeout\n");
            } else if (error_code == -2) {
                fprintf(stderr, "Error: Invalid sync pulse width\n");
            } else if (error_code == -3) {
                fprintf(stderr, "Error: Invalid data pulse width\n");
            }
            gpioDelay(100000);
            continue;
        }

        int calculated_checksum = (status_nibble + data_nibble1 + data_nibble2 + data_nibble3) % 16;
        if (checksum_nibble != calculated_checksum) {
            fprintf(stderr, "Error: Checksum mismatch (calculated: %d, received: %d)\n",
                    calculated_checksum, checksum_nibble);
            gpioDelay(100000);
            continue;
        }

        pressure = calculate_pressure(data_nibble3);
        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Error: Failed to log pressure data\n");
        }

        printf("Pressure: %.2f Pa\n", pressure);
        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

