 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          1
#define TMP117_ADDR      0x49          /* ADDR pin tied to GND */
#define TMP117_REG_TEMP  0x00          /* Temperature register (16-bit, two's-complement) */
#define TMP117_REG_ID    0x0F          /* Device ID register */
#define TMP117_ID_VAL    0x1700        /* TMP117 device ID (12-bit, left-justified) */
#define LOG_FILE         "greenhouse_temps.dat"
#define SAMPLE_PERIOD_S  60            /* seconds between samples */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed (rc=%d): %s\n",
                reg, rc, strerror(errno));
        return -1;
    }
    /* TMP117 returns MSB first */
    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[2];
    buf[0] = (char)((val >> 8) & 0xFF);
    buf[1] = (char)(val & 0xFF);
    int rc = i2cWriteI2CBlockData(handle, reg, buf, 2);
    if (rc != 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed (rc=%d): %s\n",
                reg, rc, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- TMP117 driver ------------------------------- */
static int tmp117_init(int handle)
{
    int16_t id = 0;
    if (i2c_read_reg16(handle, TMP117_REG_ID, &id) != 0) {
        fprintf(stderr, "[TMP117] cannot read device ID\n");
        return -1;
    }
    if ((id & 0xFFF0) != TMP117_ID_VAL) {
        fprintf(stderr, "[TMP117] unexpected device ID 0x%04X (expected 0x%04X)\n",
                id & 0xFFF0, TMP117_ID_VAL);
        return -1;
    }
    printf("[TMP117] detected (ID=0x%04X)\n", id & 0xFFF0);
    return 0;
}

static int tmp117_read_celsius(int handle, float *temp_c)
{
    int16_t raw = 0;
    if (i2c_read_reg16(handle, TMP117_REG_TEMP, &raw) != 0)
        return -1;

    /* 16-bit two's-complement, LSB = 0.0078125 °C */
    int32_t s = (int32_t)raw;
    *temp_c = (float)s * 0.0078125f;
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static int log_temperature(FILE *fp, float temp_c)
{
    uint8_t bytes[4];
    /* little-endian float */
    bytes[0] = (uint8_t)(temp_c & 0xFF);
    bytes[1] = (uint8_t)((temp_c >> 8) & 0xFF);
    bytes[2] = (uint8_t)((temp_c >> 16) & 0xFF);
    bytes[3] = (uint8_t)((temp_c >> 24) & 0xFF);

    size_t n = fwrite(bytes, 1, sizeof(bytes), fp);
    if (n != sizeof(bytes)) {
        fprintf(stderr, "[LOG] write failed (wrote %zu of %zu): %s\n",
                n, sizeof(bytes), strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (tmp117_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMP117 not detected or ID mismatch\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "ab");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] greenhouse monitoring started (every %d s). Ctrl-C to stop.\n",
           SAMPLE_PERIOD_S);

    /* --- Main loop --- */
    while (g_running) {
        float temp_c = 0.0f;
        if (tmp117_read_celsius(g_i2c_handle, &temp_c) != 0) {
            fprintf(stderr, "[WARN] temperature read failed; will retry next cycle\n");
        } else {
            printf("[INFO] Temperature: %.2f °C\n", temp_c);
            if (log_temperature(g_log_file, temp_c) != 0) {
                fprintf(stderr, "[WARN] logging failed; continuing\n");
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    printf("\n[INFO] shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

