#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT40_ADDR 0x40
#define CMD_MEASURE_TEMP_HUMID 0x2C
#define CMD_MEASURE_TEMP_HUMID_HIGHREP 0x26
#define CMD_SOFT_RESET 0x80
#define CONVERSION_DELAY_US 10000
#define SAMPLE_INTERVAL_US 5000000
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sht40_reset(void) {
    char cmd = CMD_SOFT_RESET;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: SHT40 soft reset write failed\n");
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int sht40_measure(int high_repeatability) {
    char cmd = high_repeatability ? CMD_MEASURE_TEMP_HUMID_HIGHREP : CMD_MEASURE_TEMP_HUMID;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: SHT40 measurement command write failed\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int sht40_read_data(float *temperature, float *humidity) {
    char buf[6];
    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Error: SHT40 read failed\n");
        return -1;
    }
    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8((uint8_t *)buf + 3, 2) != (uint8_t)buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }
    uint16_t temp_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t hum_raw = ((uint16_t)(uint8_t)buf[3] << 8) | (uint8_t)buf[4];
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static int log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (sht40_reset() != 0) {
        fprintf(stderr, "Error: SHT40 reset failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    float temperature, humidity;
    while (!terminate) {
        if (sht40_measure(1) != 0) {
            fprintf(stderr, "Error: Measurement failed, retrying in 5 seconds\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (sht40_read_data(&temperature, &humidity) != 0) {
            fprintf(stderr, "Error: Data read failed, retrying in 5 seconds\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Error: Logging failed, retrying in 5 seconds\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    fprintf(stderr, "Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

