    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_tmp117(void) {
    /* Standby mode, 1 Hz conversion rate, 16-bit resolution, default config */
    uint16_t config = 0x0000;
    char buf[3];
    buf[0] = TMP117_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error writing TMP117 config register\n");
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    char reg = TMP117_REG_TEMP;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error selecting TMP117 temperature register\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading TMP117 temperature data\n");
        return -1;
    }
    int16_t raw = (data[0] << 8) | data[1];
    *temp = (float)raw / 100.0f;
    return 0;
}

static void add_to_buffer(float temp) {
    time(&buffer.data[buffer.head].timestamp);
    buffer.data[buffer.head].temperature = temp;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
}

static int save_buffer_to_file(void) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening log file for writing: %s\n", LOG_FILE);
        return -1;
    }
    size_t written = fwrite(&buffer, sizeof(buffer), 1, fp);
    if (written != 1) {
        fprintf(stderr, "Error writing buffer to log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file\n");
        return -1;
    }
    return 0;
}

static int load_buffer_from_file(void) {
    FILE *fp = fopen(LOG_FILE, "rb");
    if (!fp) return 0; /* file does not exist yet */
    size_t read = fread(&buffer, sizeof(buffer), 1, fp);
    if (read != 1) {
        fprintf(stderr, "Error reading buffer from log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file after read\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    save_buffer_to_file();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_tmp117() != 0) {
        cleanup();
        gpioTerminate();
        return 1;
    }

    if (load_buffer_from_file() != 0) {
        fprintf(stderr, "Failed to load buffer from file\n");
    }

    buffer.head = 0;
    buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    gpioTerminate();
    return 0;
}

