/*
 * SHTC3 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHTC3 VDD  -> Pin 1 (3.3 V)
 *   SHTC3 VSS  -> Pin 2 (GND)
 *   SHTC3 SDA  -> Pin 3 (GPIO2 / I2C bus 1 SDA)
 *   SHTC3 SCL  -> Pin 4 (GPIO3 / I2C bus 1 SCL)
 *
 * Build:  gcc -O2 -Wall -Wextra -o shtc3_logger shtc3_logger.c
 * Run:    ./shtc3_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHTC3_ADDR     0x70
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define CONV_WAIT_US   12400      /* 12.4 ms max conversion time */
#define MEAS_CMD_LEN   3
#define DATA_CMD_LEN   3
#define CLEANUP_CMD_LEN 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int shtc3_write_cmd(int handle, const uint8_t *cmd, size_t len)
{
    if (i2cWriteDevice(handle, (char *)cmd, len) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for command 0x%02X\n",
                cmd[0]);
        return -1;
    }
    return 0;
}

static int shtc3_read_data(int handle, uint8_t *buf, size_t len)
{
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    if (bytes != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes, got %d\n",
                len, bytes);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHTC3 measurement                                                   */
/* ------------------------------------------------------------------ */
static int shtc3_measure(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[MEAS_CMD_LEN] = { 0x2C, 0x06, 0x00 }; /* high repeatability */
    uint8_t data[DATA_CMD_LEN] = { 0 };

    if (shtc3_write_cmd(handle, cmd, MEAS_CMD_LEN) != 0)
        return -1;

    gpioDelay(CONV_WAIT_US);

    if (shtc3_read_data(handle, data, DATA_CMD_LEN) != 0)
        return -1;

    if (shtc3_crc8(data, 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (shtc3_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor cleanup (SHTC3 soft-reset)                                   */
/* ------------------------------------------------------------------ */
static void shtc3_cleanup(int handle)
{
    uint8_t reset_cmd = 0x80;
    (void)i2cWriteDevice(handle, (char *)&reset_cmd, 1);
    gpioDelay(1000); /* 1 ms reset settling time */
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("[ERROR] fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    shtc3_cleanup(g_i2c_handle);

    while (g_running) {
        float temperature, humidity;

        if (shtc3_measure(g_i2c_handle, &temperature, &humidity) == 0) {
            if (temperature < -40.0f || temperature > 125.0f ||
                humidity < 0.0f   || humidity > 100.0f) {
                fprintf(stderr,
                        "[WARN] Out-of-range reading: T=%.2f C, RH=%.2f %%\n",
                        temperature, humidity);
            } else {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                       temperature, humidity);
                if (log_data(LOG_FILE, temperature, humidity) != 0)
                    fprintf(stderr, "[WARN] Failed to log data\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Graceful cleanup */
    if (g_i2c_handle >= 0) {
        shtc3_cleanup(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

