#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x10
#define SI7202_REG_TEMP 0x00
#define SI7202_REG_MAG 0x01
#define SI7202_REG_CONFIG 0x02
#define SI7202_CONFIG_DEFAULT 0x00
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "mag_temp_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SI7202_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    if (i2cWriteByteData(i2c_handle, SI7202_REG_CONFIG, SI7202_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Error writing config register to Si7202\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *temperature, float *magnetic_field) {
    int raw_temp, raw_mag;
    int16_t temp_raw, mag_raw;

    raw_temp = i2cReadByteData(i2c_handle, SI7202_REG_TEMP);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw_temp);
        return -1;
    }

    raw_mag = i2cReadByteData(i2c_handle, SI7202_REG_MAG);
    if (raw_mag < 0) {
        fprintf(stderr, "Error reading magnetic field register: %d\n", raw_mag);
        return -1;
    }

    temp_raw = (int16_t)((raw_temp & 0xFF) << 8);
    temp_raw |= (raw_temp >> 8) & 0xFF;
    *temperature = (float)temp_raw / 10.0f;

    mag_raw = (int16_t)((raw_mag & 0xFF) << 8);
    mag_raw |= (raw_mag >> 8) & 0xFF;
    *magnetic_field = (float)mag_raw / 100.0f;

    return 0;
}

static float calculate_rotational_speed(float magnetic_field) {
    return magnetic_field * 10.0f;
}

static int log_data(float rotational_speed, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rotational_speed, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static int log_missing_data(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,NaN,NaN\n", timestamp) < 0) {
        fprintf(stderr, "Error writing missing data to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file after missing data\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, magnetic_field, rotational_speed;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Speed (RPM),Temperature (C)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    while (running) {
        if (read_sensor_data(&temperature, &magnetic_field) == 0) {
            rotational_speed = calculate_rotational_speed(magnetic_field);
            if (log_data(rotational_speed, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, logging NaN values\n");
            if (log_missing_data() != 0) {
                fprintf(stderr, "Error logging missing data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

