#define DHT11_DATA_SIZE		40

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
	(void)sig;
	g_running = 0;
}

static void log_error(const char *msg)
{
	FILE *fp = fopen(DHT11_ERROR_FILE, "a");
	if (!fp) {
		fprintf(stderr, "Error opening error log: %s\n", strerror(errno));
		return;
	}
	time_t t = time(NULL);
	struct tm tm;
	if (localtime_r(&t, &tm)) {
		fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d - %s\n",
			tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
			tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
	}
	fclose(fp);
}

static void log_reading(float temp, float hum)
{
	FILE *fp = fopen(DHT11_READING_FILE, "a");
	if (!fp) {
		fprintf(stderr, "Error opening reading log: %s\n", strerror(errno));
		return;
	}
	time_t t = time(NULL);
	struct tm tm;
	if (localtime_r(&t, &tm)) {
		fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Temperature: %.1f C, Humidity: %.1f %%\n",
			tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
			tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
	}
	fclose(fp);
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us)
{
	int elapsed = 0;
	int step = 100;
	while (elapsed < timeout_us) {
		int val = gpiod_line_get_value(line);
		if (val < 0) {
			log_error("DHT11: read failed during wait");
			return -1;
		}
		if (val == target)
			return 0;
		usleep(step);
		elapsed += step;
	}
	return -1;
}

static int wait_for_level_us(struct gpiod_line *line, int target, int timeout_us)
{
	int elapsed = 0;
	int step = 10;
	while (elapsed < timeout_us) {
		int val = gpiod_line_get_value(line);
		if (val < 0) {
			log_error("DHT11: read failed during wait");
