static int read_dht11(struct gpiod_line *line, uint8_t data[])
{
	memset(data, 0, DHT11_DATA_SIZE);

	/* Start signal: pull low for >= 18 ms, then release */
	if (gpiod_line_request_output(line, "dht11", 0) < 0) {
		log_error("DHT11: request_output failed");
		return -1;
	}
	if (gpiod_line_set_value(line, 0) < 0) {
		log_error("DHT11: set_value low failed");
		return -1;
	}
	usleep(DHT11_START_LOW_US);

	if (gpiod_line_set_value(line, 1) < 0) {
		log_error("DHT11: set_value high failed");
		return -1;
	}
	usleep(DHT11_START_HIGH_US);

	/* Switch to input; sensor will pull low for response */
	if (gpiod_line_request_input(line, "dht11") < 0) {
		log_error("DHT11: request_input failed");
		return -1;
	}

	/* Wait for sensor response: ~80 us low then ~80 us high */
	if (wait_for_level_us(line, 0, DHT11_TIMEOUT_US) < 0) {
		log_error("DHT11: timeout waiting for response low");
		return -1;
	}
	if (wait_for_level_us(line, 1, DHT11_TIMEOUT_US) < 0) {
		log_error("DHT11: timeout waiting for response high");
		return -1;
	}
	if (wait_for_level_us(line, 0, DHT11_TIMEOUT_US) < 0) {
		log_error("DHT11: timeout waiting for response end");
		return -1;
	}

	/* Read 40 data bits */
	for (int i = 0; i < DHT11_DATA_SIZE; i++) {
		/* Each bit starts with ~50 us low */
		if (wait_for_level_us(line, 1, DHT11_TIMEOUT_US) < 0) {
			char msg[128];
			snprintf(msg, sizeof(msg), "DHT11: timeout waiting for bit %d high start", i);
			log_error(msg);
			return -1;
		}

		/* Measure high duration: ~26 us = '0', ~70 us = '1' */
		int high_start = 0;
		int high_end = 0;
		int elapsed = 0;
		int step = 10;
		int val = gpiod_line_get_value(line);
		if (val < 0) {
			log_error("DHT11: read failed during bit high measurement");
			return -1;
		}
		if (val != 1) {
			char msg[128];
			snprintf(msg, sizeof(msg), "DHT11: unexpected low during bit %d high", i);
			log_error(msg);
			return -1;
		}
		high_start = (int)elapsed;

		while (elapsed < DHT11_TIMEOUT_US) {
			usleep(step);
			elapsed += step;
			int val = gpiod_line_get_value(line);
			if (val < 0) {
				log_error("DHT11: read failed during bit high measurement");
				return -1;
			}
			if (val == 0) {
				high_end = elapsed;
				break;
			}
		}
		if (high_end == 0) {
			char msg[128];
			snprintf(msg, sizeof(msg), "DHT11: timeout waiting for bit %d high end", i);
			log_error(msg);
			return -1;
		}

		int high_us = high_end - high_start;
		if (high_us > DHT11_BIT_HIGH_THRESHOLD_US) {
			data[i / 8] |= (1 << (7 - (i % 8)));
		}
	}

	/* Verify checksum */
	uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
	if (checksum != data[4]) {
		char msg[128];
		snprintf(msg, sizeof(msg), "DHT11: checksum error (calc=%u, recv=%u)", checksum, data[4]);
		log_error(msg);
		return -1;
	}

	return 0;
}

int main(void)
{
	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = sig_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
		fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
		return 1;
	}

	struct gpiod_chip *chip = gpiod_chip_open_by_name(DHT11_CHIP_NAME);
	if (!chip) {
		fprintf(stderr, "Failed to open %s: %s\n", DHT11_CHIP_NAME, strerror(errno));
		return 1;
	}

	struct gpiod_line *line = gpiod_chip_get_line(chip, DHT11_GPIO_LINE);
	if (!line) {
		fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT11_GPIO_LINE, strerror(errno));
		gpiod_chip_close(chip);
		return 1;
	}

	uint8_t data[DHT11_DATA_SIZE];
	int consecutive_failures = 0;

	while (g_running) {
		if (read_dht11(line, data) == 0) {
			float humidity = (float)data[0] + (float)data[1] / 10.0f;
			float temperature = (float)data[2] + (float)data[3] / 10.0f;
			log_reading(temperature, humidity);
			consecutive_failures = 0;
		} else {
			consecutive_failures++;
			if (consecutive_failures >= 10) {
				log_error("DHT11: too many consecutive failures, aborting");
				break;
			}
		}
		sleep(DHT11_MIN_INTERVAL_S);
	}

	gpiod_line_release(line);
	gpiod_chip_close(chip);
	return 0;
}

