/*
 * SHT31-D temperature & humidity logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SHT31-D SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   SHT31-D SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   SHT31-D VDD  -> 3.3 V
 *   SHT31-D GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht31d_logger sht31d_logger.c -lgpiod
 * Run:    ./sht31d_logger   (requires gpiod user or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS_NAME      "i2c-1"
#define SHT31D_ADDR       0x45
#define LOG_FILE_NAME     "sht31d_data.log"
#define RETRY_COUNT       3
#define MEAS_DELAY_MS     15
#define SAMPLE_INTERVAL_S 5

/* SHT31-D measurement command (no clock-stretching, high repeatability) */
static const uint8_t CMD_MEASURE[2] = { 0x2C, 0x06 };

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SHT31-D spec     */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        ssize_t n = write(fd, cmd, len);
        if (n == (ssize_t)len)
            return 0;
        if (n < 0)
            fprintf(stderr, "[WARN] I2C write failed (attempt %d/%d): %s\n",
                    attempt + 1, RETRY_COUNT, strerror(errno));
        else
            fprintf(stderr, "[WARN] I2C short write (attempt %d/%d): %zd/%zu\n",
                    attempt + 1, RETRY_COUNT, n, len);
        usleep(100000); /* 100 ms back-off */
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len)
            return 0;
        if (n < 0)
            fprintf(stderr, "[WARN] I2C read failed (attempt %d/%d): %s\n",
                    attempt + 1, RETRY_COUNT, strerror(errno));
        else
            fprintf(stderr, "[WARN] I2C short read (attempt %d/%d): %zd/%zu\n",
                    attempt + 1, RETRY_COUNT, n, len);
        usleep(100000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sht31d(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != 0) {
        fprintf(stderr, "[ERROR] Failed to send measurement command after %d retries.\n",
                RETRY_COUNT);
        return -1;
    }

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0) {
        fprintf(stderr, "[ERROR] Failed to read 6 bytes from SHT31-D after %d retries.\n",
                RETRY_COUNT);
        return -1;
    }

    /* CRC validation */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&data[0], 2), data[2]);
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&data[3], 2), data[5]);
        return -1;
    }

