    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
