#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADPD105_ADDR_1 0x20
#define ADPD105_ADDR_2 0x21

#define ADPD105_REG_CHIP_ID 0x00
#define ADPD105_REG_MODE 0x01
#define ADPD105_REG_DATA 0x02
#define ADPD105_CHIP_ID 0x105

#define I2C_BUS 1
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adpd105_read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int adpd105_write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int adpd105_init(int handle) {
    uint8_t chip_id = 0;
    if (adpd105_read_register(handle, ADPD105_REG_CHIP_ID, &chip_id) != 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", handle);
        return -1;
    }
    if (chip_id != ADPD105_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n", chip_id, ADPD105_CHIP_ID);
        return -1;
    }
    if (adpd105_write_register(handle, ADPD105_REG_MODE, 0x01) != 0) {
        return -1;
    }
    return 0;
}

static int adpd105_read_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[6];
    int rc = i2cReadI2CBlockData(handle, ADPD105_REG_DATA, (char *)data, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading data block: %d\n", rc);
        return -1;
    }
    *red = (uint16_t)((data[0] << 8) | data[1]);
    *green = (uint16_t)((data[2] << 8) | data[3]);
    *blue = (uint16_t)((data[4] << 8) | data[5]);
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    if (red == 0 && green == 0 && blue == 0) return 0.0f;
    float r = (float)red, g = (float)green, b = (float)blue;
    float sum = r + g + b;
    if (sum == 0.0f) return 0.0f;
    r /= sum; g /= sum; b /= sum;
    float n = (r - (0.2720f * r) - (0.1760f * g) - (0.0710f * b)) / (0.1440f * r + 0.2919f * g + 0.0479f * b);
    float m = (g - (0.2227f * r) - (0.4555f * g) - (0.0128f * b)) / (0.0193f * r + 0.0324f * g + 0.0021f * b);
    float cct = 449.0f * n * n * n + 3525.0f * n * n + 6823.3f * n + 5520.33f;
    if (cct < 1000.0f) cct = 1000.0f;
    return cct;
}

static int log_data(FILE *fp, float cct) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f\n", timestamp, cct) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", handle1);
        gpioTerminate();
        return 1;
    }

    int handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", handle2);
        i2cClose(handle1);
        gpioTerminate();
        return 1;
    }

    if (adpd105_init(handle1) != 0 || adpd105_init(handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(handle1);
        i2cClose(handle2);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        i2cClose(handle1);
        i2cClose(handle2);
        gpioTerminate();
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Average_CCT\n");
        fflush(fp);
    }

    while (running) {
        uint16_t red1, green1, blue1, red2, green2, blue2;
        int ok1 = (adpd105_read_data(handle1, &red1, &green1, &blue1) == 0);
        int ok2 = (adpd105_read_data(handle2, &red2, &green2, &blue2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Error reading sensor data, skipping cycle\n");
        } else {
            float cct1 = calculate_cct(red1, green1, blue1);
            float cct2 = calculate_cct(red2, green2, blue2);
            float avg_cct = (cct1 + cct2) / 2.0f;
            if (log_data(fp, avg_cct) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down gracefully...\n");
    fclose(fp);
    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return 0;
}

