    }

    if (adpd105_init(handle1) != 0 || adpd105_init(handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(handle1);
        i2cClose(handle2);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        i2cClose(handle1);
        i2cClose(handle2);
        gpioTerminate();
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Average_CCT\n");
        fflush(fp);
    }

    while (running) {
        uint16_t red1, green1, blue1, red2, green2, blue2;
        int ok1 = (adpd105_read_data(handle1, &red1, &green1, &blue1) == 0);
        int ok2 = (adpd105_read_data(handle2, &red2, &green2, &blue2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Error reading sensor data, skipping cycle\n");
        } else {
            float cct1 = calculate_cct(red1, green1, blue1);
            float cct2 = calculate_cct(red2, green2, blue2);
            float avg_cct = (cct1 + cct2) / 2.0f;
            if (log_data(fp, avg_cct) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down gracefully...\n");
    fclose(fp);
    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return 0;
}

