#define MLX90824_REG_PRESSURE 0x01
#define MLX90824_REG_TEMPERATURE 0x02
#define MLX90824_REG_CONFIG 0x03

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_sensor_data(int handle, float *pressure, float *temperature) {
    int p_raw, t_raw;

    p_raw = i2cReadWordData(handle, MLX90824_REG_PRESSURE);
    if (p_raw < 0) {
        fprintf(stderr, "Error reading pressure register: %d\n", p_raw);
        return -1;
    }

    t_raw = i2cReadWordData(handle, MLX90824_REG_TEMPERATURE);
    if (t_raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", t_raw);
        return -1;
    }

    /* Convert raw values to physical units (example scaling; adjust per datasheet) */
    *pressure = (float)p_raw / 100.0f;
    *temperature = (float)t_raw / 100.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(fp);
}

