#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_FAN       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_ON  28.0f
#define TEMP_THRESHOLD_OFF 26.0f
#define SAMPLE_PERIOD_US  1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, float *temperature)
{
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw / 256.0f;
    return 0;
}

static void add_temperature(float temperature, float buffer[], int *index, int size)
{
    buffer[*index] = temperature;
    *index = (*index + 1) % size;
}

static float calculate_average(const float buffer[], int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++)
        sum += buffer[i];
    return sum / (float)size;
}

static int control_fan(int gpio_pin, float average_temperature)
{
    static bool fan_on = false;
    if (average_temperature > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(gpio_pin, 1) != 0) {
            fprintf(stderr, "Failed to turn fan ON\n");
            return -1;
        }
        fan_on = true;
        printf("Fan ON  (avg=%.2f C)\n", average_temperature);
    } else if (average_temperature < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(gpio_pin, 0) != 0) {
            fprintf(stderr, "Failed to turn fan OFF\n");
            return -1;
        }
        fan_on = false;
        printf("Fan OFF (avg=%.2f C)\n", average_temperature);
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_FAN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_FAN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_FAN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    float average_temperature = 0.0f;

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
        } else {
            add_temperature(temperature, temperature_buffer, &buffer_index, BUFFER_SIZE);
            average_temperature = calculate_average(temperature_buffer, BUFFER_SIZE);
            control_fan(GPIO_FAN, average_temperature);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(GPIO_FAN, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

