#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x50
#define REG_TEMP_OUT_L 0x04
#define LED_PIN        17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_temperature(int fd, float *temp)
{
    int16_t raw;
    if (i2c_read_reg16(fd, REG_TEMP_OUT_L, &raw) != 0)
        return -1;
    *temp = (float)raw / 100.0f;
    return 0;
}

static void control_led(int on)
{
    if (gpioWrite(LED_PIN, on ? 1 : 0) != 0)
        fprintf(stderr, "gpioWrite(%d) failed: %s\n", LED_PIN, strerror(errno));
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", STTS2004_ADDR, strerror(errno));
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool led_on = false;
    int consecutive_errors = 0;

    while (g_running) {
        float temp;
        if (read_temperature(fd, &temp) != 0) {
            consecutive_errors++;
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many I2C errors, aborting\n");
                break;
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        consecutive_errors = 0;

        printf("Temperature: %.2f C\n", temp);
        fflush(stdout);

        if (temp > TEMP_HIGH && !led_on) {
            control_led(1);
            led_on = true;
        } else if (temp < TEMP_LOW && led_on) {
            control_led(0);
            led_on = false;
        }

        gpioDelay(POLL_DELAY_US);
    }

    control_led(0);
    close(fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

