            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%03X: %d\n", SDP800_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
