    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        perror("Error opening data file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_sensor_data(&sensor_data) == 0) {
                success = 1;
                break;
