/*
 * Si7021 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO2  (BCM 2, I2C bus 1)
 *   Si7021 SCL  -> GPIO3  (BCM 3, I2C bus 1)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_logger si7021_logger.c -lgpiod
 * Run:    ./si7021_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS_NAME      "i2c-1"
#define SI7021_ADDR       0x40
#define LOG_FILE_NAME     "environment.log"
#define SAMPLE_INTERVAL_S 60
#define MAX_RETRIES       3
#define MEAS_DELAY_MS     20

/* Si7021 commands (no-master-hold variants) */
#define CMD_MEASURE_RH_NO_HOLD   0xE5
#define CMD_MEASURE_TEMP_NO_HOLD 0xE3
#define CMD_READ_PREV_TEMP       0xE0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_sda = NULL;
static struct gpiod_line *g_scl = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);

    if (g_log) {
        fprintf(g_log, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log);
    }
}

static void log_data(float temp_c, float rh_pct)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    printf("%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fflush(stdout);

    if (g_log) {
        fprintf(g_log, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
        fflush(g_log);
    }
}

/*
 * Read a 16-bit big-endian value from the Si7021 using a raw byte transfer.
 * The sensor echoes the command byte followed by two data bytes.
 */
static int si7021_read16(int fd, uint8_t cmd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(MEAS_DELAY_MS * 1000);

    n = read(fd, buf, 2);
    if (n != 2) {
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int si7021_read_rh(int fd, float *rh)
{
    uint16_t raw;
    if (si7021_read16(fd, CMD_MEASURE_RH_NO_HOLD, &raw) != 0) {
        return -1;
    }
    *rh = (float)raw / 100.0f;
    return 0;
}

static int si7021_read_temp(int fd, float *temp)
{
    uint16_t raw;
    if (si7021_read16(fd, CMD_MEASURE_TEMP_NO_HOLD, &raw) != 0) {
        return -1;
    }
    *temp = (float)raw / 100.0f;
    return 0;
}

static int si7021_read_temp_prev(int fd, float *temp)
{
    uint16_t raw;
    if (si7021_read16(fd, CMD_READ_PREV_TEMP, &raw) != 0) {
        return -1;
    }
    *temp = (float)raw / 100.0f;
    return 0;
}

static int read_sensor(int fd, float *temp, float *rh)
{
    int retries = MAX_RETRIES;

    while (retries-- > 0) {
        if (si7021_read_rh(fd, rh) == 0) {
            if (si7021_read_temp_prev(fd, temp) == 0) {
                return 0;
            }
        }
        usleep(100000);
    }
    return -1;
}

static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_sda) {
        gpiod_line_release(g_sda);
        g_sda = NULL;
    }
    if (g_scl) {
        gpiod_line_release(g_scl);
        g_scl = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE_NAME, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE_NAME ")");
        return EXIT_FAILURE;
    }

    g_chip = gpiod_chip_open_by_name(I2C_BUS_NAME);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        log_error("Failed to open I2C bus chip");
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    g_sda = gpiod_chip_get_line(g_chip, 2);
    g_scl = gpiod_chip_get_line(g_chip, 3);
    if (!g_sda || !g_scl) {
        perror("gpiod_chip_get_line");
        log_error("Failed to acquire I2C GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_sda, "si7021-logger", 1) != 0 ||
        gpiod_line_request_output(g_scl, "si7021-logger", 1) != 0) {
        perror("gpiod_line_request_output");
        log_error("Failed to request I2C GPIO lines as output");
        cleanup();
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open(/dev/i2c-1)");
        log_error("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        log_error("Failed to acquire I2C bus access / sensor not present");
        close(fd);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Quick presence check: read firmware revision (0xFA) */
    uint8_t rev;
    if (write(fd, (uint8_t[]){0xFA}, 1) != 1) {
        log_error("Si7021 not responding at 0x40");
        close(fd);
        cleanup();
        return EXIT_FAILURE;
    }
    if (read(fd, &rev, 1) != 1) {
        log_error("Si7021 not responding at 0x40");
        close(fd);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 detected (rev 0x%02X). Logging to %s every %d s.\n",
           rev, LOG_FILE_NAME, SAMPLE_INTERVAL_S);
    fflush(stdout);

    while (g_running) {
        float temp = 0.0f, rh = 0.0f;

        if (read_sensor(fd, &temp, &rh) == 0) {
            log_data(temp, rh);
        } else {
            log_error("Failed to read sensor data after retries");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    close(fd);
    cleanup();
    return EXIT_SUCCESS;
}

