#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02
#define MEAS_TEMP_HUMID 0x01
#define CONVERSION_DELAY_US 20000
#define LOG_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_init(int handle) {
    if (i2cWriteByteData(handle, CONFIG_REG, MEAS_TEMP_HUMID) < 0) {
        fprintf(stderr, "Error: Failed to write configuration register.\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read(int handle, float *temperature, float *humidity) {
    uint8_t buf[4];

    if (i2cWriteByteData(handle, TEMP_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set register pointer.\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read temperature and humidity data.\n");
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint16_t raw_humid = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humid / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (hdc1080_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: HDC1080 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    while (running) {
        if (hdc1080_read(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }

        for (int i = 0; i < LOG_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

