    if (mkdir(LOG_DIR, 0755) != 0 && errno != EEXIST) {
        perror("mkdir");
        return EXIT_FAILURE;
    }

    /* Open error log */
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("fopen error log");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(error_log_file);
        return EXIT_FAILURE;
