    /* Initialize circular buffer */
    buffer_init(&data_buffer);

    /* Create logging thread */
    if (pthread_create(&logging_thread, NULL, log_data_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main loop */
    while (running) {
        float co2, temperature, humidity;

        if (read_scd40_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
