            buffer_add(&data_buffer, &data);
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(SCD40_READ_DELAY_US);
    }

    /* Graceful shutdown */
    running = 0;
    cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

