/*
 * SCD40 CO2 sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SCD40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_logger scd40_logger.c -lpigpio -lpthread
 * Run:    sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR        0x62
#define SCD40_CMD_START_MEAS  0x2100
#define SCD40_CMD_STOP_MEAS   0x2000
#define SCD40_CMD_READ_MEAS   0xEC01
#define SCD40_MEAS_DELAY_US   5000000   /* 5 s after start() */
#define SCD40_READ_DELAY_US   5000000   /* 5 s between reads */
#define SCD40_LOG_INTERVAL_S  60
#define SCD40_BUFFER_SIZE     100
#define LOG_DIR               "/var/log/scd40_data"
#define ERROR_LOG_FILE        "/var/log/scd40_error.log"

typedef struct {
    float co2;
    float temperature;
    float humidity;
    time_t timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t data[SCD40_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t data_buffer;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static int logging_thread_running = 0;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Logging helpers ---- */
static void log_error(const char *message) {
    if (!error_log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log_file, "%s: %s\n", ts, message);
    fflush(error_log_file);
}

static void log_data_to_file(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    char filepath[512];
    snprintf(filepath, sizeof(filepath), "%s/scd40_data_%s.csv",
             LOG_DIR, ts);

    FILE *fp = fopen(filepath, "a");
    if (!fp) {
        log_error("Failed to open CSV file for writing");
        return;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,CO2_ppm,Temperature_C,Humidity_RH\n");
    }

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n",
            ctime(&data->timestamp), data->co2,
            data->temperature, data->humidity);
    fclose(fp);
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, const sensor_data_t *data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = *data;
    buf->head = (buf->head + 1) % SCD40_BUFFER_SIZE;
    if (buf->count == SCD40_BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % SCD40_BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void buffer_flush(circular_buffer_t *buf, const char *filename) {
    pthread_mutex_lock(&buf->mutex);
    int count = buf->count;
    int tail = buf->tail;
    pthread_mutex_unlock(&buf->mutex);

    if (count == 0) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    char filepath[512];
    snprintf(filepath, sizeof(filepath), "%s/scd40_data_%s.csv",
             LOG_DIR, ts);

    FILE *fp = fopen(filepath, "w");
    if (!fp) {
        log_error("Failed to open final CSV file for writing");
        return;
    }

    fprintf(fp, "Timestamp,CO2_ppm,Temperature_C,Humidity_RH\n");
    pthread_mutex_lock(&buf->mutex);
    for (int i = 0; i < count; i++) {
        int idx = (tail + i) % SCD40_BUFFER_SIZE;
        fprintf(fp, "%s,%.2f,%.2f,%.2f\n",
                ctime(&buf->data[idx].timestamp),
                buf->data[idx].co2,
                buf->data[idx].temperature,
                buf->data[idx].humidity);
    }
    pthread_mutex_unlock(&buf->mutex);
    fclose(fp);
}

/* ---- SCD40 I2C helpers ---- */
static int scd40_write_command(int handle, uint16_t command) {
    uint8_t buf[2] = { (uint8_t)(command >> 8), (uint8_t)(command & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int scd40_read_data(int handle, uint16_t *co2, uint16_t *temperature,
                           uint16_t *humidity) {
    uint8_t buf[9];
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        log_error("I2C read data failed");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }

    *co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    *humidity = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

