        return -1;
    }

    *co2 = (float)raw_co2;
    *temperature = (float)raw_temp / 100.0f;
    *humidity = (float)raw_hum / 100.0f;
    return 0;
}

/* ---- Logging thread ---- */
static void *log_data_thread(void *arg) {
    (void)arg;
    logging_thread_running = 1;

    while (running) {
        sleep(SCD40_LOG_INTERVAL_S);
        if (!running) break;

        sensor_data_t local_data[SCD40_BUFFER_SIZE];
        int local_count = 0;

        pthread_mutex_lock(&data_buffer.mutex);
        int count = data_buffer.count;
        int tail = data_buffer.tail;
        if (count > 0) {
            for (int i = 0; i < count; i++) {
                int idx = (tail + i) % SCD40_BUFFER_SIZE;
                local_data[i] = data_buffer.data[idx];
                local_count++;
            }
            data_buffer.count = 0;
            data_buffer.tail = 0;
        }
        pthread_mutex_unlock(&data_buffer.mutex);

        for (int i = 0; i < local_count; i++) {
            log_data_to_file(&local_data[i]);
        }
    }

    logging_thread_running = 0;
    return NULL;
}

/* ---- Signal handler ---- */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_write_command(i2c_handle, SCD40_CMD_STOP_MEAS);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
