/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure monitor
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   ICP-10125 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *   Warning LED    -> GPIO17 (pin 11, BCM 17) via 330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10125_monitor icp10125_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./icp10125_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1          /* /dev/i2c-1 on Pi 4 */
#define ICP10125_ADDR        0x50       /* TDK ICP-10125 7-bit I2C address */
#define GPIO_LED             17         /* BCM 17 – warning LED */
#define PRESSURE_THRESHOLD   95000.0f   /* Pa – below this triggers warning */
#define POLL_INTERVAL_US     1000000    /* 1 s between readings */
#define TRIGGER_DELAY_US     20000      /* 20 ms after each trigger */
#define LED_ON_MS            500        /* normal LED on duration */
#define LED_OFF_MS           500        /* normal LED off duration */
#define WARNING_LED_ON_MS    100        /* warning LED on duration */
#define WARNING_LED_OFF_MS   100        /* warning LED off duration */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static int  g_gpio_led = GPIO_LED;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  i2c_read_sensor(int fd, uint8_t *buf, size_t len);
static bool verify_crc(const uint8_t *data, size_t len, uint8_t crc);
static int  read_pressure(int fd, float *pressure);
static void control_led(int gpio_pin, bool warning_active);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C read with CRC ---------------------------- */

/*
 * Read exactly `len` bytes from the ICP-10125.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_sensor(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = i2cReadDevice(fd, (char *)buf, len);
    if (n < 0) {
        fprintf(stderr, "[I2C] i2cReadDevice failed: %s\n", pigpio_error(n));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "[I2C] short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * CRC-8 polynomial 0x31, init 0x00 (TI-style, used by TDK ICP-10125).
 */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static bool verify_crc(const uint8_t *data, size_t len, uint8_t crc)
{
    return crc8(data, len) == crc;
}

/*
 * Read pressure (Pa) and temperature (°C) from the ICP-10125.
 * Returns 0 on success, -1 on error.
 */
static int read_pressure(int fd, float *pressure)
{
    uint8_t buf[6];

    if (i2c_read_sensor(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC covers the 2-byte data word immediately preceding it. */
    if (!verify_crc(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ICP-10125] pressure CRC mismatch\n");
        return -1;
    }
    if (!verify_crc(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ICP-10125] temperature CRC mismatch\n");
        return -1;
    }

    uint16_t raw_p = (uint16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw_p;          /* raw counts -> Pa (1 Pa/count) */

    return 0;
}

/* ------------------------------- LED control ------------------------------ */

static void control_led(int gpio_pin, bool warning_active)
{
    if (warning_active) {
        /* 5 Hz warning blink: 100 ms on, 100 ms off */
        gpioWrite(gpio_pin, 1);
        gpioDelay(WARNING_LED_ON_MS  * 1000);
        gpioWrite(gpio_pin, 0);
        gpioDelay(WARNING_LED_OFF_MS * 1000);
    } else {
        /* Normal 1 Hz blink: 500 ms on, 500 ms off */
        gpioWrite(gpio_pin, 1);
        gpioDelay(LED_ON_MS  * 1000);
        gpioWrite(gpio_pin, 0);
        gpioDelay(LED_OFF_MS * 1000);
    }
}

/* ------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Ensure LED is off before releasing the line. */
    gpioWrite(g_gpio_led, 0);
    gpioSetMode(g_gpio_led, PI_INPUT);
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_fd = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_fd));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(g_gpio_led, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", g_gpio_led);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(g_gpio_led, 0);

    /* --- Signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICP-10125 monitor running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float pressure = 0.0f;

        if (read_pressure(g_i2c_fd, &pressure) != 0) {
            fprintf(stderr, "Sensor read error – continuing.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        bool warning_active = (pressure < PRESSURE_THRESHOLD);
        control_led(g_gpio_led, warning_active);

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

