#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x45
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000
#define POLL_INTERVAL_US 1000000

#define CMD_MEASURE_HIGH 0x2C
#define CMD_MEASURE_LOW  0x26

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(float *temperature, float *humidity) {
    char cmd[2];
    char data[6];
    int retries = 0;

    cmd[0] = CMD_MEASURE_HIGH;
    cmd[1] = 0x00;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, data, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        unsigned short temp_ticks = ((unsigned char)data[0] << 8) | (unsigned char)data[1];
        unsigned short hum_ticks = ((unsigned char)data[3] << 8) | (unsigned char)data[4];

        *temperature = -45.0f + 175.0f * (float)temp_ticks / 65535.0f;
        *humidity = 100.0f * (float)hum_ticks / 65535.0f;

        if (*humidity > 100.0f) *humidity = 100.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int send_http_response(int client_fd, float temperature, float humidity) {
    char response[512];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%a, %d %b %Y %H:%M:%S GMT", t);

    snprintf(response, sizeof(response),
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html; charset=UTF-8\r\n"
             "Connection: close\r\n"
             "Date: %s\r\n"
             "Server: SHT40-Server\r\n"
             "\r\n"
             "<!DOCTYPE html>\n"
             "<html>\n"
             "  <head>\n"
             "    <meta charset=\"UTF-8\">\n"
             "    <title>SHT40 Sensor</title>\n"
             "    <style>\n"
             "      body { font-family: Arial, sans-serif; text-align: center; margin-top: 50px; }\n"
             "      .sensor { font-size: 24px; margin: 20px 0; }\n"
             "      .timestamp { font-size: 18px; color: #555; }\n"
             "    </style>\n"
             "  </head>\n"
             "  <body>\n"
             "    <h1>SHT40 Sensor Data</h1>\n"
             "    <div class=\"sensor\">Temperature: %.2f &deg;C</div>\n"
             "    <div class=\"sensor\">Humidity: %.2f %%</div>\n"
             "    <div class=\"timestamp\">Last updated: %s</div>\n"
             "  </body>\n"
             "</html>\n",
             temperature, humidity, timestamp);

    if (send(client_fd, response, strlen(response), 0) < 0) {
        perror("send() failed");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;
    struct sockaddr_in address;
    socklen_t addrlen = sizeof(address);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(HTTP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor server listening on port %d...\n", HTTP_PORT);

    while (running) {
        int client_fd = accept(server_fd, (struct sockaddr *)&address, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            continue;
        }

        if (read_sht40(&temperature, &humidity) == 0) {
            send_http_response(client_fd, temperature, humidity);
        } else {
            const char *err_html =
                "HTTP/1.1 500 Internal Server Error\r\n"
                "Content-Type: text/html; charset=UTF-8\r\n"
                "Connection: close\r\n"
                "\r\n"
                "<!DOCTYPE html><html><body><h1>500 Internal Server Error</h1></body></html>";
            send(client_fd, err_html, strlen(err_html), 0);
        }

        close(client_fd);
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

