#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP102_ADDR    0x48
#define TMP102_REG_TEMP 0x00
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int read_temperature(int handle, float *temperature)
{
    int raw = i2cReadWordData(handle, TMP102_REG_TEMP);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    /* TMP102 returns MSB first; pigpio returns little-endian word */
    int16_t temp_raw = (int16_t)((raw & 0xFF) << 8 | ((raw >> 8) & 0xFF));
    *temperature = (float)temp_raw / 10.0f;
    return 0;
}

static int log_temperature(float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
