/*
 * HDC2010 Temperature & Humidity Sensor Reader
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Texas Instruments HDC2010
 * Address: 0x50 (ADDR pin tied to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010_reader hdc2010_reader.c -li2c
 *
 * NOTE: The i2c library used here is the legacy Linux I2C character-device
 *       interface (e.g., /dev/i2c-1).  If your system uses a different
 *       distribution's i2c-dev wrapper (e.g., pigpio), replace the
 *       i2c_open/i2c_read/write calls with the appropriate ioctl wrappers.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC2010_ADDR   0x50

/* HDC2010 register addresses */
#define REG_TEMP_LOW   0x00
#define REG_TEMP_HIGH  0x01
#define REG_HUM_LOW    0x02
#define REG_HUM_HIGH   0x03
#define REG_MEAS_CFG   0x0F
#define REG_INT_CFG    0x07
#define REG_INT_EN     0x06
#define REG_INT_STA    0x05
#define REG_DEV_ID     0x00

#define MEAS_CFG_MEAS  0x80   /* bit 7: start measurement */
#define MEAS_CFG_MODE  0x00   /* bit 6: 0 = temp+humidity, 1 = temp only */
#define MEAS_CFG_TRES  0x00   /* bits 5-4: 00 = 14-bit temp */
#define MEAS_CFG_HRES  0x00   /* bits 3-2: 00 = 14-bit humidity */
#define MEAS_CFG_T_EN  0x00   /* bit 1: temp conversion enable */
#define MEAS_CFG_H_EN  0x00   /* bit 0: humidity conversion enable */

#define MEAS_TIMEOUT_MS 500
#define POLL_DELAY_MS   5
#define MAX_RETRIES     3
#define SAMPLE_PERIOD_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, sizeof(reg)) != (ssize_t)sizeof(reg)) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, sizeof(*value)) != (ssize_t)sizeof(*value)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, sizeof(reg)) != (ssize_t)sizeof(reg)) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int hdc2010_init(int fd)
{
    uint8_t dev_id = 0;
    if (i2c_read_reg8(fd, REG_DEV_ID, &dev_id) != 0) {
        fprintf(stderr, "Cannot read HDC2010 device ID (sensor absent or bus error)\n");
        return -1;
    }
    if (dev_id != 0x0A) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x0A)\n", dev_id);
        return -1;
    }

    /* Clear any pending interrupt */
    if (i2c_write_reg8(fd, REG_INT_STA, 0x01) != 0)
        return -1;

    /* Enable interrupt on measurement completion (bit 0) */
    if (i2c_write_reg8(fd, REG_INT_EN, 0x01) != 0)
        return -1;

    /* Configure measurement: temp+humidity, 14-bit, both enabled */
    uint8_t meas_cfg = MEAS_CFG_MEAS | MEAS_CFG_MODE | MEAS_CFG_TRES |
                       MEAS_CFG_HRES | MEAS_CFG_T_EN | MEAS_CFG_H_EN;
    if (i2c_write_reg8(fd, REG_MEAS_CFG, meas_cfg) != 0)
        return -1;

    return 0;
}

static int hdc2010_read(int fd, float *temperature, float *humidity)
{
    uint8_t meas_cfg = 0;
    uint8_t int_sta  = 0;

    /* Start a measurement */
    if (i2c_write_reg8(fd, REG_MEAS_CFG, MEAS_CFG_MEAS) != 0)
        return -1;

    /* Poll MEASUREMENT_CONFIG bit 0 until it reads 0 (measurement complete) */
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += POLL_DELAY_MS) {
        if (i2c_read_reg8(fd, REG_MEAS_CFG, &meas_cfg) != 0)
            return -1;
        if ((meas_cfg & MEAS_CFG_MEAS) == 0)
            break;
        usleep(POLL_DELAY_MS * 1000);
    }

    if ((meas_cfg & MEAS_CFG_MEAS) != 0) {
        fprintf(stderr, "Measurement timeout (%d ms)\n", MEAS_TIMEOUT_MS);
        return -1;
    }

    /* Clear interrupt by writing 1 to INT_STA */
    if (i2c_write_reg8(fd, REG_INT_STA, 0x01) != 0)
        return -1;

    /* Read temperature (16-bit, 16.4-bit resolution) */
    uint16_t temp_raw;
    if (i2c_read_reg16(fd, REG_TEMP_LOW, &temp_raw) != 0)
        return -1;
    *temperature = ((float)temp_raw / 65536.0f) * 165.0f - 40.0f;

    /* Read humidity (16-bit, 16.4-bit resolution) */
    uint16_t hum_raw;
    if (i2c_read_reg16(fd, REG_HUM_LOW, &hum_raw) != 0)
        return -1;
    *humidity = ((float)hum_raw / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                HDC2010_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (hdc2010_init(g_i2c_fd) != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("HDC2010 initialized on %s (addr 0x%02X). Reading every %d s.\n",
           I2C_BUS, HDC2010_ADDR, SAMPLE_PERIOD_S);

    while (g_running) {
        float temperature = 0.0f;
        float humidity    = 0.0f;
        bool success = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (hdc2010_read(g_i2c_fd, &temperature, &humidity) == 0) {
                success = true;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            usleep(100000); /* 100 ms backoff */
        }

        if (success) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor after %d attempts.\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        /* Disable measurement and clear interrupt */
        (void)i2c_write_reg8(g_i2c_fd, REG_MEAS_CFG, 0x00);
        (void)i2c_write_reg8(g_i2c_fd, REG_INT_STA, 0x01);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

