/*
 * SDP800-500Pa differential pressure reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x200 (7-bit, 0x20 on the bus)
 * Measurement time: ~45 ms (datasheet: 44.8 ms typ)
 * Sample interval: 500 ms
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x200          /* 7-bit address; 0x20 on the bus */
#define MEAS_DELAY_MS  45             /* conversion time per datasheet */
#define SAMPLE_PERIOD  500            /* ms between samples */
#define MAX_RETRIES    3

/* SDP800 commands (16-bit, big-endian on the wire) */
#define CMD_READ_MEASUREMENT  0x3680   /* continuous read, no clock stretching */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Write a 16-bit command to the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int sdp_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write cmd 0x%04X failed: %s (wrote %zd bytes)\n",
                cmd, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int sdp_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/*
 * Trigger a measurement and read back the 6-byte result.
 * Returns 0 on success, -1 on error.
 */
static int sdp_read_measurement(int fd, int16_t *pressure, int16_t *temperature)
{
    if (sdp_write_cmd(fd, CMD_READ_MEASUREMENT) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t raw[6];
    if (sdp_read_bytes(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Validate CRC for pressure (bytes 0-1, CRC byte 2) */
    if (sdp_crc8(raw, 2) != raw[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC byte 5) */
    if (sdp_crc8(raw + 3, 2) != raw[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    *pressure    = (int16_t)((raw[0] << 8) | raw[1]);
    *temperature = (int16_t)((raw[3] << 8) | raw[4]);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%03X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP800-500Pa reader started on %s (addr 0x%03X). Press Ctrl+C to exit.\n",
           I2C_BUS, SDP800_ADDR);

    while (g_running) {
        int16_t pressure = 0, temperature = 0;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp_read_measurement(fd, &pressure, &temperature) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "Measurement attempt %d/%d failed; retrying in 100 ms...\n",
                    attempt + 1, MAX_RETRIES);
            usleep(100000);
        }

        if (ok) {
            printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor after %d attempts.\n", MAX_RETRIES);
        }

        /* Sleep SAMPLE_PERIOD ms, but wake early on SIGINT */
        for (int ms = 0; ms < SAMPLE_PERIOD && g_running; ms += 100)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    close(fd);
    return EXIT_SUCCESS;
}

