#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_RELAY 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_US 1000000
#define LOOP_DELAY_US 100000

#define MAX_TEMP 250.0
#define MIN_TEMP 0.0
#define MAX_PROFILE_SIZE 100

typedef struct {
    float time_seconds;
    float target_temp_celsius;
} ProfilePoint;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static ProfilePoint temperature_profile[MAX_PROFILE_SIZE];
static int profile_size = 0;
static float current_target_temp = 200.0;
static float integral = 0.0;
static float previous_error = 0.0;
static float Kp = 1.0;
static float Ki = 0.1;
static float Kd = 0.01;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_max6675(int handle, float *temperature) {
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buf[4] = {0};

    if (spiXfer(handle, tx_buf, rx_buf, 4) != 4) {
        return -1;
    }

    if ((rx_buf[0] & 0x03) != 0) {
        return -2;
    }

    uint16_t raw = ((uint16_t)(rx_buf[1] & 0x07FF) << 8) | (uint8_t)rx_buf[2];
    *temperature = (float)raw * 0.25;
    return 0;
}

static float calculate_pid(float current_temp) {
    float error = current_target_temp - current_temp;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;
    return output;
}

static void set_relay_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;
    gpioPWM(GPIO_RELAY, (int)(duty_cycle * 1000000));
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

static int load_temperature_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening temperature profile file");
        return -1;
    }

    profile_size = 0;
    for (int i = 0; i < MAX_PROFILE_SIZE; i++) {
        if (fscanf(fp, "%f,%f", &temperature_profile[i].time_seconds, &temperature_profile[i].target_temp_celsius) != 2) {
            break;
        }
        profile_size++;
    }
    fclose(fp);

    if (profile_size == 0) {
        fprintf(stderr, "Warning: No points found in temperature profile file.\n");
        return -1;
    }

    printf("Loaded %d points from temperature profile.\n", profile_size);
    return 0;
}

static void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(GPIO_RELAY, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RELAY);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(GPIO_RELAY, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_RELAY);
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(GPIO_RELAY, 1000000) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", GPIO_RELAY);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    if (load_temperature_profile(PROFILE_FILE) != 0) {
        fprintf(stderr, "Failed to load temperature profile. Using default target temperature.\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float current_time = 0.0;
    float elapsed_time = 0.0;

    while (running) {
        float temperature;
        int ret = read_max6675(spi_handle, &temperature);

        if (ret == 0) {
            elapsed_time += SAMPLE_INTERVAL_US / 1000000.0;

            while (profile_size > 0 && temperature_profile[0].time_seconds <= elapsed_time) {
                current_target_temp = temperature_profile[0].target_temp_celsius;
                memmove(temperature_profile, temperature_profile + 1, (profile_size - 1) * sizeof(ProfilePoint));
                profile_size--;
            }

            float pid_output = calculate_pid(temperature);
            set_relay_duty_cycle(pid_output);
            log_temperature(temperature);
            printf("Temperature: %.2f C, Target: %.2f C, Duty Cycle: %.2f\n", temperature, current_target_temp, pid_output);
        } else if (ret == -2) {
            fprintf(stderr, "Error: Invalid data from MAX6675 (sensor absent or bus error).\n");
        } else {
            fprintf(stderr, "Error: SPI communication failed.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

