#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/time.h>
#include <math.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_PREFIX "28-"
#define W1_TEMP_FILE "w1_slave"
#define LOG_FILE "greenhouse.log"
#define PWM_GPIO 18
#define RELAY_GPIO 17
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_SEC 5
#define MAX_SENSORS 10

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int pwm_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_all(int fd, char *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) break;
        total += (size_t)n;
    }
    return (total == len) ? 0 : -1;
}

static int read_temperature(const char *sensor_id, float *temp) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s/%s", W1_DEVICES_DIR, sensor_id, W1_TEMP_FILE);

    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;

    char data[256];
    if (read_all(fd, data, sizeof(data) - 1) < 0) {
        close(fd);
        return -1;
    }
    data[sizeof(data) - 1] = '\0';
    close(fd);

    if (strstr(data, "YES") == NULL) return -2;

    char *t = strstr(data, "t=");
    if (t == NULL) return -1;

    long val = strtol(t + 2, NULL, 10);
    *temp = (float)val / 1000.0f;
    return 0;
}

static int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        unsigned char byte = data[i];
        for (int j = 0; j < 8; j++) {
            unsigned char mix = (crc ^ byte) & 0x01;
            crc >>= 1;
            if (mix) crc ^= 0x8C;
            byte >>= 1;
        }
    }
    return crc;
}

static int find_sensors(char sensor_ids[][32], int max) {
    DIR *d = opendir(W1_DEVICES_DIR);
    if (!d) return -1;

    int count = 0;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL && count < max) {
        if (strncmp(ent->d_name, W1_SLAVE_PREFIX, strlen(W1_SLAVE_PREFIX)) == 0) {
            strncpy(sensor_ids[count], ent->d_name, 31);
            sensor_ids[count][31] = '\0';
            count++;
        }
    }
    closedir(d);
    return count;
}

static int set_pwm(int duty) {
    if (pwm_fd < 0) return -1;
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", duty);
    ssize_t w = write(pwm_fd, buf, strlen(buf));
    if (w < 0) return -1;
    return 0;
}

static int log_data(float avg_temp, float setpoint, float pid_out, int duty) {
    if (!log_fp) return -1;
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s, %.2f, %.2f, %.2f, %d\n", ts, avg_temp, setpoint, pid_out, duty);
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (pwm_fd >= 0) {
        set_pwm(0);
        close(pwm_fd);
        pwm_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    float setpoint = atof(argv[1]);
    float Kp = atof(argv[2]);
    float Ki = atof(argv[3]);
    float Kd = atof(argv[4]);

    if (setpoint <= 0 || Kp <= 0 || Ki < 0 || Kd <= 0) {
        fprintf(stderr, "Invalid PID parameters\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return 1;
    }

    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0", O_WRONLY);
    if (pwm_fd < 0) {
        perror("open pwm");
        cleanup();
        return 1;
    }

    char buf[256];
    snprintf(buf, sizeof(buf), "enable=1\n");
    write(pwm_fd, buf, strlen(buf));

    snprintf(buf, sizeof(buf), "period=%d\n", PWM_RANGE);
    write(pwm_fd, buf, strlen(buf));

    snprintf(buf, sizeof(buf), "duty_cycle=0\n");
    write(pwm_fd, buf, strlen(buf));

    char sensor_ids[MAX_SENSORS][32];
    int num_sensors = find_sensors(sensor_ids, MAX_SENSORS);
    if (num_sensors <= 0) {
        fprintf(stderr, "No DS18B20 sensors found\n");
        cleanup();
        return 1;
    }

    float integral = 0.0f;
    float prev_error = 0.0f;
    float pid_out = 0.0f;

    while (running) {
        float sum = 0.0f;
        int valid = 0;

        for (int i = 0; i < num_sensors; i++) {
            float temp;
            int rc = read_temperature(sensor_ids[i], &temp);
            if (rc == 0) {
                sum += temp;
                valid++;
            } else if (rc == -2) {
                fprintf(stderr, "Sensor %s not present\n", sensor_ids[i]);
            } else {
                fprintf(stderr, "Read error on %s\n", sensor_ids[i]);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "No valid sensors; skipping cycle\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float avg_temp = sum / valid;
        float error = setpoint - avg_temp;

        integral += error;
        if (integral > 1000.0f) integral = 1000.0f;
        if (integral < -1000.0f) integral = -1000.0f;

        float derivative = error - prev_error;
        prev_error = error;

        pid_out = Kp * error + Ki * integral + Kd * derivative;

        if (pid_out < 0) pid_out = 0;
        if (pid_out > 100) pid_out = 100;

        if (set_pwm((int)pid_out) < 0) {
            fprintf(stderr, "PWM write failed\n");
        }

        log_data(avg_temp, setpoint, pid_out, (int)pid_out);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

