#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MEASURE_DELAY  80
#define MAX_RETRIES    3
#define RETRY_DELAY    10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int aht20_measure(int fd, float *humidity)
{
    uint8_t cmd[3] = { 0xAC, 0x33, 0x00 };
    uint8_t data[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write(fd, cmd, sizeof(cmd)) < 0) {
            if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY * 1000);
            continue;
        }

        usleep(MEASURE_DELAY * 1000);

        if (i2c_read(fd, data, sizeof(data)) < 0) {
            if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY * 1000);
            continue;
        }

        if (data[0] & 0x80) {
            fprintf(stderr, "AHT20 busy, retrying...\n");
            if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY * 1000);
            continue;
        }

        uint32_t raw = ((uint32_t)data[1] << 12) |
                       ((uint32_t)data[2] << 4)  |
                       ((uint32_t)data[3] >> 4);
        *humidity = (100.0f * (float)raw) / 0x100000;
        return 0;
    }

    fprintf(stderr, "AHT20 measurement failed after %d retries\n", MAX_RETRIES);
    return -1;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "aht20-humidity", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int relay_state = 0;

    while (g_running) {
        float humidity;
        if (aht20_measure(i2c_fd, &humidity) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            fflush(stdout);

            if (humidity > HUMIDITY_HIGH && relay_state == 0) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    fprintf(stderr, "Failed to activate relay: %s\n", strerror(errno));
                } else {
                    relay_state = 1;
                    printf("Dehumidifier activated.\n");
                }
            } else if (humidity < HUMIDITY_LOW && relay_state == 1) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate relay: %s\n", strerror(errno));
                } else {
                    relay_state = 0;
                    printf("Dehumidifier deactivated.\n");
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

