#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_CMD_TEMP_HOLD 0xE3
#define HTU21D_CMD_HUMID_HOLD 0xE5
#define HTTP_SERVER "api.example.com"
#define HTTP_PORT 80
#define POLL_INTERVAL 60
#define MAX_RETRIES 3
#define JSON_BUFFER_SIZE 256
#define READ_ERROR -1.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_htu21d_humidity(int fd, float *humidity) {
    unsigned char cmd = HTU21D_CMD_HUMID_HOLD;
    unsigned char data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, cmd) < 0) {
            retries++;
            continue;
        }

        usleep(20000);

        if (i2c_read_bytes(fd, data, 3) < 0) {
            retries++;
            continue;
        }

        unsigned int raw = ((unsigned int)data[0] << 8) | data[1];
        unsigned char crc = data[2];

        unsigned char crc_calc = 0;
        for (int i = 0; i < 2; i++) {
            crc_calc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if (crc_calc & 0x80) {
                    crc_calc = (crc_calc << 1) ^ 0x31;
                } else {
                    crc_calc <<= 1;
                }
            }
        }

        if (crc_calc != crc) {
            syslog(LOG_ERR, "CRC mismatch: expected 0x%02X, got 0x%02X", crc_calc, crc);
            retries++;
            continue;
        }

        unsigned int humidity_raw = (raw & 0xFFFC) >> 2;
        *humidity = -6.0f + 125.0f * (float)humidity_raw / 65536.0f;

        if (*humidity < 0.0f || *humidity > 100.0f) {
            syslog(LOG_ERR, "Humidity out of range: %.2f%%", *humidity);
            retries++;
            continue;
        }

        return 0;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

static int send_http_post(const char *json_data) {
    struct sockaddr_in server_addr;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        sock_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (sock_fd < 0) {
            syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
            retries++;
            continue;
        }

        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(HTTP_PORT);

        if (inet_pton(AF_INET, HTTP_SERVER, &server_addr.sin_addr) <= 0) {
            syslog(LOG_ERR, "Invalid address: %s", HTTP_SERVER);
            close(sock_fd);
            sock_fd = -1;
            retries++;
            continue;
        }

        if (connect(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
            close(sock_fd);
            sock_fd = -1;
            retries++;
            continue;
        }

        char request[512];
        int request_len = snprintf(request, sizeof(request),
            "POST /humidity HTTP/1.1\r\n"
            "Host: %s\r\n"
            "Content-Type: application/json\r\n"
            "Content-Length: %zu\r\n"
            "Connection: close\r\n"
            "\r\n"
            "%s",
            HTTP_SERVER, strlen(json_data), json_data);

        if (request_len < 0 || (size_t)request_len >= sizeof(request)) {
            syslog(LOG_ERR, "Request buffer too small");
            close(sock_fd);
            sock_fd = -1;
            retries++;
            continue;
        }

        if (send(sock_fd, request, request_len, 0) < 0) {
            syslog(LOG_ERR, "HTTP send failed: %s", strerror(errno));
            close(sock_fd);
            sock_fd = -1;
            retries++;
            continue;
        }

        unsigned char response[1024];
        ssize_t bytes_received = recv(sock_fd, response, sizeof(response) - 1, 0);
        if (bytes_received > 0) {
            response[bytes_received] = '\0';
            syslog(LOG_INFO, "HTTP response: %s", response);
            close(sock_fd);
            sock_fd = -1;
            return 0;
        } else if (bytes_received < 0) {
            syslog(LOG_ERR, "HTTP receive failed: %s", strerror(errno));
        }

        close(sock_fd);
        sock_fd = -1;
        retries++;
    }

    syslog(LOG_ERR, "Failed to send HTTP POST after %d retries", MAX_RETRIES);
    return -1;
}

static int format_json(float humidity, char *json_buffer, size_t buffer_size) {
    int ret = snprintf(json_buffer, buffer_size, "{\"humidity\":%.2f}", humidity);
    if (ret < 0 || (size_t)ret >= buffer_size) {
        syslog(LOG_ERR, "JSON formatting failed");
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D monitor started on %s (addr 0x%02X)", I2C_BUS, HTU21D_ADDR);

    while (running) {
        float humidity = READ_ERROR;

        if (read_htu21d_humidity(i2c_fd, &humidity) == 0) {
            char json_buffer[JSON_BUFFER_SIZE];
            if (format_json(humidity, json_buffer, sizeof(json_buffer)) == 0) {
                if (send_http_post(json_buffer) != 0) {
                    syslog(LOG_ERR, "Failed to send humidity data to server");
                } else {
                    syslog(LOG_INFO, "Humidity data sent successfully: %s", json_buffer);
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from sensor");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (i2c_fd >= 0) close(i2c_fd);
    if (sock_fd >= 0) close(sock_fd);
    closelog();
    return 0;
}

