/*
 * Raspberry Pi 4B Environmental Logger
 *
 * Reads:
 *   - TMP117 temperature sensor (I2C /dev/i2c-1, address 0x49)
 *   - AHT20 humidity sensor (I2C /dev/i2c-1, address 0x38)
 *   - PIR motion sensor on GPIO17 (gpiochip4 line 17, input)
 *
 * Logs daily timestamped CSV files with header:
 *   Timestamp,Temperature(C),Humidity(%),MotionDetected
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x49
#define AHT20_ADDR     0x38
#define PIR_GPIO_LINE  17
#define GPIO_CHIP      "gpiochip4"
#define MOTION_PIN     17
#define RETRY_COUNT    3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1
#define LOG_FILE_PREFIX "sensor_data_"
#define LOG_FILE_SUFFIX ".csv"
#define MAX_FILENAME_LEN 256

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ---- TMP117 temperature reader ---- */
static int tmp117_read(int fd, float *temperature) {
    uint8_t cmd = 0x00; /* Continuous conversion, no hold */
    uint8_t buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "TMP117 write failed: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /* Conversion time: ~12 ms typ, 15 ms max */
        usleep(20000);

        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "TMP117 read failed: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *temperature = (float)raw / 256.0f;
        return 0;
    }
    return -1;
}

/* ---- AHT20 humidity reader ---- */
static int aht20_read(int fd, float *humidity) {
    uint8_t cmd = 0xBE; /* Soft reset */
    uint8_t buf[7];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "AHT20 reset write failed: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(20000);

        cmd = 0xAC; /* Measure, 12-bit humidity */
        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "AHT20 measure write failed: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(20000);

        if (read(fd, buf, 7) != 7) {
            fprintf(stderr, "AHT20 read failed: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (buf[0] & 0x80) {
            fprintf(stderr, "AHT20 busy\n");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint32_t raw = ((uint32_t)buf[1] << 12) |
                       ((uint32_t)buf[2] << 4) |
                       ((uint32_t)buf[3] >> 4);
        *humidity = ((float)raw / 1048576.0f) * 100.0f;
        return 0;
    }
    return -1;
}

/* ---- PIR motion reader ---- */
static int pir_read(struct gpiod_line *line, int *motion) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "PIR read failed: %s\n", strerror(errno));
        return -1;
    }
    *motion = val;
    return 0;
}

/* ---- Daily log file ---- */
static void get_log_filename(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(buf, len, LOG_FILE_PREFIX "%Y%m%d" LOG_FILE_SUFFIX, tm);
}

static int create_log_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp) {
        fclose(fp);
        return 0;
    }
    fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to create log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

static int log_data(const char *filename, float temp, float hum, int motion) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

int main(void) {
    int tmp117_fd = -1, aht20_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    tmp117_fd = open(I2C_BUS, O_RDWR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(tmp117_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set TMP117 slave address: %s\n", strerror(errno));
    }

    aht20_fd = open(I2C_BUS, O_RDWR);
    if (aht20_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(aht20_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set AHT20 slave address: %s\n", strerror(errno));
    }

    /* Open GPIO chip and get PIR line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Create initial log file */
    char filename[MAX_FILENAME_LEN];
    get_log_filename(filename, sizeof(filename));
    if (create_log_file(filename) < 0) {
        goto cleanup;
    }

    time_t last_midnight = time(NULL);
    while (running) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char filename[MAX_FILENAME_LEN];
        get_log_filename(filename, sizeof(filename));

        if (tm->tm_hour == 0 && tm->tm_min == 0 && tm->tm_sec < 5) {
            if (difftime(now, last_midnight) >= 24 * 3600) {
                if (create_log_file(filename) < 0) {
                    fprintf(stderr, "Failed to create new log file\n");
                } else {
                    last_midnight = now;
                }
            }
        }

        float temp = 0.0f, hum = 0.0f;
        int motion = 0;

        if (tmp117_read(tmp117_fd, &temp) < 0) {
            fprintf(stderr, "TMP117 read failed after retries\n");
        }
        if (aht20_read(aht20_fd, &hum) < 0) {
            fprintf(stderr, "AHT20 read failed after retries\n");
        }
        if (pir_read(pir_line, &motion) < 0) {
            fprintf(stderr, "PIR read failed after retries\n");
        }

        if (log_data(filename, temp, hum, motion) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    ret = 0;

cleanup:
    if (tmp117_fd >= 0) close(tmp117_fd);
    if (aht20_fd >= 0) close(aht20_fd);
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

