#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO   22
#define MOTOR_IN1_GPIO   23
#define MOTOR_IN2_GPIO   24

#define POLL_INTERVAL_US  2000000  /* 2 seconds */
#define MOTOR_RUN_US      5000000  /* 5 seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned gpio, unsigned mode)
{
    if (gpioSetMode(gpio, mode) != 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioSetMode(%u, %u) failed: %s",
                 gpio, mode, strerror(errno));
        log_event(buf);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioWrite(%u, %u) failed: %s",
                 gpio, level, strerror(errno));
        log_event(buf);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioRead(%u) failed: %s", gpio, strerror(errno));
        log_event(buf);
    }
    return v;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    if (safe_set_mode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_ENA_GPIO,  PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_IN1_GPIO,  PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_IN2_GPIO,  PI_OUTPUT) != 0) return -1;

    /* Ensure motor is off at startup */
    if (safe_write(MOTOR_ENA_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_IN1_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_IN2_GPIO, 0) != 0) return -1;

    return 0;
}

static void stop_motor(void)
{
    safe_write(MOTOR_ENA_GPIO, 0);
    safe_write(MOTOR_IN1_GPIO, 0);
    safe_write(MOTOR_IN2_GPIO, 0);
}

static int close_window(void)
{
    log_event("Closing window...");

    if (safe_write(MOTOR_IN1_GPIO, 1) != 0) return -1;
    if (safe_write(MOTOR_IN2_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_ENA_GPIO, 1) != 0) return -1;

    gpioDelay(MOTOR_RUN_US);

    stop_motor();
    log_event("Window closed.");
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    log_event("Rain sensor monitoring started.");

    while (g_running) {
        int rain = safe_read(RAIN_SENSOR_GPIO);

        if (rain < 0) {
            log_event("Error reading rain sensor; skipping cycle.");
        } else if (rain == 0) {
            log_event("Rain detected!");
            if (close_window() != 0) {
                log_event("Error closing window.");
            }
        } else {
            log_event("No rain.");
        }

        if (g_running)
            gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down...");
    stop_motor();
    gpioTerminate();
    log_event("Cleanup complete.");
    return EXIT_SUCCESS;
}

