#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_load(int *cpu_load)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int ret = fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                     &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);

    if (ret != 10) {
        fprintf(stderr, "Error reading /proc/stat data\n");
        return -1;
    }

    static unsigned long long prev_user = 0, prev_nice = 0, prev_system = 0, prev_idle = 0, prev_iowait = 0,
                              prev_irq = 0, prev_softirq = 0, prev_steal = 0, prev_guest = 0, prev_guest_nice = 0;

    unsigned long long cur_user = user, cur_nice = nice, cur_system = system, cur_idle = idle,
                       cur_iowait = iowait, cur_irq = irq, cur_softirq = softirq, cur_steal = steal,
                       cur_guest = guest, cur_guest_nice = guest_nice;

    if (prev_user == 0) {
        prev_user = cur_user; prev_nice = cur_nice; prev_system = cur_system; prev_idle = cur_idle;
        prev_iowait = cur_iowait; prev_irq = cur_irq; prev_softirq = cur_softirq; prev_steal = cur_steal;
        prev_guest = cur_guest; prev_guest_nice = cur_guest_nice;
        return 0;
    }

    unsigned long long prev_idle_total = prev_idle + prev_iowait;
    unsigned long long cur_idle_total = cur_idle + cur_iowait;
    unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long cur_non_idle = cur_user + cur_nice + cur_system + cur_irq + cur_softirq + cur_steal + cur_guest + cur_guest_nice;

    unsigned long long prev_total = prev_idle_total + prev_non_idle;
    unsigned long long cur_total = cur_idle_total + cur_non_idle;

    unsigned long long delta_idle = cur_idle_total - prev_idle_total;
    unsigned long long delta_total = cur_total - prev_total;

    if (delta_total == 0) {
        *cpu_load = 0;
    } else {
        *cpu_load = (int)((delta_total - delta_idle) * 100 / delta_total);
    }

    prev_user = cur_user; prev_nice = cur_nice; prev_system = cur_system; prev_idle = cur_idle;
    prev_iowait = cur_iowait; prev_irq = cur_irq; prev_softirq = cur_softirq; prev_steal = cur_steal;
    prev_guest = cur_guest; prev_guest_nice = cur_guest_nice;

    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    if (red < 0) red = 0; if (red > 255) red = 255;
    if (green < 0) green = 0; if (green > 255) green = 255;
    if (blue < 0) blue = 0; if (blue > 255) blue = 255;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

static void map_cpu_load_to_color(int cpu_load, int *red, int *green, int *blue)
{
    if (cpu_load < 0) cpu_load = 0;
    if (cpu_load > 100) cpu_load = 100;

    if (cpu_load <= 50) {
        *red = 0;
        *green = (int)((float)cpu_load / 50.0f * 255.0f);
        *blue = 255;
    } else {
        *red = (int)(((float)(cpu_load - 50) / 50.0f) * 255.0f);
        *green = 255;
        *blue = 0;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

