    uint8_t data[6];
    int32_t raw_temperature, raw_pressure;

    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS: %s\n", strerror(errno));
