        fprintf(stderr, "Invalid address: %s\n", UDP_IP);
        return -1;
    }
    if (sendto(udp_socket, data, strlen(data), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Error sending UDP data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    float temperature, pressure;
    char json_string[128];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not found (ID: 0x%02X, expected: 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_bmp280_data(i2c_handle, &temperature, &pressure) == 0) {
            snprintf(json_string, sizeof(json_string), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
            if (send_udp_data(json_string) != 0) {
                fprintf(stderr, "Failed to send UDP data\n");
            }
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

