#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      500000
#define SPI_FLAGS      0
#define FAN_GPIO       18
#define PWM_FREQUENCY  1000
#define PWM_RANGE      255
#define BUFFER_SIZE    20
#define SAMPLE_PERIOD  1.0

#define TEMP_LOW       25.0
#define TEMP_MID       40.0
#define TEMP_HIGH      60.0
#define DUTY_LOW       0
#define DUTY_MID       128
#define DUTY_HIGH      255

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} FanData;

static FanData fan_buffer[BUFFER_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int calculate_duty(float temperature) {
    if (temperature < TEMP_LOW) return DUTY_LOW;
    if (temperature < TEMP_MID) return (int)((temperature - TEMP_LOW) * (DUTY_MID - DUTY_LOW) / (TEMP_MID - TEMP_LOW) + 0.5);
    if (temperature < TEMP_HIGH) return (int)((temperature - TEMP_MID) * (DUTY_HIGH - DUTY_MID) / (TEMP_HIGH - TEMP_MID) + 0.5);
    return DUTY_HIGH;
}

static int read_max31855(int spi_handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X)\n", raw);
        return -1;
    }

    int16_t thermocouple = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple & 0x2000) thermocouple |= 0xC000;

    *temperature = thermocouple * 0.25f;
    return 0;
}

static void add_to_buffer(float temperature, int pwm_duty) {
    time(&fan_buffer[buffer_index].timestamp);
    fan_buffer[buffer_index].temperature = temperature;
    fan_buffer[buffer_index].pwm_duty    = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Fan Data Log (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        ctime_r(&fan_buffer[idx].timestamp, ts);
        ts[strlen(ts) - 1] = '\0';
        printf("[%s] Temp: %.2f C, PWM: %d\n",
               ts, fan_buffer[idx].temperature, fan_buffer[idx].pwm_duty);
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM initial off failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping cycle\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        int duty = calculate_duty(temperature);
        if (gpioPWM(FAN_GPIO, duty) < 0) {
            fprintf(stderr, "Error: gpioPWM set failed\n");
        }

        add_to_buffer(temperature, duty);
        printf("Temp: %.2f C, PWM: %d\n", temperature, duty);

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    spiClose(spi_handle);
    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

