    int32_t x1 = ((raw_temp - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t raw_pressure, int32_t raw_temp, const bmp180_cal_t *cal) {
    int32_t x1 = ((raw_temp - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t b3 = (((int32_t)cal->ac1 * 4 + x3 + x4 + 2) >> 2);
    uint32_t x5 = ((int32_t)cal->ac3 * b6) >> 13;
    uint32_t x6 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + x4 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (50000 >> 3);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

