        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nCleaning up...\n");
    gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

