#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         SPI_MODE_0
#define LOG_FILE         "rtd_log.csv"
#define SAMPLE_INTERVAL  5
#define RTD_A           3.9083e-3
#define RTD_B           -5.775e-7
#define RTD_R0          100.0
#define RTD_RNOMAL      1384.31
#define RTD_MAX_TEMP    1000.0
#define RTD_MIN_TEMP    -200.0
#define MAX_SPI_RETRIES  3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_max31865(uint16_t *rtd_resistance, float *temperature)
{
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, sizeof(tx)) == 0) {
            break;
        }
        usleep(10000);
    }

    if (attempt == MAX_SPI_RETRIES) {
        fprintf(stderr, "SPI communication failed after %d retries\n", MAX_SPI_RETRIES);
        return -1;
    }

    uint16_t fault_status = ((uint16_t)rx[0] << 8) | rx[1];
    if (fault_status & 0x0007) {
        fprintf(stderr, "MAX31865 fault detected: 0x%03X\n", fault_status);
        return -2;
    }

    uint16_t rtd_raw = ((uint16_t)rx[2] << 8) | rx[3];
    *rtd_resistance = rtd_raw;

    float rtd = (float)rtd_raw;
    float rtd_ratio = rtd / RTD_RNOMAL;
    float temp = RTD_A + RTD_B * rtd_ratio * rtd_ratio;
    *temperature = temp;

    return 0;
}

static float calculate_temperature(uint16_t rtd_resistance)
{
    float rtd = (float)rtd_resistance;
    float rtd_ratio = rtd / RTD_RNOMAL;
    float temp = RTD_A + RTD_B * rtd_ratio * rtd_ratio;
    return temp;
}

static int log_data(float temperature)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() != 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature (C)\n");
        fflush(g_log_fp);
    }

    printf("MAX31865 RTD Logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t rtd_resistance;
        float temperature;

        int ret = read_max31865(&rtd_resistance, &temperature);
        if (ret == 0) {
            if (log_data(temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else if (ret == -2) {
            fprintf(stderr, "Sensor fault detected. Check wiring and sensor.\n");
        } else {
            fprintf(stderr, "SPI communication error. Retrying...\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

