#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BME280_ADDR    0x76
#define BME280_CHIP_ID 0x60

#define BME280_REG_ID       0xD0
#define BME280_REG_RESET    0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS   0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG   0xF5
#define BME280_REG_DATA     0xF7

#define BME280_RESET_CMD    0xB6

#define LOG_FILE "bme280_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_read_reg24(int fd, uint8_t reg, uint32_t *val) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *val = ((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4);
    return 0;
}

static int bme280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &chip_id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t status;
    int retries = 10;
    do {
        if (i2c_read_reg8(fd, BME280_REG_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Failed to read status: %s\n", strerror(errno));
            return -1;
        }
        if (status & 0x01) usleep(2000);
        retries--;
    } while (retries > 0 && (status & 0x01));

    if (retries == 0) {
        fprintf(stderr, "Error: Sensor not ready after reset\n");
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write humidity control: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error: Failed to write config: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write control: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int bme280_read(int fd, float *temp, float *hum, float *press) {
    uint32_t raw_t, raw_p, raw_h;
    int32_t t_fine;

    if (i2c_read_reg24(fd, BME280_REG_DATA, &raw_p) < 0) return -1;
    if (i2c_read_reg24(fd, BME280_REG_DATA + 3, &raw_t) < 0) return -1;
