#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define ALERT_GPIO 24
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL_US 50000
#define PRESSURE_THRESHOLD_HPA 5.0f
#define ALERT_DURATION_US 1000000

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float pressure;
} PressureData;

static PressureData buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)data, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data from BMP180.\n");
        return -1;
    }
    ac1 = (int16_t)((data[0] << 8) | data[1]);
    ac2 = (int16_t)((data[2] << 8) | data[3]);
    ac3 = (int16_t)((data[4] << 8) | data[5]);
    ac4 = (uint16_t)((data[6] << 8) | data[7]);
    ac5 = (uint16_t)((data[8] << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1  = (int16_t)((data[12] << 8) | data[13]);
    b2  = (int16_t)((data[14] << 8) | data[15]);
    mb  = (int16_t)((data[16] << 8) | data[17]);
    mc  = (int16_t)((data[18] << 8) | data[19]);
    md  = (int16_t)((data[20] << 8) | data[21]);
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: Failed to write temperature command to BMP180.\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature data from BMP180.\n");
        return -1;
    }
    *raw_temp = (int32_t)((data[0] << 8) | data[1]);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0) {
        fprintf(stderr, "Error: Failed to write pressure command to BMP180.\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure data from BMP180.\n");
        return -1;
    }
    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> 8;
    return 0;
}

