    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void add_to_buffer(float pressure) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) return 0.0f;
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += buffer[i].pressure;
    }
    return (float)(sum / buffer_count);
}

static void trigger_alert(void) {
    gpioWrite(ALERT_GPIO, 1);
    fprintf(stderr, "Alert triggered! Pressure deviation detected.\n");
}

static void clear_alert(void) {
    gpioWrite(ALERT_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int32_t raw_temp, raw_pressure;
        if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            float pressure = calculate_pressure(raw_temp, raw_pressure);
            add_to_buffer(pressure);
            float avg_pressure = calculate_average_pressure();
            if (buffer_count > 1) {
                float diff = pressure - avg_pressure;
                if (diff > PRESSURE_THRESHOLD_HPA || diff < -PRESSURE_THRESHOLD_HPA) {
                    trigger_alert();
                    gpioDelay(ALERT_DURATION_US);
                    clear_alert();
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    clear_alert();
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

