#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli / 1000;
}

static int calculate_duty_cycle(int temperature) {
    if (temperature < MIN_TEMP) {
        return 0;
    } else if (temperature > MAX_TEMP) {
        return PWM_RANGE;
    }

    float fraction = (float)(temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP);
    return (int)(fraction * PWM_RANGE);
}

static int log_data(int temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %d C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    if (fclose(fp) != 0) {
