#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR     0x76
#define BMP280_ALT_ADDR 0x77
#define BMP280_REG_ID   0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL  0xF4
#define BMP280_REG_DATA  0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID   0x58
#define LOG_INTERVAL_S   5
#define LOG_FILE         "weather_data.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint16_t dig_T1; int16_t dig_T2; int16_t dig_T3;
    uint16_t dig_P1; int16_t dig_P2; int16_t dig_P3;
    int16_t dig_P4; int16_t dig_P5; int16_t dig_P6;
    int16_t dig_P7; int16_t dig_P8; int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, buf, sizeof(buf)) != 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) != 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_REG_RESET, 0xB6) != 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_DATA, data, 6) != 0) return -1;
    *raw_p = (int32_t)(((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | (data[2] >> 4));
    *raw_t = (int32_t)(((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | (data[5] >> 4));
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    double v1 = ((double)raw_t / 16384.0 - (double)cal->dig_T1 / 1024.0) * (double)cal->dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0);
    v2 = v2 * v2 * (double)cal->dig_T3;
    *t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_p, int32_t t_fine, const bmp280_calib_t *cal) {
    double v1 = (double)t_fine / 2.0 - 64000.0;
    double v2 = v1 * v1 * (double)cal->dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)cal->dig_P5 * 2.0;
    v2 = v2 / 4.0 + (double)cal->dig_P4 * 65536.0;
    v1 = ((double)cal->dig_P3 * v1 * v1 / 524288.0 + (double)cal->dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)cal->dig_P1;
    if (v1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - v2 / 4096.0) * 6250.0 / v1;
    v1 = (double)cal->dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)cal->dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)cal->dig_P7) / 16.0;
    return p / 100.0;
}

static int bmp280_trigger_forced(int fd) {
    return i2c_write_reg8(fd, BMP280_REG_CTRL, 0x27);
}

static int bmp280_wait_data(int fd) {
    uint8_t ctrl;
    for (int i = 0; i < 50; i++) {
        if (i2c_read_reg8(fd, BMP280_REG_CTRL, &ctrl) != 0) return -1;
        if ((ctrl & 0x09) == 0) return 0;
        usleep(2000);
    }
    return -1;
}

static int log_data(FILE *fp, double temp_c, double press_hpa) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    if (tm == NULL) return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp_c, press_hpa) < 0) return -1;
    if (fflush(fp) != 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    int addr = BMP280_ADDR;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        addr = BMP280_ALT_ADDR;
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
    }

    if (bmp280_init(fd) != 0) {
        fprintf(stderr, "BMP280 init failed at address 0x%02X\n", addr);
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_read_calibration(fd, &cal) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen " LOG_FILE);
        close(fd);
        return 1;
    }

    while (g_running) {
        if (bmp280_trigger_forced(fd) != 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
            break;
        }
        if (bmp280_wait_data(fd) != 0) {
            fprintf(stderr, "Error waiting for data ready\n");
            break;
        }
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Error reading raw data: %s\n", strerror(errno));
            break;
        }
        int32_t t_fine;
        double temp_c = bmp280_compensate_temp(raw_t, &cal, &t_fine);
        double press_hpa = bmp280_compensate_press(raw_p, t_fine, &cal);
        if (log_data(fp, temp_c, press_hpa) != 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            break;
        }
        printf("Logged: %.2f °C, %.2f hPa\n", temp_c, press_hpa);
        for (int i = 0; i < LOG_INTERVAL_S && g_running; i++) sleep(1);
    }

    if (fclose(fp) != 0) perror("fclose");
    if (close(fd) != 0) perror("close");
    return 0;
}

