#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define ALERT_PIN      18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static int  g_gpio_fd = -1;
static pthread_mutex_t g_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    float  buffer[BUFFER_SIZE];
    int    head;
    int    count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_init(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int gpio_init(void) {
    g_gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO export: %s\n", strerror(errno));
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", ALERT_PIN);
    if (write(g_gpio_fd, buf, len) < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %s\n", ALERT_PIN, strerror(errno));
        close(g_gpio_fd);
        g_gpio_fd = -1;
        return -1;
    }
    close(g_gpio_fd);
    g_gpio_fd = -1;

    g_gpio_fd = open("/sys/class/gpio/gpio18/direction", O_WRONLY);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO direction: %s\n", strerror(errno));
        return -1;
    }
    if (write(g_gpio_fd, "out", 2) < 0) {
        fprintf(stderr, "Error setting GPIO direction: %s\n", strerror(errno));
        close(g_gpio_fd);
        g_gpio_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp) {
    if (write(fd, (uint8_t[]){TEMP_REG}, 1) != 1) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    uint8_t data[2];
    ssize_t n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "Error reading from I2C (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp = (float)raw / 256.0f;
    return 0;
}

static void buffer_add(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static void *alert_thread(void *arg) {
    (void)arg;
    while (g_running) {
        float avg;
        pthread_mutex_lock(&g_buffer_mutex);
        avg = buffer_average((CircularBuffer *)arg);
        pthread_mutex_unlock(&g_buffer_mutex);

        int val = (avg > TEMP_THRESHOLD) ? 1 : 0;
        char path[64];
        int fd = open("/sys/class/gpio/gpio18/value", O_WRONLY);
        if (fd >= 0) {
            if (write(fd, val ? "1" : "0", 1) < 0) {
                fprintf(stderr, "Error writing to GPIO value: %s\n", strerror(errno));
            }
            close(fd);
        } else {
            fprintf(stderr, "Error opening GPIO value: %s\n", strerror(errno));
        }
        sleep(POLL_INTERVAL);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = i2c_init();
    if (g_i2c_fd < 0) return 1;

    if (gpio_init() < 0) {
        close(g_i2c_fd);
        return 1;
    }

    CircularBuffer cb = {0};
    pthread_t tid;
    if (pthread_create(&tid, NULL, alert_thread, &cb) != 0) {
        fprintf(stderr, "Error creating alert thread: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) == 0) {
            buffer_add(&cb, temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Sensor read failed; re-initializing I2C...\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            g_i2c_fd = i2c_init();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-init failed; exiting.\n");
                break;
            }
        }
        sleep(POLL_INTERVAL);
    }

    g_running = 0;
    pthread_join(tid, NULL);

    if (g_gpio_fd >= 0) {
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    pthread_mutex_destroy(&g_buffer_mutex);
    printf("Program terminated cleanly.\n");
    return 0;
}

