#define MAX31865_HFT_REG 0x04

#define MAX31865_CONFIG_VBIAS_50 0x80
#define MAX31865_CONFIG_4WIRE 0x00
#define MAX31865_CONFIG_FAULT_QUEUE_1 0x00
#define MAX31865_CONFIG_FAULT_MODE_1 0x00

#define R_REF 430.0
#define R_NOMINAL 100.0

typedef struct {
    double target_temperature;
    double kp;
    double ki;
    double kd;
} Config;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pwm_initialized = 0;
static double integral = 0.0;
static double previous_error = 0.0;
static Config config;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, Config *cfg) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s\n", filename, strerror(errno));
        cfg->target_temperature = 25.0;
        cfg->kp = 1.0;
        cfg->ki = 0.1;
        cfg->kd = 0.01;
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char key[64];
        char value[64];
        if (sscanf(line, "%63[^:]:%63s", key, value) == 2) {
            if (strcmp(key, "target_temperature") == 0) cfg->target_temperature = atof(value);
            else if (strcmp(key, "kp") == 0) cfg->kp = atof(value);
            else if (strcmp(key, "ki") == 0) cfg->ki = atof(value);
            else if (strcmp(key, "kd") == 0) cfg->kd = atof(value);
        }
    }
    fclose(fp);
    return 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = {(char)(reg & 0x7F), (char)value};
    char rx[2];
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = {(char)(reg | 0x80), 0x00};
    char rx[2];
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *value = (uint8_t)rx[1];
    return 0;
}

static int read_max31865(uint16_t *rtd_resistance) {
    uint8_t fault;
    if (spi_read_reg(MAX31865_FAULT_REG, &fault) != 0) return -1;
    if (fault & 0x01) {
        fprintf(stderr, "MAX31865 fault detected: %02X\n", fault);
        return -1;
    }

    uint8_t msb, lsb;
    if (spi_read_reg(MAX31865_RTD_MSB_REG, &msb) != 0) return -1;
    if (spi_read_reg(MAX31865_RTD_LSB_REG, &lsb) != 0) return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    if (raw & 0x0004) {
        fprintf(stderr, "MAX31865 overrange fault\n");
        return -1;
    }
    *rtd_resistance = raw & 0x0FFF;
    return 0;
}

static double calculate_temperature(uint16_t rtd_resistance) {
    if (rtd_resistance == 0) return -273.15;
    double rtd = (double)rtd_resistance;
    double ratio = rtd / R_NOMINAL;
    return 0.01 + 0.0039083 * ratio + 0.000000642 * ratio * ratio;
}

static double pid_calculate(double setpoint, double actual, double kp, double ki, double kd, double *integral, double *previous_error) {
    double error = setpoint - actual;
    *integral += error;
    if (*integral > 1000.0) *integral = 1000.0;
    if (*integral < -1000.0) *integral = -1000.0;
    double derivative = error - *previous_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

static void set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(PWM_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty\n");
    }
}

static void cleanup(void) {
    if (pwm_initialized) {
        gpioPWM(PWM_GPIO, 0);
        gpioTerminate();
        pwm_initialized = 0;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pwm_initialized = 1;

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set PWM GPIO mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }
    set_pwm_duty(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (read_config(CONFIG_FILE, &config) != 0) {
        fprintf(stderr, "Using default configuration\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t rtd_resistance;
    double temperature, pid_output;

    while (running) {
        if (read_max31865(&rtd_resistance) != 0) {
            fprintf(stderr, "SPI read error, setting PWM to 0\n");
            set_pwm_duty(0);
            break;
        }

        temperature = calculate_temperature(rtd_resistance);

        if (temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature exceeds maximum (%.2f > %.2f), setting PWM to 0\n", temperature, MAX_TEMP);
            set_pwm_duty(0);
            break;
        }

        pid_output = pid_calculate(config.target_temperature, temperature, config.kp, config.ki, config.kd, &integral, &previous_error);
        int duty = (int)pid_output;
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        set_pwm_duty(duty);

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double elapsed = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
        static double start_time = 0.0;
        if (start_time == 0.0) start_time = elapsed;
        double elapsed_time = elapsed - start_time;
        if (elapsed_time >= 1.0) {
            printf("Temperature: %.2f C, PWM Duty: %d%%\n", temperature, duty);
            start_time = elapsed;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_pwm_duty(0);
    cleanup();
    return 0;
}

