#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f
#define LOG_FILE "breach_log.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(int fd, bmp180_cal_t *cal) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1 + 2, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1 + 4, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC1 + 6, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC1 + 8, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC1 + 10, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1 + 12, &cal->b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1 + 14, &cal->b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1 + 16, &cal->mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1 + 18, &cal->mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1 + 20, &cal->md) < 0) return -1;
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_MSB + 1, &lsb) < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_MSB + 1, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_MSB + 2, &xlsb) < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static int32_t compute_temperature(int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    return (b5 + 8) >> 4;
}

static uint32_t compute_pressure(int32_t up, int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)cal->ac1 * 4 + x3) << 0) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (uint32_t)(p + ((x1 + x2 + 3791) >> 4));
}

static int log_breach(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }
    fprintf(log_fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(i2c_fd, &cal) < 0) {
        fprintf(stderr, "Error reading BMP180 calibration data\n");
        close(i2c_fd);
        return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t ut, up;
        int temp_ok = 0, press_ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_raw_temp(i2c_fd, &ut) == 0) {
                int32_t raw_temp = compute_temperature(ut, &cal);
                float temperature = raw_temp / 10.0f;
                temp_ok = 1;
            } else {
                fprintf(stderr, "Error reading temperature (attempt %d)\n", attempt + 1);
                usleep(100000);
                continue;
            }
            if (read_raw_pressure(i2c_fd, &up) == 0) {
                uint32_t raw_pressure = compute_pressure(up, ut, &cal);
                float pressure = raw_pressure / 100.0f;
                press_ok = 1;
            } else {
                fprintf(stderr, "Error reading pressure (attempt %d)\n", attempt + 1);
                usleep(100000);
                continue;
            }
            break;
        }

        if (!temp_ok || !press_ok) {
            fprintf(stderr, "Sensor read failed after %d attempts. Retrying in 1 second.\n", MAX_RETRIES);
            sleep(1);
            continue;
        }

        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            log_breach(temperature, pressure);
        }

        sleep(1);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp != NULL) fclose(log_fp);
    printf("\nExiting gracefully.\n");
    return 0;
}

