    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(i2c_fd, &cal) < 0) {
        fprintf(stderr, "Error reading BMP180 calibration data\n");
        close(i2c_fd);
        return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t ut, up;
        int temp_ok = 0, press_ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_raw_temp(i2c_fd, &ut) == 0) {
                int32_t raw_temp = compute_temperature(ut, &cal);
                float temperature = raw_temp / 10.0f;
                temp_ok = 1;
            } else {
                fprintf(stderr, "Error reading temperature (attempt %d)\n", attempt + 1);
                usleep(100000);
                continue;
            }
            if (read_raw_pressure(i2c_fd, &up) == 0) {
                uint32_t raw_pressure = compute_pressure(up, ut, &cal);
                float pressure = raw_pressure / 100.0f;
                press_ok = 1;
            } else {
                fprintf(stderr, "Error reading pressure (attempt %d)\n", attempt + 1);
                usleep(100000);
                continue;
            }
            break;
        }

        if (!temp_ok || !press_ok) {
            fprintf(stderr, "Sensor read failed after %d attempts. Retrying in 1 second.\n", MAX_RETRIES);
            sleep(1);
            continue;
        }

        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            log_breach(temperature, pressure);
        }

        sleep(1);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp != NULL) fclose(log_fp);
    printf("\nExiting gracefully.\n");
    return 0;
}

