/*
 * BMP180 temperature & pressure logger with fan control on Raspberry Pi 4.
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3V3, GND -> GND
 *   Fan control: GPIO18 (pin 12), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_fan bmp180_fan.c -lgpiod -lpigpio -lrt
 * Run:    sudo ./bmp180_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants -------------------------------------------------- */
#define BMP180_ADDR        0x77
#define BMP180_REG_CAL     0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_DATA    0xF6
#define BMP180_CMD_TEMP    0x2E
#define BMP180_CMD_PRESS   0x34   /* OSS = 0 */
#define BMP180_CAL_LEN     22
#define BMP180_TEMP_DELAY  5      /* ms */

/* ---- Fan / timing ----------------------------------------------------- */
#define FAN_GPIO           18
#define TEMP_THRESHOLD     30.0f
#define BUFFER_SIZE        60
#define SAMPLE_PERIOD_US   500000  /* 500 ms */

/* ---- Globals ---------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static uint16_t g_cal[11];
static float    g_temp_buf[BUFFER_SIZE];
static float    g_press_buf[BUFFER_SIZE];
static int      g_buf_idx = 0;
static int      g_buf_count = 0;

/* ---- Signal handling -------------------------------------------------- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: rc=%d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ---- Calibration ------------------------------------------------------ */
static int read_calibration(int handle)
{
    uint8_t raw[BMP180_CAL_LEN];
    if (i2c_read_block(handle, BMP180_REG_CAL, raw, sizeof(raw)) != 0)
        return -1;

    for (int i = 0; i < 11; i++)
        g_cal[i] = (uint16_t)((raw[i * 2] << 8) | raw[i * 2 + 1]);
    return 0;
}

/* ---- Temperature ------------------------------------------------------ */
static int read_temperature(int handle, float *temp)
{
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0)
        return -1;

    gpioDelay(BMP180_TEMP_DELAY * 1000);   /* microseconds */

    uint8_t raw[2];
    if (i2c_read_block(handle, BMP180_REG_DATA, raw, 2) != 0)
        return -1;

    int32_t ut = (int16_t)((raw[0] << 8) | raw[1]);
    *temp = (float)((ut - (int32_t)g_cal[5]) * g_cal[6] / 65536.0f + 20.0f);
    return 0;
}

/* ---- Pressure (OSS = 0) ------------------------------------------------ */
static int read_pressure(int handle, float *press)
{
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS) != 0)
        return -1;

    gpioDelay(5000);                       /* microseconds */

    uint8_t raw[3];
    if (i2c_read_block(handle, BMP180_REG_DATA, raw, 3) != 0)
        return -1;

    int32_t up = ((int32_t)raw[0] << 16) | ((int32_t)raw[1] << 8) | raw[2];
    up &= 0xFFFFF000;                       /* OSS = 0 */

    int32_t x1 = ((int32_t)g_cal[4] * (int32_t)up) >> 15;
    int32_t x2 = ((int32_t)g_cal[5] * (int32_t)(x1 + (int32_t)g_cal[6])) >> 15;
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)g_cal[8] * (b6 * b6) >> 12) >> 11;
    x2 = ((int32_t)g_cal[9] * b6) >> 13;
    int32_t b3 = (((int32_t)g_cal[7] * (b6 * b6) >> 12) + (x1 + x2 + 32768) >> 15);
    x1 = ((int32_t)g_cal[10] * b3) >> 15;
    x2 = ((int32_t)g_cal[11] * b6) >> 14;
    int32_t b4 = (x1 + x2 + 32768) >> 15;
    int32_t b7 = ((int32_t)up - b3) * (50000 >> 0);   /* OSS = 0 */

    int32_t p;
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *press = (float)(p + ((x1 + x2 + 3791) >> 4));
    return 0;
}

/* ---- Circular buffer --------------------------------------------------- */
static void buffer_add(float temp, float press)
{
    g_temp_buf[g_buf_idx] = temp;
    g_press_buf[g_buf_idx] = press;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

/* ---- Fan control ------------------------------------------------------ */
static void fan_set(bool on)
{
    gpioWrite(FAN_GPIO, on ? 1 : 0);
}

/* ---- Timer callback --------------------------------------------------- */
static void timer_cb(void *userdata)
{
    (void)userdata;

    float temp, press;

    if (read_temperature(g_i2c_handle, &temp) != 0) {
        fprintf(stderr, "Temperature read failed; skipping sample.\n");
        return;
    }

    if (read_pressure(g_i2c_handle, &press) != 0) {
        fprintf(stderr, "Pressure read failed; skipping sample.\n");
        return;
    }

    buffer_add(temp, press);

    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);

    printf("[%s] Temp: %.2f C  Pressure: %.2f Pa  Fan: %s\n",
           ts, temp, press, (temp > TEMP_THRESHOLD) ? "ON" : "OFF");
    fflush(stdout);

    fan_set(temp > TEMP_THRESHOLD);
}

/* ---- Cleanup ---------------------------------------------------------- */
static void cleanup(void)
{
    fan_set(false);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ------------------------------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                BMP180_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration(g_i2c_handle) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed.\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    fan_set(false);

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_cb, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFuncEx failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 logging started (500 ms period). Ctrl+C to exit.\n");

    while (g_running)
        gpioDelay(100000);                 /* 100 ms */

    gpioSetTimerFuncEx(0, 0, NULL, NULL); /* stop timer */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

