#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        2000000
#define SPI_FLAGS        0
#define HEATER_GPIO      17
#define PWM_FREQUENCY    1000
#define PWM_RANGE        1000
#define TARGET_TEMP      25.0
#define MAX_DUTY_CYCLE   800
#define LOG_FILE         "heater_log.csv"
#define SAMPLE_INTERVAL  1.0
#define MAX_RETRIES      3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int ret = spiXfer(handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: 0x%08X\n", raw);
        return -2;
    }
    int16_t thermocouple = (int16_t)(raw >> 18);
    *temperature = thermocouple * 0.25;
    return 0;
}

static int calculate_duty_cycle(float current_temp, float target_temp, int *integral, float *prev_error) {
    float error = target_temp - current_temp;
    *integral += error;
    if (*integral > 1000) *integral = 1000;
    if (*integral < -1000) *integral = -1000;
    float derivative = error - *prev_error;
    float output = 500 + (*integral * 0.1) + (derivative * 10);
    if (output < 0) output = 0;
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
    *prev_error = error;
    return (int)output;
}

static void log_data(float temperature, int duty_cycle, const char *error_msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        if (error_msg) {
            fprintf(log_file, "%s,ERROR,%s\n", ts, error_msg);
        } else {
            fprintf(log_file, "%s,%.2f,%d\n", ts, temperature, duty_cycle);
        }
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature,DutyCycle\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float integral = 0.0;
    float prev_error = 0.0;
    int duty_cycle = 0;
    while (running) {
        float temperature = 0.0;
        int retries = 0;
        bool read_ok = false;
        while (retries < MAX_RETRIES && !read_ok && running) {
            int rc = read_max31855(spi_handle, &temperature);
            if (rc == 0) {
                read_ok = true;
            } else if (rc == -2) {
                fprintf(stderr, "MAX31855 fault detected\n");
                log_data(0.0, duty_cycle, "MAX31855 fault");
                break;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000);
                }
            }
        }
        if (!read_ok) {
            gpioPWM(HEATER_GPIO, 0);
            duty_cycle = 0;
            log_data(0.0, duty_cycle, "SPI read failure");
            gpioDelay(1000000);
            continue;
        }
        int new_duty = calculate_duty_cycle(temperature, TARGET_TEMP, &integral, &prev_error);
        if (new_duty > MAX_DUTY_CYCLE) new_duty = MAX_DUTY_CYCLE;
        if (new_duty < 0) new_duty = 0;
        gpioPWM(HEATER_GPIO, new_duty);
        duty_cycle = new_duty;
        log_data(temperature, duty_cycle, NULL);
        gpioDelay((int)(SAMPLE_INTERVAL * 1000000));
    }
    gpioPWM(HEATER_GPIO, 0);
    cleanup();
    return 0;
}

