#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm(int pin, int duty)
{
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (duty %d): %s\n",
                pin, duty, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: read error on %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    *temp_out = temp;
    return 0;
}

static void control_led(int temp_milli)
{
    int r, g, b;

    if (temp_milli < 40000) {
        r = 0;
        g = 0;
        b = 255;
    } else if (temp_milli < 60000) {
        r = 0;
        g = 255;
        b = 0;
    } else {
        r = 255;
        g = 0;
        b = 0;
    }

    if (set_pwm(RED_PIN,   r)   != 0) return;
    if (set_pwm(GREEN_PIN, g)   != 0) return;
    if (set_pwm(BLUE_PIN,  b)   != 0) return;
}

static void cleanup(void)
{
    set_pwm(RED_PIN,   255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN,  255);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int temp_milli;
        if (read_temperature(&temp_milli) != 0) {
            fprintf(stderr, "Skipping update cycle due to read error.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        control_led(temp_milli);

        printf("Temperature: %d m°C  |  R: %3d  G: %3d  B: %3d\n",
               temp_milli,
               gpioGetPWMdutycycle(RED_PIN),
               gpioGetPWMdutycycle(GREEN_PIN),
               gpioGetPWMdutycycle(BLUE_PIN));

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

