#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 1000000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_BIT_LOW_US 50
#define DHT22_BIT_HIGH_US 50
#define DHT22_MAX_PULSES 85

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    uint32_t pulses[DHT22_MAX_PULSES];
    int pulse_count = 0;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    uint32_t start_tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for sensor response (line high)\n");
            return -1;
        }
    }
    start_tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 0) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for sensor response (line low)\n");
            return -1;
        }
    }
    start_tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for sensor response (line high)\n");
            return -1;
        }
    }

    for (int i = 0; i < DHT22_MAX_PULSES; i++) {
        uint32_t start = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - start > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22: Timeout waiting for low-to-high transition\n");
                return -1;
            }
        }
        uint32_t high_start = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - high_start > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22: Timeout waiting for high-to-low transition\n");
                return -1;
            }
        }
        pulses[i] = gpioTick() - high_start;
        if (i > 0 && pulses[i] > pulses[i - 1] * 10) {
            break;
        }
        pulse_count++;
    }

    if (pulse_count < 40) {
        fprintf(stderr, "DHT22: Incomplete response (%d pulses)\n", pulse_count);
        return -1;
    }

    for (int i = 0; i < 40; i++) {
        if (pulses[i] > pulses[i + 1] * 5) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
        i++;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum error (calc=%02X, recv=%02X)\n", (data[0] + data[1] + data[2] + data[3]) & 0xFF, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    if (*humidity < 0.0f || *humidity > 100.0f || *temperature < -40.0f || *temperature > 80.0f) {
        fprintf(stderr, "DHT22: Out-of-range reading (H=%.1f T=%.1f)\n", *humidity, *temperature);
        return -1;
    }

    return 0;
}

static int send_http_request(const char *ip, int port, float temperature, float humidity) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(sock);
        return -1;
    }

    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    char body[256];
    int body_len = snprintf(body, sizeof(body),
        "{\"timestamp\":\"%s\",\"temperature\":%.1f,\"humidity\":%.1f}",
        timestamp, temperature, humidity);

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST /api/humidity HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        ip, body_len, body);

    if (send(sock, request, req_len, 0) < 0) {
        perror("send");
        close(sock);
        return -1;
    }

    char response[1024];
    ssize_t bytes = recv(sock, response, sizeof(response) - 1, 0);
    if (bytes > 0) {
        response[bytes] = '\0';
        printf("Server response: %s\n", response);
    } else if (bytes == 0) {
        printf("Server disconnected\n");
    } else {
        perror("recv");
    }

    close(sock);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    float temperature, humidity;
    int success = 0;

    while (running) {
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_dht22(&temperature, &humidity) == 0) {
                printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
                if (send_http_request(SERVER_IP, SERVER_PORT, temperature, humidity) == 0) {
                    success = 1;
                    break;
                }
            } else {
                fprintf(stderr, "DHT22 read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            }
            if (attempt < MAX_RETRIES - 1) {
                sleep(2);
            }
        }

        if (!success && running) {
            fprintf(stderr, "Failed to send data after %d attempts\n", MAX_RETRIES);
        }

        if (running) {
            sleep(5);
        }
    }

    gpioTerminate();
    return 0;
}

