#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE_OSS3 0xF4
#define BMP180_CONV_DELAY_US    26000
#define LOG_FILE                "pressure_log.txt"
#define BUTTON_GPIO             4
#define DEBOUNCE_US             200000
#define SAMPLE_INTERVAL_US      2000000

static volatile sig_atomic_t g_i2c_handle = -1;
static volatile sig_atomic_t g_logging_enabled = 0;
static volatile uint32_t g_last_interrupt_tick = 0;

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }
    cal->ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(BMP180_CONV_DELAY_US);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS3) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(BMP180_CONV_DELAY_US);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read pressure data\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - 3);
    return 0;
}

static int32_t compute_b5(const bmp180_cal_t *cal, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static int32_t compute_pressure(const bmp180_cal_t *cal, int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << 0) + 2) >> 2);
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static int log_pressure(double pressure_hpa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure_hpa);
    } else {
        fprintf(fp, "<timestamp error>, %.2f hPa\n", pressure_hpa);
    }
    fclose(fp);
    return 0;
}

static void button_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t elapsed = tick - g_last_interrupt_tick;
    if (elapsed > DEBOUNCE_US) {
        g_logging_enabled = !g_logging_enabled;
        printf("Logging %s\n", g_logging_enabled ? "ENABLED" : "DISABLED");
        g_last_interrupt_tick = tick;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus 1 at 0x%02X (sensor absent?)\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(g_i2c_handle, &cal) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as input\n", BUTTON_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: cannot set pull-up on GPIO %d\n", BUTTON_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(BUTTON_GPIO, button_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Error: cannot set alert function on GPIO %d\n", BUTTON_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("BMP180 ready. Press the button on GPIO %d to toggle logging.\n", BUTTON_GPIO);

    while (1) {
        if (g_logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(g_i2c_handle, &ut) == 0 &&
                read_raw_pressure(g_i2c_handle, &up) == 0) {
                int32_t b5 = compute_b5(&cal, ut);
                int32_t pressure = compute_pressure(&cal, up, b5);
                double pressure_hpa = pressure / 100.0;
                if (log_pressure(pressure_hpa) != 0) {
                    fprintf(stderr, "Warning: failed to log pressure\n");
                }
            } else {
                fprintf(stderr, "Warning: sensor read error, skipping sample\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Unreachable in normal operation; kept for completeness. */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

