static void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

static int read_dht22(struct gpiod_line *line, float *humidity) {
    struct timespec ts_start, ts_end;
    long long diff_us;
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) {
        log_error("Failed to request line as output");
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        log_error("Failed to set line low");
        return -1;
    }
    usleep(DHT22_START_LOW_US);
    if (gpiod_line_set_value(line, 1) < 0) {
        log_error("Failed to set line high");
        return -1;
    }
    usleep(DHT22_START_HIGH_US);
    if (gpiod_line_set_value(line, 1) < 0) {
        log_error("Failed to release line");
        return -1;
    }
    if (gpiod_line_request_input(line, "dht22") < 0) {
        log_error("Failed to request line as input");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) {
        log_error("clock_gettime failed");
        return -1;
    }

    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) {
            log_error("clock_gettime failed");
            return -1;
        }
        diff_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000LL + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000LL;
        if (diff_us > DHT22_TIMEOUT_US) {
            log_error("DHT22 timeout waiting for sensor response");
            return -1;
        }

        if (gpiod_line_get_value(line) == 0) break;
    }

    for (int i = 0; i < 40; i++) {
        while (gpiod_line_get_value(line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) {
                log_error("clock_gettime failed");
                return -1;
            }
            if ((ts_end.tv_sec - ts_start.tv_sec) * 1000000LL + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000LL > DHT22_TIMEOUT_US) {
                log_error("DHT22 timeout waiting for low-to-high transition");
                return -1;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) {
            log_error("clock_gettime failed");
            return -1;
        }

        while (gpiod_line_get_value(line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) {
                log_error("clock_gettime failed");
                return -1;
