            diff_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000LL + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000LL;
            if (diff_us > DHT22_TIMEOUT_US) {
                log_error("DHT22 timeout waiting for high-to-low transition");
                return -1;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) {
            log_error("clock_gettime failed");
            return -1;
        }

        long long bit_start = (ts_start.tv_sec * 1000000LL) + (ts_start.tv_nsec / 1000LL);
        while (gpiod_line_get_value(line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) {
                log_error("clock_gettime failed");
                return -1;
            }
            long long bit_end = (ts_end.tv_sec * 1000000LL) + (ts_end.tv_nsec / 1000LL);
            diff_us = bit_end - bit_start;
            if (diff_us > DHT22_TIMEOUT_US) {
                log_error("DHT22 timeout waiting for low-to-high transition");
                return -1;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) {
            log_error("clock_gettime failed");
            return -1;
        }

