        fprintf(stderr, "Error writing fan state to %s: %s\n", FAN_STATE_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s after write: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int get_max_state(void) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s to read max_state: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int calculate_fan_speed(int temperature) {
    if (temperature < 45) return 0;
    if (temperature < 55) return 1;
    if (temperature < 65) return 2;
    return 3;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s for logging: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int max_state = get_max_state();
    if (max_state < 0) {
        fprintf(stderr, "Failed to determine max_state. Exiting.\n");
        return 1;
    }

    int current_fan_state = read_fan_state();
    if (current_fan_state < 0) {
        fprintf(stderr, "Failed to read initial fan state. Exiting.\n");
        return 1;
    }

    log_event("Fan control started.");

    while (program_running) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int target_fan_state = calculate_fan_speed(temperature);

        if (target_fan_state != current_fan_state) {
            if (target_fan_state > max_state) {
                fprintf(stderr, "Warning: requested fan state %d exceeds max_state %d. Clamping.\n", target_fan_state, max_state);
                target_fan_state = max_state;
            }
            if (write_fan_state(target_fan_state) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Fan speed set to state %d (temp: %d°C).", target_fan_state, temperature);
                log_event(log_message);
                current_fan_state = target_fan_state;
            } else {
                fprintf(stderr, "Failed to set fan state. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (write_fan_state(0) != 0) {
        fprintf(stderr, "Failed to set fan to off on shutdown.\n");
    }
    log_event("Fan control stopped.");
    return 0;
}

