#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"

#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    double Kp, Ki, Kd;
    double integral;
    double previous_error;
} PIDController;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_max31855(int handle, double *temperature) {
    char buffer[4] = {0};
    int bytes_read = spiRead(handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: open circuit\n");
            return -2;
        }
        if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: short to GND\n");
            return -2;
        }
        if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
            return -2;
        }
        fprintf(stderr, "MAX31855 fault: unknown\n");
        return -2;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;
    }
    *temperature = thermocouple_raw * 0.25;
    return 0;
}

static int set_heater_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(gpio, duty_cycle) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static double calculate_pid(PIDController *pid, double setpoint, double measured_value) {
    double error = setpoint - measured_value;
    pid->integral += error;
    if (pid->integral > 100.0) pid->integral = 100.0;
    if (pid->integral < -100.0) pid->integral = -100.0;
    double derivative = error - pid->previous_error;
    double output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    return output;
}

static int log_data(double temperature, int duty_cycle, double pid_output) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle, pid_output);
    fclose(fp);
    return 0;
}

static void cleanup() {
    set_heater_pwm(HEATER_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    PIDController pid = {Kp, Ki, Kd, 0.0, 0.0};
    double temperature;
    int duty_cycle = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int ret = read_max31855(spi_handle, &temperature);
        if (ret == 0) {
            if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                set_heater_pwm(HEATER_GPIO, 0);
                pid.integral = 0.0;
                pid.previous_error = 0.0;
            } else {
                double pid_output = calculate_pid(&pid, TARGET_TEMPERATURE, temperature);
                duty_cycle = (int)pid_output;
                if (set_heater_pwm(HEATER_GPIO, duty_cycle) < 0) {
                    fprintf(stderr, "Failed to set heater PWM\n");
                }
                if (log_data(temperature, duty_cycle, pid_output) < 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            }
        } else if (ret == -2) {
            set_heater_pwm(HEATER_GPIO, 0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
        } else {
            fprintf(stderr, "SPI read error\n");
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

