#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define DUTY_MIN 0
#define DUTY_MAX 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float map_temp_to_duty(float temp) {
    if (temp <= TEMP_MIN) return (float)DUTY_MIN;
    if (temp >= TEMP_MAX) return (float)DUTY_MAX;
    return DUTY_MIN + (temp - TEMP_MIN) * (DUTY_MAX - DUTY_MIN) / (TEMP_MAX - TEMP_MIN);
}

static int log_data(float temp, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    if (sz == 0) {
        fprintf(fp, "Timestamp,Temperature (C),PWM Duty Cycle (%%)\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", ts, temp, duty);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. GPIO%d, %d Hz PWM. Press Ctrl+C to exit.\n", FAN_GPIO, PWM_FREQUENCY);

    while (running) {
        float temp = 0.0f;
        int ret = system("sensors | grep 'Package id' | awk '{print $4}' 2>/dev/null");
        if (ret == 0) {
            FILE *fp = popen("sensors | grep 'Package id' | awk '{print $4}'", "r");
            if (fp) {
                char line[256];
                if (fgets(line, sizeof(line), fp)) {
                    if (sscanf(line, "%f", &temp) != 1) {
                        fprintf(stderr, "Failed to parse temperature from sensors output\n");
                    }
                }
                pclose(fp);
            } else {
                fprintf(stderr, "Error executing sensors command: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error executing sensors command: %s\n", strerror(errno));
        }

        int duty = (int)map_temp_to_duty(temp);
        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty);
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d%%\n", temp, duty);

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan control stopped.\n");
    return 0;
}

