    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. GPIO%d, %d Hz PWM. Press Ctrl+C to exit.\n", FAN_GPIO, PWM_FREQUENCY);

    while (running) {
        float temp = 0.0f;
        int ret = system("sensors | grep 'Package id' | awk '{print $4}' 2>/dev/null");
        if (ret == 0) {
            FILE *fp = popen("sensors | grep 'Package id' | awk '{print $4}'", "r");
            if (fp) {
                char line[256];
                if (fgets(line, sizeof(line), fp)) {
                    if (sscanf(line, "%f", &temp) != 1) {
                        fprintf(stderr, "Failed to parse temperature from sensors output\n");
                    }
                }
                pclose(fp);
            } else {
                fprintf(stderr, "Error executing sensors command: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error executing sensors command: %s\n", strerror(errno));
        }

        int duty = (int)map_temp_to_duty(temp);
        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty);
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d%%\n", temp, duty);

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan control stopped.\n");
    return 0;
}

