/*
 * Raspberry Pi Zero W — dual Sensirion SLF3S-1300F liquid flow sensor logger.
 *
 * Wiring:
 *   Sensor 1: SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3V3, GND -> GND
 *   Sensor 2: SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3V3, GND -> GND
 *
 * The sensors are assumed to be connected through a Sensirion SF06 multiplexer
 * or a comparable I2C hub so that both devices appear on the same I2C bus.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SENSOR1_ADDR         0x20
#define SENSOR2_ADDR         0x21
#define LOG_FILE             "flow_log.txt"
#define READ_INTERVAL_US     1000000          /* 1 second */
#define MAX_RETRIES          3
#define READ_BYTES           3                /* 2 data + 1 CRC */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (poly 0x31, init 0xFF, no final XOR)                 */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 3-byte frame from an SLF3S-1300F sensor                    */
/* Returns 0 on success, -1 on persistent failure.                     */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *flow_out)
{
    uint8_t buf[READ_BYTES];
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int n = i2cReadDevice(handle, (char *)buf, READ_BYTES);
        if (n == READ_BYTES) {
            if (sensirion_crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "[WARN] CRC mismatch (attempt %d)\n", attempt + 1);
                continue;
            }
            uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
            *flow_out = (float)raw / 1000.0f;   /* SLF3S-1300F: 1000 counts/mL */
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice returned %d (attempt %d/%d)\n",
                n, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(10000);                   /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flow record to the log file                    */
/* ------------------------------------------------------------------ */
static int log_flow_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f\n", ts, flow1, flow2);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int h1 = -1, h2 = -1;
    int rc = EXIT_SUCCESS;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open sensor handles ---------------------------------------- */
    h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "i2cOpen failed for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, h1);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "i2cOpen failed for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, h2);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Flow sensor logger started.  Logging to %s every 1 s.\n", LOG_FILE);
    printf("Press Ctrl-C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_sensor(h1, &f1) == 0);
        int ok2 = (read_sensor(h2, &f2) == 0);

        if (ok1 && ok2) {
            if (log_flow_data(f1, f2) != 0)
                fprintf(stderr, "[ERROR] Failed to write log entry\n");
        } else {
            if (!ok1)
                fprintf(stderr, "[ERROR] Sensor 1 read failed after %d retries\n",
                        MAX_RETRIES);
            if (!ok2)
                fprintf(stderr, "[ERROR] Sensor 2 read failed after %d retries\n",
                        MAX_RETRIES);
        }

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");

cleanup:
    if (h1 >= 0) i2cClose(h1);
    if (h2 >= 0) i2cClose(h2);
    gpioTerminate();
    return rc;
}

