code:
/*
 * Rotary Encoder Monitor using TMAG5110A1 Hall-Effect Latch Sensors
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern GPIO API)
 *
 * Wiring:
 *   TMAG5110A1 CH1 -> GPIO17 (Channel A)
 *   TMAG5110A1 CH2 -> GPIO18 (Channel B)
 *   TMAG5110A1 VDD -> 3.3 V
 *   TMAG5110A1 GND -> GND
 *   TMAG5110A1 VCC -> 3.3 V
 *   TMAG5110A1 GND -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o encoder_monitor encoder_monitor.c -lpigpio -lrt
 * Run:    sudo ./encoder_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define GPIO_A          17          /* Channel A pin */
#define GPIO_B          18          /* Channel B pin */
#define LOG_FILE        "encoder_log.txt"
#define PULSES_PER_REV  360         /* TMAG5110A1 quadrature resolution */
#define SAMPLE_DELAY_US 1000        /* 1 ms polling interval */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  initialize_gpio(void);
static void cleanup_gpio(void);
static int  read_encoder_state(void);
static float calculate_angle(int a, int b);
static int  log_position(float angle);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- GPIO Init / Cleanup ----------------------- */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    /* Configure pins as inputs with internal pull-up resistors (open-drain
     * Hall-effect latch outputs are active-high with pull-ups enabled). */
    if (gpioSetMode(GPIO_A, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_A);
        return -1;
    }
    if (gpioSetMode(GPIO_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_B);
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", GPIO_A);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", GPIO_B);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Release pins and terminate pigpio. */
    gpioTerminate();
}

/* ----------------------------- Encoder Read ------------------------------ */
static int read_encoder_state(void)
{
    int a = gpioRead(GPIO_A);
    int b = gpioRead(GPIO_B);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error: gpioRead failed (A=%d, B=%d).\n", a, b);
        return -1;
    }

    return (a << 1) | b;
}

/* ----------------------------- Angle Calculation ------------------------- */
static float calculate_angle(int a, int b)
{
    /* 2-bit quadrature state machine: 00 -> 0, 01 -> 90, 10 -> 180, 11 -> 270.
     * Each state transition increments/decrements by 90 degrees. */
    static int prev_state = 0;
    int        cur_state  = (a << 1) | b;
    float      angle      = 0.0f;

    if (cur_state != prev_state) {
        switch (cur_state) {
            case 0:  angle = 0.0f; break;
            case 1:  angle = 90.0f; break;
            case 2:  angle = 180.0f; break;
            case 3:  angle = 270.0f; break;
            default:
                fprintf(stderr, "Warning: invalid encoder state %d.\n", cur_state);
                angle = 0.0f;
                break;
        }
        prev_state = cur_state;
    }

    return angle;
}

/* ----------------------------- Logging ----------------------------------- */
static int log_position(float angle)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    cleanup_gpio();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int state = read_encoder_state();
        if (state < 0) {
            /* Transient read error: back off briefly and retry. */
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float angle = calculate_angle((state >> 1) & 1, state & 1);

        if (log_position(angle) != 0) {
            fprintf(stderr, "Warning: logging failed, continuing.\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

