/*
 * ADPD144RI photometric sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADPD144RI SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   ADPD144RI SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   ADPD144RI VDD  -> 3.3 V
 *   ADPD144RI GND  -> GND
 *   LED anode      -> GPIO17 (pin 11) via 330 ohm resistor
 *   LED cathode    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- ADPD144RI constants (from datasheet) ---- */
#define ADPD144RI_I2C_ADDR  0x28   /* 7-bit address; 0x50 in 8-bit mode */
#define I2C_BUS             "/dev/i2c-1"

/* Register addresses (16-bit, big-endian on the bus) */
#define REG_RED_DATA        0x00
#define REG_IR_DATA         0x02
#define REG_MODE            0x0F
#define REG_CONFIG          0x10

/* Mode register bits */
#define MODE_CONTINUOUS     0x01

/* GPIO17 line for the LED */
#define LED_GPIO_LINE       17

/* IR threshold for LED activation */
#define IR_THRESHOLD        2000

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US  100000

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip   = NULL;
static struct gpiod_line  *g_led    = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit ADPD144RI register (big-endian).  */
static int adpd_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit ADPD144RI register (big-endian). */
static int adpd_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_adpd144ri(int fd)
{
    /* Put sensor into standby to configure */
    if (adpd_write_reg16(fd, REG_MODE, 0x00) < 0)
        return -1;

    /* Configure register (example: enable both channels) */
    if (adpd_write_reg16(fd, REG_CONFIG, 0x0001) < 0)
        return -1;

    /* Start continuous measurement mode */
    if (adpd_write_reg16(fd, REG_MODE, MODE_CONTINUOUS) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir)
{
    if (adpd_read_reg16(fd, REG_RED_DATA, red) < 0)
        return -1;
    if (adpd_read_reg16(fd, REG_IR_DATA, ir) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADPD144RI_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Probe sensor: try a register read to confirm presence ---- */
    uint16_t probe;
    if (adpd_read_reg16(g_i2c_fd, REG_RED_DATA, &probe) < 0) {
        fprintf(stderr, "ADPD144RI not responding at 0x%02X: %s\n",
                ADPD144RI_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (init_adpd144ri(g_i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("adpd144ri_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "timestamp,red,ir\n");

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t red, ir;

        if (read_sensor_data(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(g_log_fp, red, ir);

        if (ir > IR_THRESHOLD) {
            if (gpiod_line_set_value(g_led, 1) < 0)
                fprintf(stderr, "LED on failed: %s\n", strerror(errno));
        } else {
            if (gpiod_line_set_value(g_led, 0) < 0)
                fprintf(stderr, "LED off failed: %s\n", strerror(errno));
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

