code:
#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define SENSOR_GPIO 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t counter_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Pulse counter updated by the ISR and read by the main thread. */
static volatile unsigned long pulse_count = 0;

/* Signal handler for graceful shutdown (SIGINT, SIGTERM). */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* ISR callback: increments the pulse counter atomically. */
static void pulse_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;
    pthread_mutex_lock(&counter_mutex);
    pulse_count++;
    pthread_mutex_unlock(&counter_mutex);
}

/* Calculate RPM from the pulse count over the sample interval. */
static double calculate_rpm(unsigned long pulses) {
    return (double)pulses * 60.0 / (double)SAMPLE_INTERVAL_SEC;
}

/* Log the RPM value with a timestamp to the log file. */
static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void) {
    /* Initialize the pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure the GPIO pin as input with a pull-down resistor. */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode. */
