#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x28
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LED        17
#define IR_THRESHOLD    2000
#define LOG_FILE        "adpd144ri_log.txt"
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adpd144ri_init(int fd) {
    if (i2c_write_reg8(fd, 0x00, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x01, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x02, 0x02) < 0) return -1;
    if (i2c_write_reg8(fd, 0x03, 0x03) < 0) return -1;
    return 0;
}

static int adpd144ri_read(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t r_lo, r_hi, i_lo, i_hi;

    if (i2c_read_reg8(fd, 0x04, &r_lo) < 0) return -1;
    if (i2c_read_reg8(fd, 0x05, &r_hi) < 0) return -1;
    if (i2c_read_reg8(fd, 0x06, &i_lo) < 0) return -1;
    if (i2c_read_reg8(fd, 0x07, &i_hi) < 0) return -1;

    *red = (uint16_t)((r_hi << 8) | r_lo);
    *ir  = (uint16_t)((i_hi << 8) | i_lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

int main(void) {
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        goto cleanup;
    }

    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed (sensor may be absent)\n");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LED, strerror(errno));
        goto cleanup;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;

        if (adpd144ri_read(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        log_data(log_fp, red, ir);

        if (ir > IR_THRESHOLD) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
            }
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return ret;
}

