/*
 * Raspberry Pi Zero W — Sensirion SLF3S-4000B Liquid Flow Sensor monitor
 *
 * Wiring:
 *   SLF3S SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   SLF3S SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   SLF3S VDD  -> 3.3 V (pin 1)
 *   SLF3S GND  -> GND  (pin 6)
 *
 * The SLF3S-4000B returns a 16-bit MSB-first raw value followed by a CRC-8
 * byte (polynomial 0x31, initial value 0xFF).  The flow rate is extracted
 * from the two data bytes; the CRC is validated and discarded.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x28          /* SLF3S-4000B default 7-bit I2C address */
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_MS      1000          /* 1 second sampling interval */
#define MAX_RETRIES    3

/* CRC-8 parameters used by Sensirion: poly 0x31, init 0xFF, no reflect */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a command byte to the SLF3S.  The sensor expects a single
 * command byte followed by a 3 ms measurement delay.
 */
static int slf3s_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write(cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    usleep(3000);                 /* 3 ms measurement conversion time */
    return 0;
}

/*
 * Read exactly `len` bytes from the SLF3S.
 * Returns 0 on success, -1 on error.
 */
static int slf3s_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t got = 0;
    while (got < len) {
        ssize_t n = read(fd, buf + got, len - got);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        got += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and stores the flow rate in `flow_rate_uL_min`.
 * Returns -1 on I2C or CRC error.
 */
static int read_flow_rate(int fd, float *flow_rate_uL_min)
{
    uint8_t cmd = 0x00;            /* continuous measurement start */
    uint8_t data[3];

    if (slf3s_write_cmd(fd, cmd) < 0)
        return -1;

    if (slf3s_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC over the two data bytes */
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(data, 2), data[2]);
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *flow_rate_uL_min = (float)raw;   /* raw LSB = 1 uL/min */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }
    /* Write a CSV header if the file is empty */
    if (ftell(fp) == 0)
        fprintf(fp, "timestamp,flow_rate_uL_min\n");
    return 0;
}

static void log_flow(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, flow_rate);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, SLF3S_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (log_open(LOG_FILE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    g_log_fp = fopen(LOG_FILE, "a");   /* reopen for deterministic flush */

    printf("Monitoring SLF3S-4000B on %s (addr 0x%02X) — Ctrl+C to stop.\n",
           I2C_BUS, SLF3S_ADDR);

    while (g_running) {
        float flow_rate = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            usleep(100000);          /* 100 ms back-off */
        }

        if (ok) {
            log_flow(g_log_fp, flow_rate);
            printf("Flow rate: %.2f uL/min\n", flow_rate);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; "
                            "continuing.\n", MAX_RETRIES);
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 100)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

