#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x26
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_S 5

/* MICS-VZ-89TE register addresses */
#define REG_TVOC_RAW 0x00
#define REG_ECO2_RAW 0x01
#define REG_STATUS 0x02

/* Status bits */
#define STATUS_BUSY 0x01
#define STATUS_ERROR 0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit-addressed register (big-endian on bus). */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from a 16-bit-addressed register (big-endian on bus). */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* Read a single byte register. */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[1];

    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;
    if (i2cReadDevice(handle, data, 1) != 1)
        return -1;

    *out = (uint8_t)data[0];
    return 0;
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2)
{
    uint8_t status = 0;

    if (i2c_read_reg8(handle, REG_STATUS, &status) != 0) {
        fprintf(stderr, "Error: failed to read status register.\n");
        return -1;
    }

    if (status & STATUS_ERROR) {
        fprintf(stderr, "Error: sensor reports internal error (status=0x%02X).\n", status);
        return -1;
    }
    if (status & STATUS_BUSY) {
        fprintf(stderr, "Warning: sensor is busy (status=0x%02X); retrying.\n", status);
        return -1;
    }

    if (i2c_read_reg16(handle, REG_TVOC_RAW, tvoc) != 0) {
