#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN        17
#define GPIO_CONSUMER   "ttp223_tamper"
#define POLL_INTERVAL_NS (100 * 1000 * 1000L)   /* 100 ms */
#define TAMPER_THRESHOLD_NS (5 * 1000 * 1000 * 1000L) /* 5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec last_touch_time;
    struct timespec now;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(line, GPIO_CONSUMER) < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &last_touch_time) == -1) {
        perror("clock_gettime");
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (BCM). Press Ctrl+C to exit.\n",
           GPIO_PIN);
    fflush(stdout);

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        if (val == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }

            long diff_ns = (now.tv_sec - last_touch_time.tv_sec) * 1000000000L
                         + (now.tv_nsec - last_touch_time.tv_nsec);

            if (diff_ns > TAMPER_THRESHOLD_NS) {
                printf("ALERT: Tamper detected! Touch held for over 5 seconds.\n");
                fflush(stdout);
                last_touch_time = now;
            }
        } else {
            last_touch_time.tv_sec = 0;
            last_touch_time.tv_nsec = 0;
        }

        struct timespec req = { 0, POLL_INTERVAL_NS };
        struct timespec rem;
        while (nanosleep(&req, &rem) == -1 && errno == EINTR && g_running) {
            req = rem;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Exiting gracefully.\n");
    return ret;
}

