#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/soundcard.h>
#include <linux/fb.h>
#include <stdint.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define SAMPLE_RATE 44100
#define BUFFER_SIZE 1024
#define FILE_NAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(void) {
    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd < 0) {
        perror("open(" GPIO_CHIP ")");
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE_OFFSETS, &(unsigned int){GPIO_LINE}) < 0) {
        perror("ioctl(GPIO_GET_LINE_OFFSETS)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE_IOCTL, &(unsigned int){GPIO_LINE}) < 0) {
        perror("ioctl(GPIO_GET_LINE_IOCTL)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_LINE_REQUEST_OUTPUT, &(unsigned int){GPIO_LINE}) < 0) {
        perror("ioctl(GPIO_LINE_REQUEST_OUTPUT)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_LINE_SET_VALUE, &(unsigned int){GPIO_LINE, 0}) < 0) {
        perror("ioctl(GPIO_LINE_SET_VALUE)");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int open_alsa_device(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" I2S_DEVICE ")");
        return -1;
    }

    int val = 0;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &val) < 0) {
        perror("ioctl(SNDCTL_DSP_SETFMT)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &val) < 0) {
        perror("ioctl(SNDCTL_DSP_CHANNELS)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SNDCTL_DSP_SPEED, &val) < 0) {
        perror("ioctl(SNDCTL_DSP_SPEED)");
        close(fd);
        return -1;
    }

    return fd;
}

static int capture_audio(int alsa_fd, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen(" FILE_NAME ")");
        return -1;
    }

    unsigned char buffer[BUFFER_SIZE];
    int bytes_read;

    while (running) {
        bytes_read = read(alsa_fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("read");
            break;
        } else if (bytes_read == 0) {
            fprintf(stderr, "read returned 0 bytes\n");
            break;
        }

        if (fwrite(buffer, 1, bytes_read, fp) != (size_t)bytes_read) {
            perror("fwrite");
            break;
        }
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int alsa_fd = open_alsa_device();
    if (alsa_fd < 0) {
        return EXIT_FAILURE;
    }

    if (capture_audio(alsa_fd, FILE_NAME) != 0) {
        close(alsa_fd);
        return EXIT_FAILURE;
    }

    if (close(alsa_fd) < 0) {
        perror("close(alsa_fd)");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

