    if (ioctl(fd, GPIO_LINE_SET_VALUE, &(unsigned int){GPIO_LINE, 0}) < 0) {
        perror("ioctl(GPIO_LINE_SET_VALUE)");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int open_alsa_device(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" I2S_DEVICE ")");
        return -1;
    }

    int val = 0;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &val) < 0) {
        perror("ioctl(SNDCTL_DSP_SETFMT)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &val) < 0) {
        perror("ioctl(SNDCTL_DSP_CHANNELS)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SNDCTL_DSP_SPEED, &val) < 0) {
        perror("ioctl(SNDCTL_DSP_SPEED)");
        close(fd);
        return -1;
    }

    return fd;
}

static int capture_audio(int alsa_fd, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen(" FILE_NAME ")");
        return -1;
    }

    unsigned char buffer[BUFFER_SIZE];
    int bytes_read;

    while (running) {
        bytes_read = read(alsa_fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("read");
            break;
        } else if (bytes_read == 0) {
            fprintf(stderr, "read returned 0 bytes\n");
            break;
        }

        if (fwrite(buffer, 1, bytes_read, fp) != (size_t)bytes_read) {
            perror("fwrite");
            break;
        }
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int alsa_fd = open_alsa_device();
    if (alsa_fd < 0) {
        return EXIT_FAILURE;
    }

    if (capture_audio(alsa_fd, FILE_NAME) != 0) {
        close(alsa_fd);
        return EXIT_FAILURE;
    }

    if (close(alsa_fd) < 0) {
        perror("close(alsa_fd)");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

