#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO          18
#define PWM_FREQUENCY     100
#define DEBOUNCE_MS       50
#define POLL_INTERVAL_US  50000
#define SENSOR_TIMEOUT_S  5
#define LOG_FILE          "flame_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *log, const char *event, int gpio, int level)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log, "%s - %s - GPIO%d - Level: %d\n", ts, event, gpio, level);
    fflush(log);
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO %d as input\n", FLAME_SENSOR_GPIO);
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan GPIO %d as output\n", FAN_GPIO);
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        return -1;
    }

    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", FAN_GPIO);
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error reading flame sensor GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return level;
}

static void control_fan(int flame_detected)
{
    if (gpioPWM(FAN_GPIO, flame_detected ? 128 : 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", FAN_GPIO);
    }
}

static void cleanup(void)
{
    gpioPWM(FAN_GPIO, 0);
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_INPUT);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event(g_log, "Program started", 0, 0);

    int flame_active = 0;
    time_t last_valid = time(NULL);
    int last_level = -1;

    while (g_running) {
        int level = read_flame_sensor();

        if (level < 0) {
            log_event(g_log, "Sensor read error", FLAME_SENSOR_GPIO, -1);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (level != last_level) {
            last_level = level;
            last_valid = time(NULL);
        }

        if (difftime(time(NULL), last_valid) > SENSOR_TIMEOUT_S) {
            log_event(g_log, "Sensor timeout - possible sensor absent", FLAME_SENSOR_GPIO, -1);
            break;
        }

        if (level == 0 && !flame_active) {
            log_event(g_log, "Flame detected", FLAME_SENSOR_GPIO, level);
            flame_active = 1;
            control_fan(1);
        } else if (level == 1 && flame_active) {
            log_event(g_log, "Flame ended", FLAME_SENSOR_GPIO, level);
            flame_active = 0;
            control_fan(0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event(g_log, "Program shutting down", 0, 0);
    cleanup();
    fclose(g_log);
    return EXIT_SUCCESS;
}

