#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define FRAME_PERIOD_US 100000
#define FRAME_SIZE 32768
#define LOG_FILE "radar_data.bin"

#define MAGIC_NUMBER 4144

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
} RadarConfig;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
} FrameHeader;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int handle, const uint8_t *tx, uint8_t *rx, int len) {
    int ret = spiXfer(handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed: returned %d, expected %d\n", ret, len);
        return -1;
    }
    return 0;
}

static int read_radar_frame(uint8_t *frame, int len) {
    uint8_t tx[FRAME_SIZE];
    memset(tx, 0, sizeof(tx));

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to assert trigger pin\n");
        return -1;
    }
    gpioDelay(1000);

    if (spi_transfer(spi_handle, tx, frame, len) != 0) {
        gpioWrite(TRIGGER_PIN, 0);
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deassert trigger pin\n");
        return -1;
    }

    return 0;
}

static int log_frame(const uint8_t *frame, int len) {
    FrameHeader header;
    header.timestamp = (uint64_t)time(NULL);
    header.frame_number = 1;

    if (fwrite(&header, sizeof(FrameHeader), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write frame header\n");
        return -1;
    }
    if (fwrite(frame, len, 1, log_file) != 1) {
        fprintf(stderr, "Failed to write frame data\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int log_config(const RadarConfig *config) {
    uint64_t ts = (uint64_t)time(NULL);
    RadarConfig cfg;
    memcpy(&cfg, config, sizeof(RadarConfig));

    if (fwrite(&MAGIC_NUMBER, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write magic number\n");
        return -1;
    }
    if (fwrite(&ts, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp\n");
        return -1;
    }
    if (fwrite(&cfg, sizeof(RadarConfig), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write config\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set data ready pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on data ready pin\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    RadarConfig config = {
        .magic = MAGIC_NUMBER,
        .timestamp = (uint64_t)time(NULL),
        .start_freq = 77000000000ULL,
        .end_freq = 79000000000ULL,
        .num_chirps = 64,
        .num_samples = 256
    };

    if (log_config(&config) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t *frame = malloc(FRAME_SIZE);
    if (!frame) {
        fprintf(stderr, "Failed to allocate frame buffer\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (running) {
        if (gpioRead(DATA_READY_PIN) == 1) {
            if (read_radar_frame(frame, FRAME_SIZE) == 0) {
                if (log_frame(frame, FRAME_SIZE) != 0) {
                    fprintf(stderr, "Failed to log frame\n");
                }
            } else {
                fprintf(stderr, "Failed to read radar frame\n");
            }
        }
        gpioDelay(FRAME_PERIOD_US);
    }

    printf("\nShutting down...\n");
    free(frame);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

