/*
 * OPT3001 Ambient Light Sensor reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 VCC  -> Pi 3V3  (pin 1)
 *   OPT3001 GND  -> Pi GND  (pin 9)
 *   OPT3001 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   OPT3001 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3001_reader opt3001_reader.c
 *
 * The OPT3001 is a 16-bit, auto-range, continuous-conversion ambient
 * light sensor.  It is typically found on breakout boards from
 * Adafruit, SparkFun, and other vendors.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3001 constants (from TI datasheet) ---- */
#define OPT3001_I2C_ADDR        0x44   /* 7-bit address (ADDR pin tied to GND) */
#define OPT3001_REG_RESULT      0x00   /* Result register (read-only) */
#define OPT3001_REG_CONFIG      0x01   /* Configuration register */
#define OPT3001_REG_MANUFACTURER 0x7E  /* Manufacturer ID / device ID */

#define OPT3001_MANUFACTURER_ID 0x5449  /* "TI" in ASCII (big-endian) */

/* Config register bit fields */
#define OPT3001_CFG_MODE_CONT   0x0000  /* Continuous conversion mode */
#define OPT3001_CFG_AUTO_RANGE  0x0000  /* Auto-full-scale range */
#define OPT3001_CFG_INT_EN      0x0000  /* No interrupt */
#define OPT3001_CFG_POL         0x0000  /* No polarity */
#define OPT3001_CFG_DR_100MS    0x0000  /* 100 ms conversion time */
#define OPT3001_CFG_RESET       0x0001  /* Reset bit */

/* Conversion time constants */
#define OPT3001_CONV_TIME_US    100000  /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an OPT3001 register (pigpio i2cWriteWordData
 * sends the register address as the first byte, then the 16-bit data
 * payload; the sensor expects the register address in the upper byte
 * of the word, so we swap bytes). */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    uint16_t swapped = ((value >> 8) & 0xFF) | ((value & 0xFF) << 8);
    int rc = i2cWriteWordData(handle, reg, swapped);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteWordData(reg=0x%02X, val=0x%04X) failed: %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an OPT3001 register.  pigpio's
 * i2cReadWordData returns the 16-bit word as (high_byte << 8) |
 * low_byte, so we swap bytes to reconstruct the sensor's native
 * big-endian format. */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    uint16_t swapped = ((rc >> 8) & 0xFF) | ((rc & 0xFF) << 8);
    *out = swapped;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the sensor is present by reading the manufacturer ID. */
static int opt3001_verify(int handle)
{
    uint16_t id = 0;
    if (opt3001_read_reg(handle, OPT3001_REG_MANUFACTURER, &id) < 0)
        return -1;
    if (id != OPT3001_MANUFACTURER_ID) {
        fprintf(stderr, "[ERROR] Manufacturer ID mismatch: got 0x%04X, expected 0x%04X\n",
                id, OPT3001_MANUFACTURER_ID);
        return -1;
    }
    printf("[INFO] OPT3001 detected (manufacturer ID 0x%04X)\n", id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the sensor for continuous conversion with auto-range. */
static int opt3001_configure(int handle)
{
    uint16_t cfg = OPT3001_CFG_MODE_CONT | OPT3001_CFG_AUTO_RANGE |
                   OPT3001_CFG_INT_EN | OPT3001_CFG_POL |
                   OPT3001_CFG_DR_100MS | OPT3001_CFG_RESET;

    if (opt3001_write_reg(handle, OPT3001_REG_CONFIG, cfg) < 0)
        return -1;

    /* Allow the reset bit to clear and the first conversion to start. */
    gpioDelay(10000);  /* 10 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit result register and convert to lux. */
static int opt3001_read_lux(int handle, float *lux_out)
{
    uint16_t raw = 0;
    if (opt3001_read_reg(handle, OPT3001_REG_RESULT, &raw) < 0)
        return -1;

    /* Auto-range mode: 16-bit signed two's-complement, 1 lux / LSB. */
    int16_t signed_raw = (int16_t)raw;
    *lux_out = (float)signed_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_lux_data(float lux_value)
{
    FILE *fp = fopen("light_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open light_data.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, lux_value);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the OPT3001 address ---- */
    g_i2c_handle = i2cOpen(1, OPT3001_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                OPT3001_I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence ---- */
    if (opt3001_verify(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] OPT3001 not detected on bus 1 at 0x%02X\n",
                OPT3001_I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor ---- */
    if (opt3001_configure(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] OPT3001 configuration failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] OPT3001 reader started.  Logging to light_data.txt every ~100 ms.\n");
    printf("[INFO] Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float lux = 0.0f;
        if (opt3001_read_lux(g_i2c_handle, &lux) < 0) {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle.\n");
        } else {
            printf("[INFO] Lux: %.2f\n", lux);
            log_lux_data(lux);
        }

        /* Wait for the next conversion (100 ms) */
        gpioDelay(OPT3001_CONV_TIME_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

