/*
 * flame_detect.c — Read SainSmart IR Flame Sensor on Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor VCC  -> Pi 3.3 V (pin 1)
 *   Sensor GND  -> Pi GND   (pin 9)
 *   Sensor DOUT -> Pi GPIO17 (pin 11, BCM 17)
 *
 * The SainSmart module drives DOUT high when no flame is detected and
 * low when a flame is detected (active-low, internal pull-up).
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 * Run:    ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define POLL_INTERVAL_S  1           /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("%s", buf);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config *req_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Open the GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* ---- Configure the line as input with internal pull-up ---- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        perror("gpiod_line_settings_new()");
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        perror("gpiod_line_settings_set_direction()");
        goto cleanup;
    }

    if (gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_settings_set_bias()");
        goto cleanup;
    }

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        perror("gpiod_line_config_new()");
        goto cleanup;
    }

    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1, settings) < 0) {
        perror("gpiod_line_config_add_line_settings()");
        goto cleanup;
    }

    req_cfg = gpiod_line_request_config_new();
    if (req_cfg == NULL) {
        perror("gpiod_line_request_config_new()");
        goto cleanup;
    }

    gpiod_line_request_config_set_consumer(req_cfg, "flame-sensor");

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line()");
        goto cleanup;
    }

    if (gpiod_line_request(line, req_cfg, line_cfg) < 0) {
        perror("gpiod_line_request()");
        goto cleanup;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value()");
            /* Brief pause before retrying to avoid log flooding on transient errors */
            sleep(POLL_INTERVAL_S);
            continue;
        }

        print_timestamp();
        if (value == 0) {
            printf(" Flame Detected: YES\n");
        } else {
            printf(" Flame Detected: NO\n");
        }
        fflush(stdout);

        sleep(POLL_INTERVAL_S);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (req_cfg != NULL) {
        gpiod_line_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

