#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_PIN   17
#define CENTER_PIN 18
#define RIGHT_PIN  27
#define POLL_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int rc;

    rc = signal(SIGINT, signal_handler);
    if (rc == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    rc = signal(SIGTERM, signal_handler);
    if (rc == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    rc = gpioSetMode(LEFT_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set LEFT_PIN %d as input: %d\n", LEFT_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetMode(CENTER_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set CENTER_PIN %d as input: %d\n", CENTER_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetMode(RIGHT_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set RIGHT_PIN %d as input: %d\n", RIGHT_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int left   = gpioRead(LEFT_PIN);
        int center = gpioRead(CENTER_PIN);
        int right  = gpioRead(RIGHT_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "gpioRead failed: left=%d center=%d right=%d\n",
                    left, center, right);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

