/*
 * Raspberry Pi 3 Model B+ — Dual TMAG5110 Hall-Effect Latch reader
 *
 * Wiring:
 *   Sensor 1 OUT  -> BCM GPIO4  (physical pin 7)
 *   Sensor 2 OUT  -> BCM GPIO5  (physical pin 8)
 *   VDD           -> 3.3 V
 *   GND           -> GND
 *
 * TMAG5110 OUT is open-drain with an external pull-up resistor.
 *   Magnet present  -> OUT LOW  (digital 0)
 *   Magnet absent   -> OUT HIGH (digital 1)
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lrt
 *
 * Run:
 *   ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#include <gpiod.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the default GPIO chip (gpiochip0 on RPi 3B+) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* --- Get the two GPIO lines --- */
    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(SENSOR_1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(SENSOR_2_PIN)");
        goto cleanup;
    }

    /* --- Request both lines as inputs --- */
    if (gpiod_line_request_input(line1, "tmag5110_sensor1") < 0) {
        perror("gpiod_line_request_input(SENSOR_1_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "tmag5110_sensor2") < 0) {
        perror("gpiod_line_request_input(SENSOR_2_PIN)");
        goto cleanup;
    }

    printf("TMAG5110 Hall-Effect Latch reader started.\n");
    printf("  Sensor 1 OUT -> BCM GPIO%d\n", SENSOR_1_PIN);
    printf("  Sensor 2 OUT -> BCM GPIO%d\n", SENSOR_2_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            perror("gpiod_line_get_value(SENSOR_1_PIN)");
            goto cleanup;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value(SENSOR_2_PIN)");
            goto cleanup;
        }

        /* TMAG5110 OUT is open-drain with pull-up:
         *   0 -> magnet detected (LOW)
         *   1 -> magnet absent  (HIGH) */
        printf("Sensor 1: %s | Sensor 2: %s\n",
               val1 == 0 ? "LOW (Magnet Detected)" : "HIGH (Magnet Absent)",
               val2 == 0 ? "LOW (Magnet Detected)" : "HIGH (Magnet Absent)");
        fflush(stdout);

        /* Sleep for the poll interval, but wake early on signal */
        for (int ms = 0; ms < POLL_INTERVAL_MS && g_running; ms += 10) {
            usleep(10 * 1000);
        }
    }

    printf("\nExiting cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (line1 != NULL) {
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

