#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int previous_state = -1;
    int current_state;
    int rc;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure GPIO4 as input with internal pull-up */
    rc = gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d (code %d).\n",
                TILT_SENSOR_GPIO, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO%d (code %d).\n",
                TILT_SENSOR_GPIO, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d. Press Ctrl-C to exit.\n",
           TILT_SENSOR_GPIO);
    fflush(stdout);

    while (g_running) {
        current_state = gpioRead(TILT_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO%d (code %d).\n",
                    TILT_SENSOR_GPIO, current_state);
            break;
        }

        if (current_state != previous_state) {
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            previous_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

