static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int si1145_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int si1145_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int si1145_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading word reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int si1145_wait_response(int handle) {
    for (int i = 0; i < 10; i++) {
        int resp = si1145_read_reg(handle, SI1145_REG_RESPONSE);
        if (resp < 0) return -1;
        if ((resp & 0x0F) != 0) return 0;
        gpioDelay(10000);
    }
    fprintf(stderr, "Si1145 response timeout\n");
    return -1;
}

static int si1145_send_command(int handle, uint8_t command) {
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, command) < 0) return -1;
    return si1145_wait_response(handle);
}

static int si1145_init(int handle) {
    int part_id = si1145_read_reg(handle, SI1145_REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_INT_CFG, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    if (si1145_wait_response(handle) < 0) return -1;

    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_CHLIST) < 0) return -1;
    if (si1145_write_reg(handle, 0x17, 0x07) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_PSLED21) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x03) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_PSLED3) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x03) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_PS_ADC_GAIN) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x01) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_PS_ADC_MISC) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_ALS_VIS_ADC_GAIN) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x01) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_ALS_VIS_ADC_MISC) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_ALS_IR_ADC_GAIN) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x01) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PARAM_WR | SI1145_PARAM_ALS_IR_ADC_MISC) < 0) return -1;
    if (si1145_write_reg(handle, 0x0F, 0x00) < 0) return -1;

    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO) < 0) return -1;
    if (si1145_wait_response(handle) < 0) return -1;

    return 0;
}

static int si1145_read_uv_index(int handle) {
    return si1145_read_reg(handle, SI1145_REG_UV_INDEX);
}

static int si1145_read_als_visible(int handle) {
    return si1145_read_word(handle, SI1145_REG_ALS_VIS_DATA0);
}

static int log_data(FILE *fp, float uv_index, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, uv_index, als_visible) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1, addr 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
        fflush(log_file);
    }

    while (running) {
        if (si1145_write_reg(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
            fprintf(stderr, "Error forcing ALS measurement\n");
        } else {
            gpioDelay(100000);

            int uv_index = si1145_read_uv_index(i2c_handle);
            int als_visible = si1145_read_als_visible(i2c_handle);

            if (uv_index >= 0 && als_visible >= 0) {
                float uv_float = (float)uv_index;
                if (log_data(log_file, uv_float, als_visible) < 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                printf("UV Index: %.2f, ALS Visible: %d\n", uv_float, als_visible);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        sleep(1);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

