#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x20
#define SENSOR2_ADDR   0x21
#define ALARM_PIN      17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define START_CMD_MSB  0x36
#define START_CMD_LSB  0x82
#define MEAS_DELAY_MS  100
#define LOOP_DELAY_MS  1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t addr, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t addr, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

static int read_flow_rate(int fd, uint8_t addr, float *flow_rate) {
    uint8_t buf[3];
    if (i2c_read_bytes(fd, addr, buf, 3) < 0) {
        fprintf(stderr, "I2C read error from 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch from 0x%02X\n", addr);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 1000.0f;
    return 0;
}

static void log_flow_rate(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Flow Rate: %.3f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }

    if (i2c_write_cmd(fd, SENSOR1_ADDR, START_CMD_MSB, START_CMD_LSB) < 0 ||
        i2c_write_cmd(fd, SENSOR2_ADDR, START_CMD_MSB, START_CMD_LSB) < 0) {
        fprintf(stderr, "Failed to start sensors: %s\n", strerror(errno));
        close(fd);
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }

    usleep(MEAS_DELAY_MS * 1000);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(fd, SENSOR1_ADDR, &flow1);
        int ok2 = read_flow_rate(fd, SENSOR2_ADDR, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            float avg = (flow1 + flow2) / 2.0f;
            log_flow_rate(fp, avg);
            if (avg < FLOW_THRESHOLD) {
                gpiod_line_set_value(alarm, 1);
            } else {
                gpiod_line_set_value(alarm, 0);
            }
        } else {
            fprintf(stderr, "Sensor read error (s1=%d, s2=%d)\n", ok1, ok2);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    gpiod_line_set_value(alarm, 0);
    fclose(fp);
    close(fd);
    gpiod_line_release(alarm);
    gpiod_chip_close(chip);
    return 0;
}

