#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    time_t timestamp;
    int    value;
} sensor_data_t;

static sensor_data_t sensor_buffer[BUFFER_SIZE];
static int           buffer_index = 0;
static int           buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_to_buffer(int value) {
    sensor_buffer[buffer_index].timestamp = time(NULL);
    sensor_buffer[buffer_index].value     = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&sensor_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(ts, "UNKNOWN", sizeof(ts));
        }
        printf("[%s] Sensor Value: %d\n", ts, sensor_buffer[idx].value);
    }
    printf("--- End of Log ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Monitoring KY-033 obstacle sensor on GPIO%d (pull-up enabled)...\n", SENSOR_PIN);
    printf("Press Ctrl+C to exit and view the log.\n");

    while (program_running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            printf("Alert: Obstacle detected!\n");
            fflush(stdout);
        }

        add_to_buffer(sensor_value);
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting program...\n");
    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

