        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Monitoring KY-033 obstacle sensor on GPIO%d (pull-up enabled)...\n", SENSOR_PIN);
    printf("Press Ctrl+C to exit and view the log.\n");

    while (program_running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            printf("Alert: Obstacle detected!\n");
            fflush(stdout);
        }

        add_to_buffer(sensor_value);
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting program...\n");
    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

