/*
 * D7S vibration sensor monitor for Raspberry Pi 5 (Bookworm).
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (BCM 2, /dev/i2c-1 SDA)
 *   D7S SCL  -> GPIO3 (BCM 3, /dev/i2c-1 SCL)
 *   D7S VCC  -> 3.3 V
 *   D7S GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o d7s_monitor d7s_monitor.c
 * Run:    ./d7s_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x20          /* D7S default 7-bit I2C address */
#define D7S_REG_MODE   0x00          /* Mode register */
#define D7S_REG_X_L    0x08          /* X-axis LSB (auto-increment) */
#define D7S_MODE_VIB   0x01          /* Vibration mode */
#define D7S_MODE_STANDBY 0x00       /* Standby mode */
#define D7S_ACTIVE_TIMEOUT_MS 1000  /* Max wait for sensor to become active */
#define D7S_POLL_DELAY_MS  500       /* Polling interval */
#define CSV_FILENAME      "fan_health.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C burst write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s (read %zd bytes, expected %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* D7S sensor operations                                               */
/* ------------------------------------------------------------------ */
static int d7s_init(int fd)
{
    /* Put sensor into standby so we can configure it. */
    if (i2c_write_reg8(fd, D7S_REG_MODE, D7S_MODE_STANDBY) == -1)
        return -1;

    /* Switch to vibration mode. */
    if (i2c_write_reg8(fd, D7S_REG_MODE, D7S_MODE_VIB) == -1)
        return -1;

    /* Allow the sensor to settle and become active. */
    printf("D7S switched to vibration mode; waiting up to %d ms for sensor to become active...\n",
           D7S_ACTIVE_TIMEOUT_MS);
    for (int elapsed = 0; elapsed < D7S_ACTIVE_TIMEOUT_MS && g_running; elapsed += 10)
        usleep(10000);  /* 10 ms */

    if (!g_running) {
        fprintf(stderr, "Interrupted during D7S active-wait.\n");
        return -1;
    }

    /* Verify the sensor is indeed in vibration mode. */
    uint8_t mode = 0;
    if (i2c_read_reg8(fd, D7S_REG_MODE, &mode) == -1)
        return -1;
    if (mode != D7S_MODE_VIB) {
        fprintf(stderr, "D7S did not enter vibration mode (read 0x%02X).\n", mode);
        return -1;
    }

    printf("D7S ready for vibration data.\n");
    return 0;
}

static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, D7S_REG_X_L, raw, sizeof(raw)) == -1)
        return -1;

    /* D7S acceleration registers are little-endian. */
    *x = (int16_t)((raw[1] << 8) | raw[0]);
    *y = (int16_t)((raw[3] << 8) | raw[2]);
    *z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int csv_write_header_if_new(FILE *fp)
{
    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "timestamp,x,y,z\n") < 0) {
            perror("fprintf(header)");
            return -1;
        }
        fflush(fp);
    }
    return 0;
}

static int csv_write_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        perror("fprintf(sample)");
        return -1;
    }
    if (fflush(fp) == EOF) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd != -1) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus. */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) == -1) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor. */
    if (d7s_init(g_i2c_fd) == -1) {
        fprintf(stderr, "D7S initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode. */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        perror("fopen(" CSV_FILENAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    if (csv_write_header_if_new(g_csv) == -1) {
        fprintf(stderr, "Failed to write CSV header.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging D7S vibration data to %s. Press Ctrl+C to stop.\n", CSV_FILENAME);

    int16_t x, y, z;
    while (g_running) {
        if (d7s_read_xyz(g_i2c_fd, &x, &y, &z) == -1) {
            fprintf(stderr, "D7S read error; retrying in %d ms...\n",
                    D7S_POLL_DELAY_MS);
            usleep(D7S_POLL_DELAY_MS * 1000);
            continue;
        }

        if (csv_write_sample(g_csv, x, y, z) == -1) {
            fprintf(stderr, "CSV write error; continuing.\n");
        }

        usleep(D7S_POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

