/*
 * Raspberry Pi 4 Model B — Dual KY-032 IR Obstacle Avoidance Sensor
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO23 (BCM)
 *   Sensor 2 OUT -> GPIO24 (BCM)
 *   LED anode    -> GPIO25 (BCM) via 220-330 ohm resistor
 *   LED cathode  -> GND
 *
 * The KY-032 module drives its OUT pin LOW when an obstacle is detected
 * within ~10 cm.  The LED is turned on whenever either sensor reads LOW
 * and turned off only when both sensors read HIGH.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_avoidance obstacle_avoidance.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>

#define SENSOR_1_PIN  23
#define SENSOR_2_PIN  24
#define LED_PIN       25
#define POLL_MS       100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1 = NULL, *s2 = NULL, *led = NULL;
    int rc = EXIT_FAILURE;

    /* --- signal handling for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- open the default gpiochip (gpiochip0 on Pi 4) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* --- acquire the three lines --- */
    s1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (!s1) {
        perror("gpiod_chip_get_line(SENSOR_1_PIN)");
        goto cleanup;
    }
    s2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (!s2) {
        perror("gpiod_chip_get_line(SENSOR_2_PIN)");
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line(LED_PIN)");
        goto cleanup;
    }

    /* --- request sensor lines as inputs --- */
    if (gpiod_line_request_input(s1, "ky032-s1") < 0) {
        perror("gpiod_line_request_input(s1)");
        goto cleanup;
    }
    if (gpiod_line_request_input(s2, "ky032-s2") < 0) {
        perror("gpiod_line_request_input(s2)");
        goto cleanup;
    }

    /* --- request LED line as output, initial value LOW --- */
    if (gpiod_line_request_output(led, "ky032-led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Obstacle avoidance system started.  Press Ctrl+C to exit.\n");

    /* --- main polling loop --- */
    while (g_running) {
        int v1 = gpiod_line_get_value(s1);
        int v2 = gpiod_line_get_value(s2);

        if (v1 < 0 || v2 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int obstacle = (v1 == 0 || v2 == 0) ? 1 : 0;

        if (gpiod_line_set_value(led, obstacle) < 0) {
            perror("gpiod_line_set_value(led)");
            break;
        }

        usleep(POLL_MS * 1000);
    }

    /* --- ensure LED is off on exit --- */
    if (led) {
        gpiod_line_set_value(led, 0);
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* release lines (gpiod_line_release is safe even if NULL) */
    if (s1) gpiod_line_release(s1);
    if (s2) gpiod_line_release(s2);
