static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMAG5170 register (big-endian on the bus). */
static int tmag5170_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMAG5170 register (big-endian on the bus). */
static int tmag5170_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, select) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int tmag5170_init(int handle)
{
    uint16_t device_id = 0;

    /* Verify Device ID */
    if (tmag5170_read_reg16(handle, TMAG5170_REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read Device ID — sensor absent or bus error.\n");
        return -1;
    }

    if (device_id != TMAG5170_REG_DEVICE_ID_VAL) {
        fprintf(stderr, "[ERROR] Unexpected Device ID: 0x%04X (expected 0x%04X).\n",
                device_id, TMAG5170_REG_DEVICE_ID_VAL);
        return -1;
    }

    /* Configure: continuous conversion, all axes enabled, 50 mT range */
    if (tmag5170_write_reg16(handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_VALUE) != 0) {
        fprintf(stderr, "[ERROR] Failed to write CONFIG register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int tmag5170_read_xyz(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_raw, y_raw, z_raw;

    if (tmag5170_read_reg16(handle, TMAG5170_REG_X_MSB, &x_raw) != 0)
        return -1;
    if (tmag5170_read_reg16(handle, TMAG5170_REG_Y_MSB, &y_raw) != 0)
        return -1;
    if (tmag5170_read_reg16(handle, TMAG5170_REG_Z_MSB, &z_raw) != 0)
        return -1;

    *x = (int16_t)x_raw;
    *y = (int16_t)y_raw;
    *z = (int16_t)z_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&t, &tm_buf);
    char ts[32];

    if (tm == NULL) {
        strncpy(ts, "1970-01-01T00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);
    }

    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    /* No explicit TMAG5170 library cleanup needed; pigpio handles I2C. */
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x, y, z;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at TMAG5170 address ---- */
    g_i2c_handle = i2cOpen(1, TMAG5170_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                TMAG5170_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (tmag5170_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMAG5170 initialization failed.\n");
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open CSV log file (append); write header if new ---- */
    g_log_file = fopen("magnetic_log.csv", "a+");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open magnetic_log.csv: %s\n", strerror(errno));
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Check if file is empty to decide on header */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long fsize = ftell(g_log_file);
        if (fsize == 0) {
            fprintf(g_log_file, "Timestamp,X,Y,Z\n");
            fflush(g_log_file);
        }
    } else {
        fprintf(stderr, "[WARN] Cannot determine log file size: %s\n", strerror(errno));
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (tmag5170_read_xyz(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "[WARN] I2C read error — continuing.\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

