    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        return EXIT_FAILURE;
    }

    log_event("System started.");

    while (g_running) {
        int sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value < 0) {
            log_event("Error reading sensor value.");
            fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
            sleep(REINIT_DELAY_SEC);
            if (initialize_gpio() != 0) {
                log_event("GPIO re-initialization failed. Exiting.");
                break;
            }
        } else if (sensor_value == 1) {
            log_event("ALERT: Water detected!");
            printf("ALERT: Water detected!\n");
            fflush(stdout);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_event("System shutting down.");
    gpioTerminate();
    return EXIT_SUCCESS;
}

