#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE   "rpm_log.txt"
#define TIMER_ID   0          /* pigpio timer slot 0 */

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — rising edge on the sensor pin               */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {          /* rising edge */
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Timer callback — fires every second to log RPM                      */
/* ------------------------------------------------------------------ */
static void timer_callback(void *userdata)
{
    (void)userdata;

    int pulses = __sync_fetch_and_and(&g_pulse_count, 0);   /* atomically read + reset */
    double rpm = (pulses * 60.0) / 1.0;                      /* 1 s window */

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_fp != NULL) {
        if (fprintf(g_log_fp, "%s %.2f\n", ts, rpm) < 0) {
            perror("fprintf");
        } else {
            fflush(g_log_fp);
        }
    }

    printf("%s RPM: %.2f\n", ts, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_PIN);
        goto cleanup;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_PIN);
        goto cleanup;
    }

    /* ---- register alert callback for rising edges ---- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_callback, NULL) < 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for pin %d\n", SENSOR_PIN);
        goto cleanup;
    }

    /* ---- register one-second timer ---- */
    if (gpioSetTimerFuncEx(TIMER_ID, 1000, timer_callback, NULL) < 0) {
        fprintf(stderr, "gpioSetTimerFuncEx failed for timer %d\n", TIMER_ID);
        goto cleanup;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    printf("RPM monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");

cleanup:
    /* ---- disable timer and alert callback ---- */
    gpioSetTimerFuncEx(TIMER_ID, 1000, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);

    /* ---- close log file ---- */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* ---- pigpio cleanup ---- */
    gpioTerminate();

    return EXIT_SUCCESS;
}

