#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <sys/time.h>
#include <gpiod.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"
#define NUM_PINS 2

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;

/* Quadrature state machine states */
enum { STATE_A0_B0, STATE_A0_B1, STATE_A1_B1, STATE_A1_B0 };

static const int quadrature_table[NUM_PINS][4] = {
    {1, 0, 0, 1}, /* Sensor A */
    {0, 1, 1, 0}  /* Sensor B */
};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS] = {NULL, NULL};
static int prev_state = STATE_A0_B0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
    pthread_cond_broadcast(&state_cond);
}

static void log_rotation(const char *direction) {
    struct timeval tv;
