#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_PIN  17
#define LED_PIN    18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("gpiod_chip_get_line(TOUCH_PIN)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED_PIN)");
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        perror("gpiod_line_request_output(LED_PIN)");
        goto cleanup;
    }

    /* Request touch line for rising-edge events */
    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        perror("gpiod_line_request_rising_edge_events(TOUCH_PIN)");
        goto cleanup;
    }

    printf("Touch sensor (GPIO%d) and LED (GPIO%d) ready. Press Ctrl+C to exit.\n",
           TOUCH_PIN, LED_PIN);

    int led_state = 0;

    while (running) {
        /* Block up to 1 second waiting for a rising-edge event */
        int ev = gpiod_line_event_wait(touch_line, &(struct timespec){1, 0});
