#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22
#define BUFFER_SIZE  100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int   sensor_pin;
    time_t timestamp;
    int   state;            /* 0 = released, 1 = touched */
} TouchEvent;

typedef struct {
    TouchEvent events[BUFFER_SIZE];
    int        head;
    int        tail;
    int        count;
    int        overflow_count;
} TouchLog;

static volatile sig_atomic_t g_running = 1;
static TouchLog g_log;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int sensor_pin, time_t timestamp, int state)
{
    g_log.events[g_log.head].sensor_pin = sensor_pin;
    g_log.events[g_log.head].timestamp  = timestamp;
    g_log.events[g_log.head].state      = state;
    g_log.head = (g_log.head + 1) % BUFFER_SIZE;
    if (g_log.count == BUFFER_SIZE) {
        g_log.tail = (g_log.tail + 1) % BUFFER_SIZE;
        g_log.overflow_count++;
    } else {
        g_log.count++;
    }
}

static void print_log(void)
{
    printf("\n--- Touch Log (%d entries, %d overflowed) ---\n",
           g_log.count, g_log.overflow_count);
    if (g_log.count == 0) {
        printf("  (no events recorded)\n");
        return;
    }
    int start = (g_log.count < BUFFER_SIZE) ? 0 : g_log.tail;
    for (int i = 0; i < g_log.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%3d] GPIO%2d  %02d:%02d:%02d  %s\n",
               i + 1,
               g_log.events[idx].sensor_pin,
               (g_log.events[idx].timestamp - 86400) / 3600 % 24,
               (g_log.events[idx].timestamp - 86400) / 60 % 60,
               (g_log.events[idx].timestamp - 86400) % 60,
               g_log.events[idx].state ? "Touched" : "Released");
    }
    printf("--- End of Log ---\n");
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_2_PIN);
        return -1;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED1 state.\n");
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED2 state.\n");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    memset(&g_log, 0, sizeof(g_log));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Sensor 1: GPIO%d | Sensor 2: GPIO%d\n", SENSOR_1_PIN, SENSOR_2_PIN);
    printf("  LED 1:   GPIO%d | LED 2:   GPIO%d\n", LED_1_PIN, LED_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    int prev1 = -1, prev2 = -1;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        if (s1 != prev1) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Warning: time() failed: %s\n", strerror(errno));
            }
            log_event(SENSOR_1_PIN, now, s1);
            prev1 = s1;
        }

        if (s2 != prev2) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Warning: time() failed: %s\n", strerror(errno));
            }
            log_event(SENSOR_2_PIN, now, s2);
            prev2 = s2;
        }

        if (gpioWrite(LED_1_PIN, s1) != 0) {
            fprintf(stderr, "Warning: gpioWrite(LED1) failed.\n");
        }
        if (gpioWrite(LED_2_PIN, s2) != 0) {
            fprintf(stderr, "Warning: gpioWrite(LED2) failed.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    print_log();
    printf("Touch sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

