#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_DELAY_S 1

/* Si1182 register addresses (example placeholders — adjust per datasheet) */
#define REG_HR_DATA    0x08
#define REG_SPO2_DATA  0x09
#define REG_CMD        0x07
#define CMD_START      0x01
#define CMD_STOP       0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1182(int fd)
{
    if (i2c_write_reg8(fd, REG_CMD, CMD_START) < 0)
        return -1;
    return 0;
}

static int read_hr_spo2(int fd, int *hr, int *spo2)
{
    uint8_t hr_raw, spo2_raw;

    if (i2c_read_reg8(fd, REG_HR_DATA, &hr_raw) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_SPO2_DATA, &spo2_raw) < 0)
        return -1;

    *hr   = (int)hr_raw;
    *spo2 = (int)spo2_raw;
    return 0;
}

static void log_data(FILE *fp, int hr, int spo2)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", ts, hr, spo2);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_si1182(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si1182 logging started. Press Ctrl-C to stop.\n");

    while (g_running) {
        int hr, spo2;

        if (read_hr_spo2(g_i2c_fd, &hr, &spo2) == 0) {
            log_data(g_log_fp, hr, spo2);
            printf("HR: %d BPM, SpO2: %d%%\n", hr, spo2);
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        sleep(SAMPLE_DELAY_S);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, REG_CMD, CMD_STOP);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

