#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27
#define TILT_THRESHOLD_SEC 2
#define POLL_INTERVAL_US 100000
#define LOG_FILE "bridge_integrity.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type, int sensor_pin) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) return;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s - %s - Sensor %d\n", timestamp, event_type, sensor_pin);
    fflush(log_file);
}

static void activate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to activate alarm on GPIO%d\n", ALARM_PIN);
    }
}

static void deactivate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to deactivate alarm on GPIO%d\n", ALARM_PIN);
    }
}

static void cleanup(void) {
    deactivate_alarm();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize alarm to LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    int sensor1_tilt_active = 0;
    int sensor2_tilt_active = 0;
    uint32_t sensor1_tilt_start = 0;
    uint32_t sensor2_tilt_start = 0;
    uint32_t last_poll_tick = gpioTick();

    while (running) {
        uint32_t now = gpioTick();
        if (now == 0) {
            fprintf(stderr, "Warning: gpioTick returned 0, skipping poll cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (s1 == 1 && !sensor1_tilt_active) {
            sensor1_tilt_active = 1;
            sensor1_tilt_start = now;
            log_event("Tilt Start", SENSOR_1_PIN);
        } else if (s1 == 0 && sensor1_tilt_active) {
            sensor1_tilt_active = 0;
            log_event("Tilt End", SENSOR_1_PIN);
        }

        if (s2 == 1 && !sensor2_tilt_active) {
            sensor2_tilt_active = 1;
            sensor2_tilt_start = now;
            log_event("Tilt Start", SENSOR_2_PIN);
        } else if (s2 == 0 && sensor2_tilt_active) {
            sensor2_tilt_active = 0;
            log_event("Tilt End", SENSOR_2_PIN);
        }

        if (sensor1_tilt_active || sensor2_tilt_active) {
            uint32_t elapsed = now - sensor1_tilt_start;
            if (sensor1_tilt_active && elapsed >= (TILT_THRESHOLD_SEC * 1000000)) {
                activate_alarm();
                log_event("Threshold Exceeded", SENSOR_1_PIN);
            }
            uint32_t elapsed2 = now - sensor2_tilt_start;
            if (sensor2_tilt_active && elapsed2 >= (TILT_THRESHOLD_SEC * 1000000)) {
                activate_alarm();
                log_event("Threshold Exceeded", SENSOR_2_PIN);
            }
        } else {
            deactivate_alarm();
        }

        uint32_t elapsed_since_last = now - last_poll_tick;
        if (elapsed_since_last < POLL_INTERVAL_US) {
            gpioDelay(POLL_INTERVAL_US - elapsed_since_last);
        }
        last_poll_tick = now;
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

