/*
 * Seismic event detector for Raspberry Pi 3 Model B+
 * Sensor : Omron D7S-A0011 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Alert  : LED on GPIO17 (BCM)
 *
 * Build  : gcc -O2 -Wall -o seismic seismic.c -li2c -lm -lrt
 * Run    : ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>

#include <i2c.h>

#define I2C_BUS             1
#define I2C_ADDR            0x28          /* D7S-A0011 default 7-bit address */
#define ALERT_LED_PIN       17            /* BCM GPIO17 */

#define VIBRATION_THRESHOLD 500.0f
#define POLL_INTERVAL_US    100000        /* 100 ms */
#define ALERT_DURATION_US   1000000       /* 1 s  */
#define MAX_RETRIES         3

/* D7S-A0011 register map (16-bit big-endian on the bus) */
#define REG_CTRL1           0x00
#define REG_CTRL2           0x01
#define REG_STATUS          0x02
#define REG_X_AXIS          0x04
#define REG_Y_AXIS          0x06
#define REG_Z_AXIS          0x08

/* CTRL1 bits */
#define CTRL1_PD            0x01          /* Power-down / reset bit */
#define CTRL1_ODR_MASK      0x0E          /* ODR[2:0] */

/* Status bits */
#define STATUS_OVF          0x01          /* Data overflow */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_i2c = -1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c >= 0) {
        i2c_close(g_i2c);
        g_i2c = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

static int i2c_write_reg16(int h, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    return i2c_write_block_data(h, reg, (const char *)buf, 3);
}

static int i2c_read_reg16(int h, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_block_data(h, reg, (char *)buf, 2) != 2)
        return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_sensor(int h)
{
    uint16_t ctrl1;

    /* Verify sensor presence by reading CTRL1 */
    if (i2c_read_reg16(h, REG_CTRL1, &ctrl1) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit to wake the sensor */
    ctrl1 &= ~CTRL1_PD;
    if (i2c_write_reg16(h, REG_CTRL1, ctrl1) != 0) {
        fprintf(stderr, "Failed to clear power-down bit\n");
        return -1;
    }

    /* Allow time for the sensor to settle after power-up */
    usleep(50000);
    return 0;
}

static int read_axis(int h, uint8_t reg, float *out)
{
    uint16_t raw;
    if (i2c_read_reg16(h, reg, &raw) != 0)
        return -1;
    *out = (float)raw;
    return 0;
}

static int read_vibration(int h, float *x, float *y, float *z)
{
    int rc = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read_axis(h, REG_X_AXIS, x) != 0) { rc = -1; goto retry; }
        if (read_axis(h, REG_Y_AXIS, y) != 0) { rc = -1; goto retry; }
        if (read_axis(h, REG_Z_AXIS, z) != 0) { rc = -1; goto retry; }
        return 0;
retry:
        usleep(10000);
    }
    return rc;
}

static void log_event(float mag)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!g_log)
        return;

    if (localtime_r(&t, &tm)) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(g_log, "%s - Earthquake detected! Peak vibration: %.2f\n", ts, mag);
        fflush(g_log);
    }
}

static void trigger_alert(void)
{
    if (g_log) {
        time_t t = time(NULL);
        struct tm tm;
        char ts[32];
        if (localtime_r(&t, &tm)) {
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
            fprintf(g_log, "%s - Alert LED ON\n", ts);
            fflush(g_log);
        }
    }
    /* In a real deployment this would drive the LED via a GPIO library.
     * Here we just print a message for clarity. */
    printf("Alert LED ON\n");
    usleep(ALERT_DURATION_US);
    printf("Alert LED OFF\n");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log = fopen("seismic_events.log", "a");
    if (!g_log) {
        perror("fopen seismic_events.log");
        return EXIT_FAILURE;
    }

    g_i2c = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c < 0) {
        fprintf(stderr, "i2c_open failed: %s\n", strerror(errno));
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started (D7S-A0011 @ 0x%02X). Ctrl+C to exit.\n", I2C_ADDR);

    while (g_running) {
        float x, y, z;
        if (read_vibration(g_i2c, &x, &y, &z) != 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        float mag = sqrtf(x * x + y * y + z * z);
        if (mag > VIBRATION_THRESHOLD) {
            log_event(mag);
            trigger_alert();
        }
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

