/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 * Logs HIGH->LOW transitions to /var/log/flame_events.log with syslog.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define LOG_FILE    "/var/log/flame_events.log"
#define POLL_MS     1000

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_names[NUM_SENSORS] = {"Sensor 1", "Sensor 2", "Sensor 3", "Sensor 4", "Sensor 5"};
static const char *sensor_ids[NUM_SENSORS]   = {"S001", "S002", "S003", "S004", "S005"};

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_SENSORS];
static int lines_requested = 0;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void cleanup(void)
{
    for (int i = 0; i < lines_requested; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    closelog();
}

static int log_event(const char *sensor_id, unsigned int gpio_pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %s (GPIO %u) - Flame Detected\n",
                timestamp, sensor_id, gpio_pin) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void log_sensor_read_error(unsigned int gpio_pin)
{
    syslog(LOG_ERR, "Error reading sensor on GPIO %u", gpio_pin);
}

int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame monitor starting");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get GPIO line %u: %s", sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        lines_requested++;
    }

    for (int i = 0; i < lines_requested; i++) {
        if (gpiod_line_request_input(lines[i], "flame_monitor") != 0) {
            syslog(LOG_ERR, "Failed to request GPIO line %u as input: %s",
                   sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "Monitoring %d sensors on GPIO pins: %u, %u, %u, %u, %u",
           lines_requested, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < lines_requested; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            syslog(LOG_ERR, "Initial read failed on GPIO %u: %s",
                   sensor_pins[i], strerror(errno));
            log_sensor_read_error(sensor_pins[i]);
            prev_state[i] = -1;
        } else {
            prev_state[i] = val;
        }
    }

    while (program_running) {
        for (int i = 0; i < lines_requested; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Read failed on GPIO %u: %s",
                       sensor_pins[i], strerror(errno));
                log_sensor_read_error(sensor_pins[i]);
                continue;
            }

            if (val == 0 && prev_state[i] == 1) {
                /* HIGH -> LOW: potential flame detected */
                usleep(DEBOUNCE_MS * 1000);
                int val2 = gpiod_line_get_value(lines[i]);
                if (val2 < 0) {
                    syslog(LOG_ERR, "Debounce read failed on GPIO %u: %s",
                           sensor_pins[i], strerror(errno));
                    log_sensor_read_error(sensor_pins[i]);
                } else if (val2 == 0) {
                    syslog(LOG_INFO, "Flame detected on %s (GPIO %u)",
                           sensor_ids[i], sensor_pins[i]);
                    if (log_event(sensor_ids[i], sensor_pins[i]) != 0) {
                        syslog(LOG_ERR, "Failed to log flame event for %s", sensor_ids[i]);
                    }
                }
            }
            prev_state[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

