/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring (TTP226 OUT0..OUT7 -> Raspberry Pi BCM GPIO):
 *   OUT0 -> GPIO5   OUT1 -> GPIO6
 *   OUT2 -> GPIO13  OUT3 -> GPIO19
 *   OUT4 -> GPIO26  OUT5 -> GPIO12
 *   OUT6 -> GPIO16  OUT7 -> GPIO20
 *
 * Build:  gcc -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 * Run:    ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

/* BCM GPIO numbers for TTP226 OUT0..OUT7 */
static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buf);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_states, 0, sizeof(prev_states));

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve and request each line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Error: failed to request GPIO %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Press Ctrl-C to exit.\n");

