#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x77
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000

#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS 0x04

#define VEML7700_CONFIG_SD 0x00
#define VEML7700_CONFIG_IT_100MS 0x00
#define VEML7700_CONFIG_PERS_1 0x00
#define VEML7700_CONFIG_PSM_AUTO 0x00

#define ERROR_NONE 0
#define ERROR_I2C_INIT -1
#define ERROR_I2C_OPEN -2
#define ERROR_I2C_WRITE -3
#define ERROR_I2C_READ -4
#define ERROR_PWM_INIT -5
#define ERROR_PWM_SET -6

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_init(int handle) {
    uint8_t config = VEML7700_CONFIG_SD | VEML7700_CONFIG_IT_100MS |
                     VEML7700_CONFIG_PERS_1 | VEML7700_CONFIG_PSM_AUTO;
    if (i2cWriteByteData(handle, VEML7700_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        return ERROR_I2C_WRITE;
    }
    return ERROR_NONE;
}

static int veml7700_read_lux(int handle, uint16_t *lux_out) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, VEML7700_REG_ALS, buf, 2) != 2) {
        fprintf(stderr, "Error reading VEML7700 ALS: %s\n", strerror(errno));
        return ERROR_I2C_READ;
    }
    *lux_out = ((uint16_t)(buf[1] & 0x0F) << 8) | (uint8_t)buf[0];
    return ERROR_NONE;
}

static int calculate_brightness(uint16_t lux) {
    if (lux < 100) return 100;
    if (lux < 500) return 75;
    if (lux < 1000) return 50;
    return 25;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", gpio, strerror(errno));
        return ERROR_PWM_SET;
    }
    return ERROR_NONE;
}

static void log_data(FILE *fp, uint16_t lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %u, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) != ERROR_NONE) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(GPIO_LED, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t lux = 0;
        int error_code = veml7700_read_lux(i2c_handle, &lux);
        int brightness = 0;

        if (error_code == ERROR_NONE) {
            brightness = calculate_brightness(lux);
            if (set_led_brightness(GPIO_LED, brightness) != ERROR_NONE) {
                error_code = ERROR_PWM_SET;
            }
        } else {
            error_code = error_code;
        }

        log_data(log_file, lux, brightness, error_code);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

