#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define POLL_DELAY_US 50000

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite failed for LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = gpioRead(touch_pins[i]);
        if (prev_state[i] < 0) {
            fprintf(stderr, "gpioRead failed for pin %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int led_on = 0;

    while (running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int cur = gpioRead(touch_pins[i]);
            if (cur < 0) {
                fprintf(stderr, "gpioRead failed for pin %d\n", touch_pins[i]);
                continue;
            }

            if (cur == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
                any_touched = 1;
            }
            prev_state[i] = cur;
        }

        if (any_touched && !led_on) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite failed for LED pin %d\n", LED_PIN);
            } else {
                led_on = 1;
            }
        } else if (!any_touched && led_on) {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite failed for LED pin %d\n", LED_PIN);
            } else {
                led_on = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

