#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x44
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1
#define CONV_DELAY_MS  100

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_MANUFACTURER_ID 0x7E
#define REG_DEVICE_ID   0x7F

/* Expected device ID for OPT3001 */
#define OPT3001_DEVICE_ID 0x5449

/* Configuration register bits */
#define CONFIG_RESET    0x80
#define CONFIG_MODE     0x01
#define CONFIG_INT_EN   0x02
#define CONFIG_POL      0x04
#define CONFIG_DR       0x08
#define CONFIG_TO       0x10
#define CONFIG_FLTR     0x20
#define CONFIG_CLS      0x40
#define CONFIG_MEAS     0x80

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    /* OPT3001 provides data in big-endian; driver uses little-endian */
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int opt3001_init(int fd)
{
    uint16_t id = 0;
    if (i2c_read_reg16(fd, REG_DEVICE_ID, &id) != 0) {
        fprintf(stderr, "Failed to read device ID\n");
        return -1;
    }
    if (id != OPT3001_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID 0x%04X (expected 0x%04X)\n", id, OPT3001_DEVICE_ID);
        return -1;
    }

    /* Software reset */
    if (i2c_write_reg8(fd, REG_CONFIG, CONFIG_RESET) != 0)
        return -1;
    usleep(10000); /* 10 ms */

    /* Configure: mode=normal, polarity=active low, DR=100ms, TO=100ms, filter=off, CLS=off, MEAS=1 */
    uint8_t config = CONFIG_MODE | CONFIG_POL | CONFIG_DR | CONFIG_TO | CONFIG_MEAS;
    if (i2c_write_reg8(fd, REG_CONFIG, config) != 0)
        return -1;

    return 0;
}

static int opt3001_read_lux(int fd, float *lux)
{
    uint16_t raw = 0;
    if (i2c_read_reg16(fd, REG_RESULT, &raw) != 0)
        return -1;

    /* OPT3001 result is big-endian; driver returns little-endian, so swap */
    raw = ((raw & 0xFF00) >> 8) | ((raw & 0x00FF) << 8);

    /* Convert raw to lux: raw * 0.01 */
    *lux = (float)raw * 0.01f;
    return 0;
}

static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (opt3001_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    printf("OPT3001 initialized. Logging to %s every %d second(s). Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float lux = 0.0f;
        if (opt3001_read_lux(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Failed to read lux value\n");
        } else {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            } else {
                printf("%s, %.2f\n", __TIME__, lux);
            }
        }

        /* Wait at least 100 ms after configuration before next conversion */
        usleep(CONV_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

