#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x28
#define SLF3S_CMD      0x3600
#define SLF3S_READ_LEN 3
#define SAMPLE_PERIOD  1
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define LOG_FILE       "cooling_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c_read_bytes: read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: short read (%zd of %zu bytes)\n", n, len);
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("init_i2c: open " I2C_BUS);
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        perror("init_i2c: ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_flow_rate(int fd, float *flow_rate)
{
    if (i2c_write_cmd(fd, SLF3S_CMD) < 0)
        return -1;

    usleep(2000);

    uint8_t buf[SLF3S_READ_LEN];
    if (i2c_read_bytes(fd, buf, SLF3S_READ_LEN) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "read_flow_rate: CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw;
    return 0;
}

static const char *status_str(int status)
{
    switch (status) {
        case 0: return "OK";
        case 1: return "ERROR";
        case 2: return "INVALID";
        default: return "UNKNOWN";
    }
}

static void log_data(FILE *fp, float flow_rate, int status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("log_data: localtime_r");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%s\n", ts, flow_rate, status_str(status));
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        return EXIT_FAILURE;
    }

    int file_exists = (access(LOG_FILE, F_OK) == 0);
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("main: fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_fp);
    }

    printf("Coolant flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate;
        int status = 0;

        if (read_flow_rate(g_i2c_fd, &flow_rate) < 0) {
            status = 1;
            log_data(g_log_fp, 0.0f, status);
        } else if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            status = 2;
            log_data(g_log_fp, flow_rate, status);
            fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow_rate);
            if (i2c_write_cmd(g_i2c_fd, SLF3S_CMD) < 0) {
                fprintf(stderr, "Re-init failed; continuing.\n");
            }
        } else {
            log_data(g_log_fp, flow_rate, status);
            printf("Flow Rate: %.2f ml/min\n", flow_rate);
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

