/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 *   DO  -> GPIO17 (BCM 17, physical pin 11)
 * Buzzer : active buzzer
 *   IN  -> GPIO18 (BCM 18, physical pin 12)
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run  : ./flame_alert
 */

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define FLAME_SENSOR_PIN 17   /* BCM 17, physical pin 11 */
#define BUZZER_PIN       18   /* BCM 18, physical pin 12 */
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define POLL_CHUNK_MS     100
#define LOG_FILE          "alert_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(FILE *log_file, const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "[%s] %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control (interruptible)                                     */
/* ------------------------------------------------------------------ */
static int buzzer_on(struct gpiod_line *buzzer_line)
{
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Failed to set buzzer HIGH: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *buzzer_line)
{
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Failed to set buzzer LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int buzzer_pulse(struct gpiod_line *buzzer_line, int duration_ms)
{
    if (buzzer_on(buzzer_line) < 0)
        return -1;

    /*
     * Interruptible 2-second buzzer burst broken into 100 ms slices
     * so SIGINT/SIGTERM can break out promptly.
     */
    for (int elapsed = 0; elapsed < duration_ms && g_running; elapsed += POLL_CHUNK_MS) {
        if (gpiod_line_set_value(buzzer_line, 0) < 0) {
            fprintf(stderr, "Failed to set buzzer LOW during pulse: %s\n",
                    strerror(errno));
            return -1;
        }
        usleep(POLL_CHUNK_MS * 1000);
        if (gpiod_line_set_value(buzzer_line, 1) < 0) {
            fprintf(stderr, "Failed to set buzzer HIGH during pulse: %s\n",
                    strerror(errno));
            return -1;
        }
        usleep((POLL_CHUNK_MS - 1) * 1000); /* keep total ~100 ms per slice */
    }

    return buzzer_off(buzzer_line);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open log file ------------------------------------------------ */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* ---- Open GPIO chip ------------------------------------------------ */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Get lines ----------------------------------------------------- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Failed to get flame sensor line (GPIO%d): %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line (GPIO%d): %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines ------------------------------------------------- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Signal handlers ---------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Initial state ------------------------------------------------- */
    int last_flame_state = gpiod_line_get_value(flame_line);
    if (last_flame_state < 0) {
        fprintf(stderr, "Failed to read initial flame sensor state: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (log_event(log_file, "System started") < 0)
        goto cleanup;

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ----------------------------------------------------- */
    while (g_running) {
        int flame_state = gpiod_line_get_value(flame_line);
        if (flame_state < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n",
                    strerror(errno));
            break;
        }

        /* LOW (0) on the digital output means flame detected */
        if (flame_state == 0 && last_flame_state != 0) {
            printf("Flame detected!\n");
            if (log_event(log_file, "FLAME DETECTED") < 0)
                break;
            if (buzzer_pulse(buzzer_line, BUZZER_DURATION_MS) < 0)
                break;
        }

        last_flame_state = flame_state;

        /* Interruptible 500 ms poll interval */
        for (int elapsed = 0; elapsed < POLL_INTERVAL_MS && g_running;
             elapsed += POLL_CHUNK_MS) {
            usleep(POLL_CHUNK_MS * 1000);
        }
    }

    /* ---- Cleanup ------------------------------------------------------- */
    if (buzzer_line)
        buzzer_off(buzzer_line);

    if (log_event(log_file, "System stopped") < 0)
        goto cleanup;

    ret = EXIT_SUCCESS;

cleanup:
    if (flame_line)
        gpiod_line_release(flame_line);
    if (buzzer_line)
        gpiod_line_release(buzzer_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);

    return ret;
}

