    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        current_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_state < 0) {
            fprintf(stderr, "Error reading touch sensor pin\n");
            break;
        }

        if (current_state == 1 && last_state == 0) {
            gpioDelay(DEBOUNCE_MS * 1000);
            if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                led_state = !led_state;
                if (gpioWrite(LED_PIN, led_state) != 0) {
                    fprintf(stderr, "Failed to write to LED pin\n");
                    break;
                }

                if (log_touch_event() != 0) {
                    fprintf(stderr, "Warning: log write failed, continuing\n");
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
    }

    printf("Touch sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

