/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *
 * The TMAG5110A1 latch output is open-drain:
 *   - Logic LOW  (0)  => South pole (magnet) present
 *   - Logic HIGH (1)  => Magnet removed
 *
 * Internal pull-ups are enabled so the line is defined when the
 * latch output is released (magnet absent).  We poll every 100 ms.
 *
 * Build:  gcc -Wall -Wextra -O2 -o mag_monitor mag_monitor.c -lpigpio -lrt
 * Run:    sudo ./mag_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_timestamp(FILE *fp)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    fprintf(fp, "%s", ts);
}

static void log_state_change(int sensor_id, int state)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Log file not open; cannot log state change.\n");
        return;
    }

    log_timestamp(g_log_file);
    fprintf(g_log_file, " Sensor %d: %s\n",
            sensor_id,
            state == 0 ? "Magnet Present (South Pole)" : "Magnet Removed");
    fflush(g_log_file);
}

static void log_error(const char *msg)
{
    fprintf(stderr, "Error: %s\n", msg);
    if (g_log_file != NULL) {
        log_timestamp(g_log_file);
        fprintf(g_log_file, " Error: %s\n", msg);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Configure a pin as input with internal pull-up.
 * Returns 0 on success, non-zero on failure.
 */
static int configure_input_with_pullup(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pin);
        return -1;
    }
    return 0;
}

/*
 * Read the digital state of a pin.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    int pins[3] = { SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN };
    int prev[3] = { -1, -1, -1 };   /* -1 = uninitialized */
    int i;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins ---- */
    for (i = 0; i < 3; i++) {
        if (configure_input_with_pullup(pins[i]) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 latch sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Logging state changes to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (i = 0; i < 3; i++) {
            int v = read_sensor(pins[i]);
            if (v < 0) {
                log_error("Failed to read sensor value");
                continue;
            }

            if (prev[i] == -1) {
                /* First read: record initial state without logging a
                 * spurious "transition" from an unknown value. */
                prev[i] = v;
            } else if (v != prev[i]) {
                log_state_change(i + 1, v);
                prev[i] = v;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

