#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define LOG_FILE "heart_rate.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_IRQ_ENABLE 0x04
#define REG_IRQ_MODE1 0x05
#define REG_IRQ_MODE2 0x06
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_ALS_VIS_DATA0 0x10
#define REG_ALS_VIS_DATA1 0x11
#define REG_ALS_IR_DATA0 0x12
#define REG_ALS_IR_DATA1 0x13
#define REG_HR_DATA0 0x14
#define REG_HR_DATA1 0x15
#define REG_COMMAND 0x30

#define EXPECTED_PART_ID 0x82
#define EXPECTED_HW_REV 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_si1182(void) {
    uint8_t part_id, hw_rev;

    if (read_reg(REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    if (read_reg(REG_HW_REV, &hw_rev) < 0) return -1;
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    if (write_reg(REG_INT_CFG, 0x00) < 0) return -1;
    if (write_reg(REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (write_reg(REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (write_reg(REG_IRQ_MODE2, 0x00) < 0) return -1;
    if (write_reg(REG_HW_KEY, 0x00) < 0) return -1;
    if (write_reg(REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_reg(REG_COMMAND, 0x01) < 0) return -1;

    return 0;
}

static int read_heart_rate(uint16_t *hr) {
    uint8_t lo, hi;
    if (read_reg(REG_HR_DATA0, &lo) < 0) return -1;
    if (read_reg(REG_HR_DATA1, &hi) < 0) return -1;
    *hr = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int log_data(int bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    uint16_t raw_hr;
    int bpm;
    int i;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n", I2C_BUS, SI1182_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int hr_buffer[MOVING_AVG_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;
    int sum = 0;

    while (running) {
        if (read_heart_rate(&raw_hr) < 0) {
            fprintf(stderr, "Error reading heart rate, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        sum -= hr_buffer[buffer_index];
        hr_buffer[buffer_index] = (int)raw_hr;
        sum += hr_buffer[buffer_index];
        buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
        if (buffer_count < MOVING_AVG_SIZE) buffer_count++;

        bpm = sum / buffer_count;

        if (bpm < MIN_BPM || bpm > MAX_BPM) {
            fprintf(stderr, "BPM out of range: %d\n", bpm);
        } else {
            if (log_data(bpm) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

