/*
 * touch_counter.c — TTP226 8-channel capacitive touch -> 8-bit counter
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter   (needs gpiod group membership on the pins)
 *
 * Hardware (Raspberry Pi Zero W):
 *   TTP226 OUT1..OUT8 -> BCM 5, 6, 7, 8, 9, 10, 11, 12
 *   8-bit counter     -> BCM 17..24 (bit 0 on 17, bit 7 on 24)
 *   VDD 3.3 V, GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS  8
#define NUM_OUTPUTS   8
#define LOG_FILE      "touch_log.txt"
#define POLL_MS       10
#define STAB_MS       200

static const unsigned int sensor_pins[NUM_CHANNELS] = {
    5, 6, 7, 8, 9, 10, 11, 12
};
static const unsigned int output_pins[NUM_OUTPUTS] = {
    17, 18, 19, 20, 21, 22, 23, 24
};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void timestamp_utc(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    gmtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tmv);
}

static int log_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    char ts[32];
    timestamp_utc(ts, sizeof ts);
    fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
    if (ferror(fp)) {
        fprintf(stderr, "Warning: write error on %s: %s\n",
                LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: close error on %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor[NUM_CHANNELS];
    struct gpiod_line *output[NUM_OUTPUTS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        sensor[i] = NULL;
    for (int i = 0; i < NUM_OUTPUTS; i++)
        output[i] = NULL;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open gpiochip0 ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- acquire sensor lines (input) ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor[i], "touch_counter") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- acquire output lines (output, initial 0) ---- */
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        output[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(output[i], "touch_counter", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for BCM %u: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- stabilization delay ---- */
    printf("Stabilizing sensor for %d ms...\n", STAB_MS);
    fflush(stdout);
    usleep(STAB_MS * 1000);

    int counter = 0;
    int prev[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev[i] = 0;

    printf("Touch sensor ready. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for BCM %u: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;  /* skip this channel, keep running */
            }
            if (val == 1 && prev[i] == 0) {
                counter = (counter + 1) & 0xFF;
                if (log_event(i + 1, counter) < 0)
                    fprintf(stderr, "Warning: log_event failed for channel %d\n",
                            i + 1);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                fflush(stdout);
            }
            prev[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- reset outputs to 0 ---- */
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (output[i]) {
            if (gpiod_line_set_value(output[i], 0) < 0)
                fprintf(stderr, "Warning: set output BCM %u to 0 failed: %s\n",
                        output_pins[i], strerror(errno));
            gpiod_line_release(output[i]);
        }
    }
    /* ---- release sensor lines ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor[i])
            gpiod_line_release(sensor[i]);
    }
    /* ---- close chip ---- */
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

