            fprintf(stderr, "gpiod_line_request_input failed for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- acquire output lines (output, initial 0) ---- */
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        output[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(output[i], "touch_counter", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for BCM %u: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- stabilization delay ---- */
    printf("Stabilizing sensor for %d ms...\n", STAB_MS);
    fflush(stdout);
    usleep(STAB_MS * 1000);

    int counter = 0;
    int prev[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev[i] = 0;

    printf("Touch sensor ready. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for BCM %u: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;  /* skip this channel, keep running */
            }
            if (val == 1 && prev[i] == 0) {
                counter = (counter + 1) & 0xFF;
                if (log_event(i + 1, counter) < 0)
                    fprintf(stderr, "Warning: log_event failed for channel %d\n",
                            i + 1);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                fflush(stdout);
            }
            prev[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- reset outputs to 0 ---- */
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (output[i]) {
            if (gpiod_line_set_value(output[i], 0) < 0)
                fprintf(stderr, "Warning: set output BCM %u to 0 failed: %s\n",
                        output_pins[i], strerror(errno));
            gpiod_line_release(output[i]);
        }
    }
    /* ---- release sensor lines ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor[i])
            gpiod_line_release(sensor[i]);
    }
    /* ---- close chip ---- */
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

