#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 27
#define SENSOR4_GPIO 22
#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        perror("time");
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, const char *timestamp,
                    int s1, int s2, int s3, int s4)
{
    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int ret = EXIT_SUCCESS;
    int gpios[4] = {SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO, SENSOR4_GPIO};
    const char *gpio_names[4] = {"sensor1", "sensor2", "sensor3", "sensor4"};
    int sensor_values[4];
    char timestamp[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(gpios[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed for %s (GPIO %d)\n",
                    gpio_names[i], gpios[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }
        /* Enable internal pull-up so the line is defined when no sensor pulls it low. */
        if (gpioSetPullUpDown(gpios[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "gpioSetPullUpDown failed for %s (GPIO %d)\n",
                    gpio_names[i], gpios[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    /* Write header if file is empty. */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            perror("fprintf header");
            ret = EXIT_FAILURE;
            goto cleanup;
        }
        if (fflush(g_log_fp) != 0) {
            perror("fflush header");
            ret = EXIT_FAILURE;
            goto cleanup;
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal SIGINT");
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal SIGTERM");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Polling KY-033 sensors every 100 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        int read_failed = 0;

        for (int i = 0; i < 4; i++) {
            int v = gpioRead(gpios[i]);
            if (v < 0) {
                fprintf(stderr, "gpioRead failed for %s (GPIO %d)\n",
                        gpio_names[i], gpios[i]);
                read_failed = 1;
            } else {
                sensor_values[i] = v;
            }
        }

        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Failed to get timestamp; skipping log entry.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (log_data(g_log_fp, timestamp, sensor_values[0], sensor_values[1],
                     sensor_values[2], sensor_values[3]) != 0) {
            fprintf(stderr, "Failed to log data; continuing.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

cleanup:
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            perror("fclose");
            ret = EXIT_FAILURE;
        }
        g_log_fp = NULL;
    }
    gpioTerminate();
    return ret;
}

