            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n", GPIO17, strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line18, "tilt-monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n", GPIO18, strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev17 = gpiod_line_get_value(line17);
    int prev18 = gpiod_line_get_value(line18);
    if (prev17 < 0 || prev18 < 0) {
        fprintf(stderr, "Initial read failed: %s\n", strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            fprintf(stderr, "Read error on GPIO lines: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val17 == 0 && prev17 == 1) {
            if (log_event(1) == 0) {
                printf("Sensor 1 tilted\n");
            }
        }
        if (val18 == 0 && prev18 == 1) {
            if (log_event(2) == 0) {
                printf("Sensor 2 tilted\n");
            }
        }

        prev17 = val17;
        prev18 = val18;

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    cleanup();
    return ret;
}

