#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

int main(void) {
    int left_state, center_state, right_state;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with internal pull-up resistors */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Left, Center, Right\n");
    fflush(stdout);

    while (running) {
        left_state = read_sensor(LEFT_SENSOR_PIN);
        center_state = read_sensor(CENTER_SENSOR_PIN);
        right_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_state < 0 || center_state < 0 || right_state < 0) {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            break;
        }

        printf("%d, %d, %d\n", left_state, center_state, right_state);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

