#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SI1175_I2C_ADDR 0x60
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 100000

#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_als_data(int handle, uint16_t *als_data) {
    int data0 = i2cReadByteData(handle, SI1175_REG_ALS_VIS_DATA0);
    if (data0 < 0) {
        fprintf(stderr, "Error reading ALS data0: %s\n", strerror(errno));
        return -1;
    }

    int data1 = i2cReadByteData(handle, SI1175_REG_ALS_VIS_DATA1);
    if (data1 < 0) {
        fprintf(stderr, "Error reading ALS data1: %s\n", strerror(errno));
        return -1;
    }

    *als_data = ((uint16_t)data1 << 8) | (uint16_t)data0;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SI1175_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SI1175_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1175 ALS sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als_data = 0;
        if (read_als_data(handle, &als_data) == 0) {
