 *       This code uses only the libgpiod API and does NOT require
 *       any special kernel modules or configuration beyond what is
 *       needed for the standard Raspberry Pi GPIO setup.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_LINES 3
#define POLL_INTERVAL_US 100000  /* 100 ms */

static const unsigned int line_offsets[NUM_LINES] = { 2, 3, 4 };
static const char *line_names[NUM_LINES] = { "left", "middle", "right" };

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_LINES];
    int values[NUM_LINES];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_LINES; i++) {
        lines[i] = NULL;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line individually and request it as input */
    for (int i = 0; i < NUM_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offsets[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: failed to get GPIO line %u: %s\n",
                    line_offsets[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "track_sensor") < 0) {
            fprintf(stderr, "Error: failed to request GPIO line %u as input: %s\n",
                    line_offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Polling Keywish 3-Way Tracking Sensor (GPIO2, GPIO3, GPIO4) every 100 ms. Press Ctrl-C to exit.\n");

    while (g_running) {
        int read_failed = 0;

        for (int i = 0; i < NUM_LINES; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error: failed to read GPIO line %u: %s\n",
                        line_offsets[i], strerror(errno));
                read_failed = 1;
                break;
            }
            values[i] = val;
        }

        if (read_failed) {
            /* On a read error, continue polling rather than aborting */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        printf("L:%d M:%d R:%d\n", values[0], values[1], values[2]);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually */
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

