 *
 * Wiring (TTP226 breakout, 3.3 V supply):
 *   VCC  -> 3.3 V (pin 1)
 *   GND  -> GND  (pin 9)
 *   TP1  -> GPIO5 (BCM 5,  pin 29)
 *   TP2  -> GPIO6 (BCM 6,  pin 31)
 *   TP3  -> GPIO13 (BCM 13, pin 33)
 *   TP4  -> GPIO19 (BCM 19, pin 35)
 *   TP5  -> GPIO26 (BCM 26, pin 37)
 *   TP6  -> GPIO12 (BCM 12, pin 32)
 *   TP7  -> GPIO16 (BCM 16, pin 36)
 *   TP8  -> GPIO20 (BCM 20, pin 38)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_poll touch_poll.c -lrt
 */
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static double elapsed_seconds(const struct timespec *start,
                               const struct timespec *now)
{
    return (double)(now->tv_sec - start->tv_sec)
         + (double)(now->tv_nsec - start->tv_nsec) / 1.0e9;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_acquired[NUM_CHANNELS];
    int i;
    int ret = EXIT_FAILURE;
    struct timespec start, now;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i]     = NULL;
        line_acquired[i] = 0;
    }

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
        line_acquired[i] = 1;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(lines[i], "ttp226-touch") != 0) {
            fprintf(stderr, "Failed to request GPIO %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
        perror("clock_gettime");
        goto cleanup;
    }

    printf("TTP226 touch sensor polling started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n",
                        channel_pins[i], strerror(errno));
                error = 1;
                break;
            }
            values[i] = val;
        }

        if (error)
            goto cleanup;

        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        printf("[%7.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               elapsed_seconds(&start, &now),
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (line_acquired[i])
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

