static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_led_color(uint8_t red, uint8_t green, uint8_t blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

static int interpolate_color(uint8_t r1, uint8_t g1, uint8_t b1,
                             uint8_t r2, uint8_t g2, uint8_t b2,
                             int steps, int *out_r, int *out_g, int *out_b)
{
    if (steps <= 0) return -1;
    double dr = (double)(r2 - r1) / steps;
    double dg = (double)(g2 - g1) / steps;
    double db = (double)(b2 - b1) / steps;
    for (int i = 0; i <= steps; i++) {
        double r = r1 + dr * i;
        double g = g1 + dg * i;
        double b = b1 + db * i;
        if (r < 0.0) r = 0.0; else if (r > 255.0) r = 255.0;
        if (g < 0.0) g = 0.0; else if (g > 255.0) g = 255.0;
        if (b < 0.0) b = 0.0; else if (b > 255.0) b = 255.0;
        *out_r = (uint8_t)r;
        *out_g = (uint8_t)g;
        *out_b = (uint8_t)b;
        return 0;
    }
    return -1;
}

