#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29
#define TCS34725_PON   0x80
#define TCS34725_AEN   0x41
#define TCS34725_ATIME 0x81
#define TCS34725_ID    0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A
#define LED_PIN        17
#define RED_THRESHOLD  200
#define POLL_DELAY_MS  200
#define INTEGRATION_TIME 154

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_block(fd, TCS34725_ID, &id, 1) != 0) return -1;
    if (id != 0x44 && id != 0x10) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X\n", id);
        return -1;
    }
    if (i2c_write_byte(fd, TCS34725_PON, 0x01) != 0) return -1;
    usleep(3000);
    if (i2c_write_byte(fd, TCS34725_ATIME, (uint8_t)(INTEGRATION_TIME - 1)) != 0) return -1;
    if (i2c_write_byte(fd, TCS34725_AEN, 0x03) != 0) return -1;
    return 0;
}

static int tcs34725_read_rgbc(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[8];
    if (i2c_read_block(fd, TCS34725_CDATAL, buf, 8) != 0) return -1;
    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led, "tcs34725_led", 0) != 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t r, g, b, c;
        if (tcs34725_read_rgbc(fd, &r, &g, &b, &c) != 0) {
            fprintf(stderr, "Read failed; re-initializing sensor...\n");
            if (tcs34725_init(fd) != 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
        } else {
            printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);
            gpiod_line_set_value(led, (r > RED_THRESHOLD) ? 1 : 0);
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    i2c_write_byte(fd, TCS34725_PON, 0x00);
    i2c_write_byte(fd, TCS34725_AEN, 0x00);
    close(fd);
    return EXIT_SUCCESS;
}

