/*
 * Raspberry Pi 4 Model B – BH1750 ambient light sensor → WS2812B LED strip
 *
 * Hardware:
 *   - BH1750 on I2C bus 1, address 0x23 (ADDR pin tied to GND)
 *   - WS2812B data line on GPIO18 (BCM pin 18, hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_strip light_strip.c -lm
 *
 * The WS2812B timing is generated using the hardware PWM/wave subsystem
 * (pwmSetClock / pwmSetDataRate / gpioWaveAddNew / gpioWaveTxSend).
 * This avoids the pigpio library and keeps the code self-contained.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD     0x10   /* One-time high-resolution measurement */
#define BH1750_CONV_MS 180    /* Conversion time for high-res mode */

#define NUM_LEDS       10
#define PWM_PIN        18     /* BCM 18 – hardware PWM0 */
#define PWM_FREQ_HZ    800000 /* 800 kHz – typical WS2812B requirement */
#define PWM_RANGE      255    /* 8-bit resolution */

#define LOG_MIN        0.01   /* lux floor for log mapping */
#define LOG_MAX        1000.0 /* lux ceiling for log mapping */
#define BRIGHTNESS_MAX 255.0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c write cmd");
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            perror("i2c read16");
        else
            fprintf(stderr, "i2c read16: short read (%zd bytes)\n", n);
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ---- WS2812B hardware PWM/wave generation ---- */

/*
 * WS2812B timing (approximate):
 *   T0H = 0.35 us, T0L = 0.8 us  (total ~1.15 us)
 *   T1H = 0.6 us,  T1L = 0.6 us  (total ~1.2 us)
 *   Bit period = ~1.15 us → 870 kHz data rate
 *   We use 800 kHz PWM and adjust duty cycles to approximate the timing.
 */

static void ws2812_send(uint8_t *data, int len)
{
    if (len <= 0)
        return;

    /* Build a single wave with all 24 * len bits */
    int total_bits = len * 24;
    uint32_t *bits = malloc(total_bits * sizeof(uint32_t));
    if (!bits) {
        perror("malloc");
        return;
    }

    for (int i = 0; i < len; i++) {
        for (int j = 7; j >= 0; j--) {
            uint8_t bit = (data[i] >> j) & 1;
            bits[i * 24 + (7 - j)] = (bit) ? 0x000000FF : 0x00FFFFFF;
        }
    }

    int wave_id = gpioWaveAddNew();
    if (wave_id < 0) {
        fprintf(stderr, "gpioWaveAddNew failed: %d\n", wave_id);
        free(bits);
        return;
    }

    gpioPulse_t *pulses = malloc(total_bits * sizeof(gpioPulse_t));
    if (!pulses) {
        fprintf(stderr, "malloc pulses failed\n");
        gpioWaveDelete(wave_id);
        free(bits);
        return;
    }

    /* 800 kHz PWM → period = 1250 ns */
    uint32_t half_period = PWM_RANGE / 2; /* 122.5 ns per unit step */

    for (int i = 0; i < total_bits; i++) {
        uint32_t duty = bits[i];
        pulses[i].gpioOn  = (duty & 0x000000FF) ? (1u << PWM_PIN) : 0;
        pulses[i].gpioOff = (duty & 0x0000FF00) ? (1u << PWM_PIN) : 0;
        pulses[i].usDelay = 0;
    }

    pulses[0].gpioOn  = 0;
    pulses[0].gpioOff = (1u << PWM_PIN);

    gpioWaveClear();
    gpioWaveAddGeneric(total_bits, pulses);

    int ret = gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
    if (ret < 0) {
        fprintf(stderr, "gpioWaveTxSend failed: %d\n", ret);
    }

    /* Wait for wave to complete */
    while (gpioWaveTxBusy())
        usleep(100);

    gpioWaveDelete(wave_id);
    free(pulses);
    free(bits);
}

/* ---- Signal handling ---- */

static void cleanup(void)
{
    /* Turn off LEDs and stop PWM */
    uint8_t off[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++)
        off[i] = 0;
    ws2812_send(off, NUM_LEDS);

    /* Reset PWM */
    gpioSetPWMfrequency(PWM_PIN, 0);
    gpioSetPWMrange(PWM_PIN, 1);
    gpioWrite(PWM_PIN, 0);

    /* Close I2C */
    if (i2c_fd >= 0)
        close(i2c_fd);
}

/* ---- Main ---- */

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open I2C */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure PWM */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ_HZ);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    uint8_t led_data[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++)
        led_data[i] = 0;

    while (g_running) {
        /* Trigger one-time high-resolution measurement */
        if (i2c_write_cmd(i2c_fd, BH1750_CMD) < 0) {
            fprintf(stderr, "BH1750 write failed – retrying next cycle\n");
            usleep(100000);
            continue;
        }

        /* Wait for conversion */
        usleep(BH1750_CONV_MS * 1000);

        uint16_t raw;
        if (i2c_read16(i2c_fd, &raw) < 0) {
            fprintf(stderr, "BH1750 read failed – retrying next cycle\n");
            usleep(100000);
            continue;
        }

        float lux = (float)raw / 1.2f;

        /* Logarithmic mapping */
        float log_lux = log10f(lux + 1.0f);
        float norm = (log_lux - LOG_MIN) / (LOG_MAX - LOG_MIN);
        if (norm < 0.0f) norm = 0.0f;
        if (norm > 1.0f) norm = 1.0f;

        float brightness = norm * BRIGHTNESS_MAX;
        int level = (int)brightness;

        /* WS2812B expects 24-bit per LED */
        for (int i = 0; i < NUM_LEDS; i++) {
            led_data[i] = (uint8_t)level;
        }

