/*
 * Raspberry Pi Zero W — BH1750 ambient light sensor → APA102 LED strip.
 *
 * Hardware:
 *   - BH1750 on /dev/i2c-1, address 0x23 (ADDR pin tied to GND).
 *   - APA102 on /dev/spidev0.0, 1 MHz SPI, CE0 active-low.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_BUS        "/dev/spidev0.0"
#define BH1750_ADDR    0x23
#define BH1750_CONV_MS 120
#define SPI_SPEED_HZ   1000000
#define NUM_LEDS       16

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * BH1750 continuous-H-40 mode: one-shot conversion, then read 2 bytes.
 * The sensor is woken by writing 0x01, then a conversion is triggered
 * by writing 0x10 (one-shot, H-1 resolution, ~120 ms).
 */
static int bh1750_read(int fd, uint16_t *out)
{
    uint8_t cmd = 0x10;          /* one-shot, H-1 (1 lux resolution) */
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 one-shot write: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != 2) {
        fprintf(stderr, "BH1750 read: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *bus, uint32_t speed_hz)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * APA102 data frame (32 bits):
 *   [0..31]  Start frame (0x00)
 *   [32..63] LED frame (0x00, brightness, blue, green, red)
 *   [96..127] End frame (0xFF)
 *
 * brightness (8 bits): 0 = off, 255 = full on.
 */
static int apa102_send(int fd, uint8_t brightness)
{
    uint8_t start[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t led[4]   = {0x00, brightness, 0x00, 0x00};
    uint8_t end[4]   = {0xFF, 0xFF, 0xFF, 0xFF};

    uint8_t tx[4 + 4 * NUM_LEDS + 4];
    size_t idx = 0;
    memcpy(&tx[idx], start, 4); idx += 4;
    for (int i = 0; i < NUM_LEDS; i++)
        memcpy(&tx[idx], led, 4), idx += 4;
    memcpy(&tx[idx], end, 4); idx += 4;

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = 0;
    tr.len           = idx;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0)
        return EXIT_FAILURE;

    int spi_fd = spi_open(SPI_BUS, SPI_SPEED_HZ);
    if (spi_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 → APA102 LED strip. Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw;
        if (bh1750_read(i2c_fd, &raw) < 0) {
            fprintf(stderr, "Sensor read failed; turning LEDs off.\n");
            apa102_send(spi_fd, 0);
            usleep(100000);
            continue;
        }

        /* Scale 0..65535 → 0..255 */
        uint8_t brightness = (uint8_t)(raw / 256);
        if (apa102_send(spi_fd, brightness) < 0)
            fprintf(stderr, "SPI write failed.\n");

        printf("Raw: %u  Brightness: %u\n", raw, brightness);
        usleep(100000);
    }

    /* Graceful shutdown: turn off all LEDs and release resources. */
    apa102_send(spi_fd, 0);
    close(spi_fd);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

