#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x70
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 180
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_LEDS 10
#define FADE_TIME_MS 500
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_handles[3] = {-1, -1, -1};
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int addr) {
    int handle = i2cOpen(I2C_BUS, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x%02X not found (pigpio error %d)\n", addr, handle);
        return -1;
    }
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Warning: Failed to set BH1750 mode at 0x%02X\n", addr);
        i2cClose(handle);
        return -1;
    }
    return handle;
}

static int read_bh1750(int handle) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed on BH1750 handle %d\n", handle);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    char data[4 + NUM_LEDS * 4];
    data[0] = 0xE0;
    data[1] = 0xFF;
    data[2] = 0xFF;
    data[3] = 0xFF;
    for (int i = 0; i < NUM_LEDS; i++) {
        data[4 + i * 4] = 0x00;
        data[5 + i * 4] = 0x00;
        data[6 + i * 4] = 0x00;
        data[7 + i * 4] = (char)brightness;
    }
    data[4 + NUM_LEDS * 4] = 0xFF;
    data[5 + NUM_LEDS * 4] = 0xFF;
    data[6 + NUM_LEDS * 4] = 0xFF;
    data[7 + NUM_LEDS * 4] = 0x00;
    if (spiWrite(spi_handle, data, sizeof(data)) < 0) {
        fprintf(stderr, "Error: SPI write failed\n");
    }
}

static void fade_led_brightness(int target_brightness) {
    int current = 0;
    int step = (target_brightness > current) ? 1 : -1;
    int steps = abs(target_brightness - current);
    int delay_us = (FADE_TIME_MS * 1000) / steps;
    for (int i = 0; i <= steps; i++) {
        if (!running) break;
        current += step;
        set_led_brightness(current);
        gpioDelay(delay_us);
    }
}

static void cleanup(void) {
    set_led_brightness(0);
    for (int i = 0; i < 3; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }
    i2c_handles[0] = init_bh1750(BH1750_ADDR_1);
    i2c_handles[1] = init_bh1750(BH1750_ADDR_2);
    i2c_handles[2] = init_bh1750(BH1750_ADDR_3);
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    int valid_count = 0;
    int sum = 0;
    while (running) {
        sum = 0;
        valid_count = 0;
        for (int i = 0; i < 3; i++) {
            if (i2c_handles[i] < 0) continue;
            if (i2cWriteByte(i2c_handles[i], 0x00) < 0) continue;
            gpioDelay(BH1750_CONV_TIME_MS * 1000);
            int val = read_bh1750(i2c_handles[i]);
            if (val >= 0) {
                sum += val;
                valid_count++;
            }
        }
        int avg = (valid_count > 0) ? (sum / valid_count) : 0;
        int brightness = (avg > 255) ? 255 : avg;
        fade_led_brightness(brightness);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }
    cleanup();
    return 0;
}

