#define VEML7700_REG_ALS_INT 0x09
#define VEML7700_REG_ALS_TH1 0x0A
#define VEML7700_REG_ALS_TH2 0x0B
#define VEML7700_REG_ALS_SD_CONF 0x0C
#define VEML7700_REG_ALS_SD_TH1 0x0D
#define VEML7700_REG_ALS_SD_TH2 0x0E
#define VEML7700_REG_ALS_SD_INT 0x0F
#define VEML7700_REG_ALS_SD_INT_EN 0x10
#define VEML7700_REG_ALS_SD_INT_CLR 0x11
#define VEML7700_REG_ALS_SD_INT_EN_CLR 0x12
#define VEML7700_REG_ALS_SD_INT_EN_SET 0x13
