#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define FLAME_READ_COUNT 5
#define FLAME_READ_DELAY_US 100000
#define SELF_TEST_BLINK_COUNT 2
#define SELF_TEST_BLINK_DELAY_US 500000
#define ERROR_BLINK_COUNT 5
#define ERROR_BLINK_DELAY_US 100000
#define ERROR_BUZZER_PATTERN_COUNT 3
#define ERROR_BUZZER_PATTERN_DELAY_US 200000
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        log_event("Error: Failed to read flame sensor.");
        return -1;
    }
    return value;
}

static int self_test(void) {
    int flame_reads[FLAME_READ_COUNT];
    int low_count = 0;

    log_event("Starting self-test...");

    for (int i = 0; i < SELF_TEST_BLINK_COUNT; i++) {
        if (gpioWrite(LED_PIN, 1) < 0) {
            log_event("Error: Failed to set LED high during self-test.");
            return -1;
        }
        gpioDelay(SELF_TEST_BLINK_DELAY_US);
        if (gpioWrite(LED_PIN, 0) < 0) {
            log_event("Error: Failed to set LED low during self-test.");
            return -1;
        }
        gpioDelay(SELF_TEST_BLINK_DELAY_US);
    }

    for (int i = 0; i < FLAME_READ_COUNT; i++) {
        int v = read_flame_sensor();
        if (v < 0) return -1;
        flame_reads[i] = v;
        if (v == 0) low_count++;
        gpioDelay(FLAME_READ_DELAY_US);
    }

    if (low_count == FLAME_READ_COUNT) {
        log_event("Self-test failed: Flame sensor indicates flame detected on all reads.");
        return -1;
    }

    log_event("Self-test passed.");
    return 0;
}

static void error_signal(void) {
    log_event("Error: Flame sensor indicates flame detected on all reads.");

    for (int i = 0; i < ERROR_BLINK_COUNT; i++) {
        if (gpioWrite(LED_PIN, 1) < 0) {
            log_event("Error: Failed to set LED high during error signal.");
            return;
        }
        gpioDelay(ERROR_BLINK_DELAY_US);
        if (gpioWrite(LED_PIN, 0) < 0) {
            log_event("Error: Failed to set LED low during error signal.");
            return;
        }
        gpioDelay(ERROR_BLINK_DELAY_US);
    }

    for (int i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("Error: Failed to set buzzer high during error signal.");
            return;
        }
        gpioDelay(ERROR_BUZZER_PATTERN_DELAY_US);
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("Error: Failed to set buzzer low during error signal.");
            return;
        }
        gpioDelay(ERROR_BUZZER_PATTERN_DELAY_US);
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("Error: Failed to set buzzer high during error signal.");
            return;
        }
        gpioDelay(ERROR_BUZZER_PATTERN_DELAY_US);
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("Error: Failed to set buzzer low during error signal.");
            return;
        }
        gpioDelay(ERROR_BUZZER_PATTERN_DELAY_US);
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        log_event("Error: Failed to set buzzer low during error signal.");
    }
}

static void cleanup(void) {
    gpioWrite(LED_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Warning: Failed to set pull-up on flame sensor pin.\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    if (self_test() < 0) {
        error_signal();
        cleanup();
        return 1;
    }

    log_event("System ready. Monitoring flame sensor...");

    int flame_detected = 0;
    int last_flame_state = 1;

    while (running) {
        int flame_value = read_flame_sensor();
        if (flame_value < 0) {
            log_event("Error: Failed to read flame sensor in main loop.");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (flame_value == 0) {
            if (!flame_detected) {
                flame_detected = 1;
                log_event("Flame detected!");
            }
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                log_event("Error: Failed to set buzzer high.");
            }
            if (gpioWrite(LED_PIN, 1) < 0) {
                log_event("Error: Failed to set LED high.");
            }
        } else {
            if (flame_detected) {
                flame_detected = 0;
                log_event("Flame cleared.");
            }
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                log_event("Error: Failed to set buzzer low.");
            }
            if (gpioWrite(LED_PIN, 0) < 0) {
                log_event("Error: Failed to set LED low.");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down...");
    cleanup();
    return 0;
}

