#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_ONE  0x10   /* One-time high-resolution measurement */
#define BH1750_CMD_PWR  0x01   /* Power on */
#define BH1750_CMD_RST  0x07   /* Reset */
#define LED_PIN        17
#define BUFFER_SIZE    60
#define MIN_FREQ_HZ    0.5
#define MAX_FREQ_HZ    5.0
#define MAX_LUX        1000.0
#define SAMPLE_PERIOD  1       /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_CMD_PWR) < 0) return -1;
    usleep(10000);  /* 10 ms power-on delay */
    if (i2c_write_byte(fd, BH1750_CMD_RST) < 0) return -1;
    usleep(10000);  /* 10 ms reset delay */
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    if (i2c_write_byte(fd, BH1750_CMD_ONE) < 0) return -1;
    usleep(180000);  /* 180 ms measurement time (high-res mode) */

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void buffer_add(float *buf, int *idx, float val)
{
    buf[*idx] = val;
    *idx = (*idx + 1) % BUFFER_SIZE;
}

static float buffer_avg(const float *buf, int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buf[i];
    return sum / (float)size;
}

static void led_square(int pin, float freq_hz)
{
    float half_period_s = 1.0f / (2.0f * freq_hz);
    int half_us = (int)(half_period_s * 1e6f);
    usleep(half_us);
    if (half_us > 0) {
        int val = 1;
        if (ioctl(pin, 0, &val) < 0) return;
        usleep(half_us);
        val = 0;
        if (ioctl(pin, 0, &val) < 0) return;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    /* Export and set LED pin as output */
    FILE *gpio_fd = fopen("/sys/class/gpio/export", "w");
    if (!gpio_fd) {
        fprintf(stderr, "Cannot open /sys/class/gpio/export: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    fprintf(gpio_fd, "%d", LED_PIN);
    fclose(gpio_fd);

    usleep(100000);  /* let sysfs settle */

    gpio_fd = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (!gpio_fd) {
        fprintf(stderr, "Cannot open GPIO direction: %s\n", strerror(errno));
        g_i2c_fd = -1;
        return 1;
    }
    fprintf(gpio_fd, "out");
    fclose(gpio_fd);

    float lux_buf[BUFFER_SIZE];
    int buf_idx = 0;
    int consecutive_errors = 0;

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(g_i2c_fd, &lux) < 0) {
            consecutive_errors++;
            fprintf(stderr, "Sensor read error (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many consecutive errors, aborting\n");
                break;
            }
            sleep(SAMPLE_PERIOD);
            continue;
        }
        consecutive_errors = 0;

        buffer_add(lux_buf, &buf_idx, lux);
        float avg = buffer_avg(lux_buf, BUFFER_SIZE);

        float freq = MIN_FREQ_HZ +
                     (avg / MAX_LUX) * (MAX_FREQ_HZ - MIN_FREQ_HZ);

        int val = 1;
        if (ioctl(LED_PIN, 0, &val) < 0) {
            fprintf(stderr, "GPIO write failed: %s\n", strerror(errno));
            break;
        }
        usleep((int)(500000.0f / (2.0f * freq)));

        val = 0;
        if (ioctl(LED_PIN, 0, &val) < 0) {
            fprintf(stderr, "GPIO write failed: %s\n", strerror(errno));
            break;
        }
        usleep((int)(500000.0f / (2.0f * freq)));

        printf("Lux: %.2f, Avg: %.2f, LED: %.2f Hz\n", lux, avg, freq);
        sleep(SAMPLE_PERIOD);
    }

    /* Cleanup */
    gpio_fd = fopen("/sys/class/gpio/unexport", "w");
    if (gpio_fd) {
        fprintf(gpio_fd, "%d", LED_PIN);
        fclose(gpio_fd);
    }
    if (g_i2c_fd >= 0) close(g_i2c_fd);

    return 0;
}

