static void shift_out(uint8_t data) {
    for (int i = 7; i >= 0; i--) {
        if (gpioWrite(CLOCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to write CLOCK low\n");
            return;
        }
        int bit = (data >> i) & 1;
        if (gpioWrite(DATA_PIN, bit) < 0) {
            fprintf(stderr, "Error: failed to write DATA\n");
            return;
        }
        if (gpioWrite(CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: failed to write CLOCK high\n");
            return;
        }
    }
    if (gpioWrite(LATCH_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write LATCH high\n");
    }
    if (gpioWrite(LATCH_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write LATCH low\n");
    }
}

static void display_digit(int digit) {
    switch (digit) {
        case 5:
            shift_out(0x30);
            break;
        default:
            shift_out(0x00);
            break;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set DATA_PIN %d as output\n", DATA_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set CLOCK_PIN %d as output\n", CLOCK_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN %d as output\n", LATCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(DATA_PIN, 0) < 0 || gpioWrite(CLOCK_PIN, 0) < 0 || gpioWrite(LATCH_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize GPIO lines to low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        display_digit(5);
        usleep(500000);
        if (!running) break;
        display_digit(0);
        usleep(500000);
    }

    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

