/*
 * blink_button.c - Blink LED on GPIO17 with 1s on/off period, stop on falling
 * edge from button on GPIO18 (pull-up, falling-edge event).
 *
 * Build:  gcc -o blink_button blink_button.c -lgpiod
 * Run:    ./blink_button
 */
#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define LED_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define BUTTON_LINE_OFFSET 18       /* BCM 18, physical pin 12 */
#define CONSUMER        "blink-button"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful Ctrl-C exit */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line (output, initially low) */
    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Get the button line (input with pull-up, falling-edge event) */
    button_line = gpiod_chip_get_line(chip, BUTTON_LINE_OFFSET);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(button_line, CONSUMER) < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    /* Main blink loop with button interruptible */
    while (g_running) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("gpiod_line_set_value (LED on)");
            goto cleanup;
        }
        printf("LED ON\n");
        fflush(stdout);

        /* Blink for 1 second, checking for shutdown */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000); /* 100 ms slices */

        if (!g_running)
            break;

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value (LED off)");
            goto cleanup;
        }
        printf("LED OFF\n");
        fflush(stdout);

        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    /* Button press detected - stop blinking */
    printf("Button pressed! Stopping LED.\n");
    fflush(stdout);

    /* Ensure LED is off */
    if (led_line)
        gpiod_line_set_value(led_line, 0);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (led_line)
        gpiod_line_release(led_line);
    if (button_line)
        gpiod_line_release(button_line);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

