    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line(BUTTON)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "led-blink", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* Request button line as input with pull-down */
    ret = gpiod_line_request_input_flags(button_line, "button-monitor",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    printf("Button-controlled LED blinking started. Press Ctrl-C to exit.\n");

    while (running) {
        int button_val = gpiod_line_get_value(button_line);
        if (button_val < 0) {
            perror("gpiod_line_get_value(BUTTON)");
            break;
        }

        if (button_val == 1) {
            /* Button pressed: blink LED */
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED on)");
                break;
            }
            usleep(BLINK_INTERVAL_MS * 1000);

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED off)");
                break;
            }
            usleep(BLINK_INTERVAL_MS * 1000);
        } else {
            /* Button not pressed: ensure LED is off */
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED off)");
                break;
            }
            usleep(50 * 1000); /* small debounce / poll interval */
        }
    }

cleanup:
    /* Ensure LED is off on exit */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

