#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18
#define PWM_PERIOD_NS 10000000  /* 10 ms -> 100 Hz */
#define PWM_STEP_NS   100000    /* 100 us per step */
#define LOOP_DELAY_MS 100
#define MAX_INTENSITY 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void sleep_ns(long ns)
{
    struct timespec ts = {
        .tv_sec  = ns / 1000000000L,
        .tv_nsec = ns % 1000000000L
    };
    while (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts) == EINTR) {
        if (!running)
            return;
    }
}

static void pwm_set(struct gpiod_line *line, int intensity)
{
    if (intensity < 0) intensity = 0;
    if (intensity > MAX_INTENSITY) intensity = MAX_INTENSITY;

    int on_ns  = (intensity * PWM_PERIOD_NS) / MAX_INTENSITY;
    int off_ns = PWM_PERIOD_NS - on_ns;

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to set line high: %s\n", strerror(errno));
        return;
    }
    sleep_ns(on_ns);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to set line low: %s\n", strerror(errno));
        return;
    }
    sleep_ns(off_ns);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL;
    struct gpiod_line *green_line = NULL;
    struct gpiod_line *blue_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    red_line   = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Error: failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb-led", 0) < 0) {
        fprintf(stderr, "Error: failed to request red line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(green_line, "rgb-led", 0) < 0) {
        fprintf(stderr, "Error: failed to request green line as output: %s\n", strerror(errno));
