#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define LED_GPIO 18
#define CSV_FILE "color_log.csv"
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define ADPD188BI_REG_ALS_LSB 0x00
#define ADPD188BI_REG_ALS_MSB 0x01
#define ADPD188BI_REG_RED_LSB 0x02
#define ADPD188BI_REG_RED_MSB 0x03
#define ADPD188BI_REG_GREEN_LSB 0x04
#define ADPD188BI_REG_GREEN_MSB 0x05
#define ADPD188BI_REG_BLUE_LSB 0x06
#define ADPD188BI_REG_BLUE_MSB 0x07

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int read_16bit(int handle, uint8_t lsb_reg, uint8_t msb_reg, uint16_t *value) {
    uint8_t lsb, msb;
    if (read_register(handle, lsb_reg, &lsb) != 0) return -1;
    if (read_register(handle, msb_reg, &msb) != 0) return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_16bit(handle, ADPD188BI_REG_ALS_LSB, ADPD188BI_REG_ALS_MSB, als) != 0) return -1;
    if (read_16bit(handle, ADPD188BI_REG_RED_LSB, ADPD188BI_REG_RED_MSB, red) != 0) return -1;
    if (read_16bit(handle, ADPD188BI_REG_GREEN_LSB, ADPD188BI_REG_GREEN_MSB, green) != 0) return -1;
    if (read_16bit(handle, ADPD188BI_REG_BLUE_LSB, ADPD188BI_REG_BLUE_MSB, blue) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            als, red, green, blue);
    fflush(fp);
}

static void control_led(uint16_t als) {
    int duty = (int)((float)als / 65535.0f * 255.0f);
    if (duty > 255) duty = 255;
    if (duty < 0) duty = 0;
    gpioPWM(LED_GPIO, duty);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioPWM(LED_GPIO, 0);

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(csv_file);
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t als, red, green, blue;
        if (read_sensor_data(i2c_handle, &als, &red, &green, &blue) == 0) {
            log_data(csv_file, als, red, green, blue);
            control_led(als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

