#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700CQ register definitions (verified against datasheet) ---- */
#define FXOS8700_ADDRESS        0x1E
#define FXOS8700_WHO_AM_I       0x0D
#define FXOS8700_WHO_AM_I_VAL   0xC7
#define FXOS8700_CTRL_REG1      0x2A
#define FXOS8700_M_CTRL_REG1    0x5B
#define FXOS8700_M_CTRL_REG2    0x5C
#define FXOS8700_OUT_X_MSB      0x01
#define FXOS8700_OUT_X_LSB      0x02
#define FXOS8700_OUT_Y_MSB      0x03
#define FXOS8700_OUT_Y_LSB      0x04
#define FXOS8700_OUT_Z_MSB      0x05
#define FXOS8700_OUT_Z_LSB      0x06

/* CTRL_REG1 bits: ODR[3:0]=1100 (200 Hz), ACTIVE=1, STANDBY=0 -> 0xC0 */
#define FXOS8700_CTRL1_ACTIVE   0x80
#define FXOS8700_CTRL1_ODR_200  0xC0
#define FXOS8700_CTRL1_VAL      (FXOS8700_CTRL1_ACTIVE | FXOS8700_CTRL1_ODR_200)

/* M_CTRL_REG1: DR=1 (high-performance mode), 100 Hz ODR, ±2 g range -> 0x1F */
#define FXOS8700_M_CTRL1_VAL    0x1F

/* Acceleration sensitivity at ±2 g: 1 mg / LSB = 0.001 g/LSB */
#define ACCEL_SENSITIVITY       0.001f

/* Impact threshold (g) */
#define IMPACT_THRESHOLD        5.0f

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS                 1

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US      50000

/* Global I2C handle for signal-handler cleanup */
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — close I2C and terminate pigpio cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    _exit(0);
}

/* ------------------------------------------------------------------ */
/* Verify the device identity                                         */
/* ------------------------------------------------------------------ */
static int verify_device(int handle)
{
    int who = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: I2C read failed for WHO_AM_I (pigpio rc=%d)\n", who);
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the FXOS8700CQ                                          */
/* ------------------------------------------------------------------ */
static int init_fxos8700(int handle)
{
    /* Put device in standby so configuration registers can be written */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set CTRL_REG1 standby\n");
        return -1;
    }

    /* Configure magnetometer: high-performance mode, 100 Hz, ±2 g */
    if (i2cWriteByteData(handle, FXOS8700_M_CTRL_REG1, FXOS8700_M_CTRL1_VAL) < 0) {
        fprintf(stderr, "Error: failed to write M_CTRL_REG1\n");
        return -1;
    }

    /* Activate sensor at 200 Hz */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, FXOS8700_CTRL1_VAL) < 0) {
        fprintf(stderr, "Error: failed to activate CTRL_REG1\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (x, y, z) in g                                     */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C block read failed for acceleration data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute acceleration magnitude                                      */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log impact event to file                                            */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open impact_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the FXOS8700CQ address */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify device identity */
    if (verify_device(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: FXOS8700CQ not detected on bus %d addr 0x%02X\n",
                I2C_BUS, FXOS8700_ADDRESS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialise sensor */
    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: FXOS8700CQ initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("FXOS8700CQ initialised. Monitoring for impacts (threshold %.1f g)...\n",
           IMPACT_THRESHOLD);

    /* Main sampling loop */
    while (1) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            float mag = calculate_magnitude(x, y, z);
            if (mag > IMPACT_THRESHOLD) {
                log_impact(x, y, z, mag);
            }
        }
        /* On read error, the error is already reported to stderr;
           we continue sampling rather than aborting. */

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Unreachable in normal operation; signal handler exits cleanly */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

