#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADXL345_ADDR   0x53
#define ADXL345_DEVID  0x00
#define ADXL345_POWER  0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_FILTER 0x28
#define ADXL345_RANGE  0x2C
#define ADXL345_FULL_RES 0x08
#define ADXL345_RANGE_2G 0x00
#define ADXL345_DEVID_VAL 0xE5
#define LED_PIN        17
#define SAMPLE_PERIOD_US 100000
#define ACCEL_THRESHOLD 2.0f
#define SCALE_FACTOR 0.0039f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int adxl345_read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int adxl345_init(void) {
    uint8_t devid = 0;
    if (adxl345_read_reg(ADXL345_DEVID, &devid) < 0) return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID_VAL);
        return -1;
    }

    if (adxl345_write_reg(ADXL345_POWER, 0x00) < 0) return -1;
    if (adxl345_write_reg(ADXL345_FILTER, 0x08) < 0) return -1;
    if (adxl345_write_reg(ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (adxl345_write_reg(ADXL345_RANGE, ADXL345_RANGE_2G | ADXL345_FULL_RES) < 0) return -1;
    if (adxl345_write_reg(ADXL345_POWER, 0x08) < 0) return -1;

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed: %d\n", rc);
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    *x = (float)raw_x * SCALE_FACTOR;
    *y = (float)raw_y * SCALE_FACTOR;
    *z = (float)raw_z * SCALE_FACTOR;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(log_file);
}

static void control_led(float x, float y, float z) {
    int on = (fabsf(x) > ACCEL_THRESHOLD || fabsf(y) > ACCEL_THRESHOLD || fabsf(z) > ACCEL_THRESHOLD);
    gpioWrite(LED_PIN, on ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n", I2C_BUS, ADXL345_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen("accel_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open accel_log.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    while (running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Read error — skipping sample\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_PIN, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

