#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

#define ACCEL_CTRL_REG1 0x20
#define ACCEL_OUT_X_L 0x28
#define MAG_CTRL_REG1 0x00
#define MAG_CTRL_REG2 0x01
#define MAG_CTRL_REG3 0x02
#define MAG_OUT_X_L 0x08

#define ACCEL_SENSITIVITY 16384.0f
#define MAG_SENSITIVITY 1100.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_accel(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ACCEL_OUT_X_L, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / ACCEL_SENSITIVITY;
    *y = (float)raw_y / ACCEL_SENSITIVITY;
    *z = (float)raw_z / ACCEL_SENSITIVITY;
    return 0;
}

static int read_mag(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, MAG_OUT_X_L, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / MAG_SENSITIVITY;
    *y = (float)raw_y / MAG_SENSITIVITY;
    *z = (float)raw_z / MAG_SENSITIVITY;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float roll = atan2f(ay, az);
    float mx_comp = mx * cosf(pitch) + mz * sinf(pitch);
    float my_comp = mx * sinf(roll) * sinf(pitch) + my * cosf(roll) - mz * sinf(roll) * cosf(pitch);
    float heading = atan2f(my_comp, mx_comp) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

