        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(mag_handle, MAG_CTRL_REG1, 0x10) < 0) {
        fprintf(stderr, "Error setting magnetometer control register 1\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(mag_handle, MAG_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error setting magnetometer control register 2\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(mag_handle, MAG_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error setting magnetometer control register 3\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

