#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x28
#define SENSOR2_ADDR 0x29
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

static int read_audio_sample(int handle, int16_t *sample) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading audio sample: %s\n", strerror(errno));
        return -1;
    }
    *sample = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_tdoa(const struct timespec *ts1, const struct timespec *ts2) {
    return (double)(ts2->tv_sec - ts1->tv_sec) +
           (double)(ts2->tv_nsec - ts1->tv_nsec) / 1e9;
}

static void log_data(const struct timespec *ts, int16_t s1, int16_t s2, double tdoa) {
    fprintf(log_file, "%ld.%09ld,%d,%d,%.9f\n",
            ts->tv_sec, ts->tv_nsec, s1, s2, tdoa);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        struct timespec ts1, ts2;
        int16_t s1, s2;

        if (read_audio_sample(i2c_handle1, &s1) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_audio_sample(i2c_handle2, &s2) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts1);
        clock_gettime(CLOCK_REALTIME, &ts2);

        double tdoa = calculate_tdoa(&ts1, &ts2);
        log_data(&ts1, s1, s2, tdoa);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

