#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0x03          /* mode 3: CPOL=1, CPHA=1 */
#define SAMPLE_PERIOD  100000        /* microseconds (100 ms) */
#define STALL_US       40            /* minimum stall between request and transfer */
#define GYRO_SENS      0.005         /* deg/sec/LSB */
#define ACCEL_SENS     0.00025       /* g/LSB */

#define REG_GYRO_XOUT  0x04
#define REG_GYRO_YOUT  0x06
#define REG_GYRO_ZOUT  0x08
#define REG_ACCEL_XOUT 0x0A
#define REG_ACCEL_YOUT 0x0C
#define REG_ACCEL_ZOUT 0x0E

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_csv_file   = NULL;
static int      g_pigpio_inited = 0;

static void cleanup(void)
{
    if (g_csv_file) {
        fflush(g_csv_file);
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_pigpio_inited) {
        gpioTerminate();
        g_pigpio_inited = 0;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * ADIS16488A SPI read protocol (16-bit words):
 *   tx[0] = 0x00  (command: MSB=0)
 *   tx[1] = addr | 0x80  (MSB=1 to indicate read)
 *   rx[0] = don't care
 *   rx[1] = data LSB
 *   tx[2] = 0x00  (dummy to clock out the remaining 8 data bits)
