/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM, SPI0 CE0)
 *   ADIS16448 SDO -> GPIO9  (BCM, SPI0 MISO)
 *   ADIS16448 SDA -> GPIO10 (BCM, SPI0 MOSI)
 *   ADIS16448 SCL -> GPIO11 (BCM, SPI0 SCLK)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o adis16448 adis16448.c -lgpiod
 * Run:    ./adis16448   (requires read access to /dev/spidev0.0)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ---- ADIS16448 register addresses (16-bit, big-endian on wire) ---- */
#define ADIS16448_REG_GX_OUT   0x04
#define ADIS16448_REG_GY_OUT   0x06
#define ADIS16448_REG_GZ_OUT   0x08
#define ADIS16448_REG_AX_OUT   0x0A
#define ADIS16448_REG_AY_OUT   0x0C
#define ADIS16448_REG_AZ_OUT   0x0E

/* ---- Scaling factors (from ADIS16448 datasheet) ---- */
#define GYRO_SCALE_DPS_PER_LSB  0.02f   /* degrees/sec per LSB */
#define ACCEL_SCALE_G_PER_LSB   0.00025f /* g per LSB */

/* ---- SPI / GPIO configuration ---- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          3          /* CPOL=1, CPHA=1 */

#define GPIO_CHIP_NAME    "gpiochip4" /* BCM GPIO8 on Pi 4/5 */
#define CS_GPIO_OFFSET    8           /* BCM GPIO8 = SPI0 CE0 */

#define SAMPLE_PERIOD_MS  100

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static struct gpiod_chip  *g_chip   = NULL;
static struct gpiod_line  *g_cs_line = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);   /* deassert CS */
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Assert CS (active-low) and deassert after the transfer.             */
static int cs_control(int fd, bool assert_cs)
{
    if (gpiod_line_set_value(g_cs_line, assert_cs ? 0 : 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        return -1;
    }
    /* Small delay so the ADIS16448 sees a clean CS edge */
    usleep(1000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Single-register read: send 16-bit address (bit7=1), receive 16-bit
 * data.  Returns 0 on success and stores the raw 16-bit value in *out;
 * returns -1 on error.
 */
static int read_register16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (cs_control(fd, true) < 0)
        return -1;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        cs_control(fd, false);   /* best-effort deassert */
        return -1;
    }

    if (cs_control(fd, false) < 0)
        return -1;

    *out = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_axis(int fd, uint8_t reg, float scale, float *out)
{
    uint16_t raw;
    if (read_register16(fd, reg, &raw) < 0)
        return -1;
    *out = (float)raw * scale;
    return 0;
}

/* ------------------------------------------------------------------ */
static void print_data(float gx, float gy, float gz,
                       float ax, float ay, float az)
{
    printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps\n", gx, gy, gz);
    printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n", ax, ay, az);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t  mode = SPI_MODE;
    uint32_t speed = SPI_SPEED_HZ;
    uint8_t  bits  = SPI_BITS_PER_WORD;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and claim CS line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_GPIO_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                CS_GPIO_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_cs_line, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 reader started on %s (CS=GPIO%d). Press Ctrl+C to exit.\n",
           SPI_DEVICE, CS_GPIO_OFFSET);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_axis(g_spi_fd, ADIS16448_REG_GX_OUT, GYRO_SCALE_DPS_PER_LSB, &gx) < 0 ||
            read_axis(g_spi_fd, ADIS16448_REG_GY_OUT, GYRO_SCALE_DPS_PER_LSB, &gy) < 0 ||
            read_axis(g_spi_fd, ADIS16448_REG_GZ_OUT, GYRO_SCALE_DPS_PER_LSB, &gz) < 0 ||
            read_axis(g_spi_fd, ADIS16448_REG_AX_OUT, ACCEL_SCALE_G_PER_LSB,  &ax) < 0 ||
            read_axis(g_spi_fd, ADIS16448_REG_AY_OUT, ACCEL_SCALE_G_PER_LSB,  &ay) < 0 ||
            read_axis(g_spi_fd, ADIS16448_REG_AZ_OUT, ACCEL_SCALE_G_PER_LSB,  &az) < 0) {
            fprintf(stderr, "SPI read error; continuing.\n");
        } else {
            print_data(gx, gy, gz, ax, ay, az);
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

