#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define SAMPLE_US   100000

#define ADIS16448_GYRO_XOUT  0x04
#define ADIS16448_GYRO_YOUT  0x06
#define ADIS16448_GYRO_ZOUT  0x08
#define ADIS16448_ACCEL_XOUT 0x0A
#define ADIS16448_ACCEL_YOUT 0x0C
#define ADIS16448_ACCEL_ZOUT 0x0E

#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(uint8_t reg, int16_t *out) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    gpioDelay(40);
    tx[0] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_imu_data(float *gx, float *gy, float *gz,
                         float *ax, float *ay, float *az) {
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

    if (read_register(ADIS16448_GYRO_XOUT, &raw_gx) != 0) return -1;
    if (read_register(ADIS16448_GYRO_YOUT, &raw_gy) != 0) return -1;
    if (read_register(ADIS16448_GYRO_ZOUT, &raw_gz) != 0) return -1;
    if (read_register(ADIS16448_ACCEL_XOUT, &raw_ax) != 0) return -1;
    if (read_register(ADIS16448_ACCEL_YOUT, &raw_ay) != 0) return -1;
    if (read_register(ADIS16448_ACCEL_ZOUT, &raw_az) != 0) return -1;

    *gx = (float)raw_gx * GYRO_SCALE;
    *gy = (float)raw_gy * GYRO_SCALE;
    *gz = (float)raw_gz * GYRO_SCALE;
    *ax = (float)raw_ax * ACCEL_SCALE;
    *ay = (float)raw_ay * ACCEL_SCALE;
    *az = (float)raw_az * ACCEL_SCALE;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float gx, gy, gz, ax, ay, az;

    while (running) {
        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f deg/s | Accel: X=%.4f, Y=%.4f, Z=%.4f g\n",
                   gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Error reading IMU data\n");
        }
        gpioDelay(SAMPLE_US);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

