/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1  (GPIO2=SDA, GPIO3=SCL)
 * Sensor address: 0x68 (AD0 tied to GND)
 * Reads raw 16-bit accelerometer and gyroscope values every 50 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6886_reader mpu6886_reader.c
 * Run:    ./mpu6886_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68

/* MPU-6886 register addresses */
#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG      0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_GYRO_XOUT_H 0x43
#define REG_ACCEL_XOUT_H 0x3B

#define SAMPLE_PERIOD_US 50000  /* 50 ms */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor configuration                                                */
/* ------------------------------------------------------------------ */
static int configure_mpu6886(int fd)
{
    /* Sample rate divider = 7  -> 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* DLPF_CFG = 3  -> 184 Hz gyro, 188 Hz accel, 1 kHz internal */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x03) < 0)
        return -1;

    /* Gyro full-scale ±250 dps  -> 0x00 */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    /* Accel full-scale ±2 g    -> 0x00 */
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    /* Probe the sensor by reading the WHO_AM_I register (0x75) */
    uint8_t whoami = 0;
    if (i2c_read_reg8(g_fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "MPU-6886 not responding at 0x%02X on %s\n",
                MPU6886_ADDR, I2C_BUS);
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }
    if (whoami != 0x68 && whoami != 0x70) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x68 or 0x70\n",
                whoami);
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    if (configure_mpu6886(g_fd) < 0) {
        fprintf(stderr, "Sensor configuration failed.\n");
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized on %s at 0x%02X. Sampling every 50 ms.\n",
           I2C_BUS, MPU6886_ADDR);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        int16_t ax = 0, ay = 0, az = 0;
        int16_t gx = 0, gy = 0, gz = 0;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (i2c_read_reg16(g_fd, REG_ACCEL_XOUT_H, &ax) == 0 &&
                i2c_read_reg16(g_fd, REG_ACCEL_XOUT_H + 2, &ay) == 0 &&
                i2c_read_reg16(g_fd, REG_ACCEL_XOUT_H + 4, &az) == 0 &&
                i2c_read_reg16(g_fd, REG_GYRO_XOUT_H, &gx) == 0 &&
                i2c_read_reg16(g_fd, REG_GYRO_XOUT_H + 2, &gy) == 0 &&
                i2c_read_reg16(g_fd, REG_GYRO_XOUT_H + 4, &gz) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            usleep(1000);
        }

        if (ok) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "All %d read attempts failed; continuing.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    return EXIT_SUCCESS;
}

