#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (from Adafruit breakout datasheet) ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_DEVID          0xE5
#define ADXL345_RANGE_2G       0x00
#define ADXL345_FULL_RES       0x08
#define ADXL345_POWER_ON       0x08
#define ADXL345_POWER_SLEEP    0x04
#define SCALE_FACTOR_2G        256.0f   /* LSB per g in full-resolution mode */

/* ---- Application constants ---- */
#define I2C_BUS                1
#define LED_GPIO               17
#define IMPACT_THRESHOLD       2.5f
#define POLL_INTERVAL_US       10000   /* 10 ms */
#define LED_ON_DURATION_US     500000  /* 500 ms */
#define LOG_FILE               "impact_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; return 0 on success, -1 on   */
/* error.                                                              */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; return 0 on success, -1 on  */
/* error.                                                             */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, set range, full-res,      */
/* enable measurement mode.                                           */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    if (adxl_read_reg(handle, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "[ERROR] DEVID mismatch: got 0x%02X, expected 0x%02X.\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    /* DATA_FORMAT: 0x00 = ±2 g, full resolution, right-justified */
    if (adxl_write_reg(handle, ADXL345_REG_DATA_FORMAT,
                       ADXL345_RANGE_2G | ADXL345_FULL_RES) != 0)
        return -1;

    /* POWER_CTL: bit D3 = measure (0x08) */
    if (adxl_write_reg(handle, ADXL345_REG_POWER_CTL,
                       ADXL345_POWER_ON) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z, little-endian) and      */
/* convert to g.                                                      */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, raw, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d (expected 6).\n", rc);
        return -1;
    }

    int16_t x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    *x = (float)x_raw / SCALE_FACTOR_2G;
    *y = (float)y_raw / SCALE_FACTOR_2G;
    *z = (float)z_raw / SCALE_FACTOR_2G;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute magnitude of acceleration vector.                          */
/* ------------------------------------------------------------------ */
static float magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log an impact event to the file.                                    */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float mag)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed; logging without timestamp.\n");
        fprintf(g_log_file, "UNKNOWN, UNKNOWN, UNKNOWN, UNKNOWN, %.3f\n", mag);
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(g_log_file, "%s, %.3f, %.3f, %.3f, %.3f\n", ts, x, y, z, mag);
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Turn the LED on for the configured duration.                        */
/* ------------------------------------------------------------------ */
static void trigger_led(int gpio)
{
    if (gpioWrite(gpio, 1) != 0)
        fprintf(stderr, "[WARN] gpioWrite(1) failed on GPIO %d.\n", gpio);
    gpioDelay(LED_ON_DURATION_US);
    if (gpioWrite(gpio, 0) != 0)
        fprintf(stderr, "[WARN] gpioWrite(0) failed on GPIO %d.\n", gpio);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put ADXL345 into sleep mode before closing */
        (void)i2cWriteByteData(g_i2c_handle, ADXL345_REG_POWER_CTL,
                               ADXL345_POWER_SLEEP);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ADXL345 init ---- */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 monitoring started. Threshold = %.1f g. Ctrl+C to exit.\n",
           IMPACT_THRESHOLD);

    /* ---- Main loop ---- */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
            /* Bus error — back off briefly and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float mag = magnitude(x, y, z);

        if (mag > IMPACT_THRESHOLD) {
            printf("[IMPACT] mag=%.3f g  (X=%.3f Y=%.3f Z=%.3f)\n", mag, x, y, z);
            log_impact(x, y, z, mag);
            trigger_led(LED_GPIO);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

