#define I2C_BUS 1
#define ICM20602_ADDR 0x68
#define ACCEL_XOUT_H 0x2D
#define GYRO_XOUT_H 0x33
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define LOG_FILE "imu_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_imu_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[12];
    int16_t *out[6] = {ax, ay, az, gx, gy, gz};

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 12) != 12) {
