#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define MMA8451Q_REG_ID 0x0D
#define MMA8451Q_REG_CTRL_REG1 0x2A
#define MMA8451Q_REG_XYZ_DATA_CFG 0x0E
#define MMA8451Q_REG_STATUS 0x00
#define MMA8451Q_REG_OUT_X_MSB 0x01
#define MMA8451Q_REG_WHO_AM_I 0x0D
#define MMA8451Q_WHO_AM_I_VAL 0x2A
#define MMA8451Q_CTRL_REG1_DEFAULT 0x01
#define MMA8451Q_XYZ_DATA_CFG_DEFAULT 0x00
#define THRESHOLD_G 2.0f
#define LED_GPIO 17
#define POLL_DELAY_US 100000
#define LED_ON_US 500000
#define LOG_FILE "impact_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, value=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read error: reg=0x%02X, len=%u, rc=%d\n", reg, len, rc);
    }
    return rc;
}

static int init_mma8451q(int handle) {
    int id = i2c_read_reg(handle, MMA8451Q_REG_WHO_AM_I);
    if (id < 0) return -1;
    if (id != MMA8451Q_WHO_AM_I_VAL) {
        fprintf(stderr, "MMA8451Q not found: WHO_AM_I=0x%02X (expected 0x%02X)\n", id, MMA8451Q_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(handle, MMA8451Q_REG_CTRL_REG1, MMA8451Q_CTRL_REG1_DEFAULT) < 0) return -1;
    if (i2c_write_reg(handle, MMA8451Q_REG_XYZ_DATA_CFG, MMA8451Q_XYZ_DATA_CFG_DEFAULT) < 0) return -1;

    return 0;
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, MMA8451Q_REG_OUT_X_MSB, buf, 6) < 0) return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 1024.0f;
    float y_g = (float)y / 1024.0f;
    float z_g = (float)z / 1024.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d, Magnitude=%.2f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: rc=%d\n", I2C_BUS, MMA8451Q_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mma8451q(i2c_handle) < 0) {
        fprintf(stderr, "MMA8451Q initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring acceleration... Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            if (magnitude > THRESHOLD_G) {
                gpioWrite(LED_GPIO, 1);
                gpioDelay(LED_ON_US);
                gpioWrite(LED_GPIO, 0);
                log_data(log_file, x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

