#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMAG5273_ADDR  0x00
#define CSV_FILENAME   "magnetic_field_log.csv"
#define SAMPLE_PERIOD  1

/* TMAG5273 register addresses */
#define REG_DEVICE_CONFIG  0x00
#define REG_X_MSB          0x01
#define REG_X_LSB          0x02
#define REG_Y_MSB          0x03
#define REG_Y_LSB          0x04
#define REG_Z_MSB          0x05
#define REG_Z_LSB          0x06
#define REG_TEMP_MSB       0x07
#define REG_TEMP_LSB       0x08
#define REG_STATUS         0x09

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, reg, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &lsb) < 0) return -1;
    *val = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, REG_X_MSB, x) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_MSB, y) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_MSB, z) < 0) return -1;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(buf, len, "1970-01-01 00:00:00");
    }
}

static int log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ensure_csv_header(void)
{
    FILE *check = fopen(CSV_FILENAME, "r");
    if (check != NULL) {
        fclose(check);
        return 0;
    }
    FILE *fp = fopen(CSV_FILENAME, "w");
    if (fp == NULL) {
        fprintf(stderr, "Cannot create %s: %s\n", CSV_FILENAME, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "timestamp,x,y,z\n") < 0) {
        fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Cannot close CSV after header: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
