        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby mode so we can configure registers */
    if (adxl_write_reg(fd, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full resolution, +/- 2 g, right-justified */
    if (adxl_write_reg(fd, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Bandwidth rate: 100 Hz */
    if (adxl_write_reg(fd, ADXL345_BW_RATE, 0x0A) != 0)
        return -1;

    /* Free-fall threshold and duration */
    if (adxl_write_reg(fd, 0x2A, FREEFALL_THRESHOLD) != 0)   /* THRESH_FF */
        return -1;
    if (adxl_write_reg(fd, 0x2B, FREEFALL_DURATION) != 0)   /* TIME_FF */
        return -1;

    /* Clear any latched interrupt */
    if (adxl_write_reg(fd, ADXL345_INT_SOURCE, 0x00) != 0)
        return -1;

    /* Enable free-fall interrupt on INT1 */
    if (adxl_write_reg(fd, ADXL345_INT_ENABLE, 0x04) != 0)
        return -1;

    /* Map free-fall to INT1 */
    if (adxl_write_reg(fd, ADXL345_INT_MAP, 0x00) != 0)
        return -1;

    /* Enter measurement mode */
    if (adxl_write_reg(fd, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    /* Write register pointer to DATAX0 */
    msgs[0].addr  = ADXL345_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len   = 1;
    msgs[0].buf   = &ADXL345_DATAX0;

    /* Read 6 bytes of acceleration data */
    msgs[1].addr  = ADXL345_I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len   = 6;
    msgs[1].buf   = buf;

    data.msgs  = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C read (DATAX0) failed: %s\n", strerror(errno));
        return -1;
    }

    /* ADXL345 is little-endian: low byte first, then high byte */
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_str[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", ts_str, ts.tv_nsec / 1000000L,
            x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable interrupts and put sensor in standby */
        (void)adxl_write_reg(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        (void)adxl_write_reg(g_i2c_fd, ADXL345_INT_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request_config req_cfg;
    struct pollfd pfd;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADXL345_I2C_ADDR, strerror(errno));
        goto fail_i2c;
    }

    /* ---- Verify sensor presence ---- */
    uint8_t devid = 0;
    if (adxl_read_reg(g_i2c_fd, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "ADXL345 not responding on %s\n", I2C_BUS);
        goto fail_i2c;
    }

    /* ---- Initialize sensor ---- */
    if (adxl_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        goto fail_i2c;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto fail_i2c;
    }
    fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
    fflush(g_log_fp);

    /* ---- Open GPIO chip and request INT1 line as input ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto fail_log;
    }

    g_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        goto fail_chip;
    }

    req_cfg.consumer     = "adxl345_freefall";
    req_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req_cfg.flags        = 0;
    if (gpiod_line_request(g_line, &req_cfg, 0) != 0) {
        fprintf(stderr, "Cannot request GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        goto fail_chip;
    }

    /* ---- Poll the GPIO line for falling-edge events ---- */
    pfd.fd   = gpiod_line_event_get_fd(g_line);
    pfd.events = POLLIN;
    pfd.revents = 0;

    printf("Free-fall detection started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int pr = poll(&pfd, 1, POLL_TIMEOUT_MS);
        if (pr < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "poll error: %s\n", strerror(errno));
            break;
        }
        if (pr == 0)
            continue;  /* timeout, loop back */

        if (pfd.revents & (POLLERR | POLLNVAL)) {
            fprintf(stderr, "GPIO event error\n");
            break;
        }

        /* Read the event to clear it */
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(g_line, &ev) != 0) {
            fprintf(stderr, "Failed to read GPIO event: %s\n", strerror(errno));
            break;
        }

        if (ev.event_type != GPIOD_LINE_EVENT_FALLING_EDGE)
            continue;

        /* ---- Free-fall confirmed: log samples until interrupt clears ---- */
        int keep_logging = 1;
        while (keep_logging && g_running) {
            int16_t x, y, z;
            if (adxl_read_xyz(g_i2c_fd, &x, &y, &z) != 0) {
                fprintf(stderr, "Sensor read error during free-fall\n");
                break;
            }
            log_sample(g_log_fp, x, y, z);
            usleep(SAMPLE_PERIOD_US);
        }
    }

    ret = EXIT_SUCCESS;

fail_chip:
    if (chip)
        gpiod_chip_close(chip);
fail_log:
    cleanup();
    return ret;

fail_i2c:
    cleanup();
    return EXIT_FAILURE;
}

