/*
 * LSM6DSR Fall Detection Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LSM6DSR SDA -> GPIO2 (BCM 2, I2C bus 1)
 *   LSM6DSR SCL -> GPIO3 (BCM 3, I2C bus 1)
 *   LSM6DSR VDD -> 3.3 V
 *   LSM6DSR GND -> GND
 *
 * Build: gcc -O2 -Wall -o fall_detect fall_detect.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR I2C address (SA0 tied to GND) ---- */
#define LSM6DSR_ADDR 0x6A

/* ---- LSM6DSR register addresses ---- */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_L_XL      0x28

/* ---- Expected chip ID ---- */
#define LSM6DSR_WHO_AM_I 0x6A

/* ---- Fall-detection thresholds ---- */
#define FREEFALL_THRESHOLD  0.2f   /* g */
#define IMPACT_THRESHOLD    2.5f   /* g */
#define DETECTION_WINDOW    1.0f   /* seconds */

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US    9615   /* ~104 Hz */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a single byte to a register ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

/* ---- Read a single byte from a register ---- */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write (reg select) failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read failed");
        return -1;
    }
    return 0;
}

/* ---- Read a 6-byte block starting at reg ---- */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_block: write (reg select) failed");
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        perror("i2c_read_block: read failed");
        return -1;
    }
    return 0;
}

/* ---- Verify sensor presence ---- */
static int verify_sensor(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I);
        return -1;
    }
    return 0;
}

/* ---- Configure LSM6DSR ---- */
static int init_lsm6dsr(int fd)
{
    /* CTRL1_XL: ODR=104 Hz (0x60), FS_XL=±2 g (0x00) -> 0x60 */
    if (i2c_write_reg8(fd, CTRL1_XL, 0x60) < 0)
        return -1;

    /* CTRL2_G: ODR=104 Hz (0x60), FS_G=±250 dps (0x00) -> 0x60 */
    if (i2c_write_reg8(fd, CTRL2_G, 0x60) < 0)
        return -1;

    return 0;
}

/* ---- Read accelerometer (6 bytes, little-endian) ---- */
static int read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUTX_L_XL, buf, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);

    /* ±2 g range -> 1 mg/LSB = 0.001 g/LSB */
    *x = (float)rx * 0.001f;
    *y = (float)ry * 0.001f;
    *z = (float)rz * 0.001f;
    return 0;
}

/* ---- Read gyroscope (6 bytes, little-endian) ---- */
static int read_gyro(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUTX_L_G, buf, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);

    /* ±250 dps range -> 8.75 mdps/LSB = 0.00875 dps/LSB */
    *x = (float)rx * 0.00875f;
    *y = (float)ry * 0.00875f;
    *z = (float)rz * 0.00875f;
    return 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

/* ---- Fall-detection state machine ---- */
typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} FallState;

static FallState g_state = IDLE;
static struct timespec g_freefall_ts = {0, 0};

static void process_fall(float ax, float ay, float az)
{
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    switch (g_state) {
    case IDLE:
        if (mag < FREEFALL_THRESHOLD) {
            g_state = FREEFALL;
            clock_gettime(CLOCK_MONOTONIC, &g_freefall_ts);
        }
        break;

    case FREEFALL:
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - g_freefall_ts.tv_sec)
                       + (now.tv_nsec - g_freefall_ts.tv_nsec) / 1e9;
        if (elapsed >= DETECTION_WINDOW) {
            g_state = IMPACT;
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s: IMPACT detected (mag=%.3f g)\n", ts, mag);
        }
        break;

    case IMPACT:
        /* Reset after impact */
        g_state = IDLE;
        break;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor */
    if (verify_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR not detected at 0x%02X\n", LSM6DSR_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (init_lsm6dsr(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to configure LSM6DSR\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("motion_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen motion_log.txt");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,gyro_x_dps,gyro_y_dps,gyro_z_dps,"
                          "accel_x_g,accel_y_g,accel_z_g,fall_state\n");
    }

    printf("LSM6DSR fall detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_gyro(g_i2c_fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_accel(g_i2c_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        process_fall(ax, ay, az);

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        fprintf(g_log_fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%d\n",
                ts, gx, gy, gz, ax, ay, az, g_state);
        fflush(g_log_fp);

        usleep(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

