#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0x03          /* mode 3: CPOL=1, CPHA=1 */
#define WHO_AM_I_REG   0x00
#define WHO_AM_I_VAL   0x0003
#define GYRO_XOUT_H    0x04
#define GYRO_XOUT_L    0x05
#define GYRO_YOUT_H    0x06
#define GYRO_YOUT_L    0x07
#define GYRO_ZOUT_H    0x08
#define GYRO_ZOUT_L    0x09
#define SCALE_FACTOR   0.0305f
#define LOG_FILE       "gyro_log.csv"
#define SAMPLE_US      10000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_read_register(int handle, uint8_t reg, uint16_t *value)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(int handle, uint8_t reg, uint16_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)(value & 0xFF) };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        return -1;
    }
    return 0;
}

static int verify_gyro(void)
{
    uint16_t id = 0;
    if (spi_read_register(g_spi_handle, WHO_AM_I_REG, &id) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                id, WHO_AM_I_VAL);
        return -1;
    }
    printf("ADIS16266 verified (WHO_AM_I = 0x%04X)\n", id);
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z)
{
    uint16_t x_raw, y_raw, z_raw;

    if (spi_read_register(g_spi_handle, GYRO_XOUT_H, &x_raw) != 0) return -1;
    if (spi_read_register(g_spi_handle, GYRO_YOUT_H, &y_raw) != 0) return -1;
    if (spi_read_register(g_spi_handle, GYRO_ZOUT_H, &z_raw) != 0) return -1;

    *x = ((int16_t)x_raw) * SCALE_FACTOR;
    *y = ((int16_t)y_raw) * SCALE_FACTOR;
    *z = ((int16_t)z_raw) * SCALE_FACTOR;
    return 0;
}

static int log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f\n",
                tbuf, ts.tv_nsec / 1000000L, x, y, z) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (verify_gyro() != 0) {
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Gyro_X, Gyro_Y, Gyro_Z\n");
        fflush(g_log_file);
    }

    printf("Logging gyro data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

