/*
 * GY-50 L3G4200D gyroscope logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   L3G4200D VCC  -> Pi 3V3  (pin 1)
 *   L3G4200D GND  -> Pi GND  (pin 6)
 *   L3G4200D SCL  -> Pi GPIO3 / SCL1 (pin 5)
 *   L3G4200D SDA  -> Pi GPIO2 / SDA1 (pin 3)
 *
 * I2C bus 1, address 0x68 (SA0 tied to GND).
 * Sensitivity: 8.75 mdps/LSB  ->  divide raw by 114.285714
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c -li2c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants ---- */
#define L3G4200D_ADDR        0x68
#define WHO_AM_I             0x0F
#define WHO_AM_I_EXPECTED    0xD3
#define CTRL_REG1            0x20
#define CTRL_REG4            0x23
#define OUT_X_L              0x28
#define OUT_X_H              0x29
#define OUT_Y_L              0x2A
#define OUT_Y_H              0x2B
#define OUT_Z_L              0x2C
#define OUT_Z_H              0x2D

#define I2C_BUS              "/dev/i2c-1"
#define LOG_FILE             "gyro_log.csv"
#define SAMPLE_PERIOD_US     10000   /* 10 ms */
#define MAX_RETRIES          3

/* Sensitivity: 8.75 mdps/LSB  ->  1 / 8.75 = 114.2857142857 */
#define GYRO_SENSITIVITY     114.2857142857f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register; returns 0 on success.    */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register; returns 0 on success.   */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success.   */
static int i2c_read_reg16(int fd, uint8_t reg_l, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg_l, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X) failed: %s\n",
                reg_l, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X) failed: %s\n",
                reg_l, strerror(errno));
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_gyro(void)
{
    int retries = 0;

    /* ---- Verify device identity ---- */
    uint8_t who;
    if (i2c_read_reg8(g_i2c_fd, WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_EXPECTED);
        return -1;
    }

    /* ---- Power on, enable all axes, ODR = 952 Hz ---- */
    if (i2c_write_reg8(g_i2c_fd, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1.\n");
        return -1;
    }

    /* ---- Enable block data update (BDU) so reads are always 2-byte ---- */
    if (i2c_write_reg8(g_i2c_fd, CTRL_REG4, 0x08) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro(float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(g_i2c_fd, OUT_X_L, &raw_x) != 0) return -1;
    if (i2c_read_reg16(g_i2c_fd, OUT_Y_L, &raw_y) != 0) return -1;
    if (i2c_read_reg16(g_i2c_fd, OUT_Z_L, &raw_z) != 0) return -1;

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
