#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME    "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and resources are     */
/* released cleanly.                                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and flush immediately.     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_event(FILE *file, int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(file, "%s – Flame detected: %s\n",
                timestamp, flame_detected ? "YES" : "NO") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* ---- Install SIGINT handler for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialization failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file in append mode ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl-C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);

        if (level == PI_BAD_GPIO) {
            fprintf(stderr, "gpioRead returned PI_BAD_GPIO for GPIO%d\n",
                    FLAME_SENSOR_GPIO);
            log_event(g_log_file, 0);
        } else if (level == 0) {
            /* Active-LOW: LOW => flame detected */
            printf("FLAME DETECTED!\n");
            if (log_event(g_log_file, 1) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            /* HIGH => no flame */
            if (log_event(g_log_file, 0) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Sleep 500 ms; gpioDelay is interruptible by signals */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

