#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_I2C_ADDR   0x68
#define SAMPLE_PERIOD  100000  /* microseconds (100 ms) */
#define LOG_FILE       "vibration_log.csv"

/* D7S-0001 register addresses (16-bit, big-endian on the bus) */
#define REG_X_LSB      0x00
#define REG_X_MSB      0x01
#define REG_Y_LSB      0x02
#define REG_Y_MSB      0x03
#define REG_Z_LSB      0x04
#define REG_Z_MSB      0x05

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a 16-bit big-endian value to a 16-bit register address. */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address. */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (uint8_t)(reg >> 8);
    reg_buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }

    uint8_t val_buf[2];
    ssize_t n = read(fd, val_buf, sizeof(val_buf));
    if (n != (ssize_t)sizeof(val_buf)) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X): expected 2 bytes, got %zd (%s)\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = ((uint16_t)val_buf[0] << 8) | val_buf[1];
    return 0;
}

/* Read acceleration data from the D7S-0001 sensor. */
static int read_d7s_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_raw, y_raw, z_raw;

    if (i2c_read_reg16(fd, REG_X_LSB, &x_raw) != 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_LSB, &y_raw) != 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_LSB, &z_raw) != 0) return -1;

    *x = (int16_t)x_raw;
    *y = (int16_t)y_raw;
    *z = (int16_t)z_raw;
    return 0;
}

/* Generate an ISO-8601 UTC timestamp string. */
static int get_timestamp(char *buf, size_t len)
{
