static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (uint8_t)(reg >> 8);
    reg_buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
