#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define HALL_SENSOR_1_PIN 17
#define HALL_SENSOR_2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_data(FILE *fp, int hall1_state, int hall2_state) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s.%03ld, Hall1: %d, Hall2: %d\n",
                timestamp, ts.tv_nsec / 1000000L, hall1_state, hall2_state) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *fp = NULL;
    int hall1_state = 0;
    int hall2_state = 0;
    int ret = EXIT_FAILURE;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HALL_SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_1_PIN);
        goto cleanup_gpio;
    }
    if (gpioSetMode(HALL_SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_2_PIN);
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(HALL_SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_1_PIN);
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(HALL_SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_2_PIN);
        goto cleanup_gpio;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        goto cleanup_gpio;
    }

    printf("Monitoring Hall sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           HALL_SENSOR_1_PIN, HALL_SENSOR_2_PIN);

    while (program_running) {
        hall1_state = gpioRead(HALL_SENSOR_1_PIN);
        if (hall1_state < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", HALL_SENSOR_1_PIN, strerror(errno));
            goto cleanup_all;
        }

        hall2_state = gpioRead(HALL_SENSOR_2_PIN);
        if (hall2_state < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", HALL_SENSOR_2_PIN, strerror(errno));
            goto cleanup_all;
        }

        if (log_data(fp, hall1_state, hall2_state) != 0) {
            fprintf(stderr, "Error logging data\n");
            goto cleanup_all;
        }

        if (hall1_state == 1 && hall2_state == 1) {
            printf("Conveyor halted!\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            perror("fclose");
        }
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

