#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define OUT_X_LSB      0x02
#define OUT_Y_MSB      0x03
#define OUT_Y_LSB      0x04
#define OUT_Z_MSB      0x05
#define OUT_Z_LSB      0x06
#define FALL_LOG_FILE  "fall_log.txt"
#define TILT_THRESHOLD 45.0
#define LOOP_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mma8452q_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    uint8_t ctrl = 0;
    if (i2c_read_reg8(fd, CTRL_REG1, &ctrl) < 0)
        return -1;

    /* Standby (clear ACTIVE bit) */
    if (i2c_write_reg8(fd, CTRL_REG1, ctrl & ~0x01) < 0)
        return -1;
    usleep(10000);

    /* 100 Hz data rate, active mode */
    if (i2c_write_reg8(fd, CTRL_REG1, (ctrl & ~0x0C) | 0x08) < 0)
        return -1;
    usleep(10000);

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calculate_tilt(int16_t x, int16_t y, int16_t z)
{
    double mag = sqrt((double)x * x + (double)y * y + (double)z * z);
    if (mag < 1.0)
        return 0.0;
    return atan2((double)y, (double)x) * 180.0 / M_PI;
}

static void log_fall(FILE *fp, int16_t x, int16_t y, int16_t z)
{
