/*
 * LIS3MDL magnetic field logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LIS3MDL SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   LIS3MDL SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   LIS3MDL VDD  -> 3.3 V
 *   LIS3MDL GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnetic_logger magnetic_logger.c
 *
 * The LIS3MDL is configured for continuous-conversion mode (CTRL_REG1
 * = 0x20) and high-resolution mode (CTRL_REG2 = 0x08).  The ±4 gauss
 * full-scale setting yields a sensitivity of 0.146 mG/LSB.  The
 * calibration constants (offset_mG, scale_mG) are applied after the
 * raw 16-bit two's-complement reads.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL constants (from datasheet) ---- */
#define LIS3MDL_ADDR        0x1E
#define LIS3MDL_CTRL_REG1   0x20
#define LIS3MDL_CTRL_REG2   0x21
#define LIS3MDL_OUT_X_L     0x28
#define LIS3MDL_OUT_X_H     0x29
#define LIS3MDL_OUT_Y_L     0x2A
#define LIS3MDL_OUT_Y_H     0x2B
#define LIS3MDL_OUT_Z_L     0x2C
#define LIS3MDL_OUT_Z_H     0x2D

/* ±4 gauss full-scale setting -> 0.146 mG/LSB */
#define SENSITIVITY_MG_LSB  0.146f

/* Metal-detector threshold (mG) */
#define METAL_THRESHOLD_MG  800.0f

/* ---- Calibration constants (replace with your calibrated values) ---- */
static const float offset_mG[3] = { 0.0f, 0.0f, 0.0f };
static const float scale_mG[3]  = { 1.0f, 1.0f, 1.0f };

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register; return 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register; return 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian two's-complement value from two registers. */
static int i2c_read_reg16_le(int fd, uint8_t reg_l, int16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg_l + 1, &hi) != 0)
        return -1;
    *out = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the LIS3MDL: continuous mode, high-resolution, ±4 gauss. */
static int lis3mdl_init(int fd)
{
    /* CTRL_REG1: temp enable (0x01) | continuous mode (0x00) = 0x01 */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG1, 0x01) != 0)
        return -1;

    /* CTRL_REG2: high-resolution mode (0x08) | ±4 gauss (0x00) = 0x08 */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG2, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all three axes and apply calibration.  Returns 0 on success. */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    int16_t raw[3];

    if (i2c_read_reg16_le(fd, LIS3MDL_OUT_X_L, &raw[0]) != 0)
        return -1;
    if (i2c_read_reg16_le(fd, LIS3MDL_OUT_Y_L, &raw[1]) != 0)
        return -1;
    if (i2c_read_reg16_le(fd, LIS3MDL_OUT_Z_L, &raw[2]) != 0)
        return -1;

    *x = (float)raw[0] * SENSITIVITY_MG_LSB * scale_mG[0] + offset_mG[0];
    *y = (float)raw[1] * SENSITIVITY_MG_LSB * scale_mG[1] + offset_mG[1];
    *z = (float)raw[2] * SENSITIVITY_MG_LSB * scale_mG[2] + offset_mG[2];
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
static void check_metal(float x, float y, float z)
{
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > METAL_THRESHOLD_MG) {
        fprintf(stderr,
                "ALERT: Metal detected! X=%.2f mG Y=%.2f mG Z=%.2f mG | "
                "mag=%.2f mG\n", x, y, z, mag);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor with retries ---- */
    int init_ok = 0;
    for (int attempt = 0; attempt < 3; ++attempt) {
        if (lis3mdl_init(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "LIS3MDL init attempt %d/%d failed; retrying in 1 s...\n",
                attempt + 1, 3);
        sleep(1);
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after 3 attempts.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open log file once ---- */
    g_log_fp = fopen("magnetic_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(magnetic_log.txt) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at 10 Hz. "
           "Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            check_metal(x, y, z);
        } else {
            fprintf(stderr, "Read error; continuing.\n");
        }

        /* 10 Hz -> 100 ms */
        usleep(100000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0)
            fprintf(stderr, "close(i2c) failed: %s\n", strerror(errno));
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

