#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

#define ADXL354B_REG_STATUS 0x00
#define ADXL354B_REG_PARTID 0x02
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_XDATA_H 0x08
#define ADXL354B_REG_XDATA_L 0x09
#define ADXL354B_REG_YDATA_H 0x0A
#define ADXL354B_REG_YDATA_L 0x0B
#define ADXL354B_REG_ZDATA_H 0x0C
#define ADXL354B_REG_ZDATA_L 0x0D

#define ADXL354B_PARTID 0x354B

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error (reg 0x%02X): returned %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error (reg 0x%02X): returned %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_read_burst(uint8_t reg, uint8_t *data, int len) {
    char tx[1 + len];
    char rx[1 + len];
    tx[0] = (char)(reg | 0xC0);
    memset(rx, 0, sizeof(rx));
    int result = spiXfer(spi_handle, tx, rx, 1 + len);
    if (result != (1 + len)) {
        fprintf(stderr, "SPI burst read error (reg 0x%02X, len %d): returned %d\n", reg, len, result);
        return -1;
    }
    memcpy(data, rx + 1, len);
    return 0;
}

static int adxl354b_reset(void) {
    if (spi_write_register(ADXL354B_REG_RESET, 0x56) != 0) return -1;
    gpioDelay(1000);
    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) return -1;
    gpioDelay(1000);
    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) return -1;
        if ((status & 0x01) != 0) break;
        gpioDelay(1000);
    }
    if ((status & 0x01) == 0) {
        fprintf(stderr, "ADXL354B STABLE bit not set after reset\n");
        return -1;
    }
    return 0;
}

static int adxl354b_init(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) return -1;
    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "Unexpected PARTID: 0x%04X (expected 0x%04X)\n", partid, ADXL354B_PARTID);
        return -1;
    }
    if (adxl354b_reset() != 0) return -1;
    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x01) != 0) return -1;
    return 0;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (spi_read_burst(ADXL354B_REG_XDATA_H, data, 6) != 0) return -1;
    *x = (int16_t)(((uint16_t)data[0] << 8) | data[1]);
    *y = (int16_t)(((uint16_t)data[2] << 8) | data[3]);
    *z = (int16_t)(((uint16_t)data[4] << 8) | data[5]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (adxl354b_init() != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int16_t x, y, z;
    while (running) {
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !success && running) {
            if (read_acceleration(&x, &y, &z) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(10000);
                }
            }
        }
        if (success) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

