#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses */
#define ADIS16362_REG_XGYRO_OUT  0x04
#define ADIS16362_REG_YGYRO_OUT  0x06
#define ADIS16362_REG_ZGYRO_OUT  0x08
#define ADIS16362_REG_XACCL_OUT  0x0A
#define ADIS16362_REG_YACCL_OUT  0x0C
#define ADIS16362_REG_ZACCL_OUT  0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE 0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x0000  /* Mode 0, active-low CE */

/* Sampling interval */
#define SAMPLE_DELAY_US 10000 /* 10 ms -> ~100 Hz */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362                           */
/* ------------------------------------------------------------------ */
static int read_register16(int handle, uint8_t reg, int16_t *value)
{
    char tx[2];
    char rx[2];

    /* Phase 1: send address with MSB set (read command) */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00; /* dummy byte to clock out data */

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read phase 1 failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Phase 2: send dummy address to clock out the data */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read phase 2 failed for reg 0x%02X\n", reg);
        return -1;
    }

    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six-axis data                                             */
/* ------------------------------------------------------------------ */
static int read_imu_data(int handle, float *gyro_x, float *gyro_y,
                         float *gyro_z, float *accel_x, float *accel_y,
                         float *accel_z)
{
    int16_t raw;

    if (read_register16(handle, ADIS16362_REG_XGYRO_OUT, &raw) != 0)
        return -1;
    *gyro_x = (float)raw * GYRO_SCALE;

    if (read_register16(handle, ADIS16362_REG_YGYRO_OUT, &raw) != 0)
        return -1;
