/*
 * KY-032 IR Obstacle Avoidance Sensor Poller
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (C API, version 2.0+)
 *
 * Wiring
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC         -> 3.3 V (physical pin 1)
 *   GND         -> GND  (physical pin 9)
 *
 * The KY-032 module has an active-low output: 0 = obstacle detected,
 * 1 = path clear.  pigpio reads the line level directly, so a logical
 * 0 on the GPIO line means an obstacle is present.
 *
 * Build:  gcc -Wall -Wextra -O2 -o ky032_poll ky032_poll.c -lpigpio -lrt
 * Run:    sudo ./ky032_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;
    char timestamp[32];

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs --- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Read both sensors together in one bulk call --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            fprintf(stderr,
                    "%s  Error: gpioRead failed (s1=%d, s2=%d).\n",
                    timestamp, s1, s2);
            break;
        }

        get_timestamp(timestamp, sizeof(timestamp));

        if (s1 == 0) {
            printf("%s  Sensor 1: Obstacle Detected (GPIO%d)\n",
                   timestamp, SENSOR_1_GPIO);
        } else {
            printf("%s  Sensor 1: Path Clear (GPIO%d)\n",
                   timestamp, SENSOR_1_GPIO);
        }

        if (s2 == 0) {
            printf("%s  Sensor 2: Obstacle Detected (GPIO%d)\n",
                   timestamp, SENSOR_2_GPIO);
        } else {
            printf("%s  Sensor 2: Path Clear (GPIO%d)\n",
                   timestamp, SENSOR_2_GPIO);
        }

        fflush(stdout);

        /* Sleep 100 ms; gpioDelay is interruptible by signals */
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

