/*
 * FXOS8700 accelerometer + magnetometer reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   FXOS8700 SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 register definitions (verified against Adafruit datasheet) ---- */
#define FXOS8700_ADDRESS        0x1E   /* SA0 tied to GND */
#define FXOS8700_ID             0x00
#define FXOS8700_ID_VALUE       0xC7   /* expected ID byte */
#define FXOS8700_STATUS         0x00
#define FXOS8700_OUT_X_MSB      0x01   /* 12-byte block: accel X/Y/Z (14-bit, left-aligned) */
#define FXOS8700_M_CTRL_REG1    0x0B
#define FXOS8700_M_CTRL_REG2    0x0C
#define FXOS8700_M_DATA_CFG     0x10
#define FXOS8700_M_DATA_X_MSB   0x11   /* 6-byte block: mag X/Y/Z (16-bit) */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X) short read: got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int init_fxos8700(int handle)
{
    uint8_t id = 0;

    /* 1. Verify device identity */
    if (i2c_read_reg(handle, FXOS8700_ID, &id, 1) != 0) {
        fprintf(stderr, "Cannot read FXOS8700 ID register.\n");
        return -1;
    }
    if (id != FXOS8700_ID_VALUE) {
        fprintf(stderr, "FXOS8700 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id, FXOS8700_ID_VALUE);
        return -1;
    }
    printf("FXOS8700 detected (ID = 0x%02X).\n", id);

    /* 2. Standby mode so we can configure registers */
    if (i2c_write_reg(handle, FXOS8700_STATUS, 0x00) != 0)
        return -1;

    /* 3. Configure magnetometer: OSR = 1 (12.5 Hz), gain = +/- 1.3 gauss */
    if (i2c_write_reg(handle, FXOS8700_M_CTRL_REG1, 0x1F) != 0)
        return -1;

    /* 4. Configure magnetometer data rate: 80 Hz ODR */
    if (i2c_write_reg(handle, FXOS8700_M_CTRL_REG2, 0x20) != 0)
        return -1;

    /* 5. Configure magnetometer data range (+/- 1.3 gauss) */
    if (i2c_write_reg(handle, FXOS8700_M_DATA_CFG, 0x00) != 0)
        return -1;

    /* 6. Enter active mode */
    if (i2c_write_reg(handle, FXOS8700_STATUS, 0x01) != 0)
        return -1;

    return 0;
}

/* ---- Read 12-byte combined block ---- */
static int read_combined_block(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                               int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t raw[12];

    if (i2c_read_reg(handle, FXOS8700_OUT_X_MSB, raw, sizeof(raw)) != 0)
        return -1;

    /* Accelerometer: 14-bit left-aligned, two's complement */
    *ax = (int16_t)(((raw[0] << 8) | raw[1]) >> 2) & 0x3FFF;
    if (*ax & 0x2000) *ax |= 0xC000;   /* sign-extend */
    *ay = (int16_t)(((raw[2] << 8) | raw[3]) >> 2) & 0x3FFF;
    if (*ay & 0x2000) *ay |= 0xC000;
    *az = (int16_t)(((raw[4] << 8) | raw[5]) >> 2) & 0x3FFF;
    if (*az & 0x2000) *az |= 0xC000;

    /* Magnetometer: 16-bit two's complement */
    *mx = (int16_t)((raw[6] << 8) | raw[7]);
    *my = (int16_t)((raw[8] << 8) | raw[9]);
    *mz = (int16_t)((raw[10] << 8) | raw[11]);

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                FXOS8700_ADDRESS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Reading FXOS8700 every 100 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_combined_block(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Mag: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; retrying next cycle.\n");
        }

        /* 100 ms delay (microseconds) */
        gpioDelay(100000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

