        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                FXOS8700_ADDRESS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Reading FXOS8700 every 100 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_combined_block(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Mag: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; retrying next cycle.\n");
        }

        /* 100 ms delay (microseconds) */
        gpioDelay(100000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

