#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_DEVID_VALUE 0xE5
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int adxl345_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int adxl345_init(int handle) {
    uint8_t devid = 0;
    if (adxl345_read_register(handle, ADXL345_REG_DEVID, &devid) != 0) {
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    if (adxl345_write_register(handle, ADXL345_REG_POWER_CTL, 0x00) != 0) return -1;
    if (adxl345_write_register(handle, ADXL345_REG_BW_RATE, 0x0A) != 0) return -1;
    if (adxl345_write_register(handle, ADXL345_REG_POWER_CTL, 0x08) != 0) return -1;

    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x / 256.0;
    *y = (float)raw_y / 256.0;
    *z = (float)raw_z / 256.0;
    return 0;
}

static float calculate_tilt_angle(float x, float y, float z) {
    float tilt_x = atan2f(x, sqrtf(y * y + z * z)) * 180.0 / M_PI;
    float tilt_y = atan2f(y, sqrtf(x * x + z * z)) * 180.0 / M_PI;
    return sqrtf(tilt_x * tilt_x + tilt_y * tilt_y);
}

static void log_tilt_event(float tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Tilt angle: %.2f degrees\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, tilt_angle);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z, tilt_angle;

    while (running) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            tilt_angle = calculate_tilt_angle(x, y, z);
            if (tilt_angle > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

