#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define WINDOW_SECONDS 5
#define SAMPLE_INTERVAL_US 1000
#define PAUSE_SECONDS 1
#define TIMESTAMP_LEN 32

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    if (time(&rawtime) == (time_t)-1) {
        perror("time");
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    return 0;
}

static int read_sensor(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(level));
        return -1;
    }
    return level;
}

static int count_high_readings(int pin, int duration_seconds) {
    int count = 0;
    int elapsed = 0;
    while (elapsed < duration_seconds && g_running) {
        int level = read_sensor(pin);
        if (level < 0) {
            return -1;
        }
        if (level == 1) {
            count++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
        elapsed += (SAMPLE_INTERVAL_US / 1000000);
    }
    return count;
}

static void print_status(const char *timestamp, int high_count, int threshold) {
    if (high_count > threshold) {
        printf("%s - ALERT: %d high readings exceed threshold %d\n",
               timestamp, high_count, threshold);
    } else {
        printf("%s - Status: %d high readings (threshold %d)\n",
               timestamp, high_count, threshold);
    }
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long threshold = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        return EXIT_FAILURE;
    }
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int high_count = count_high_readings(SENSOR_PIN, WINDOW_SECONDS);
        if (high_count < 0) {
            fprintf(stderr, "Sensor read error; aborting\n");
            break;
        }

        char timestamp[TIMESTAMP_LEN];
        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Timestamp error; aborting\n");
            break;
        }

        print_status(timestamp, high_count, (int)threshold);

        if (g_running) {
            sleep(PAUSE_SECONDS);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

