/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12 V electromagnetic door locks via TIP120-driven 5 V
 * active-HIGH relay modules on BCM GPIO17 (Door A) and BCM GPIO27 (Door B).
 *
 * Locks are energized (closed) when the GPIO line is LOW and de-energized
 * (unlocked) when the line is HIGH.  A successful entry generates a
 * random six-digit security code, logs it to access_log.txt, and prints
 * the code to stdout.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_A_LINE	17	/* BCM 17 */
#define GPIO_B_LINE	27	/* BCM 27 */
#define UNLOCK_DURATION_SEC	5
#define CODE_LEN		6
#define LOG_FILE		"access_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Returns a random six-digit code (100000..999999).                  */
static int generate_security_code(void)
{
    return (rand() % 900000) + 100000;
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on error.                                  */
static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, code) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on error.                                  */
static int unlock_door(struct gpiod_line *line, int duration_sec)
{
