#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char buf[2];
    int result;

    /* Send power-on command (0x01) */
    result = i2cWriteByte(handle, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error: I2C write (power-on) failed: %d\n", result);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONVERSION_TIME_MS * 1000);

    /* Send one-time high-resolution measurement command (0x10) */
    result = i2cWriteByte(handle, 0x10);
    if (result < 0) {
        fprintf(stderr, "Error: I2C write (measurement) failed: %d\n", result);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONVERSION_TIME_MS * 1000);

    /* Read 2 bytes of data */
    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes)\n", result);
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] << 8)) | (uint16_t)buf[1];
    *lux_out = (float)raw / 1.2f;

    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    int handle = -1;
    float lux = 0.0f;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: Failed to register SIGINT handler");
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_bh1750(handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data\n");
        }

        /* Sleep for the sample interval, checking running flag every second */
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    /* Clean up */
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

