/*
 * LSM303DLHC magnetometer reader with hardware PWM LED output.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (SDA1 = GPIO2, SCL1 = GPIO3)
 * Sensor: LSM303DLHC magnetometer (block read from 0x08)
 * LED:    GPIO17 (BCM) via hardware PWM
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303_pwm lsm303_pwm.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- LSM303DLHC magnetometer constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MAG_I2C_ADDR   0x08          /* LSM303DLHC mag data register pointer */
#define MAG_REG        0x08          /* first data register (X MSB) */
#define MAG_READ_LEN   6             /* X_MSB, X_LSB, Z_MSB, Z_LSB, ... */
#define SAMPLE_US      100000        /* 100 ms between samples */

/* ---- LED / PWM constants ---- */
#define LED_GPIO       17            /* BCM 17 */
#define PWM_RANGE      1000          /* 0-1000 duty cycle steps */
#define PWM_FREQ_HZ    1000          /* 1 kHz carrier */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(g_log_fp, "[unknown time] ERROR: %s\n", msg);
    }
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes from the LSM303DLHC magnetometer.
 * Returns 0 on success, -1 on I2C error. */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[MAG_READ_LEN];

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        log_error("I2C read failed (sensor absent or bus error)");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void set_led_brightness(int brightness)
{
    if (brightness < 0)   brightness = 0;
    if (brightness > 100) brightness = 100;

    int duty = (int)((brightness / 100.0) * PWM_RANGE);
    if (gpioPWM(LED_GPIO, duty) < 0) {
        log_error("gpioPWM failed");
    }
}

