    if (gpioInitialise() < 0) {
        log_error("gpioInitialise failed");
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        log_error("gpioSetMode failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        log_error("gpioSetPWMrange failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ_HZ) < 0) {
        log_error("gpioSetPWMfrequency failed");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(LED_GPIO, 0);   /* start dark */

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("open I2C bus failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MAG_I2C_ADDR) < 0) {
        log_error("ioctl I2C_SLAVE failed (sensor not present?)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            double magnitude = sqrt((double)x * x +
                                    (double)y * y +
                                    (double)z * z);
