/*
 * HMC5883L Magnetometer Offset Correction on Raspberry Pi Zero W
 *
 * Reads raw X/Y/Z data from the HMC5883L over I2C bus 1, maintains a
 * running average of the last 100 samples to compute hard-iron
 * offsets, applies the offsets to each new reading, and prints the
 * offset-corrected values every 500 ms.
 *
 * Wiring:
 *   HMC5883L VCC -> 3.3 V (Pin 1)
 *   HMC5883L GND -> GND   (Pin 6)
 *   HMC5883L SDA -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   HMC5883L SCL -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -o hmc5883l_offset hmc5883l_offset.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ---- HMC5883L register addresses ---- */
#define HMC5883L_CONFIG_A   0x00
#define HMC5883L_CONFIG_B   0x01
#define HMC5883L_MODE       0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

/* ---- I2C bus and address ---- */
#define I2C_BUS        1
#define HMC5883L_ADDR  0x1E

/* ---- Running average window ---- */
#define SAMPLE_WINDOW 100

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a single byte to an HMC5883L register ---- */
static int hmc5883l_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ---- Read a block of bytes starting at an HMC5883L register ---- */
static int hmc5883l_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %s\n",
                reg, len, strerror(errno));
    }
    return rc;
}

/* ---- Initialize the HMC5883L ---- */
static int hmc5883l_init(int handle)
{
    /* Configuration A: 8-average, 15 Hz output rate, normal measurement */
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_A, 0x70) < 0)
        return -1;

    /* Configuration B: Gain = 1.3 Ga (0x20) */
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_B, 0x20) < 0)
        return -1;

    /* Mode: Continuous measurement */
    if (hmc5883l_write_reg(handle, HMC5883L_MODE, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read raw X/Y/Z magnetic field data ---- */
static int hmc5883l_read_raw(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    /* Read 6 bytes starting at DATA_X_MSB (0x03):
     *   buf[0] = X MSB, buf[1] = X LSB
     *   buf[2] = Z MSB, buf[3] = Z LSB
     *   buf[4] = Y MSB, buf[5] = Y LSB
     */
    if (hmc5883l_read_block(handle, HMC5883L_DATA_X_MSB, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* ---- Running average over the last SAMPLE_WINDOW samples ---- */
typedef struct {
    int16_t x[SAMPLE_WINDOW];
    int16_t y[SAMPLE_WINDOW];
    int16_t z[SAMPLE_WINDOW];
    int    count;
    int    index;
} RunningAverage;

static void running_average_init(RunningAverage *ra)
{
    memset(ra, 0, sizeof(*ra));
}

static void running_average_add(RunningAverage *ra, int16_t x, int16_t y, int16_t z)
{
    ra->x[ra->index] = x;
    ra->y[ra->index] = y;
    ra->z[ra->index] = z;
    ra->index = (ra->index + 1) % SAMPLE_WINDOW;
    if (ra->count < SAMPLE_WINDOW)
        ra->count++;
}

static void running_average_get(RunningAverage *ra, int16_t *ox, int16_t *oy, int16_t *oz)
{
    if (ra->count == 0) {
        *ox = *oy = *oz = 0;
        return;
    }

    double sx = 0.0, sy = 0.0, sz = 0.0;
    for (int i = 0; i < ra->count; i++) {
        sx += ra->x[i];
        sy += ra->y[i];
        sz += ra->z[i];
    }

    *ox = (int16_t)(sx / ra->count);
    *oy = (int16_t)(sy / ra->count);
    *oz = (int16_t)(sz / ra->count);
}

/* ---- Main ---- */
int main(void)
{
    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HMC5883L address */
    g_i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, HMC5883L_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the magnetometer */
    if (hmc5883l_init(g_i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize running average */
    RunningAverage ra;
    running_average_init(&ra);

    printf("HMC5883L Offset Correction\n");
    printf("Sampling every 500 ms. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;

        if (hmc5883l_read_raw(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
            gpioDelay(500000);
            continue;
        }

        /* Accumulate for running average */
        running_average_add(&ra, x, y, z);

        /* Compute hard-iron offset from accumulated samples */
        int16_t ox, oy, oz;
        running_average_get(&ra, &ox, &oy, &oz);

        /* Apply offset to current reading */
        int16_t cx = x - ox;
        int16_t cy = y - oy;
        int16_t cz = z - oz;

        printf("X: %6d  Y: %6d  Z: %6d  |  Offsets: X: %6d  Y: %6d  Z: %6d\n",
               cx, cy, cz, ox, oy, oz);
        fflush(stdout);

        gpioDelay(500000); /* 500 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

