#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register definitions (verified against ST datasheet) ---- */
#define LSM303D_ACCEL_ADDR   0x19
#define LSM303D_MAG_ADDR     0x1E

#define LSM303D_WHO_AM_I     0x0F
#define LSM303D_WHO_AM_I_VAL 0x49

#define LSM303D_CTRL_REG1    0x20
#define LSM303D_CTRL_REG4    0x23
#define LSM303D_OUT_X_L_A    0x28
#define LSM303D_INT1_CFG     0x30
#define LSM303D_INT1_THS     0x31
#define LSM303D_INT1_DURATION 0x32

