/* INT1_THS: threshold 2000 mg (0x08 << 4) | 0x00 = 0x0800 */
#define LSM303D_INT1_THS_VAL 0x0800

/* INT1_DURATION: zero duration (0x00) */
#define LSM303D_INT1_DURATION_VAL 0x00

/* Sensitivity: 0.061 mg/LSB for 2 g full-scale */
#define LSM303D_SENSITIVITY  0.061f

/* ---- Application constants ---- */
#define I2C_BUS             "/dev/i2c-1"
#define GPIO_CHIP           "gpiochip4"   /* BCM GPIO 23 on Pi Zero W */
#define INT1_PIN            23            /* BCM 23, physical pin 16 */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000         /* 10 ms */
#define THRESHOLD_MG        2000.0f

/* ---- Data structures ---- */
typedef struct {
    float x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int               g_i2c_fd   = -1;
static struct gpiod_chip *g_chip     = NULL;
static struct gpiod_line *g_int_line = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  i2c_write_reg16(int fd, uint8_t reg, uint16_t val);
static int  i2c_read_reg16(int fd, uint8_t reg, uint16_t *val);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_accel(int fd, accel_data_t *out);
static int  init_lsm303d(int fd);
static void buffer_add(circular_buffer_t *buf, accel_data_t d);
static void buffer_dump(const circular_buffer_t *buf);
static void cleanup(void);
static void sigint_handler(int sig);

/* ---- I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write16 to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ---- LSM303D init ---- */
static int init_lsm303d(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, LSM303D_WHO_AM_I_VAL);
