        return -1;

    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, LSM303D_INT1_CFG_VAL) != 0)
        return -1;

    if (i2c_write_reg16(fd, LSM303D_INT1_THS, LSM303D_INT1_THS_VAL) != 0)
        return -1;

    if (i2c_write_reg8(fd, LSM303D_INT1_DURATION,
                       LSM303D_INT1_DURATION_VAL) != 0)
        return -1;

    return 0;
}

/* ---- Accelerometer read ---- */
static int i2c_read_accel(int fd, accel_data_t *out)
{
    uint16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A, &raw_x) != 0)
        return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A + 2, &raw_y) != 0)
        return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A + 4, &raw_z) != 0)
        return -1;

    out->x = ((int16_t)raw_x) * LSM303D_SENSITIVITY;
    out->y = ((int16_t)raw_y) * LSM303D_SENSITIVITY;
    out->z = ((int16_t)raw_z) * LSM303D_SENSITIVITY;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(circular_buffer_t *buf, accel_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_dump(const circular_buffer_t *buf)
{
    int start = (buf->count < 10) ? 0 : buf->head - 10;
    printf("Timestamp: %ld.%06ld\n",
           (long)time(NULL), (long)0);
    for (int i = 0; i < (buf->count < 10 ? buf->count : 10); i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  Sample %d: X=%.2f mg, Y=%.2f mg, Z=%.2f mg\n",
               i, buf->data[idx].x, buf->data[idx].y, buf->data[idx].z);
    }
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer (CTRL_REG1 = 0x00) */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int_line) {
        gpiod_line_release(g_int_line);
        g_int_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ACCEL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ACCEL_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm303d(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line as input with rising-edge events */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_int_line = gpiod_chip_get_line(g_chip, INT1_PIN);
    if (!g_int_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                INT1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                INT1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    circular_buffer_t buf = {0};

    printf("LSM303D monitoring started. Press Ctrl-C to exit.\n");

    while (g_running) {
        accel_data_t sample;
        if (i2c_read_accel(g_i2c_fd, &sample) != 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample.\n");
        } else {
            buffer_add(&buf, sample);
        }

        /* Poll for INT1 events */
        struct timespec ts = {0, 10000000}; /* 10 ms */
        int ret = gpiod_line_event_wait(g_int_line, &ts);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait error: %s\n",
                    strerror(errno));
            break;
        }
        if (ret == 1) {
            struct gpiod_line_event ev;
            if (gpiod_line_event_read(g_int_line, &ev) == 0) {
                if (ev.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    buffer_dump(&buf);
                }
            }
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

