#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1 17
#define SOLENOID_2 27
#define DELAY_MS   500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            return;
        }
    }
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d LOW\n", SOLENOID_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_2, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d LOW\n", SOLENOID_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active = SOLENOID_1;

    while (g_running) {
        if (gpioWrite(active, 1) != 0) {
            fprintf(stderr, "Failed to energise GPIO%d\n", active);
            break;
        }
        sleep_ms(DELAY_MS);

        if (!g_running)
            break;

        if (gpioWrite(active, 0) != 0) {
            fprintf(stderr, "Failed to de-energise GPIO%d\n", active);
            break;
        }
        sleep_ms(DELAY_MS);

        active = (active == SOLENOID_1) ? SOLENOID_2 : SOLENOID_1;
    }

    /* Clean shutdown: ensure both solenoids are de-energised */
    gpioWrite(SOLENOID_1, 0);
    gpioWrite(SOLENOID_2, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

