#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define READ_TIMEOUT_SEC 5
#define LOCK_HOLD_SEC 2

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_uart(const char *device) {
    int handle = serOpen((char *)device, 9600, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: failed to open UART %s (code %d).\n", device, handle);
        return -1;
    }
    return handle;
}

static int read_code(int handle, char *code, int max_len) {
    int i;
    for (i = 0; i < max_len; i++) {
        int c = serRead(handle, 1);
        if (c < 0) {
            fprintf(stderr, "Error: serRead failed on handle %d (code %d).\n", handle, c);
            return -1;
        }
        if (c == 0) {
            return 0; /* timeout */
        }
        if (c != (int)(unsigned char)code[i]) {
            fprintf(stderr, "Error: unexpected byte 0x%02X on handle %d.\n", (unsigned char)c, handle);
            return -1;
        }
    }
    return i;
}

static int read_code_nonblocking(int handle, char *code, int max_len) {
    int i;
    for (i = 0; i < max_len; i++) {
        int c = serRead(handle, 1);
        if (c < 0) {
            fprintf(stderr, "Error: serRead failed on handle %d (code %d).\n", handle, c);
            return -1;
        }
        if (c == 0) {
            return 0; /* timeout */
        }
        if ((unsigned char)c < '0' || (unsigned char)c > '9') {
            fprintf(stderr, "Warning: non-digit byte 0x%02X received on handle %d; resetting buffer.\n", (unsigned char)c, handle);
            return 0;
        }
        code[i] = (char)c;
    }
    return i;
}

static int read_code_full(int handle, char *code, int max_len) {
    int i;
    for (i = 0; i < max_len; i++) {
        int c = serRead(handle, 1);
        if (c < 0) {
            fprintf(stderr, "Error: serRead failed on handle %d (code %d).\n", handle, c);
            return -1;
        }
        if (c == 0) {
            return 0; /* timeout */
        }
        if ((unsigned char)c < '0' || (unsigned char)c > '9') {
            fprintf(stderr, "Warning: non-digit byte 0x%02X received on handle %d; resetting buffer.\n", (unsigned char)c, handle);
            return 0;
        }
        code[i] = (char)c;
    }
    return i;
}

static int codes_match(const char *a, const char *b) {
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (a[i] != b[i]) {
            return 0;
        }
    }
    return 1;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Doors unlocked for %d seconds.\n", LOCK_HOLD_SEC);
    time_sleep(LOCK_HOLD_SEC);
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LOCK2_GPIO);
        return -1;
    }
    printf("Doors locked.\n");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int handle1 = init_uart("/dev/serial0");
    if (handle1 < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = init_uart("/dev/serial1");
    if (handle2 < 0) {
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];
    code1[CODE_LENGTH] = '\0';
    code2[CODE_LENGTH] = '\0';

    printf("Dual-factor door lock system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int r1 = read_code_nonblocking(handle1, code1, CODE_LENGTH);
        int r2 = read_code_nonblocking(handle2, code2, CODE_LENGTH);

        if (r1 == 0) {
            fprintf(stderr, "Warning: timeout reading from handle %d.\n", handle1);
        }
        if (r2 == 0) {
            fprintf(stderr, "Warning: timeout reading from handle %d.\n", handle2);
        }

        if (r1 > 0 && r2 > 0) {
            if (codes_match(code1, code2)) {
                if (codes_match(code1, EXPECTED_CODE)) {
                    printf("Authentication successful. Codes match expected code.\n");
                    if (unlock_doors() != 0) {
                        fprintf(stderr, "Error: unlock_doors() failed.\n");
                    }
                } else {
                    fprintf(stderr, "Error: codes do not match expected code.\n");
                }
            } else {
                fprintf(stderr, "Error: codes do not match each other.\n");
            }
            code1[0] = '\0';
            code2[0] = '\0';
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    serClose(handle1);
    serClose(handle2);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

