/*
 * PIR-triggered door-strike relay controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor  -> GPIO4  (physical pin 7, input)
 *   - Door-strike relay    -> GPIO17 (physical pin 11, output)
 *
 * Behavior:
 *   Polls the PIR sensor every 50 ms.  On a HIGH reading, logs the event,
 *   energizes the relay for 1 s, and logs the relay on/off transitions.
 *   If the PIR stays HIGH for more than 10 s the relay is de-energized,
 *   a WARNING is logged describing a potential malfunction, and a
 *   shutdown event is logged.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_relay pir_relay.c -lgpiod
 *
 * Run:
 *   sudo ./pir_relay   (root needed for syslog and /dev/gpiochip0)
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#define PIR_LINE_OFFSET      4   /* GPIO4  */
#define RELAY_LINE_OFFSET    17  /* GPIO17 */
#define POLL_INTERVAL_MS     50
#define RELAY_ON_DURATION_S  1
#define PIR_TIMEOUT_S        10
#define LOG_FILE             "/var/log/pir_relay.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    syslog(LOG_INFO, "[%s] %s", ts, message);
}

/* ------------------------------------------------------------------ */
int main(void)
{
