#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON 0
#define RELAY_OFF 1

#define CYCLE_DURATION 300
#define PAUSE_DURATION 60
#define TIMER_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

static int set_relay(int pin, int state) {
    int rc = gpioWrite(pin, state);
    if (rc != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to set relay on GPIO %d to %d (rc=%d)", pin, state, rc);
        syslog(LOG_ERR, "%s", msg);
        return -1;
    }
    return 0;
}

static void activate_relay(int pin, int duration) {
    if (set_relay(pin, RELAY_ON) != 0) return;
    log_message("Relay activated");
    gpioDelay(duration * 1000000);
    if (set_relay(pin, RELAY_OFF) != 0) return;
    log_message("Relay deactivated");
    gpioDelay(PAUSE_DURATION * 1000000);
}

static void timer_callback(void *user_data) {
    (void)user_data;
    static int relay_index = 0;
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    activate_relay(pins[relay_index], CYCLE_DURATION);
    relay_index = (relay_index + 1) % 4;
}

static void cleanup(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], RELAY_OFF);
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    log_message("Irrigation system starting");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
        if (gpioWrite(pins[i], RELAY_OFF) != 0) {
            log_message("Failed to initialize relay pins to OFF");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetTimerFunc(0, TIMER_INTERVAL, timer_callback) != 0) {
        log_message("Failed to set up timer");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Irrigation system running");

    while (running) {
        sleep(1);
    }

    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

