#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG 0x1A

#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

#define I2C_BUS "/dev/i2c-1"
#define DRIVER_PATH "/sys/kernel/mpu6050_accel/latest"

typedef struct {
    int16_t x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static circular_buffer_t buffer;
static struct sigaction sa;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, MPU6050_SMPLRT_DIV, 0x07) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_GYRO_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void buffer_add(circular_buffer_t *buf, accel_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
}

static int write_to_driver(accel_data_t data) {
    char path[256];
    snprintf(path, sizeof(path), "%s/x", DRIVER_PATH);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d\n", data.x);
    fclose(fp);

    snprintf(path, sizeof(path), "%s/y", DRIVER_PATH);
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d\n", data.y);
    fclose(fp);

    snprintf(path, sizeof(path), "%s/z", DRIVER_PATH);
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d\n", data.z);
    fclose(fp);
    return 0;
}

static void timer_handler(union sigval sv) {
    (void)sv;
    accel_data_t data;
    if (read_accel_data(i2c_fd, &data) == 0) {
        buffer_add(&buffer, data);
        write_to_driver(data);
    }
}

static struct sigevent sev = {0};
static timer_t timer_id;

int main(void) {
    struct sigaction sa_old;
    struct itimerspec its;
    struct sigevent sev_old;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, &sa_old) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, &sa_old) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    memset(&buffer, 0, sizeof(buffer));

    sev.sigev_notify = SIGEV_SIGNAL;
