#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME  "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int relay_seconds[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_relay(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(struct gpiod_line *lines[], int num_lines)
{
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            (void)set_relay(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    struct timespec next_time;
    struct timespec now;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "relay-toggle", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &next_time) != 0) {
        perror("clock_gettime");
        goto cleanup;
    }

    while (program_running) {
        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            perror("clock_gettime");
            break;
        }

        if (now.tv_sec > next_time.tv_sec ||
            (now.tv_sec == next_time.tv_sec && now.tv_nsec >= next_time.tv_nsec)) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                int current_value = gpiod_line_get_value(lines[i]);
                if (current_value < 0) {
                    fprintf(stderr, "Error reading GPIO line %u: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                int new_value = (current_value == 0) ? 1 : 0;
                if (set_relay(lines[i], new_value) != 0) {
                    goto cleanup;
                }
                next_time.tv_sec += relay_seconds[i];
            }
        } else {
            struct timespec sleep_time;
            sleep_time.tv_sec = next_time.tv_sec - now.tv_sec;
            sleep_time.tv_nsec = next_time.tv_nsec - now.tv_nsec;
            if (sleep_time.tv_nsec < 0) {
                sleep_time.tv_sec--;
                sleep_time.tv_nsec += 1000000000L;
            }
            if (sleep_time.tv_sec < 0 || sleep_time.tv_nsec < 0) {
                break;
            }
            if (nanosleep(&sleep_time, NULL) != 0) {
                if (errno == EINTR) {
                    continue;
                }
                perror("nanosleep");
                break;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup(lines, NUM_RELAYS);
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

