#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define LOG_FILE "alarm_log.txt"
#define POLL_INTERVAL_US 100000
#define RELAY_ACTIVE_MS 3000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s: %s\n", timestamp, message);
    } else {
        fprintf(fp, "(unknown time): %s\n", message);
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_relay(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error activating relay on GPIO %d\n", pin);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error deactivating relay on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing relay state on GPIO %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound-activated relay system started. Press Ctrl+C to exit.\n");

    int last_state = 0;
    int relay_active = 0;

    while (running) {
        int current_state = gpioRead(SOUND_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (current_state == 1 && last_state == 0) {
            if (!relay_active) {
                printf("Sound detected! Activating relay.\n");
                if (activate_relay(RELAY_PIN, RELAY_ACTIVE_MS) == 0) {
                    relay_active = 1;
                    if (log_event("Sound detected, relay activated") != 0) {
                        fprintf(stderr, "Error logging event.\n");
                    }
                } else {
                    fprintf(stderr, "Error activating relay.\n");
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

