#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_CONFIG 0x1B
#define GYRO_SCALE 131.0
#define BUFFER_SIZE 100
#define THRESHOLD 50.0
#define SAMPLE_DELAY_US 10000

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;
    return 0;
}

static void buffer_add(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) buffer->count++;
    if (buffer->count == BUFFER_SIZE) buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
}

static void buffer_get_latest(circular_buffer_t *buffer, gyro_data_t *data) {
    if (buffer->count == 0) {
        memset(data, 0, sizeof(gyro_data_t));
        return;
    }
    int index = (buffer->tail + buffer->count - 1) % BUFFER_SIZE;
    *data = buffer->data[index];
}

static float calculate_magnitude(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

static void threshold_exceeded(float magnitude) {
    printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    circular_buffer_t buffer = {0};
    gyro_data_t latest_data = {0};

    printf("MPU6050 gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        buffer_add(&buffer, gyro_data);
        buffer_get_latest(&buffer, &latest_data);

        float magnitude = calculate_magnitude(latest_data);
        if (magnitude > THRESHOLD) {
            threshold_exceeded(magnitude);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

