#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/time.h>
#include <sys/select.h>
#include <stdint.h>
#include <stdbool.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define SAMPLE_INTERVAL_SEC 5
#define RESPONSE_TIMEOUT_SEC 1
#define RESPONSE_SIZE 9
#define READ_DELAY_MS 100
#define MAX_RETRIES 10

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timeval tv;
    struct tm tm_info;
    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    if (pos + 8 < len) {
        snprintf(buf + pos, len - pos, ".%06ldZ", (long)tv.tv_usec);
    }
}

static void log_error(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (error_fp) {
        fprintf(error_fp, "%s: %s (errno: %s)\n", ts, msg, strerror(errno));
        fflush(error_fp);
    }
    fprintf(stderr, "%s: %s (errno: %s)\n", ts, msg, strerror(errno));
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        log_error("Failed to open UART device");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr failed");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);

    tty.c_oflag = 0;

    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr failed");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len, int timeout_sec) {
    size_t total = 0;
    while (total < len) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv;
        tv.tv_sec = timeout_sec;
        tv.tv_usec = 0;

        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue;
            log_error("select failed");
            return -1;
        }
        if (rv == 0) {
            log_error("Timeout waiting for UART data");
            return -1;
        }

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            log_error("read failed");
            return -1;
        }
        if (n == 0) {
            log_error("UART read returned 0 (device disconnected?)");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_co2(int fd, int *co2_ppm) {
    uint8_t cmd[9] = {0x78, 0x39, 0x0A, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t resp[9];

    if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        log_error("Failed to write MH-Z19B command");
        return -1;
    }

    usleep(READ_DELAY_MS * 1000);

    if (read_exact(fd, resp, sizeof(resp), RESPONSE_TIMEOUT_SEC) != 0) {
        return -1;
    }

    if (resp[0] != 0x78 || resp[1] != 0x39) {
        log_error("Invalid response header");
        return -1;
    }

    uint16_t raw = ((uint16_t)resp[2] << 8) | resp[3];
    uint8_t checksum = resp[8];
    uint8_t calc = (uint8_t)(resp[2] + resp[3] + resp[4] + resp[5] + resp[6] + resp[7]);

    if (calc != checksum) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Checksum mismatch: calc=0x%02X, recv=0x%02X", calc, checksum);
        log_error(msg);
        return -1;
    }

    if (raw == 0xFFFF) {
        log_error("Sensor reported error (0xFFFF)");
        return -1;
    }

    *co2_ppm = (int)raw;
    return 0;
}

static void log_data(int co2_ppm, bool error_flag) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (log_fp) {
        fprintf(log_fp, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %s}\n",
                ts, co2_ppm, error_flag ? "true" : "false");
        fflush(log_fp);
    }

    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %s}\n",
           ts, co2_ppm, error_flag ? "true" : "false");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        log_error("Failed to open log file");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_fp) {
        log_error("Failed to open error log file");
        fclose(log_fp);
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int co2_ppm = -1;
        bool error_flag = false;

        if (read_co2(uart_fd, &co2_ppm) == 0) {
            log_data(co2_ppm, false);
        } else {
            error_flag = true;
            log_data(0, true);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (log_fp) fclose(log_fp);
    if (error_fp) fclose(error_fp);
    if (uart_fd >= 0) close(uart_fd);

    return EXIT_SUCCESS;
}

