#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define HARD_IRON_X 100.0
#define HARD_IRON_Y -50.0
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0

#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

typedef struct {
    float heading;
    struct timespec timestamp;
} CircularBufferEntry;

static CircularBufferEntry circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

static int initialize_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error: Failed to write to HMC5883L config A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to write to HMC5883L config B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to HMC5883L mode\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int16_t *x, int16_t *y) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

static float apply_hard_iron_compensation(float heading) {
    return heading - HARD_IRON_X + HARD_IRON_Y;
}

static void add_to_circular_buffer(float heading) {
    circular_buffer[buffer_index].heading = heading;
    clock_gettime(CLOCK_REALTIME, &circular_buffer[buffer_index].timestamp);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static float get_average_heading(void) {
    if (buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += circular_buffer[i].heading;
    }
    return sum / (float)buffer_count;
}

static void control_gpio(float heading) {
    float average_heading = get_average_heading();
    float deviation = fabsf(heading - average_heading);
    if (deviation > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_hmc5883l() != 0) {
        fprintf(stderr, "Error: HMC5883L initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y;
    float heading;

    while (running) {
        if (read_magnetometer_data(&x, &y) == 0) {
            heading = calculate_heading(x, y);
            heading = apply_hard_iron_compensation(heading);
            add_to_circular_buffer(heading);
            control_gpio(heading);
        } else {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

