#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22
#define LOG_FILE "lighting_log.txt"
#define CONVERSION_DELAY_US 120000
#define LOOP_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to write power-on command to BH1750 (handle %d): %s\n",
                handle, strerror(errno));
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 (handle %d): %s\n",
                handle, bytes < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_lamp(float lux) {
    if (lux < 50.0f) {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux < 150.0f) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux < 300.0f) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 1);
    } else {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 1);
    }
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f\n", timestamp, lux);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            control_lamp(lux);
            log_data(log_file, lux);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
            gpioWrite(RED_PIN, 0);
            gpioWrite(GREEN_PIN, 0);
            gpioWrite(BLUE_PIN, 0);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

