/*
 * Door lock/unlock controller using a 28BYJ-48 stepper motor and an L293D
 * H-bridge driver on a Raspberry Pi.
 *
 * Wiring (BCM numbering):
 *   GPIO17 -> L293D IN1
 *   GPIO18 -> L293D IN2
 *   GPIO27 -> L293D IN3
 *   GPIO22 -> L293D IN4
 *   GPIO24 -> LOCK button (active-LOW with internal pull-up)
 *   GPIO23 -> UNLOCK button (active-LOW with internal pull-up)
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define LOCK_BTN 24
#define UNLOCK_BTN 23

/* ---- Motor parameters ---- */
#define STEPS_PER_REV 512          /* 28BYJ-48 full-step sequence */
#define STEP_DELAY_US 2000         /* 2 ms between half-steps */
#define HALF_STEPS_PER_REV 2048    /* 512 * 4 (full-step two-phase) */

/* ---- Full-step two-phase drive sequence (4 states) ---- */
static const int step_seq[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* De-energize all four motor coils.                                    */
static void motor_off(void)
{
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

/* ------------------------------------------------------------------ */
/* Drive one full-step (two half-steps) in the given direction.        */
/* dir = +1 -> clockwise, -1 -> counter-clockwise.                      */
static void step_motor(int dir)
{
    static int phase = 0;
    static int last_phase = -1;

    if (dir == 0)
        return;

    if (dir == 1) {
        phase = (phase + 1) % 4;
    } else {
        phase = (phase + 3) % 4;   /* equivalent to phase - 1 mod 4 */
    }

    if (phase == last_phase)
        return;                    /* prevent spurious re-trigger */

    last_phase = phase;

    gpioWrite(IN1, step_seq[phase][0]);
    gpioWrite(IN2, step_seq[phase][1]);
    gpioWrite(IN3, step_seq[phase][2]);
    gpioWrite(IN4, step_seq[phase][3]);

    gpioDelay(STEP_DELAY_US);
}

/* ------------------------------------------------------------------ */
/* Rotate the motor a given number of half-steps in the given direction.*/
static void rotate(int half_steps, int dir)
{
    for (int i = 0; i < half_steps && g_running; i++)
        step_motor(dir);
}

/* ------------------------------------------------------------------ */
/* Lock the door: rotate clockwise (512 full-steps = 1/4 turn).        */
static void lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    rotate(STEPS_PER_REV, 1);
    printf("Door locked.\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Unlock the door: rotate counter-clockwise (512 full-steps).         */
static void unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    rotate(STEPS_PER_REV, -1);
    printf("Door unlocked.\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as an input with an internal pull-up.          */
static int setup_input(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize all GPIO pins for motor and button control.              */
static int initialize_gpio(void)
{
    int pins[] = {IN1, IN2, IN3, IN4, LOCK_BTN, UNLOCK_BTN};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (setup_input(pins[i]) < 0)
            return -1;
    }

    /* Motor pins are driven HIGH/LOW; no pull-up/down needed. */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for motor pin %d\n", pins[i]);
            return -1;
        }
    }

    /* Start with coils de-energized. */
    motor_off();
    return 0;
}

/* ------------------------------------------------------------------ */
/* Release all GPIO resources.                                         */
static void cleanup_gpio(void)
{
    if (g_pigpio_initialized) {
        motor_off();
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* Configure GPIO pins. */
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Door lock controller ready. Press LOCK or UNLOCK buttons.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main event loop ---- */
    while (g_running) {
        if (!g_running)
            break;

        /* Check LOCK button (active-LOW: 0 = pressed). */
        if (gpioRead(LOCK_BTN) == 0) {
            lock_door();
            /* Wait for button release to prevent re-triggering. */
            while (g_running && gpioRead(LOCK_BTN) == 0)
                gpioDelay(10000);   /* 10 ms poll interval */
        }

        if (!g_running)
            break;

        /* Check UNLOCK button (active-LOW: 0 = pressed). */
        if (gpioRead(UNLOCK_BTN) == 0) {
            unlock_door();
            /* Wait for button release. */
            while (g_running && gpioRead(UNLOCK_BTN) == 0)
                gpioDelay(10000);
        }

        gpioDelay(10000);  /* 10 ms idle poll to reduce CPU usage. */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fflush(stdout);
    cleanup_gpio();
    printf("Door lock controller terminated.\n");
    return EXIT_SUCCESS;
}

