#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_DUTY_MAX 18000000
#define PWM_DUTY_MIN 2000000
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int init_mpu6050(int fd) {
    uint8_t whoami;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x68, got 0x%02X\n", whoami);
        return -1;
    }
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

void calc_angles(int16_t ax, int16_t ay, int16_t az, float *pitch, float *roll) {
    float fx = (float)ax / 16384.0f;
    float fy = (float)ay / 16384.0f;
    float fz = (float)az / 16384.0f;
    *roll = atan2f(fy, fz) * 180.0f / M_PI;
    *pitch = atan2f(-fx, sqrtf(fy * fy + fz * fz)) * 180.0f / M_PI;
}

int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int duty = PWM_DUTY_MIN + (int)(((float)angle / 180.0f) * (PWM_DUTY_MAX - PWM_DUTY_MIN));
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *p = fopen(path, "r");
    if (!p) { fprintf(stderr, "Failed to read PWM period: %s\n", strerror(errno)); return -1; }
    int period = atoi(fgets(path, sizeof(path), p));
    fclose(p);
    if (period <= 0) { fprintf(stderr, "Invalid PWM period: %d\n", period); return -1; }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    p = fopen(path, "w");
    if (!p) { fprintf(stderr, "Failed to write duty cycle: %s\n", strerror(errno)); return -1; }
    fprintf(p, "%d", duty);
    fclose(p);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    p = fopen(path, "w");
    if (!p) { fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno)); return -1; }
    fprintf(p, "1");
    fclose(p);
    return 0;
}

int log_data(float pitch, float roll, int angle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, angle);
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = init_i2c();
    if (i2c_fd < 0) return 1;
    if (init_mpu6050(i2c_fd) < 0) { close(i2c_fd); return 1; }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) { fprintf(stderr, "Failed to open log file: %s\n", strerror(errno)); close(i2c_fd); return 1; }

    int16_t ax, ay, az;
    float pitch, roll;
    int angle;
    int retries = 0;

    while (running) {
        if (read_accel(i2c_fd, &ax, &ay, &az) < 0) {
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        retries = 0;
        calc_angles(ax, ay, az, &pitch, &roll);
        angle = (int)(pitch + 90.0f);
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Failed to set servo angle.\n");
        }
        log_data(pitch, roll, angle);
        usleep(100000);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    return 0;
}

