#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int parse_schedule_line(const char *line, int *relay, int *state, int *duration) {
    char time_str[8];
    char rest[256];
    char *saveptr = NULL;

    if (sscanf(line, "%7s %d %d %d%n", time_str, relay, state, duration, &rest[0]) != 4) {
        return -1;
    }
    if (strlen(time_str) != 8) {
        return -1;
    }
    if (*relay < 0 || *relay >= NUM_RELAYS) {
        return -1;
    }
    if (*state != 0 && *state != 1) {
        return -1;
    }
    if (*duration < 0 || *duration > FADE_DURATION) {
        return -1;
    }
    return 0;
}

static int set_relay_state(int relay, int state) {
    if (relay < 0 || relay >= NUM_RELAYS) {
        return -1;
    }
    if (gpioPWM(relay_pins[relay], state ? PWM_RANGE : 0) < 0) {
        return -1;
    }
    return 0;
}

static int fade_relay(int relay, int target_state, int duration) {
    if (relay < 0 || relay >= NUM_RELAYS) {
        return -1;
    }
    if (target_state != 0 && target_state != 1) {
        return -1;
    }
    if (duration <= 0 || duration > FADE_DURATION) {
        return -1;
    }

    int current_state = gpioRead(relay_pins[relay]);
    if (current_state < 0) {
        return -1;
    }

    if (current_state == target_state) {
        return 0;
    }

    int step_delay = (duration * 1000) / FADE_DURATION;
    if (step_delay < 1) {
        step_delay = 1;
    }

    int step = (target_state == 1) ? 1 : -1;
    int duty = (target_state == 1) ? 0 : PWM_RANGE;

    while (program_running) {
        if (gpioPWM(relay_pins[relay], duty) < 0) {
            return -1;
        }
        time_sleep(step_delay / 1000.0);
        duty += step;
        if (duty >= PWM_RANGE) {
            duty = PWM_RANGE;
            break;
        }
        if (duty <= 0) {
            duty = 0;
            break;
        }
    }

    if (set_relay_state(relay, target_state) < 0) {
        return -1;
    }
    return 0;
}

static int load_schedule(FILE *fp, int *schedule, int *schedule_size) {
    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        line[strcspn(line, "\n")] = '\0';
        int relay, state, duration;
        if (parse_schedule_line(line, &relay, &state, &duration) == 0) {
            if (relay >= 0 && relay < NUM_RELAYS) {
                schedule[count].relay = relay;
                schedule[count].state = state;
                schedule[count].duration = duration;
                count++;
            }
        }
    }
    if (ferror(fp)) {
        return -1;
    }
    *schedule_size = count;
    return 0;
}

static int apply_schedule(int *schedule, int schedule_size) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }
    struct tm *tm_info = localtime(&now);
    if (tm_info == NULL) {
        return -1;
    }

    int current_relay_state[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        current_relay_state[i] = gpioRead(relay_pins[i]);
        if (current_relay_state[i] < 0) {
            return -1;
        }
    }

    for (int i = 0; i < schedule_size; i++) {
        int relay = schedule[i].relay;
        int state = schedule[i].state;
        int duration = schedule[i].duration;

        if (current_relay_state[relay] == state) {
            continue;
        }

        if (fade_relay(relay, state, duration) < 0) {
            return -1;
        }
        current_relay_state[relay] = state;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Error: Failed to initialize PWM on GPIO %d.\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set up signal handlers.\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpioPWM(relay_pins[i], 0);
        }
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int schedule[100];
