    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open schedule file '%s'.\n", SCHEDULE_FILE);
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpioPWM(relay_pins[i], 0);
        }
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (load_schedule(fp, schedule, &schedule_size) < 0) {
        fprintf(stderr, "Error: Failed to load schedule from '%s'.\n", SCHEDULE_FILE);
        fclose(fp);
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpioPWM(relay_pins[i], 0);
        }
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: Error closing schedule file.\n");
    }

    while (program_running) {
        if (apply_schedule(schedule, schedule_size) < 0) {
            fprintf(stderr, "Error: Failed to apply schedule.\n");
        }
        time_sleep(1.0);
    }

