#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQUENCY 20
#define MAX_FREQUENCY 20000
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  400.0

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define LOOP_DELAY_US    20000
#define MEASURE_DELAY_US 60000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin low.\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize buzzer pin low.\n");
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set trigger high.\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set trigger low.\n");
    }
}

static uint32_t measure_echo_us(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return 0;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return 0;
        }
    }
    end_tick = gpioTick();

    return end_tick - start_tick;
}

static float calculate_distance(uint32_t echo_us) {
    if (echo_us == 0) {
        return -1.0f;
    }
    return (float)echo_us / 58.0f;
}

static int map_distance_to_frequency(float distance) {
    if (distance < 0.0f) {
        return -1;
    }
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    }
    if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    float freq = (MAX_FREQUENCY - MIN_FREQUENCY) * (1.0f - (distance / MAX_DISTANCE)) + MIN_FREQUENCY;
    return (int)freq;
}

static void set_buzzer_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: frequency %d out of range [%d, %d].\n",
                frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        return;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency to %d Hz.\n", frequency);
        return;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
    }
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();
        uint32_t echo_us = measure_echo_us();

        float distance = calculate_distance(echo_us);
        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor read timeout or missing sensor.\n");
        } else {
            int frequency = map_distance_to_frequency(distance);
            if (frequency < 0) {
                fprintf(stderr, "Error: invalid distance mapping.\n");
            } else {
                set_buzzer_frequency(frequency);
            }
        }

        gpioDelay(MEASURE_DELAY_US);
    }

    cleanup();
    printf("Theremin stopped.\n");
    return 0;
}

