        int g = (int)((1.0 - prox) * 255.0);
        int b = 0;

        if (set_all(r, g, b) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        usleep(50000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

