#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_CONFIG 0x1B
#define GYRO_SCALE 131.0
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "gyro_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050 (write PWR_MGMT_1): %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyro config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int16_t x, y, z;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed.\n");
        close(fd);
        return 1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    printf("MPU-6050 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error: Could not read gyro data: %s\n", strerror(errno));
            break;
        }
        log_data(fp, x, y, z);
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return 0;
}

