#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000
#define PWM_DUTY_50 128

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile sig_atomic_t melody_playing = 0;

static const int melody[][2] = {
    {262, 500}, {294, 500}, {330, 500}, {349, 500},
    {392, 500}, {440, 500}, {494, 500}, {523, 500}
};
static const int melody_length = sizeof(melody) / sizeof(melody[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)level;
    (void)user;
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    if (diff > DEBOUNCE_US) {
        button_pressed = 1;
        last_tick = tick;
    }
}

static int play_tone(int freq, int duration_ms) {
    if (freq <= 0) return -1;
    if (gpioSetPWMfrequency(BUZZER_PIN, freq) < 0) return -1;
    if (gpioPWM(BUZZER_PIN, PWM_DUTY_50) < 0) return -1;
    gpioDelay(duration_ms * 1000);
    if (gpioPWM(BUZZER_PIN, 0) < 0) return -1;
    return 0;
}

static void play_melody(void) {
    for (int i = 0; i < melody_length; i++) {
        if (!melody_playing) break;
        if (play_tone(melody[i][0], melody[i][1]) < 0) {
            fprintf(stderr, "Error playing tone at index %d\n", i);
            break;
        }
    }
    gpioPWM(BUZZER_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set button pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise buzzer PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set button ISR\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            if (!melody_playing) {
                melody_playing = 1;
                printf("Button pressed! Playing melody...\n");
                play_melody();
                melody_playing = 0;
            } else {
                printf("Button pressed again! Stopping melody.\n");
                gpioPWM(BUZZER_PIN, 0);
                melody_playing = 0;
            }
        }
        gpioDelay(10000);
    }

    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Doorbell system stopped.\n");
    return EXIT_SUCCESS;
}

