#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define POLL_TIMEOUT_MS 1000
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
}

static int log_event(FILE *fp, int value) {
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    if (fprintf(fp, "%s,%d\n", ts, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int poll_timeout = POLL_TIMEOUT_MS;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default: %d ms\n", POLL_TIMEOUT_MS);
            poll_timeout = POLL_TIMEOUT_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d\n", GPIO_PIN);
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_count = 0;
    int last_value = -1;

    printf("Monitoring SW-420 vibration sensor on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        int value = gpioRead(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            break;
        }

        if (value != last_value) {
            if (log_event(log_fp, value) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }

            window[window_index] = value;
            window_index = (window_index + 1) % WINDOW_SIZE;
            if (window_count < WINDOW_SIZE) {
                window_count++;
            }

            int high_count = 0;
            for (int i = 0; i < window_count; i++) {
                if (window[i] == 1) {
                    high_count++;
                }
            }

            if (high_count >= 3) {
                char ts[32];
                get_iso8601_timestamp(ts, sizeof(ts));
                printf("EARTHQUAKE ALERT: %s - Vibration detected!\n", ts);
                fflush(stdout);
            }

            last_value = value;
        }

        if (gpioDelay(poll_timeout * 1000) != 0) {
            fprintf(stderr, "gpioDelay failed: %s\n", strerror(errno));
            break;
        }
    }

    printf("\nExiting gracefully...\n");
    fclose(log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

