/*
 * LSM303DLHC magnetometer reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303DLHC SDA  -> Pi GPIO2 (physical pin 3)
 *   LSM303DLHC SCL  -> Pi GPIO3 (physical pin 5)
 *   LSM303DLHC VDD  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *
 * I2C bus: /dev/i2c-1  (BCM2835 peripheral bus)
 * LSM303DLHC magnetometer address: 0x1E (SDA low)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_reader mag_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MAG_ADDR       0x1E          /* LSM303DLHC mag 7-bit address */
#define MAG_REG_M_OUT_X_L 0x08      /* X-axis low byte (auto-increment) */
#define SAMPLE_PERIOD_S 1

/* Hard-iron calibration offsets (raw counts) */
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

/* Compass directions */
static const char *compass[8] = {
    "N", "NE", "E", "SE", "S", "SW", "W", "NW"
};

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read 6 bytes of magnetometer data starting at MAG_REG_M_OUT_X_L.
 * The LSM303DLHC auto-increments the register pointer, so a single
 * read of 6 bytes returns X_L, X_H, Z_L, Z_H, Y_L, Y_H (per datasheet).
 */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t reg = MAG_REG_M_OUT_X_L;
    uint8_t buf[6];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select): %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read (6 bytes): %s\n", strerror(errno));
        return -1;
    }

    /* Datasheet order: X, Z, Y (little-endian) */
    *x = (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
    *z = (int16_t)((uint16_t)buf[3] << 8 | buf[2]);
    *y = (int16_t)((uint16_t)buf[5] << 8 | buf[4]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                         */
/* ------------------------------------------------------------------ */
static void calibrate(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                      int16_t *cx, int16_t *cy, int16_t *cz)
{
    *cx = raw_x - X_OFFSET;
    *cy = raw_y - Y_OFFSET;
    *cz = raw_z - Z_OFFSET;
}

/* ------------------------------------------------------------------ */
/* Heading                                                             */
/* ------------------------------------------------------------------ */
static float calculate_heading(int16_t cx, int16_t cy)
{
    float heading = atan2f((float)cy, (int16_t)cx) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

static const char *determine_direction(float heading)
{
    int idx = (int)(heading / 45.0f);
    if (idx < 0)        idx = 0;
    if (idx > 7)        idx = 7;
    return compass[idx];
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    int need_header = 0;

    if (access(path, F_OK) == 0) {
        /* File exists: append */
        g_log_fp = fopen(path, "a");
    } else {
        /* File does not exist: create and write header */
        g_log_fp = fopen(path, "w");
        if (g_log_fp == NULL) {
            fprintf(stderr, "fopen(%s, w): %s\n", path, strerror(errno));
            return -1;
        }
        need_header = 1;
    }

    if (need_header) {
        if (fprintf(g_log_fp, "Timestamp, Calibrated X, Calibrated Y, "
                        "Calibrated Z, Heading\n") < 0) {
            fprintf(stderr, "fprintf(header): %s\n", strerror(errno));
            fclose(g_log_fp);
            g_log_fp = NULL;
            return -1;
        }
        if (fflush(g_log_fp) == EOF) {
            fprintf(stderr, "fflush(header): %s\n", strerror(errno));
            fclose(g_log_fp);
            g_log_fp = NULL;
            return -1;
        }
    }

    return 0;
}

static void log_sample(int16_t cx, int16_t cy, int16_t cz, float heading)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s, %d, %d, %d, %.2f\n",
                ts, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf(log): %s\n", strerror(errno));
    }
    if (fflush(g_log_fp) == EOF) {
        fprintf(stderr, "fflush(log): %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, MAG_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (log_open("mag_log.csv") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC magnetometer reader started.\n");
    printf("Logging to mag_log.csv. Press Ctrl-C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        int16_t cx, cy, cz;
        float heading;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            /* I2C error: skip this sample, keep running */
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        calibrate(raw_x, raw_y, raw_z, &cx, &cy, &cz);
        heading = calculate_heading(cx, cy);
        const char *dir = determine_direction(heading);

        printf("Heading: %s (%.2f degrees)\n", dir, heading);
        log_sample(cx, cy, cz, heading);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

