#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 200000
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_touch_tick = 0;
static volatile int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time() failed");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r() failed");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
            timestamp, relay_state ? "ON" : "OFF");

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

static void toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return;
    }
    log_event(relay_state);
}

static void touch_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 1) {
        return;
    }

    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_DELAY_US) {
        return;
    }
    last_touch_tick = tick;

    toggle_relay();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing relay state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction() failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off relay during shutdown\n");
    }

    log_event(0);

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

