/*
 * Automated plant watering system for Raspberry Pi Zero W.
 * Two SG90 servos: valve on GPIO17 (BCM), nozzle on GPIO18 (BCM).
 * Soil moisture simulated with a cyclic sequence; valve opens below 50,
 * nozzle sweeps through 0, 45, 90, 135, 180 degrees, spray for 5 s,
 * then wait 5 s.  SIGINT/SIGTERM clean shutdown.
 *
 * Build:  gcc -Wall -Wextra -O2 -o watering watering.c -lthe_driver -lrt
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>

/* ---- Library stubs (replace with real driver headers) ---- */
#include <the_driver.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define VALVE_SERVO_PIN   17
#define NOZZLE_SERVO_PIN  18

/* ---- Moisture thresholds ---- */
#define MOISTURE_THRESHOLD 50

/* ---- Timing ---- */
#define CYCLE_DELAY_SEC    1
#define SPRAY_DURATION_SEC 5
#define NOZZLE_STEP_DELAY  2
#define NOZZLE_HOLD_SEC    5
#define CYCLE_WAIT_SEC     5
#define RETRY_DELAY_MS     100
#define MAX_RETRIES        3

/* ---- SG90 pulse widths (µs) for common angles ---- */
#define VALVE_OPEN_PW      1500   /* 90° */
#define VALVE_CLOSED_PW    500    /* 0°  */
#define NOZZLE_PW_SEQ      {500, 1000, 1500, 2000, 2500}

/* ---- Simulated moisture sequence ---- */
static const int moisture_sequence[] = {20, 40, 60, 80, 100};
static const int moisture_sequence_size =
    (int)(sizeof(moisture_sequence) / sizeof(moisture_sequence[0]));

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  set_servo_angle(int pin, int angle);
static int  open_valve(void);
static int  close_valve(void);
static int  sweep_nozzle(void);
static int  spray_water(void);
static int  check_moisture(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (the_driver_init() != 0) {
        fprintf(stderr, "Error: the_driver_init() failed.\n");
        return EXIT_FAILURE;
    }

    while (g_running) {
        int moisture = check_moisture();
        printf("Moisture level: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            if (open_valve() != 0) {
                fprintf(stderr, "Error: failed to open valve.\n");
                cleanup();
                return EXIT_FAILURE;
            }

            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Warning: nozzle sweep encountered errors.\n");
            }

            if (spray_water() != 0) {
                fprintf(stderr, "Warning: spray_water() failed.\n");
            }

            if (close_valve() != 0) {
                fprintf(stderr, "Warning: failed to close valve.\n");
            }
        }

        for (int i = 0; i < CYCLE_WAIT_SEC && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Library API wrappers with retry logic.                              */
/* ------------------------------------------------------------------ */
static int set_servo_angle(int pin, int angle)
{
    int pw = 0;
    switch (angle) {
        case 0:   pw = 500; break;
        case 45:  pw = 1000; break;
        case 90:  pw = 1500; break;
        case 135: pw = 2000; break;
        case 180: pw = 2500; break;
        default:
            fprintf(stderr, "Error: invalid angle %d.\n", angle);
            return -1;
    }

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int rc = the_driver_set_servo_angle(pin, pw);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: the_driver_set_servo_angle(pin=%d, pw=%d) failed (attempt %d/%d).\n",
                pin, pw, attempt, MAX_RETRIES);
        if (attempt < MAX_RETRIES) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int open_valve(void)
{
    return set_servo_angle(VALVE_SERVO_PIN, 90);
}

static int close_valve(void)
{
    return set_servo_angle(VALVE_SERVO_PIN, 0);
}

static int sweep_nozzle(void)
{
    const int angles[] = {0, 45, 90, 135, 180};
    const int n = (int)(sizeof(angles) / sizeof(angles[0]));

    for (int i = 0; i < n && g_running; i++) {
        if (set_servo_angle(NOZZLE_SERVO_PIN, angles[i]) != 0) {
            fprintf(stderr, "Error: failed to set nozzle to %d degrees.\n", angles[i]);
            return -1;
        }
        for (int s = 0; s < NOZZLE_STEP_DELAY && g_running; s++) {
            sleep(1);
        }
    }
    return 0;
}

static int spray_water(void)
{
    for (int s = 0; s < SPRAY_DURATION_SEC && g_running; s++) {
        sleep(1);
    }
    return 0;
}

static int check_moisture(void)
{
    static int index = 0;
    int moisture = moisture_sequence[index];
    index = (index + 1) % moisture_sequence_size;
    return moisture;
}

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets flag and stops servos. */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Stop both servos by calling the library API with a zero argument. */
    the_driver_set_servo_angle(VALVE_SERVO_PIN, 0);
    the_driver_set_servo_angle(NOZZLE_SERVO_PIN, 0);
    the_driver_cleanup();
}

