    return 0;
}

static int check_moisture(void)
{
    static int index = 0;
    int moisture = moisture_sequence[index];
    index = (index + 1) % moisture_sequence_size;
    return moisture;
}

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets flag and stops servos. */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Stop both servos by calling the library API with a zero argument. */
    the_driver_set_servo_angle(VALVE_SERVO_PIN, 0);
    the_driver_set_servo_angle(NOZZLE_SERVO_PIN, 0);
    the_driver_cleanup();
}

