#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define SAMPLE_HZ      10
#define SAMPLE_PERIOD  (1000000 / SAMPLE_HZ)
#define LOG_FILE       "gyro_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd)
{
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);
    return 0;
}

static int read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0)
        return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(fp, "# gyro_log started, sampling %d Hz\n", SAMPLE_HZ);
    fflush(fp);

    int16_t x, y, z;
    while (g_running) {
        if (read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
        } else {
            log_data(fp, x, y, z);
        }
        usleep(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

