#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms timeout for echo edges */
#define SAMPLE_US   1000000 /* 1 s sampling interval */
#define PAUSE_US    60000   /* 60 ms pause between measurements */
#define TRIGGER_US  10      /* 10 us trigger pulse */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        return -1;
    }
    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static long long get_time_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_edge(int level, long long *out)
{
    long long start = get_time_us();
    if (start < 0) {
        return -1;
    }
    while (g_running) {
        int v = gpioRead(ECHO_PIN);
        if (v < 0) {
            return -1;
        }
        if (v == level) {
            long long now = get_time_us();
            if (now < 0) {
                return -1;
            }
            *out = now;
            return 0;
        }
        if ((now - start) > TIMEOUT_US) {
            return -1;
        }
        gpioDelay(10);
    }
    return -1;
}

