/*
 * VL53L1X distance sensor reader with relay control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: VL53L1X on I2C bus 1, default address 0x29
 * Relay:  GPIO18 (BCM) active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_radar vl53l1x_radar.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- VL53L1X constants (default I2C address) ---- */
#define VL53L1X_ADDR             0x29
#define I2C_BUS                 "/dev/i2c-1"
#define POLL_INTERVAL_US        100000   /* 100 ms */
#define DIST_THRESHOLD_CM       50
#define RELAY_PIN               18       /* BCM 18 */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET          0x000B
#define REG_SYSTEM_START        0x0000
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE     0x0096

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int                   g_i2c_fd  = -1;
static struct gpiod_chip    *g_chip    = NULL;
static struct gpiod_line    *g_relay   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then a single data byte.          */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then read `len` bytes.              */
static int i2c_read_reg(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    /* Soft reset: write 0x00, then 0x01 to trigger reset. */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(1000);
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x01) < 0)
        return -1;
    usleep(1000);

    /* Start continuous ranging mode. */
    if (i2c_write_reg8(fd, REG_SYSTEM_START, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist[2];

    /* Poll the range status register until data is ready. */
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg(fd, REG_RESULT_RANGE_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)  /* bit 0 = new sample ready */
            break;
        usleep(1000);
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X: no new sample within 100 ms\n");
        return -1;
    }

    /* Read 2-byte distance (big-endian). */
    if (i2c_read_reg(fd, REG_RESULT_DISTANCE, dist, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)dist[0] << 8) | dist[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_relay) {
        gpiod_line_set_value(g_relay, 0);
        gpiod_line_release(g_relay);
        g_relay = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Probe sensor presence ---- */
    uint8_t probe = 0;
    if (i2c_read_reg(g_i2c_fd, REG_SOFT_RESET, &probe, 1) < 0) {
        fprintf(stderr, "VL53L1X not responding at 0x%02X on %s\n",
                VL53L1X_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request relay line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fall back to gpiochip0 on older kernels. */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_relay = gpiod_chip_get_line(g_chip, RELAY_PIN);
    if (!g_relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                RELAY_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_relay, "vl53l1x_radar", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                RELAY_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X radar running. Threshold = %d cm. Ctrl+C to exit.\n",
           DIST_THRESHOLD_CM);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t dist_mm = 0;

        if (vl53l1x_read_distance(g_i2c_fd, &dist_mm) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
        } else {
            uint16_t dist_cm = dist_mm / 10;
            printf("Distance: %u cm\n", dist_cm);

            int relay_val = (dist_cm <= DIST_THRESHOLD_CM) ? 1 : 0;
            if (gpiod_line_set_value(g_relay, relay_val) < 0) {
                fprintf(stderr, "Warning: failed to set relay: %s\n",
                        strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

