/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules are driven via the BCM GPIO pins:
 *   GPIO17 (physical pin 11)
 *   GPIO18 (physical pin 12)
 *   GPIO27 (physical pin 13)
 *   GPIO22 (physical pin 15)
 *
 * The relays are requested as outputs with active-low semantics so that
 * a logical HIGH on the line energises the relay coil (watering active).
 * Each relay is energised for 5 s, and the full sequence repeats once
 * every 24 hours.  The start time of each cycle is logged to
 * watering_log.txt in YYYY-MM-DD HH:MM:SS format.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define WATERING_DURATION_SEC 5
#define CYCLE_INTERVAL_SEC 86400   /* 24 hours */
#define POLL_INTERVAL_SEC 60        /* seconds between relay activations */
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int log_cycle_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        fprintf(stderr, "fprintf() to log file failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log file failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int activate_relay(struct gpiod_line *line, int duration_sec)
{
    /* Active-low: HIGH energises the relay. */
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to energise relay: %s\n", strerror(errno));
        return -1;
    }

    /* Sleep in 1 s increments so we can respond to signals promptly. */
    for (int i = 0; i < duration_sec && g_running; i++)
        sleep(1);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to de-energise relay: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int rc = EXIT_FAILURE;

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the default GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the first chip found (RPi 4 uses gpiochip4). */
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Request each relay line as an output, active-low ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "plant-watering", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Plant watering system started.  Relays on GPIO17, GPIO18, "
           "GPIO27, GPIO22.  Cycle interval: %d s.  Ctrl+C to exit.\n",
           CYCLE_INTERVAL_SEC);

    /* ---- Main control loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            printf("Activating relay %d (GPIO%u) for %d seconds...\n",
                   i + 1, relay_pins[i], WATERING_DURATION_SEC);

            if (activate_relay(lines[i], WATERING_DURATION_SEC) < 0) {
                fprintf(stderr, "Relay %d activation failed; aborting.\n",
                        i + 1);
                goto cleanup;
            }
        }

        if (!g_running)
            break;

        printf("Cycle complete.  Logging start time to '%s'...\n", LOG_FILE);
        if (log_cycle_start() < 0)
            fprintf(stderr, "Warning: logging failed; continuing.\n");

        /* Sleep in 1 s increments so signals are caught promptly. */
        for (int i = 0; i < CYCLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* ---- Release all lines and close the chip ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    printf("Plant watering system stopped.\n");
    return rc;
}

