#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOG_FILE "smart_lighting.log"

static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    log_message("pigpio initialised successfully");

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set GPIO %d as output", relay_pins[i]);
            log_message(msg);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set PWM frequency on GPIO %d", relay_pins[i]);
            log_message(msg);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set PWM range on GPIO %d", relay_pins[i]);
            log_message(msg);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set initial PWM on GPIO %d", relay_pins[i]);
            log_message(msg);
            gpioTerminate();
            return -1;
        }
    }
    log_message("GPIO setup complete");
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
    }
    gpioTerminate();
    log_message("GPIO cleanup complete");
}

static void set_all_relays(int intensity) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioPWM(relay_pins[i], intensity) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set PWM on GPIO %d", relay_pins[i]);
            log_message(msg);
        }
    }
}

int main(void) {
