#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_US 50000
#define MAX_REINIT_ATTEMPTS 3
#define THRESHOLD 250.0

typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void add_to_buffer(int16_t x, int16_t y, int16_t z) {
    clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void control_led(int x, int y, int z) {
    bool above = (fabs((double)x) > THRESHOLD ||
                  fabs((double)y) > THRESHOLD ||
                  fabs((double)z) > THRESHOLD);
    gpioWrite(LED_GPIO, above ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int reinit_attempts = 0;
    while (running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            control_led(x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Read failed, re-initializing I2C...\n");
            if (++reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-init attempts reached, exiting.\n");
                break;
            }
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

