#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_GPIO_OFFSET  8          /* BCM GPIO8, SPI CE0 */
#define SPI_SPEED_HZ    1000000    /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        0
#define RETRY_COUNT     3
#define SAMPLE_DELAY_US 10000      /* 10 ms */
#define LOG_FILE        "gyro_log.txt"

/* MPU-9250 register addresses */
#define PWR_MGMT_1      0x6B
#define GYRO_XOUT_H     0x43
#define GYRO_YOUT_H     0x45
#define GYRO_ZOUT_H     0x47

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static FILE    *g_log_file = NULL;
static struct gpiod_line *g_cs_line = NULL;
static struct gpiod_chip *g_chip    = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int fd, struct gpiod_line *cs, int32_t *x, int32_t *y, int32_t *z)
{
    uint8_t tx[6];
    uint8_t rx[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        memset(tx, 0, sizeof(tx));
        memset(rx, 0, sizeof(rx));

        /* Select the MPU-9250 by pulling CS low */
        if (gpiod_line_set_value(cs, 0) < 0) {
            fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
            retries--;
            usleep(1000);
            continue;
        }

        /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
        tx[0] = GYRO_XOUT_H;
        tx[1] = GYRO_YOUT_H;
        tx[2] = GYRO_ZOUT_H;
        tx[3] = 0x00;
        tx[4] = 0x00;
        tx[5] = 0x00;

        if (spi_transfer(fd, tx, rx, 6) < 0) {
            retries--;
            usleep(1000);
            continue;
        }

        /* Deselect the MPU-9250 by pulling CS high */
        if (gpiod_line_set_value(cs, 1) < 0) {
            fprintf(stderr, "Failed to de-assert CS: %s\n", strerror(errno));
            retries--;
            usleep(1000);
            continue;
        }

        /* Combine high and low bytes (big-endian) */
        *x = (int32_t)((rx[1] << 8) | rx[0]);
        *y = (int32_t)((rx[3] << 8) | rx[2]);
        *z = (int32_t)((rx[5] << 8) | rx[4]);
        return 0;
    }

    fprintf(stderr, "Failed to read gyro data after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void log_data(FILE *fp, int32_t x, int32_t y, int32_t z)
{
    struct timespec ts;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    int32_t x, y, z;

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Open GPIO chip and get CS line */
    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_GPIO_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_GPIO_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    /* Request CS line as output, initially high (deselected) */
    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Wake up MPU-9250 (clear sleep bit) */
    uint8_t wake_cmd = 0x00;
    uint8_t wake_tx[2] = { PWR_MGMT_1, wake_cmd };
    uint8_t wake_rx[2] = { 0, 0 };
    if (spi_transfer(g_spi_fd, wake_tx, wake_rx, 2) < 0) {
        fprintf(stderr, "Failed to wake up MPU-9250: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Allow time for oscillator to stabilize */
    usleep(100000);

    printf("Gyroscope data logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_gyro_data(g_spi_fd, g_cs_line, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, skipping log entry.\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

