#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0
#define SAMPLE_INTERVAL_US 10000

#define MPU6050_REG_SMPLRT_DIV 0x19
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_PWR_MGMT_1 0x6B

typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static circular_buffer_t buffer;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };
    return (spiXfer(spi_handle, tx, rx, 2) != 2) ? -1 : 0;
}

static int init_mpu6050(void) {
    if (spi_write_register(MPU6050_REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Could not wake MPU-6050.\n");
        return -1;
    }
    gpioDelay(100000);
    if (spi_write_register(MPU6050_REG_SMPLRT_DIV, 0x07) != 0) return -1;
    if (spi_write_register(MPU6050_REG_GYRO_CONFIG, 0x00) != 0) return -1;
    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    char tx[7] = { (char)(MPU6050_REG_GYRO_XOUT_H | 0x80), 0, 0, 0, 0, 0, 0 };
    char rx[7] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 7) != 7) return -1;
    int16_t x = (int16_t)(((uint8_t)rx[2] << 8) | (uint8_t)rx[1]);
    int16_t y = (int16_t)(((uint8_t)rx[4] << 8) | (uint8_t)rx[3]);
    int16_t z = (int16_t)(((uint8_t)rx[6] << 8) | (uint8_t)rx[5]);
    data->x = (float)x / 131.0f;
    data->y = (float)y / 131.0f;
    data->z = (float)z / 131.0f;
    clock_gettime(CLOCK_MONOTONIC, &data->timestamp);
    return 0;
}

static void add_to_buffer(gyro_data_t data) {
    buffer.data[buffer.head] = data;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    int start = (buffer.count < BUFFER_SIZE) ? 0 : buffer.head;
    for (int i = 0; i < buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("%ld.%09ld,%f,%f,%f\n",
               (long)buffer.data[idx].timestamp.tv_sec,
               buffer.data[idx].timestamp.tv_nsec,
               buffer.data[idx].x, buffer.data[idx].y, buffer.data[idx].z);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed.\n");
        gpioTerminate();
        return 1;
    }
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    buffer.head = 0;
    buffer.count = 0;
    while (running) {
        gyro_data_t data;
        if (read_gyro_data(&data) != 0) {
            fprintf(stderr, "Warning: SPI read error.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        add_to_buffer(data);
        if (data.x > THRESHOLD || data.x < -THRESHOLD ||
            data.y > THRESHOLD || data.y < -THRESHOLD ||
            data.z > THRESHOLD || data.z < -THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            gpioDelay(500000);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(500000);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    print_buffer();
    cleanup();
    return 0;
}

