#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPU6050_ADDR   0x68
#define LED_PIN        21
#define SAMPLE_US      100000   /* 100 ms */
#define TILT_THRESHOLD 45.0f

/* MPU-6050 register addresses */
#define REG_SMPLRT_DIV   0x19
#define REG_PWR_MGMT_1   0x6B
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a signed 16-bit big-endian register pair; returns 0 on success, -1 on error. */
static int read_int16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "I2C read error at register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int init_mpu6050(int handle)
{
    /* Wake up the device: clear SLEEP bit in PWR_MGMT_1. */
    if (i2cWriteByteData(handle, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Optional: configure sample rate divider (1 kHz / (1 + 7) = 125 Hz). */
    if (i2cWriteByteData(handle, REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to write SMPLRT_DIV\n");
        return -1;
    }
    return 0;
}

static void log_tilt_data(float roll, float pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        perror("fopen(\"tilt_log.txt\")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    }
    fclose(fp);
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, MPU6050_ADDR, handle);
        goto cleanup_gpio;
    }

    if (init_mpu6050(handle) != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        goto cleanup_i2c;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        goto cleanup_i2c;
    }

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_int16(handle, REG_ACCEL_XOUT_H, &ax) != 0 ||
            read_int16(handle, REG_ACCEL_XOUT_H + 2, &ay) != 0 ||
            read_int16(handle, REG_ACCEL_XOUT_H + 4, &az) != 0 ||
            read_int16(handle, REG_GYRO_XOUT_H, &gx) != 0 ||
            read_int16(handle, REG_GYRO_XOUT_H + 2, &gy) != 0 ||
            read_int16(handle, REG_GYRO_XOUT_H + 4, &gz) != 0) {
            fprintf(stderr, "Sensor read error; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Convert to physical units (raw / 16384 for accel, raw / 131 for gyro). */
        float ax_g = (float)ax / 16384.0f;
        float ay_g = (float)ay / 16384.0f;
        float az_g = (float)az / 16384.0f;
        float gx_dps = (float)gx / 131.0f;
        float gy_dps = (float)gy / 131.0f;
        float gz_dps = (float)gz / 131.0f;

        /* Euler angles from gyro (first-order approximation). */
        static float roll  = 0.0f;
        static float pitch = 0.0f;
        static uint32_t gyro_ts = 0;
        uint32_t now = gpioTick();
        float dt = (float)(now - gyro_ts) / 1000000.0f; /* seconds */
        if (dt > 0.0f) {
            roll  += gy_dps * dt;
            pitch += gx_dps * dt;
        }
        gyro_ts = now;

        /* Euler angles from accelerometer. */
        float roll_acc = atan2f((float)ay, (float)az) * 180.0f / (float)M_PI;
        float pitch_acc = atan2f(-ax, sqrtf(ay * ay + az * az)) * 180.0f / (float)M_PI;

        /* Blend: gyro + accel. */
        roll  = 0.95f * roll  + 0.05f * roll_acc;
        pitch = 0.95f * pitch + 0.05f * pitch_acc;

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        log_tilt_data(roll, pitch);

        if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
