#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0
#define SAMPLE_DELAY_US 10000
#define MAX_REINIT_ATTEMPTS 3

/* ADXRS290 register addresses (sent MSB first) */
#define ADXRS290_REG_XGYRO_OUT 0x00
#define ADXRS290_REG_YGYRO_OUT 0x02
#define ADXRS290_REG_TEMP_OUT  0x04
#define ADXRS290_REG_STATUS    0x06
#define ADXRS290_REG_WHO_AM_I  0x08
#define ADXRS290_REG_CTRL_REG1 0x0A
#define ADXRS290_REG_CTRL_REG2 0x0C
#define ADXRS290_REG_CTRL_REG3 0x0E

#define ADXRS290_WHO_AM_I_VAL 0x29

/* CTRL_REG1: 0x80 = enable gyro X/Y axes, 0x00 = 100 Hz ODR */
#define ADXRS290_CTRL_REG1_VAL 0x80

/* CTRL_REG2: 0x00 = ±250 dps full-scale range */
#define ADXRS290_CTRL_REG2_VAL 0x00

/* CTRL_REG3: 0x00 = continuous-conversion mode */
#define ADXRS290_CTRL_REG3_VAL 0x00

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int init_gyro(void) {
    uint8_t who_am_i = 0;

    if (spi_read_register(ADXRS290_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != ADXRS290_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                ADXRS290_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    if (spi_write_register(ADXRS290_REG_CTRL_REG1, ADXRS290_CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }
    if (spi_write_register(ADXRS290_REG_CTRL_REG2, ADXRS290_CTRL_REG2_VAL) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG2\n");
        return -1;
    }
    if (spi_write_register(ADXRS290_REG_CTRL_REG3, ADXRS290_CTRL_REG3_VAL) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG3\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_raw = 0, y_raw = 0;

    if (spi_read_register(ADXRS290_REG_XGYRO_OUT, &x_raw) != 0) {
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_YGYRO_OUT, &y_raw) != 0) {
        return -1;
    }

    *x_rate = (int16_t)((x_raw << 8) | (x_raw & 0xFF));
    *y_rate = (int16_t)((y_raw << 8) | (y_raw & 0xFF));
    return 0;
}

static int log_data(FILE *f, int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    if (fprintf(f, "%.9f,%d,%d\n", timestamp, x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(f) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialisation failed\n");
        cleanup();
        return 1;
    }

    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }

    if (fprintf(fp, "timestamp,x_rate,y_rate\n") < 0) {
        perror("fprintf header");
        cleanup();
        return 1;
    }

    int reinit_attempts = 0;

    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0;

        if (read_gyro_data(&x_rate, &y_rate) != 0) {
            fprintf(stderr, "Failed to read gyro data. Re-initialising SPI...\n");
            reinit_attempts++;
            if (init_spi() != 0) {
                fprintf(stderr, "SPI re-initialisation failed. Attempt %d/%d\n",
                        reinit_attempts, MAX_REINIT_ATTEMPTS);
                if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Max re-initialisation attempts reached. Exiting.\n");
                    break;
                }
            } else {
                reinit_attempts = 0;
            }
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (log_data(fp, x_rate, y_rate) != 0) {
            fprintf(stderr, "Failed to log data. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

