#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define ALERT_DURATION_MS 2000
#define SEISMIC_THRESHOLD_MS 500
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s - Seismic event detected!\n", timestamp) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        } else {
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

static void alert_callback(int pin, int level, uint32_t tick) {
    (void)pin;
    (void)tick;

    if (level == 1) {
        if (gpioWrite(ALERT_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set alert pin HIGH\n");
            return;
        }
        gpioDelay(ALERT_DURATION_MS * 1000);
        if (gpioWrite(ALERT_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set alert pin LOW\n");
        }
    }
}

static void sensor_callback(int pin, int level, uint32_t tick) {
    (void)pin;
    (void)tick;

    if (level == 1) {
        log_event();
    }
