#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define LED_GPIO       17
#define THRESHOLD      20.0f
#define BUFFER_SIZE    100
#define GYRO_X_REG     0x00
#define GYRO_Y_REG     0x02
#define GYRO_Z_REG     0x04
#define GYRO_CONFIG_REG 0x0F
#define GYRO_CONFIG_VAL 0x00
#define GYRO_SENSITIVITY 0.00875f

typedef struct {
    struct timespec timestamp;
    float x_rate;
    float y_rate;
    float z_rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int init_gyro(void) {
    if (spi_write_register(GYRO_CONFIG_REG, GYRO_CONFIG_VAL) != 0) {
        fprintf(stderr, "Failed to write gyro config register\n");
        return -1;
    }
    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    uint8_t x_raw, y_raw, z_raw;

    if (spi_read_register(GYRO_X_REG, &x_raw) != 0) return -1;
    if (spi_read_register(GYRO_Y_REG, &y_raw) != 0) return -1;
    if (spi_read_register(GYRO_Z_REG, &z_raw) != 0) return -1;

    data->x_rate = (float)((int16_t)((x_raw << 8) | (x_raw & 0xFF))) * GYRO_SENSITIVITY;
    data->y_rate = (float)((int16_t)((y_raw << 8) | (y_raw & 0xFF))) * GYRO_SENSITIVITY;
    data->z_rate = (float)((int16_t)((z_raw << 8) | (z_raw & 0xFF))) * GYRO_SENSITIVITY;

    if (clock_gettime(CLOCK_MONOTONIC, &data->timestamp) != 0) {
        fprintf(stderr, "clock_gettime failed\n");
        return -1;
    }
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    if (pthread_mutex_init(&buf->mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        exit(EXIT_FAILURE);
    }
}

static void buffer_add(circular_buffer_t *buf, gyro_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void buffer_get(circular_buffer_t *buf, int index, gyro_data_t *data) {
    pthread_mutex_lock(&buf->mutex);
    if (index < 0 || index >= buf->count) {
        pthread_mutex_unlock(&buf->mutex);
        return;
    }
    int actual_index = (buf->tail + index) % BUFFER_SIZE;
    *data = buf->data[actual_index];
    pthread_mutex_unlock(&buf->mutex);
}

static void control_led(float x_rate) {
    if (x_rate > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gyro() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&gyro_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gyro_data_t gyro_data;
    int buffer_index = 0;

    while (running) {
        if (read_gyro_data(&gyro_data) == 0) {
            buffer_add(&gyro_buffer, gyro_data);
            control_led(gyro_data.x_rate);
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        gpioDelay(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

