#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define FADE_STEP_US 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_lamp_pwm(int pin, int duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (duty %d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int duration_s) {
    int steps = (duration_s * 1000000) / FADE_STEP_US;
    if (steps <= 0) steps = 1;
    int step_delay_us = FADE_STEP_US;

    int duty = PWM_RANGE;
    if (set_lamp_pwm(pin, duty) < 0) return -1;

    for (int i = 0; i < steps && g_running; i++) {
        duty -= (PWM_RANGE / steps);
        if (duty < 0) duty = 0;
        if (set_lamp_pwm(pin, duty) < 0) return -1;
        gpioDelay(step_delay_us);
    }

    if (set_lamp_pwm(pin, 0) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    gpioPWM(LAMP1_PIN, 0);
    gpioPWM(LAMP2_PIN, 0);
    gpioPWM(LAMP3_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        fprintf(stderr, "  duration_seconds: integer 1-3600\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: invalid duration '%s' (must be 1-3600)\n", argv[1]);
