#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define YELLOW_PIN2 24

#define RED_DURATION   10
#define YELLOW_DURATION 2
#define GREEN_DURATION  10
#define YELLOW_DURATION2 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(unsigned int seconds) {
    while (seconds > 0 && running) {
        unsigned int chunk = (seconds > 1) ? 1 : seconds;
        sleep(chunk);
        seconds -= chunk;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL;
    struct gpiod_line *yellow_line = NULL;
    struct gpiod_line *green_line = NULL;
    struct gpiod_line *yellow_line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    yellow_line2 = gpiod_chip_get_line(chip, YELLOW_PIN2);
    if (!red_line || !yellow_line || !green_line || !yellow_line2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(yellow_line, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(green_line, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(yellow_line2, "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        /* Red: LOW energizes relay, HIGH de-energizes */
        if (gpiod_line_set_value(red_line, 0) < 0) { perror("set red"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line, 1) < 0) { perror("set yellow"); goto cleanup; }
        if (gpiod_line_set_value(green_line, 1) < 0) { perror("set green"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line2, 1) < 0) { perror("set yellow2"); goto cleanup; }
        printf("Red\n");
        sleep_seconds(RED_DURATION);

        if (!running) break;

        if (gpiod_line_set_value(red_line, 1) < 0) { perror("set red"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line, 0) < 0) { perror("set yellow"); goto cleanup; }
        if (gpiod_line_set_value(green_line, 1) < 0) { perror("set green"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line2, 1) < 0) { perror("set yellow2"); goto cleanup; }
        printf("Red + Yellow\n");
        sleep_seconds(YELLOW_DURATION);

        if (!running) break;

        if (gpiod_line_set_value(red_line, 1) < 0) { perror("set red"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line, 1) < 0) { perror("set yellow"); goto cleanup; }
        if (gpiod_line_set_value(green_line, 0) < 0) { perror("set green"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line2, 1) < 0) { perror("set yellow2"); goto cleanup; }
        printf("Green\n");
        sleep_seconds(GREEN_DURATION);

        if (!running) break;

        if (gpiod_line_set_value(red_line, 1) < 0) { perror("set red"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line, 1) < 0) { perror("set yellow"); goto cleanup; }
        if (gpiod_line_set_value(green_line, 1) < 0) { perror("set green"); goto cleanup; }
        if (gpiod_line_set_value(yellow_line2, 0) < 0) { perror("set yellow2"); goto cleanup; }
        printf("Yellow\n");
        sleep_seconds(YELLOW_DURATION2);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (yellow_line) gpiod_line_release(yellow_line);
    if (green_line) gpiod_line_release(green_line);
    if (yellow_line2) gpiod_line_release(yellow_line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

