    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n",
                    LOG_FILE, strerror(errno));
            return -1;
        }
    }

    if (fprintf(log_file, "%s - Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_buzzer_and_led(void) {
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Error activating buzzer on GPIO%d: %s\n",
                BUZZER_PIN, strerror(errno));
        return -1;
    }
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error activating LED on GPIO%d: %s\n",
                LED_PIN, strerror(errno));
        gpioWrite(BUZZER_PIN, 0);
        return -1;
    }
    return 0;
}

static void deactivate_buzzer_and_led(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
}

static void cleanup(void) {
    deactivate_buzzer_and_led();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int flame_count = 0;
    int consecutive_low = 0;
    int first_read = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting flame sensor pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing buzzer state: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing LED state: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (sensor_value == 0) {
            if (first_read) {
                flame_count = 1;
                first_read = 0;
            } else {
                flame_count++;
            }

            if (flame_count >= FLAME_THRESHOLD) {
                if (log_flame_event() < 0) {
                    fprintf(stderr, "Error logging flame event, exiting.\n");
                    break;
                }
                if (activate_buzzer_and_led() < 0) {
                    fprintf(stderr, "Error activating buzzer and LED, exiting.\n");
                    break;
                }
                consecutive_low = 1;
            }
        } else {
            if (first_read) {
                flame_count = 0;
                first_read = 0;
            } else {
                flame_count = 0;
            }
            consecutive_low = 0;
        }

        if (consecutive_low) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (read_flame_sensor() != 0) {
                deactivate_buzzer_and_led();
                consecutive_low = 0;
            }
        } else {
            gpioDelay(POLL_DELAY_US);
        }
    }

    cleanup();
    printf("Flame detection system stopped.\n");
    return EXIT_SUCCESS;
}

