#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <sys/time.h>
#include <gpiod.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_INTERVAL_MS 1000
#define HALF_INTERVAL_MS (DISPENSE_INTERVAL_MS / 2)
#define LOG_FILE "dispense_log.txt"
#define DRIVER_LIBRARY_NAME "gpiod"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Solenoid %d, %d ms\n", timestamp, solenoid_pin, duration_ms) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int dispense_solenoid(struct gpiod_line *line, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error activating solenoid: %s\n", strerror(errno));
        return -1;
    }

    struct timeval start, now;
    if (gettimeofday(&start, NULL) < 0) {
        fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
        gpiod_line_set_value(line, 0);
        return -1;
    }

    while (program_running) {
        if (gettimeofday(&now, NULL) < 0) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            gpiod_line_set_value(line, 0);
            return -1;
        }
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L + (now.tv_usec - start.tv_usec) / 1000L;
        if (elapsed_ms >= duration_ms) {
            break;
        }
        usleep(10000); /* 10 ms polling interval */
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *solenoid1_line = NULL;
    struct gpiod_line *solenoid2_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines for the solenoids */
    solenoid1_line = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!solenoid1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_1_PIN, strerror(errno));
        goto cleanup;
    }

    solenoid2_line = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!solenoid2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request the lines as outputs, initially low */
    if (gpiod_line_request_output(solenoid1_line, "solenoid_dispenser", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID_1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(solenoid2_line, "solenoid_dispenser", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID_2_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Solenoid dispenser started. Press Ctrl+C to exit.\n");

    while (program_running) {
        printf("Dispensing solenoid 1...\n");
        if (dispense_solenoid(solenoid1_line, HALF_INTERVAL_MS) < 0) {
            fprintf(stderr, "Error dispensing solenoid 1\n");
            goto cleanup;
        }
        if (log_dispense_event(SOLENOID_1_PIN, HALF_INTERVAL_MS) < 0) {
            fprintf(stderr, "Error logging dispense event for solenoid 1\n");
        }

        if (!program_running) break;

        printf("Dispensing solenoid 2...\n");
        if (dispense_solenoid(solenoid2_line, HALF_INTERVAL_MS) < 0) {
            fprintf(stderr, "Error dispensing solenoid 2\n");
            goto cleanup;
        }
        if (log_dispense_event(SOLENOID_2_PIN, HALF_INTERVAL_MS) < 0) {
            fprintf(stderr, "Error logging dispense event for solenoid 2\n");
        }

        /* Wait for the remaining half of the interval before the next cycle */
        if (program_running) {
            usleep((DISPENSE_INTERVAL_MS - HALF_INTERVAL_MS) * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Deactivate solenoids and release resources */
    if (solenoid1_line) {
        gpiod_line_set_value(solenoid1_line, 0);
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        gpiod_line_set_value(solenoid2_line, 0);
        gpiod_line_release(solenoid2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Solenoid dispenser stopped.\n");
    return ret;
}

