#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 50000
#define OBSTACLE_THRESHOLD 20.0
#define OBSTACLE_SPEED 128
#define MAX_SPEED 255

#define LOG_FILE "balance_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_forward = NULL;
static struct gpiod_line *line_backward = NULL;
static struct gpiod_line *line_enable = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    line_forward = gpiod_chip_get_line(chip, MOTOR_A_FORWARD);
    line_backward = gpiod_chip_get_line(chip, MOTOR_A_BACKWARD);
    line_enable = gpiod_chip_get_line(chip, MOTOR_A_ENABLE);
    if (!line_forward || !line_backward || !line_enable) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(line_forward, "self_balancer", 0) < 0 ||
        gpiod_line_request_output(line_backward, "self_balancer", 0) < 0 ||
        gpiod_line_request_output(line_enable, "self_balancer", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > MAX_SPEED) motor_a_speed = MAX_SPEED;
    if (motor_a_speed < -MAX_SPEED) motor_a_speed = -MAX_SPEED;
    if (motor_b_speed > MAX_SPEED) motor_b_speed = MAX_SPEED;
    if (motor_b_speed < -MAX_SPEED) motor_b_speed = -MAX_SPEED;

    if (motor_a_speed > 0) {
        gpiod_line_set_value(line_forward, 1);
        gpiod_line_set_value(line_backward, 0);
        gpiod_line_set_value(line_enable, 1);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_FORWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_BACKWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_ENABLE), 1);
    } else if (motor_a_speed < 0) {
        gpiod_line_set_value(line_forward, 0);
        gpiod_line_set_value(line_backward, 1);
        gpiod_line_set_value(line_enable, 1);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_FORWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_BACKWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_ENABLE), 1);
    } else {
        gpiod_line_set_value(line_forward, 0);
        gpiod_line_set_value(line_backward, 0);
        gpiod_line_set_value(line_enable, 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_FORWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_BACKWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_ENABLE), 0);
    }

    if (motor_b_speed > 0) {
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_FORWARD), 1);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_BACKWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_ENABLE), 1);
    } else if (motor_b_speed < 0) {
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_FORWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_BACKWARD), 1);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_ENABLE), 1);
    } else {
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_FORWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_BACKWARD), 0);
        gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_ENABLE), 0);
    }
}

static void stop_motors(void) {
    gpiod_line_set_value(line_forward, 0);
    gpiod_line_set_value(line_backward, 0);
    gpiod_line_set_value(line_enable, 0);
    gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_FORWARD), 0);
    gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_BACKWARD), 0);
    gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_B_ENABLE), 0);
}

static float calculate_pid(float error, float *integral, float *previous_error, float kp, float ki, float kd) {
    *integral += error;
    float derivative = error - *previous_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    float kp = 1.0, ki = 0.01, kd = 0.1;
    float integral = 0.0, previous_error = 0.0;
    float tilt_error, distance;
    int motor_a_speed, motor_b_speed;

    srand(time(NULL));

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        tilt_error = (float)(rand() % 21 - 10);
        distance = (float)(rand() % 399 + 2);

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -OBSTACLE_SPEED;
            motor_b_speed = -OBSTACLE_SPEED;
        } else {
            float pid_output = calculate_pid(tilt_error, &integral, &previous_error, kp, ki, kd);
            motor_a_speed = (int)pid_output;
            motor_b_speed = (int)pid_output;
        }

        set_motor_speed(motor_a_speed, motor_b_speed);
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        usleep(LOOP_DELAY_US);
    }

    stop_motors();
    if (log_file) fclose(log_file);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

