/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures audio via ALSA (8000 Hz, 16-bit mono, 1024-period) and maps RMS
 * amplitude to a common-cathode RGB LED on GPIO17(R), GPIO18(G), GPIO27(B)
 * using software PWM via the driver library.  On SIGINT/SIGTERM the program
 * releases every resource cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lm -lpigpio -lrt
 *         (pigpio required for software PWM; libgpiod is not used here.)
 *
 * When ALSA is unavailable (e.g. no /dev/snd/), a simulated sine-wave
 * amplitude drives the LED through a 10-sweep color cycle.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

/* ---- Audio capture parameters ---- */
#define SAMPLE_RATE      8000
#define PERIOD_SIZE      1024
#define AMPLITUDE_SCALE  1.0f
#define SAMPLE_PERIOD_US 10000   /* 10 ms */

/* ---- Color cycle ---- */
#define COLOR_CYCLE_SIZE 10

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_alsa_available = 0;

/* ---- Color table ---- */
static const unsigned char color_table[][3] = {
    {255, 0,   0},   /* red   */
    {255, 128, 0},   /* orange*/
    {255, 255, 0},   /* yellow*/
    {0,   255, 0},   /* green */
    {0,   0,   255}, /* blue  */
    {255, 0,   255}, /* magenta*/
    {128, 0,   128}, /* purple*/
    {255, 255, 255}, /* white */
    {0,   0,   0},   /* black */
    {128, 128, 128}  /* gray  */
};

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Software PWM helpers ---- */
static void set_pwm(int pin, int duty_percent)
{
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    gpioPWM(pin, duty_percent);
}

static void set_color(int r, int g, int b)
{
    set_pwm(RED_PIN,   r);
    set_pwm(GREEN_PIN, g);
    set_pwm(BLUE_PIN,  b);
}

/* ---- Color cycle ---- */
static void cycle_color(int *index)
{
    (*index)++;
    if (*index >= COLOR_CYCLE_SIZE) *index = 0;
}

/* ---- Simulated sine-wave amplitude (when ALSA unavailable) ---- */
static float simulate_amplitude(void)
{
    static int phase = 0;
    phase++;
    return (float)sin((double)phase / 100.0) * 127.0f + 127.5f;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    set_color(0, 0, 0);
    gpioTerminate();
}

/* ---- ALSA capture thread (compiled only when ALSA is available) ---- */
#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#include <pthread.h>

static snd_pcm_t *g_alsa_handle = NULL;
static pthread_t  g_alsa_thread;
