static void *alsa_capture_thread(void *arg)
{
    (void)arg;
    snd_pcm_hw_params_t *hw_params = NULL;
    snd_pcm_sw_params_t *sw_params  = NULL;
    int err;

    while (g_running) {
        err = snd_pcm_prepare(g_alsa_handle);
        if (err < 0) {
            fprintf(stderr, "ALSA prepare failed: %s\n", snd_strerror(err));
            break;
        }

        err = snd_pcm_readi(g_alsa_handle, (char *)g_audio_buffer, PERIOD_SIZE);
        if (err == -EPIPE) {
            fprintf(stderr, "ALSA buffer overrun; resuming...\n");
            snd_pcm_prepare(g_alsa_handle);
            continue;
        }
        if (err == -ESTRPIPE) {
            fprintf(stderr, "ALSA suspended; resuming...\n");
            snd_pcm_resume(g_alsa_handle);
            continue;
        }
        if (err < 0) {
            fprintf(stderr, "ALSA read error: %s\n", snd_strerror(err));
            break;
        }
        if (err == 0) {
            fprintf(stderr, "ALSA read returned 0 (unexpected)\n");
            break;
        }
    }

    g_alsa_thread_running = 0;
    return NULL;
}

static void init_alsa(void)
{
    int err;

    err = snd_pcm_open(&g_alsa_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "ALSA open failed: %s\n", snd_strerror(err));
        g_alsa_available = 0;
        return;
    }

    snd_pcm_hw_params_alloca(&hw_params);
    snd_pcm_sw_params_alloca(&sw_params);

    err = snd_pcm_hw_params_any(g_alsa_handle, hw_params);
    if (err < 0) { fprintf(stderr, "hw_params_any: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_hw_params_set_access(g_alsa_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) { fprintf(stderr, "set_access: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_hw_params_set_format(g_alsa_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) { fprintf(stderr, "set_format: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_hw_params_set_rate_near(g_alsa_handle, hw_params, &SAMPLE_RATE, 0);
    if (err < 0) { fprintf(stderr, "set_rate: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_hw_params_set_channels(g_alsa_handle, hw_params, 1);
    if (err < 0) { fprintf(stderr, "set_channels: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_hw_params_set_period_size_near(g_alsa_handle, hw_params, &PERIOD_SIZE, 0);
    if (err < 0) { fprintf(stderr, "set_period_size: %s\n", snd_strerror(err)); goto fail; }

    err = snd_pcm_hw_params(g_alsa_handle, hw_params);
    if (err < 0) { fprintf(stderr, "hw_params: %s\n", snd_strerror(err)); goto fail; }

    err = snd_pcm_sw_params_any(g_alsa_handle, sw_params);
    if (err < 0) { fprintf(stderr, "sw_params_any: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_sw_params_set_start_threshold(g_alsa_handle, sw_params, 0);
    if (err < 0) { fprintf(stderr, "set_start_threshold: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_sw_params_set_stop_threshold(g_alsa_handle, sw_params, 0);
    if (err < 0) { fprintf(stderr, "set_stop_threshold: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_sw_params_set_silence_threshold(g_alsa_handle, sw_params, 0);
    if (err < 0) { fprintf(stderr, "set_silence_threshold: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_sw_params_set_avail_min(g_alsa_handle, sw_params, PERIOD_SIZE);
    if (err < 0) { fprintf(stderr, "set_avail_min: %s\n", snd_strerror(err)); goto fail; }
    err = snd_pcm_sw_params(g_alsa_handle, sw_params);
    if (err < 0) { fprintf(stderr, "sw_params: %s\n", snd_strerror(err)); goto fail; }

    g_audio_buffer = malloc((size_t)PERIOD_SIZE * sizeof(short));
    if (!g_audio_buffer) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        goto fail;
    }
    g_audio_buffer_size = PERIOD_SIZE;
    g_alsa_thread_running = 1;
    if (pthread_create(&g_alsa_thread, NULL, alsa_capture_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create ALSA thread: %s\n", strerror(errno));
        free(g_audio_buffer);
        g_audio_buffer = NULL;
        g_audio_buffer_size = 0;
        goto fail;
    }
    g_alsa_available = 1;
    return;

fail:
    snd_pcm_close(g_alsa_handle);
    g_alsa_handle = NULL;
    g_alsa_available = 0;
}

static void stop_alsa(void)
{
    if (g_alsa_available) {
        g_running = 0;
        if (g_alsa_thread_running) {
            pthread_join(g_alsa_thread, NULL);
            g_alsa_thread_running = 0;
        }
        if (g_audio_buffer) {
            free(g_audio_buffer);
            g_audio_buffer = NULL;
            g_audio_buffer_size = 0;
        }
        snd_pcm_drain(g_alsa_handle);
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        g_alsa_available = 0;
    }
}
