#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x92
#define TCS34725_CDATA   0x94
#define TCS34725_RDATA   0x96
#define TCS34725_GDATA   0x98
#define TCS34725_BDATA   0x9A

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_fp        = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
    return rc;
}

static int read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    return rc;
}

static int init_sensor(int handle)
{
    /* Power on */
    if (write_reg(handle, TCS34725_ENABLE, 0x01) < 0)
        return -1;

    /* Set integration time to 154 ms (0x0A) */
    if (write_reg(handle, TCS34725_ATIME, 0x0A) < 0)
        return -1;

    /* Enable RGBC ADC (0x03) */
    if (write_reg(handle, TCS34725_ENABLE, 0x03) < 0)
        return -1;

    return 0;
}

static int read_color(int handle, uint16_t *c, uint16_t *r,
                      uint16_t *g, uint16_t *b)
{
    int rc;

    rc = i2cReadWordData(handle, TCS34725_CDATA);
    if (rc < 0) {
        fprintf(stderr, "Failed to read clear channel: %s\n",
                pigpio_error(rc));
        *c = 0;
    } else {
        *c = (uint16_t)rc;
    }

    rc = i2cReadWordData(handle, TCS34725_RDATA);
    if (rc < 0) {
        fprintf(stderr, "Failed to read red channel: %s\n",
                pigpio_error(rc));
        *r = 0;
    } else {
        *r = (uint16_t)rc;
    }

    rc = i2cReadWordData(handle, TCS34725_GDATA);
    if (rc < 0) {
        fprintf(stderr, "Failed to read green channel: %s\n",
                pigpio_error(rc));
        *g = 0;
    } else {
        *g = (uint16_t)rc;
    }

    rc = i2cReadWordData(handle, TCS34725_BDATA);
    if (rc < 0) {
        fprintf(stderr, "Failed to read blue channel: %s\n",
                pigpio_error(rc));
        *b = 0;
    } else {
        *b = (uint16_t)rc;
    }

    return 0;
}

static int log_data(FILE *fp, uint16_t c, uint16_t r, uint16_t g, uint16_t b)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    if (fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b) < 0) {
        fprintf(stderr, "fprintf to CSV failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_fp = fopen(CSV_FILENAME, "a");
    if (g_fp == NULL) {
        perror("fopen(" CSV_FILENAME ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_fp) == 0) {
        if (fprintf(g_fp, "timestamp,clear,red,green,blue\n") < 0) {
            perror("fprintf(header)");
            fclose(g_fp);
            i2cClose(g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fflush(g_fp);
    }

    printf("Logging color data to %s (Ctrl+C to stop)...\n", CSV_FILENAME);

    while (g_running) {
        uint16_t c, r, g, b;

        if (read_color(g_i2c_handle, &c, &r, &g, &b) == 0) {
            if (log_data(g_fp, c, r, g, b) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; logging zeros\n");
            if (log_data(g_fp, 0, 0, 0, 0) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");

    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

