#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION  3600
#define SUNSET_DURATION   3600
#define DAYTIME_DURATION  21600
#define NIGHTTIME_DURATION 52560

#define NUM_RELAYS 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int all_relays_off(void) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (set_relay(pins[i], 0) != 0) {
            return -1;
        }
    }
    return 0;
}

static int sunrise_phase(void) {
    for (int i = 0; i <= 100 && running; i++) {
        int duty = (i * 100) / 100;
        int state = (duty > 0) ? 0 : 1;
        int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
        for (int j = 0; j < NUM_RELAYS; j++) {
            if (set_relay(pins[j], state) != 0) {
                return -1;
            }
        }
        gpioDelay(36000);
    }
    return 0;
}

static int sunset_phase(void) {
    for (int i = 100; i >= 0 && running; i--) {
        int duty = (i * 100) / 100;
        int state = (duty > 0) ? 0 : 1;
        int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
        for (int j = 0; j < NUM_RELAYS; j++) {
            if (set_relay(pins[j], state) != 0) {
                return -1;
            }
        }
        gpioDelay(36000);
    }
    return 0;
}

static int daytime_phase(void) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int j = 0; j < NUM_RELAYS; j++) {
        if (set_relay(pins[j], 0) != 0) {
            return -1;
        }
    }
    gpioDelay(2160000);
    return 0;
}

static int nighttime_phase(void) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int j = 0; j < NUM_RELAYS; j++) {
        if (set_relay(pins[j], 1) != 0) {
            return -1;
        }
    }
    gpioDelay(5256000);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        all_relays_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (sunrise_phase() != 0) {
            break;
        }
        if (!running) break;
        if (daytime_phase() != 0) {
            break;
        }
        if (!running) break;
        if (sunset_phase() != 0) {
            break;
        }
        if (!running) break;
        if (nighttime_phase() != 0) {
            break;
        }
    }

    all_relays_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

