#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_S 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define TIMESTAMP_LEN 20
#define CMD_LEN 256

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_motion(const char *timestamp) {
    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }
    if (fprintf(log_fp, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_video(const char *timestamp) {
    char filepath[256];
    char command[CMD_LEN];

    if (snprintf(filepath, sizeof(filepath), "%s%s.h264", VIDEO_DIR, timestamp) >= (int)sizeof(filepath)) {
        fprintf(stderr, "Error: video path too long\n");
        return -1;
    }

    if (snprintf(command, CMD_LEN, "raspivid -o %s -t %d", filepath, VIDEO_DURATION_S * 1000) >= (int)CMD_LEN) {
        fprintf(stderr, "Error: command string too long\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "raspivid killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    printf("Video captured: %s\n", filepath);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d\n", GPIO_PIN);
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    uint32_t last_trigger_tick = 0;
    int last_level = 1;

    while (running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            break;
        }

        if (level == 0 && last_level == 1) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;

            if (last_trigger_tick == 0 || elapsed >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                char timestamp[TIMESTAMP_LEN];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);
                    if (log_motion(timestamp) == 0) {
                        if (capture_video(timestamp) != 0) {
                            fprintf(stderr, "Error capturing video\n");
                        }
                    } else {
                        fprintf(stderr, "Error logging motion event\n");
                    }
                } else {
                    fprintf(stderr, "Error getting timestamp\n");
                }
                last_trigger_tick = now;
            }
        }
        last_level = level;
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

