            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;

            if (last_trigger_tick == 0 || elapsed >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                char timestamp[TIMESTAMP_LEN];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);
                    if (log_motion(timestamp) == 0) {
                        if (capture_video(timestamp) != 0) {
                            fprintf(stderr, "Error capturing video\n");
                        }
                    } else {
                        fprintf(stderr, "Error logging motion event\n");
                    }
                } else {
                    fprintf(stderr, "Error getting timestamp\n");
                }
                last_trigger_tick = now;
            }
        }
        last_level = level;
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

