#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SAMPLE_RATE_HZ 100
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_RATE_HZ)
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpu6050_init(int handle) {
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050 (PWR_MGMT_1): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000);
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyro data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, double timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(fp, "%.3f,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mpu6050_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    int reinit_attempts = 0;
    while (running) {
        int16_t x, y, z;
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            reinit_attempts = 0;
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
            log_data(log_file, timestamp, x, y, z);
        } else {
            reinit_attempts++;
            fprintf(stderr, "Warning: I2C read failed (attempt %d/%d)\n",
                    reinit_attempts, MAX_REINIT_ATTEMPTS);
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: max re-init attempts reached, continuing without logging\n");
            } else {
                if (mpu6050_init(i2c_handle) != 0) {
                    fprintf(stderr, "Error: re-initialisation failed\n");
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

