#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_ZONE_1 4
#define RELAY_ZONE_2 17
#define RELAY_ZONE_3 27
#define RELAY_ZONE_4 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int zones[] = {RELAY_ZONE_1, RELAY_ZONE_2, RELAY_ZONE_3, RELAY_ZONE_4};
    for (size_t i = 0; i < sizeof(zones) / sizeof(zones[0]); ++i) {
        if (gpioSetMode(zones[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", zones[i]);
            return -1;
        }
        if (gpioWrite(zones[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH (relay off).\n", zones[i]);
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void)
{
    return (rand() % 100) + 1;
}

static int control_relay(int zone, int state)
{
    if (gpioWrite(zone, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", zone);
        return -1;
    }
    return 0;
}

static int log_data(int moisture, int relay1_state, int relay2_state,
                    int relay3_state, int relay4_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
                timestamp, moisture,
                relay1_state ? "ON" : "OFF",
                relay2_state ? "ON" : "OFF",
                relay3_state ? "ON" : "OFF",
                relay4_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    int zones[] = {RELAY_ZONE_1, RELAY_ZONE_2, RELAY_ZONE_3, RELAY_ZONE_4};
    for (size_t i = 0; i < sizeof(zones) / sizeof(zones[0]); ++i) {
        gpioWrite(zones[i], 1);
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = read_moisture_sensor();

        int relay1_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

        if (control_relay(RELAY_ZONE_1, relay1_state) != 0 ||
            control_relay(RELAY_ZONE_2, relay2_state) != 0 ||
            control_relay(RELAY_ZONE_3, relay3_state) != 0 ||
            control_relay(RELAY_ZONE_4, relay4_state) != 0) {
            fprintf(stderr, "Error: GPIO control failed; aborting.\n");
            break;
        }

        if (log_data(moisture, relay1_state, relay2_state, relay3_state, relay4_state) != 0) {
            fprintf(stderr, "Error: logging failed; aborting.\n");
            break;
        }

        printf("Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
               moisture,
               relay1_state ? "ON" : "OFF",
               relay2_state ? "ON" : "OFF",
               relay3_state ? "ON" : "OFF",
               relay4_state ? "ON" : "OFF");

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; ++i) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    cleanup();
    printf("Smart Greenhouse Irrigation System stopped.\n");
    return EXIT_SUCCESS;
}

