/*
 * ADXL345 free-fall detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   Alarm LED    -> GPIO27 (BCM 27, pin 13) via 330 ohm resistor to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o freefall freefall.c -lgpiod
 * Run:    ./freefall   (requires gpiod group membership or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>

#include <gpiod.h>

/* ---- ADXL345 constants (datasheet) ---- */
#define ADXL345_I2C_ADDR      0x53
#define ADXL345_REG_DEVID     0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0    0x32
#define ADXL345_DEVID_VALUE   0xE5
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_POWER_CTL_SLEEP   0x04
#define ADXL345_FILTER_BW_100HZ   0x0A
#define ADXL345_RANGE_4G          0x00

/* ---- Application constants ---- */
#define I2C_BUS_NAME   "/dev/i2c-1"
#define ALARM_GPIO     27
#define FREEFALL_THRESHOLD_G  0.2f
#define FREEFALL_DURATION_S   0.5f
#define POLL_INTERVAL_US      100000   /* 100 ms */
#define ALARM_DURATION_S      5.0f
#define LOG_FILE_NAME         "freefall.log"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int                   g_i2c_fd = -1;
static struct gpiod_chip    *g_chip   = NULL;
static struct gpiod_line    *g_alarm  = NULL;

/* ------------------------------------------------------------------ */
