    if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL,
                       ADXL345_POWER_CTL_SLEEP) != 0) {
        fprintf(stderr, "Failed to put sensor in sleep mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL,
                       ADXL345_POWER_CTL_MEASURE) != 0) {
        fprintf(stderr, "Failed to enable measurement mode.\n");
        cleanup();
        return EXIT_FAILURE;
