            usleep((useconds_t)(FREEFALL_DURATION_S * 1e6));
            if (!g_running) break;

            if (read_acceleration(g_i2c_fd, &x, &y, &z) != 0) {
                fprintf(stderr, "Read error during confirmation; continuing.\n");
                continue;
            }

            freefall = (fabsf(x) < FREEFALL_THRESHOLD_G &&
                        fabsf(y) < FREEFALL_THRESHOLD_G &&
                        fabsf(z) < FREEFALL_THRESHOLD_G);

            if (freefall) {
                printf("Free-fall detected!  X=%.3f Y=%.3f Z=%.3f g\n", x, y, z);
                log_event(x, y, z);

