                    /* Keep the alarm on for 5 seconds, checking for shutdown. */
                    for (int i = 0; i < 50 && g_running; i++) {
                        usleep(100000); /* 100 ms slices */
                    }
                    if (gpiod_line_set_value(g_alarm, 0) < 0) {
                        fprintf(stderr, "Failed to set alarm low: %s\n",
                                strerror(errno));
                    }
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

