#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400.0
#define MAX_PULSE_US 23200
#define TIMEOUT_US 100000
#define TRIG_PULSE_US 10
#define LOOP_DELAY_US 200000
#define TICKS_PER_US 1.0 / 1000.0

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile int g_echo_received = 0;
static volatile int g_echo_timeout = 0;
static FILE *g_log_file = NULL;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t g_running = 1;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_received = 0;
        g_echo_timeout = 0;
    } else if (level == 0) {
        g_end_tick = tick;
        g_echo_received = 1;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        return -1;
    }

    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise TRIG_PIN low\n");
        return -1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN high\n");
        return;
    }
    gpioDelay(TRIG_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN low\n");
    }
}

static double calculate_distance_cm(uint32_t pulse_us)
{
    return (double)pulse_us * 0.01715;
}

static void log_distance(double distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_file, "%s.%09ld,%.2f\n", timestamp, ts.tv_nsec, distance) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    } else {
        fflush(g_log_file);
    }
}

int main(void)
{
