#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x19
#define BUZZER_GPIO 17
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define BUZZER_DURATION_US 1000000

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte_retry(int handle, uint8_t reg, uint8_t value) {
    int result;
    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %d\n", reg, i + 1, RETRY_COUNT, result);
        if (i < RETRY_COUNT - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_byte_retry(int handle, uint8_t reg, uint8_t *value) {
    int result;
    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) { *value = (uint8_t)result; return 0; }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %d\n", reg, i + 1, RETRY_COUNT, result);
        if (i < RETRY_COUNT - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_block_retry(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int result;
    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (result == (int)len) return 0;
        fprintf(stderr, "I2C block read from reg 0x%02X failed (attempt %d/%d): %d\n", reg, i + 1, RETRY_COUNT, result);
        if (i < RETRY_COUNT - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int init_lis3dh(int handle) {
    if (i2c_write_byte_retry(handle, CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Failed to set CTRL_REG1 (normal mode, all axes enabled)\n");
        return -1;
    }
    if (i2c_write_byte_retry(handle, CTRL_REG4, 0x38) != 0) {
        fprintf(stderr, "Failed to set CTRL_REG4 (high resolution, +/- 2g)\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block_retry(handle, OUT_X_L, buf, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void activate_buzzer(int gpio_pin, int duration_us) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(duration_us);
    gpioWrite(gpio_pin, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) freefall_threshold = atof(argv[1]);
    if (argc > 2) impact_threshold = atof(argv[2]);

    if (freefall_threshold <= 0.0f || impact_threshold <= 0.0f || freefall_threshold >= impact_threshold) {
        fprintf(stderr, "Invalid thresholds: freefall must be > 0 and < impact\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring for freefall and impact (freefall < %.2f g, impact > %.2f g)...\n", freefall_threshold, impact_threshold);

    bool in_freefall = false;

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(100000);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude < freefall_threshold && !in_freefall) {
            printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
            in_freefall = true;
        } else if (magnitude > impact_threshold && in_freefall) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer(BUZZER_GPIO, BUZZER_DURATION_US);
            in_freefall = false;
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

