#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x19
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_STATUS 0x27
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33
#define LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lis3dh(int handle) {
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL1, 0x57) < 0) return -1;
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL4, 0x08) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, buf, 6) != 6) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;
    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int lis3dh_addr = LIS3DH_ADDR;
    float threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            lis3dh_addr = (int)strtol(argv[i + 1], NULL, 16);
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = (float)atof(argv[i + 1]);
            i++;
        }
    }

    if (threshold <= 0.0f) {
        fprintf(stderr, "Threshold must be greater than 0.\n");
        return 0;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (non-hardware environment).\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, lis3dh_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", lis3dh_addr, i2c_handle);
        gpioTerminate();
        return 0;
    }

    int who = i2cReadByteData(i2c_handle, LIS3DH_REG_WHO_AM_I);
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "LIS3DH not detected (WHO_AM_I=0x%02X, expected 0x%02X).\n", who, LIS3DH_WHO_AM_I_VAL);
        cleanup();
        return 0;
    }

    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing LIS3DH.\n");
        cleanup();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z);
                printf("Threshold exceeded! Logging and shutting down.\n");
                system("sudo shutdown -h now");
                break;
            }
        } else {
            fprintf(stderr, "Error reading acceleration data.\n");
            x = y = z = 0.0f;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

