/*
 * Autonomous line-following robot for Raspberry Pi 5.
 * Sensor : SunFounder 3-Way Tracking Sensor (digital IR reflectance)
 * Wiring (BCM numbering):
 *   Left sensor   -> GPIO4
 *   Center sensor -> GPIO17
 *   Right sensor  -> GPIO27
 *   Alert LED/buzzer -> GPIO22 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o line_follower line_follower.c -lgpiod
 * Run:    sudo ./line_follower   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_PIN          22

#define BUFFER_SIZE        5
#define POLL_INTERVAL_MS   10
#define ALERT_DURATION_S   2

#define GPIO_CHIP_NAME     "/dev/gpiochip0"

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip   = NULL;
static struct gpiod_line  *g_left   = NULL;
static struct gpiod_line  *g_center = NULL;
static struct gpiod_line  *g_right  = NULL;
static struct gpiod_line  *g_alert  = NULL;

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
typedef struct {
    int   data[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void cb_add(CircularBuffer *cb, int value)
{
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static int cb_count(const CircularBuffer *cb)
{
    return cb->count;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_alert) {
        gpiod_line_set_value(g_alert, 0);
        gpiod_line_release(g_alert);
        g_alert = NULL;
    }
    if (g_right) {
        gpiod_line_release(g_right);
        g_right = NULL;
    }
    if (g_center) {
        gpiod_line_release(g_center);
        g_center = NULL;
    }
    if (g_left) {
        gpiod_line_release(g_left);
        g_left = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(struct gpiod_line *line, const char *name)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "[ERROR] %s read failed: %s\n", name, strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Motor control (placeholder)                                        */
/* ------------------------------------------------------------------ */
static void move_forward(void)
{
    printf("Motor: FORWARD\n");
}

static void turn_left(void)
{
    printf("Motor: LEFT\n");
}

static void turn_right(void)
{
    printf("Motor: RIGHT\n");
}

static void stop_motors(void)
{
    printf("Motor: STOP\n");
}

/* ------------------------------------------------------------------ */
/* Alert                                                               */
/* ------------------------------------------------------------------ */
static void trigger_alert(void)
{
    printf("[ALERT] No line detected for 5 consecutive readings!\n");
    if (gpiod_line_set_value(g_alert, 1) < 0) {
        fprintf(stderr, "[ERROR] Alert LED ON failed: %s\n", strerror(errno));
        return;
    }
    sleep(ALERT_DURATION_S);
    if (gpiod_line_set_value(g_alert, 0) < 0)
        fprintf(stderr, "[ERROR] Alert LED OFF failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    CircularBuffer sensor_buffer;
    cb_init(&sensor_buffer);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    g_chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "[ERROR] gpiod_chip_open(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    g_left   = gpiod_chip_get_line(g_chip, LEFT_SENSOR_PIN);
    g_center = gpiod_chip_get_line(g_chip, CENTER_SENSOR_PIN);
    g_right  = gpiod_chip_get_line(g_chip, RIGHT_SENSOR_PIN);
