#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x10
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0f
#define SAMPLE_INTERVAL_US 100000
#define POLL_TIMEOUT_US 50000
#define POLL_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        perror("fopen(magnetic_events.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "<unknown time>: %s\n", message);
    }
    fclose(fp);
}

static int read_si7210(int handle, float *magnetic_field) {
    char buf[2];
    int rc;

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        log_event("I2C read error");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *magnetic_field = (float)raw / 100.0f;
    return 0;
}

static int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        log_event("gpioWrite relay error");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_event("gpioSetMode relay failed");
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("i2cOpen failed");
        gpioTerminate();
        return 1;
    }

    int relay_state = 0;
    int consecutive_errors = 0;

    while (running) {
        float magnetic_field = 0.0f;

        if (read_si7210(i2c_handle, &magnetic_field) != 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                log_event("Too many consecutive I2C errors, aborting");
                break;
            }
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(1000000);
            continue;
        }
        consecutive_errors = 0;

        char msg[128];
        snprintf(msg, sizeof(msg), "Magnetic field: %.2f mT", magnetic_field);
        log_event(msg);

        if (magnetic_field > THRESHOLD_MT) {
            if (relay_state == 0) {
                if (control_relay(RELAY_GPIO, 1) == 0) {
                    relay_state = 1;
                    log_event("Relay activated");
                }
            }
        } else {
            if (relay_state == 1) {
                if (control_relay(RELAY_GPIO, 0) == 0) {
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

