/*
 * flow_monitor.c — Raspberry Pi Zero W
 *
 * Monitors two Sensirion SLF3S-1300F liquid-flow sensors (40 ml/min)
 * on I2C bus 1 and controls a safety relay on GPIO 18 (BCM).
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lgpiod
 * Run:    ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define SENSOR1_ADDR       0x20
#define SENSOR2_ADDR       0x21
#define RELAY_GPIO         18          /* BCM pin */
#define FLOW_THRESHOLD     5.0f        /* ml/min */
#define POLL_INTERVAL_MS   100
#define LOG_FILE           "flow_log.txt"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_h1 = -1;
static int      g_i2c_h2 = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_relay = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_relay) {
        gpiod_line_set_value(g_relay, 0);   /* de-energize relay */
        gpiod_line_release(g_relay);
        g_relay = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_h1 >= 0) {
        i2c_close(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2c_close(g_i2c_h2);
        g_i2c_h2 = -1;
    }
    /* gpiod_cleanup() is called by the library on exit, but we call it explicitly. */
    gpiod_cleanup();
}

/* ---- Read flow rate from one sensor ----
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t cmd[2] = {0x36, 0x08};   /* start continuous measurement */
    uint8_t buf[3];

    if (i2c_write(handle, (char *)cmd, 2, 0) != 0) {
        fprintf(stderr, "[WARN] I2C write failed on handle %d: %s\n",
                handle, strerror(errno));
        return -1;
    }

    /* Datasheet: first measurement is ready after ~45 ms; we wait 50 ms. */
    usleep(50000);

    ssize_t n = i2c_read(handle, (char *)buf, 3, 0);
    if (n != 3) {
        fprintf(stderr, "[WARN] I2C read failed on handle %d: got %zd bytes, %s\n",
                handle, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d\n", handle);
        return -2;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_out = (float)raw / 1000.0f;   /* ml/min */
    return 0;
}

/* ---- Log flow rates with millisecond timestamp ---- */
static void log_flow_rates(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[WARN] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm;
        localtime_r(&ts.tv_sec, &tm);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
                tbuf, ts.tv_nsec / 1000000, f1, f2);
    } else {
        fprintf(fp, "[timestamp-error], Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
                f1, f2);
    }

    fflush(fp);
    fclose(fp);
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize gpiod */
    if (gpiod_init() != 0) {
        fprintf(stderr, "[ERROR] gpiod_init failed\n");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (gpiochip0 on Pi Zero W) */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "[ERROR] gpiod_chip_open: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_relay = gpiod_chip_get_line(g_chip, RELAY_GPIO);
    if (!g_relay) {
        fprintf(stderr, "[ERROR] gpiod_chip_get_line(%d): %s\n",
                RELAY_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_relay, "flow_monitor", 0) != 0) {
        fprintf(stderr, "[ERROR] gpiod_line_request_output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open I2C handles for both sensors */
    g_i2c_h1 = i2c_open(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "[ERROR] i2c_open(bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, SENSOR1_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = i2c_open(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "[ERROR] i2c_open(bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, SENSOR2_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started.  Threshold: %.1f ml/min  Relay: BCM %d\n",
           FLOW_THRESHOLD, RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_flow_rate(g_i2c_h1, &f1);
        int r2 = read_flow_rate(g_i2c_h2, &f2);

        if (r1 == 0 && r2 == 0) {
            log_flow_rates(f1, f2);

            bool below = (f1 < FLOW_THRESHOLD) || (f2 < FLOW_THRESHOLD);
            if (gpiod_line_set_value(g_relay, below ? 1 : 0) != 0) {
                fprintf(stderr, "[WARN] gpiod_line_set_value: %s\n", strerror(errno));
            }
        } else {
            /* On error, ensure relay is de-energized for safety */
            (void)gpiod_line_set_value(g_relay, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* ---- Shutdown ---- */
    printf("\nShutting down...\n");
    (void)gpiod_line_set_value(g_relay, 0);
    cleanup();
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

