#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define SERVO_LOCK_PW  2000   /* microseconds */
#define SERVO_UNLOCK_PW 1000 /* microseconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pin, int pulsewidth)
{
    int rc = gpioServo(pin, pulsewidth);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed on pin %d (rc=%d)\n", pin, rc);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses and release the bus */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure servo pin as output */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set lock button pin %d as input\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set unlock button pin %d as input\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on lock button pin %d\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on unlock button pin %d\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");
    printf("  Lock button : GPIO %d (press to lock)\n", LOCK_BUTTON);
    printf("  Unlock button: GPIO %d (press to unlock)\n", UNLOCK_BUTTON);
    printf("  Servo       : GPIO %d\n", SERVO_PIN);
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            /* Button pressed (active low with pull-up) */
            printf("Locking door...\n");
            fflush(stdout);
            if (set_servo_pulse(SERVO_PIN, SERVO_LOCK_PW) != 0) {
                fprintf(stderr, "Failed to send lock pulse\n");
            } else {
                printf("Door locked.\n");
                fflush(stdout);
            }
            /* Debounce: wait for button release and a short delay */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                usleep(10000); /* 10 ms */
            }
            usleep(50000);    /* 50 ms */
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            /* Button pressed (active low with pull-up) */
            printf("Unlocking door...\n");
            fflush(stdout);
            if (set_servo_pulse(SERVO_PIN, SERVO_UNLOCK_PW) != 0) {
                fprintf(stderr, "Failed to send unlock pulse\n");
            } else {
                printf("Door unlocked.\n");
                fflush(stdout);
            }
            /* Debounce: wait for button release and a short delay */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                usleep(10000); /* 10 ms */
            }
            usleep(50000);    /* 50 ms */
        }

        usleep(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

