#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO        4
#define FLOODLIGHT_GPIO 17
#define LOG_FILE        "security_log.txt"
#define POLL_DELAY_US   100000   /* 100 ms */
#define FLOODLIGHT_ON_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(FILE *fp, const char *event, int duration)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - %s", timestamp, event) < 0) {
        fprintf(stderr, "fprintf failed\n");
        return -1;
    }
    if (duration >= 0) {
        if (fprintf(fp, " (Duration: %d seconds)", duration) < 0) {
            fprintf(stderr, "fprintf failed\n");
            return -1;
        }
    }
    if (fputc('\n', fp) == EOF) {
        fprintf(stderr, "fputc failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

static int control_floodlight(int on)
{
    if (gpioWrite(FLOODLIGHT_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(%d) failed\n", FLOODLIGHT_GPIO);
        return -1;
    }
    return 0;
}

int main(void)
{
    FILE *fp = NULL;
    int pigpio_initialized = 0;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(PIR_GPIO) failed\n");
        goto cleanup;
    }
    if (gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FLOODLIGHT_GPIO) failed\n");
        goto cleanup;
    }
    if (control_floodlight(0) < 0) {
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Monitoring PIR sensor on GPIO %d. Floodlight on GPIO %d. Press Ctrl+C to exit.\n",
           PIR_GPIO, FLOODLIGHT_GPIO);

    while (g_running) {
        if (gpioRead(PIR_GPIO) == 1) {
            printf("Motion detected!\n");

            if (log_event(fp, "Motion detected", -1) < 0) {
