#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <stdarg.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define MAX_BUFFER 1024
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_FREQ 50

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    syslog(LOG_INFO, "%s", timestamp);
    fprintf(log_file, "%s ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    fflush(log_file);
    va_end(args);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message("Invalid angle: %d", angle);
        return -1;
    }
    int pulse = SERVO_MIN_PULSE + (int)((float)angle / 180.0f * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        log_message("gpioServo failed for angle %d", angle);
        return -1;
    }
    return 0;
}

static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_message("gpioRead failed for PIR sensor");
        return -1;
    }
    return value;
}

static void handle_client(int client_fd) {
    char buffer[MAX_BUFFER];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, MAX_BUFFER - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        char *newline = strpbrk(buffer, "\r\n");
        if (newline) *newline = '\0';

        char *command = strtok(buffer, " ");
        if (command == NULL) {
            log_message("Empty command received");
            continue;
        }

        if (strcmp(command, "the") == 0) {
            char *api_call = strtok(NULL, " ");
            if (api_call == NULL) {
                log_message("Missing API call after 'the'");
                continue;
            }
            char *angle_str = strtok(NULL, " ");
            if (angle_str == NULL) {
                log_message("Missing angle after API call");
                continue;
            }
            int angle = atoi(angle_str);
            if (angle < 0 || angle > 180) {
                log_message("Invalid angle: %d", angle);
                continue;
            }
            if (set_servo_angle(angle) == 0) {
                char response[MAX_BUFFER];
                snprintf(response, sizeof(response), "OK: Servo set to %d degrees", angle);
                send(client_fd, response, strlen(response), 0);
            } else {
                const char *response = "ERROR: Failed to set servo angle";
                send(client_fd, response, strlen(response), 0);
            }
        } else if (strcmp(command, "PIR") == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value < 0) {
                const char *response = "ERROR: Failed to read PIR sensor";
                send(client_fd, response, strlen(response), 0);
            } else {
                char response[MAX_BUFFER];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                send(client_fd, response, strlen(response), 0);
            }
        } else {
            const char *response = "ERROR: Invalid command";
            send(client_fd, response, strlen(response), 0);
        }
    }

    if (bytes_received < 0) {
        log_message("recv failed: %s", strerror(errno));
    }
    close(client_fd);
    log_message("Client disconnected");
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        cleanup();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_message("Failed to set SERVO_PIN mode");
        cleanup();
        return 1;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_message("Failed to set PIR_PIN mode");
        cleanup();
        return 1;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        log_message("Socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("setsockopt failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message("Bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message("Listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    log_message("Listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (running) {
                log_message("Accept failed: %s", strerror(errno));
            }
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        log_message("Connection accepted from %s", client_ip);
        handle_client(client_fd);
    }

    log_message("Shutting down gracefully");
    cleanup();
    return 0;
}

