#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR             0x23
#define BH1750_POWER_ON         0x01
#define BH1750_RESET            0x07
#define BH1750_CONT_HIGH_RES    0x10
#define BH1750_MEASUREMENT_MS   120
#define GROW_LIGHT_GPIO         23
#define LUX_THRESHOLD           150.0f
#define LOG_FILE                "grow_log.txt"
#define SAMPLE_INTERVAL_S       2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int bh1750_write(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd=0x%02X)\n", cmd);
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux_out)
{
    if (lux_out == NULL) {
        return -1;
    }

    if (bh1750_write(handle, BH1750_POWER_ON) < 0) {
        return -1;
    }
    if (bh1750_write(handle, BH1750_RESET) < 0) {
        return -1;
    }

    if (bh1750_write(handle, BH1750_CONT_HIGH_RES) < 0) {
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_MS * 1000);

    char buf[2] = {0};
    int  bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "[ERROR] I2C read failed (got %d bytes, expected 2)\n", bytes);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int gpio, int state)
{
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed\n", gpio, state);
    }
}

static void log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return;
    }
    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    control_relay(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
