    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(1, 0x%02X) failed: %d\n", BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", GROW_LIGHT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_relay(GROW_LIGHT_GPIO, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light controller started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(g_i2c_handle, &lux) < 0) {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        } else {
            log_data(g_log_file, lux);
            if (lux < LUX_THRESHOLD) {
                control_relay(GROW_LIGHT_GPIO, 1);
            } else {
                control_relay(GROW_LIGHT_GPIO, 0);
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

