/*
 * HX711 Load Cell Monitor with Solenoid Lock Control
 * Board:  Raspberry Pi 3 Model B+
 * Wiring:
 *   HX711 DOUT -> GPIO23 (physical pin 16)
 *   HX711 SCK  -> GPIO24 (physical pin 18)
 *   Solenoid   -> GPIO25 (physical pin 22)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hx711_lock hx711_lock.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <getopt.h>
#include <gpiod.h>

#define HX711_DOUT_PIN  23
#define HX711_SCK_PIN   24
#define SOLENOID_PIN    25

#define DEFAULT_THRESHOLD 1000.0f
#define DEFAULT_SCALE     1.0f
#define DEFAULT_DURATION  200
#define NUM_READINGS      5
#define TARE_READINGS     10
#define HX711_TIMEOUT_US 1000000  /* 1 second */
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HX711 bit-bang helpers (gpiod line API)                            */
/* ------------------------------------------------------------------ */

static int hx711_wait_dout(struct gpiod_line *dout)
{
    uint64_t deadline = gpiod_line_get_time_ns(dout, NULL) + HX711_TIMEOUT_US * 1000;
    while (gpiod_line_get_value(dout) == 1) {
        uint64_t now = gpiod_line_get_time_ns(dout, NULL);
        if (now >= deadline) {
            syslog(LOG_ERR, "HX711 DOUT timeout waiting for data ready");
            return -1;
        }
    }
    return 0;
}

static int hx711_read24(struct gpiod_line *sck, struct gpiod_line *dout,
                         int32_t *out)
{
    if (hx711_wait_dout(dout) < 0)
        return -1;

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0)
            return -1;
        usleep(1);
        value <<= 1;
        if (gpiod_line_set_value(sck, 0) < 0)
            return -1;
        usleep(1);
        int bit = gpiod_line_get_value(dout);
        if (bit < 0)
            return -1;
        value |= (uint32_t)bit;
    }

    /* 25th pulse: Channel A, Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0)
        return -1;
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0)
        return -1;
    usleep(1);

    /* Sign-extend 24-bit two's-complement to 32-bit */
    if (value & 0x800000)
        value |= 0xFF000000;
    *out = (int32_t)value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    float threshold;
    float scale;
    int   solenoid_duration_ms;
} Config;

static Config g_config = {
    .threshold          = DEFAULT_THRESHOLD,
    .scale              = DEFAULT_SCALE,
    .solenoid_duration_ms = DEFAULT_DURATION,
};

static void parse_arguments(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
        case 't':
            g_config.threshold = (float)atof(optarg);
            break;
        case 's':
            g_config.scale = (float)atof(optarg);
            break;
        case 'd':
            g_config.solenoid_duration_ms = atoi(optarg);
            break;
        default:
            fprintf(stderr,
                    "Usage: %s [-t threshold_g] [-s scale_factor] [-d solenoid_ms]\n",
                    argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                         */
/* ------------------------------------------------------------------ */

static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_dout = NULL;
static struct gpiod_line *g_sck  = NULL;
static struct gpiod_line *g_sol  = NULL;

static int gpio_setup(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    g_dout = gpiod_chip_get_line(g_chip, HX711_DOUT_PIN);
    g_sck  = gpiod_chip_get_line(g_chip, HX711_SCK_PIN);
    g_sol  = gpiod_chip_get_line(g_chip, SOLENOID_PIN);
    if (!g_dout || !g_sck || !g_sol) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(g_dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static void gpio_cleanup(void)
{
    if (g_sol) {
        gpiod_line_set_value(g_sol, 0);
        gpiod_line_release(g_sol);
        g_sol = NULL;
    }
    if (g_sck) {
        gpiod_line_release(g_sck);
        g_sck = NULL;
    }
    if (g_dout) {
        gpiod_line_release(g_dout);
        g_dout = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Tare calibration                                                   */
/* ------------------------------------------------------------------ */

static int tare_hx711(void)
{
    int32_t sum = 0;
    int ok = 0;

    for (int i = 0; i < TARE_READINGS; i++) {
        int32_t raw;
        if (hx711_read24(g_sck, g_dout, &raw) == 0) {
            sum += raw;
            ok++;
        } else {
            syslog(LOG_ERR, "Tare read %d failed", i + 1);
        }
        usleep(10000); /* 10 ms between tare samples */
    }

    if (ok == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        return -1;
    }

    int32_t avg = sum / ok;
    syslog(LOG_INFO, "Tare complete. Offset: %d", avg);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Weight measurement                                                 */
/* ------------------------------------------------------------------ */

static int read_weight(int32_t *out)
{
    int32_t sum = 0;
    int ok = 0;

    for (int i = 0; i < NUM_READINGS; i++) {
        int32_t raw;
        if (hx711_read24(g_sck, g_dout, &raw) == 0) {
            sum += raw;
            ok++;
        } else {
            syslog(LOG_ERR, "Weight read %d failed", i + 1);
        }
        usleep(10000);
    }

    if (ok == 0) {
        syslog(LOG_ERR, "Weight measurement failed: no valid readings");
        return -1;
    }

    *out = sum / ok;
    return 0;
}

static float calculate_weight(int32_t raw)
{
    return ((float)raw - g_config.scale) / g_config.scale;
}

/* ------------------------------------------------------------------ */
/* Solenoid control                                                   */
/* ------------------------------------------------------------------ */

static void activate_solenoid(void)
{
    syslog(LOG_INFO, "Weight threshold exceeded. Activating solenoid lock.");
    if (gpiod_line_set_value(g_sol, 1) < 0) {
        syslog(LOG_ERR, "Failed to activate solenoid: %s", strerror(errno));
        return;
    }
    usleep(g_config.solenoid_duration_ms * 1000);
    if (gpiod_line_set_value(g_sol, 0) < 0) {
        syslog(LOG_ERR, "Failed to deactivate solenoid: %s", strerror(errno));
    }
    syslog(LOG_INFO, "Solenoid lock deactivated.");
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    parse_arguments(argc, argv);

    openlog("hx711_lock", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting HX711 load cell monitor (threshold=%.1f g, scale=%.2f)",
           g_config.threshold, g_config.scale);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_setup() < 0) {
        syslog(LOG_ERR, "GPIO setup failed. Exiting.");
        closelog();
        return EXIT_FAILURE;
    }

    if (tare_hx711() < 0) {
        syslog(LOG_ERR, "Tare failed. Exiting.");
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int32_t raw;
        if (read_weight(&raw) < 0) {
            syslog(LOG_ERR, "Weight read failed. Exiting.");
            break;
        }

        float weight = calculate_weight(raw);
        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > g_config.threshold) {
            activate_solenoid();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    gpio_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

