 * relay_controller.c — MQTT-controlled relay on Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c
 * Run:    ./relay_controller
 *
 * Hardware:
 *   - Relay module DO pin -> GPIO17 (BCM 17, physical pin 11)
 *   - Relay VCC          -> 3.3 V (or 5 V per module spec)
 *   - Relay GND          -> GND
 *   - MQTT broker:       localhost:1883
 *   - Topic:             home/lights/control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define MQTT_BROKER_ADDRESS  "localhost"
#define MQTT_BROKER_PORT     1883
#define MQTT_CLIENT_ID       "relay_controller_1"
#define MQTT_TOPIC           "home/lights/control"
#define GPIO_PIN             17
#define MQTT_KEEPALIVE       60
#define RECONNECT_DELAY_SEC  5

static volatile sig_atomic_t g_running = 1;
static int g_mqtt_connected = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_setup(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, 0) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    syslog(LOG_INFO, "GPIO%d configured as output, relay OFF (LOW)");
    return 0;
}

static void gpio_set_relay(int state)
{
    if (gpioWrite(GPIO_PIN, state) != 0)
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_PIN, state);
    else
        syslog(LOG_INFO, "GPIO%d set to %d (relay %s)",
               GPIO_PIN, state, state ? "ON" : "OFF");
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(int rc)
{
    if (rc == 0) {
        syslog(LOG_INFO, "MQTT connected (rc=%d), subscribing to %s", rc, MQTT_TOPIC);
        g_mqtt_connected = 1;
    } else {
        syslog(LOG_ERR, "MQTT connect failed (rc=%d)", rc);
    }
}

static void on_disconnect(int rc)
{
    syslog(LOG_INFO, "MQTT disconnected (rc=%d)", rc);
    g_mqtt_connected = 0;
}

static void on_message(const char *topic, const char *payload)
{
    (void)topic;

    if (payload == NULL || payload[0] == '\0') {
        syslog(LOG_ERR, "Empty or null payload on topic %s", topic);
        return;
    }

    if (strcmp(payload, "ON") == 0) {
        gpio_set_relay(1);
    } else if (strcmp(payload, "OFF") == 0) {
        gpio_set_relay(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' on topic %s", payload, topic);
    }
}

