#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_FREQ 50
#define SERVO_PERIOD 20000

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int pulse_widths[] = {1000, 1500, 2000, 500, 2500};

    for (int i = 0; i < 5; i++) {
        int pin = pins[i];
        int pw = pulse_widths[i];

