#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <stdatomic.h>
#include <pigpio.h>

#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define TICKS_PER_REVOLUTION 64
#define TARGET_RPM 50.0
#define LOOP_DELAY_US 100000
#define STALL_TIMEOUT_SEC 2

#define KP 1.0
#define KI 0.1

static volatile sig_atomic_t program_running = 1;

static atomic_int_t encoder_a_ticks = 0;
static atomic_int_t encoder_b_ticks = 0;

static volatile sig_atomic_t encoder_a_state = 0;
static volatile sig_atomic_t encoder_b_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    int phase_a = gpioRead(ENCODER_A_PHASE_A);
    int phase_b = gpioRead(ENCODER_A_PHASE_B);
    if (phase_a == encoder_a_state) return;
    encoder_a_state = phase_a;
    int new_state = (phase_a << 1) | phase_b;
    if (new_state == 0b10) atomic_fetch_add(&encoder_a_ticks, 1);
    else if (new_state == 0b01) atomic_fetch_sub(&encoder_a_ticks, 1);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    int phase_a = gpioRead(ENCODER_B_PHASE_A);
    int phase_b = gpioRead(ENCODER_B_PHASE_B);
    if (phase_a == encoder_b_state) return;
    encoder_b_state = phase_a;
    int new_state = (phase_a << 1) | phase_b;
    if (new_state == 0b10) atomic_fetch_add(&encoder_b_ticks, 1);
    else if (new_state == 0b01) atomic_fetch_sub(&encoder_b_ticks, 1);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT);
    gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_PHASE_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_B, PI_PUD_UP);
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, EITHER_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to set ISR for Encoder A phase A.\n");
        return -1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, EITHER_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to set ISR for Encoder B phase A.\n");
        return -1;
    }
    return 0;
}

static void set_motor_direction(int motor, int direction) {
    if (motor == 0) {
        gpioWrite(MOTOR_A_DIR_PIN, direction);
    } else if (motor == 1) {
        gpioWrite(MOTOR_B_DIR_PIN, direction);
    }
}

static void set_motor_pwm(int motor, int pwm_value) {
    if (motor == 0) {
        gpioPWM(MOTOR_A_PWM_PIN, pwm_value);
    } else if (motor == 1) {
        gpioPWM(MOTOR_B_PWM_PIN, pwm_value);
    }
}

static int read_encoder_ticks(int motor) {
    if (motor == 0) {
        return atomic_load(&encoder_a_ticks);
    } else if (motor == 1) {
        return atomic_load(&encoder_b_ticks);
    }
    return 0;
}

static void reset_encoder_ticks(int motor) {
    if (motor == 0) {
        atomic_store(&encoder_a_ticks, 0);
    } else if (motor == 1) {
        atomic_store(&encoder_b_ticks, 0);
    }
}

static double calculate_rpm(int ticks, double dt) {
    if (dt <= 0.0) return 0.0;
    double revolutions = (double)ticks / TICKS_PER_REVOLUTION;
    return (revolutions / dt) * 60.0;
}

static int calculate_pwm(double error, double *integral, double *previous_error) {
    double delta_t = 0.1;
    *integral += error * delta_t;
    double output = KP * error + KI * (*integral);
    if (output < 0) {
        output = 0;
        *integral = 0;
    } else if (output > PWM_RANGE) {
        output = PWM_RANGE;
        *integral = 0;
    }
    *previous_error = error;
    return (int)output;
}

static void stop_motors(void) {
    set_motor_pwm(0, 0);
    set_motor_pwm(1, 0);
    set_motor_direction(0, 0);
    set_motor_direction(1, 0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }
    if (initialize_gpio() != 0) {
        return 1;
    }
    set_motor_direction(0, 1);
    set_motor_direction(1, 1);
    double integral_a = 0.0, previous_error_a = 0.0;
    double integral_b = 0.0, previous_error_b = 0.0;
    time_t last_tick_time_a = time(NULL);
    time_t last_tick_time_b = time(NULL);
    printf("Motor control started. Press Ctrl+C to exit.\n");
    while (program_running) {
        int ticks_a = read_encoder_ticks(0);
        int ticks_b = read_encoder_ticks(1);
        time_t current_time = time(NULL);
        double dt = (double)(current_time - last_tick_time_a);
        if (dt > STALL_TIMEOUT_SEC) {
            printf("Warning: Encoder A stall detected.\n");
        }
        if (dt > STALL_TIMEOUT_SEC) {
            printf("Warning: Encoder B stall detected.\n");
        }
        double rpm_a = calculate_rpm(ticks_a, dt);
        double rpm_b = calculate_rpm(ticks_b, dt);
        int pwm_a = calculate_pwm(TARGET_RPM - rpm_a, &integral_a, &previous_error_a);
        int pwm_b = calculate_pwm(TARGET_RPM - rpm_b, &integral_b, &previous_error_b);
        set_motor_pwm(0, pwm_a);
        set_motor_pwm(1, pwm_b);
        printf("Motor A: RPM = %.2f, PWM = %d\n", rpm_a, pwm_a);
        printf("Motor B: RPM = %.2f, PWM = %d\n", rpm_b, pwm_b);
        last_tick_time_a = current_time;
        last_tick_time_b = current_time;
        gpioDelay(LOOP_DELAY_US);
    }
    stop_motors();
    gpioTerminate();
    printf("Motor control stopped.\n");
    return 0;
}

