#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_US 180000
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_PIN);
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

static int read_lux(int *lux_out) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, 0x10);
    if (result < 0) {
        fprintf(stderr, "Error writing mode command to BH1750: %d\n", result);
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_US);

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from BH1750: expected 2 bytes, got %d\n", result);
        return -1;
    }

    *lux_out = (buf[0] << 8) | buf[1];
    return 0;
}

static int control_relay(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

static void log_data(int lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    int lux = 0;
    int relay_state = 0;
    int first_reading = 1;

    if (gpioInitialise() < 0) {
