#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms in microseconds */
#define LOOP_DELAY_US 10000       /* 10 ms in microseconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("[%s] Relay %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int relay_state = 0;
    int last_touch_state = 0;
    int current_touch_state = 0;
    int first_read = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-toggled relay control started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch_state < 0) {
            fprintf(stderr, "Failed to read touch sensor pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (first_read) {
            last_touch_state = current_touch_state;
            first_read = 0;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            /* Rising edge: wait for debounce and confirm touch */
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed = gpioRead(TOUCH_SENSOR_PIN);
            if (confirmed < 0) {
                fprintf(stderr, "Failed to read touch sensor pin %d during debounce\n", TOUCH_SENSOR_PIN);
                break;
            }
            if (confirmed == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Failed to write relay pin %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
                /* Wait for touch release before allowing next toggle */
                while (running) {
                    current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
                    if (current_touch_state < 0) {
                        fprintf(stderr, "Failed to read touch sensor pin %d\n", TOUCH_SENSOR_PIN);
                        running = 0;
                        break;
                    }
                    if (current_touch_state == 0) {
                        break;
                    }
                    gpioDelay(LOOP_DELAY_US);
                }
                if (!running) {
                    break;
                }
                last_touch_state = current_touch_state;
            }
        } else {
            last_touch_state = current_touch_state;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Ensure relay is OFF on exit */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn off relay on exit\n");
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

