#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO    27
#define FLOW_THRESHOLD   5.0f
#define FLOW_HYSTERESIS  0.5f
#define DEBOUNCE_US      1000000
#define SAMPLE_US        1000000
#define LOG_FILE         "water_flow.log"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (log_file == NULL) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void flow_sensor_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static float calculate_flow_rate(void) {
    int count;
    pthread_mutex_lock(&pulse_mutex);
    count = pulse_count;
    pulse_count = 0;
    pthread_mutex_unlock(&pulse_mutex);
    float rate = (float)count / 60.0f;
    return rate;
}

static void control_solenoid(float flow_rate) {
    static int solenoid_state = 1;
    if (flow_rate > FLOW_THRESHOLD && solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0);
        solenoid_state = 0;
        log_message("Solenoid valve shut off");
    } else if (flow_rate < (FLOW_THRESHOLD - FLOW_HYSTERESIS) && solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1);
        solenoid_state = 1;
        log_message("Solenoid valve opened");
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    gpioWrite(SOLENOID_GPIO, 1);
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (log_file != NULL) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on flow sensor GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid initial state\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, flow_sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        float flow_rate = calculate_flow_rate();
        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Flow rate: %.2f LPM", flow_rate);
        log_message(log_buf);
        control_solenoid(flow_rate);
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

