#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <pigpio.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_KNOWN_WEIGHT 100.0
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define PORT 12345
#define MAX_CLIENTS 5
#define MAX_BUFFER 1024
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define HX711_TIMEOUT 1000
#define STABILIZE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_sockets[MAX_CLIENTS];
static int client_count = 0;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static double known_weight = DEFAULT_KNOWN_WEIGHT;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (server_fd >= 0) {
        shutdown(server_fd, SHUT_RDWR);
        close(server_fd);
        server_fd = -1;
    }
    for (int i = 0; i < MAX_CLIENTS; i++) {
        if (client_sockets[i] >= 0) {
            shutdown(client_sockets[i], SHUT_RDWR);
            close(client_sockets[i]);
            client_sockets[i] = -1;
        }
    }
    gpioTerminate();
    exit(0);
}

static int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n",
                CONFIG_FILE, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "known_weight") == 0) {
            known_weight = atof(value);
        }
    }
    fclose(fp);
    if (calibration_factor <= 0 || known_weight <= 0) {
        fprintf(stderr, "Warning: Invalid config values. Using defaults.\n");
        calibration_factor = DEFAULT_CALIBRATION_FACTOR;
        known_weight = DEFAULT_KNOWN_WEIGHT;
    }
    printf("Config loaded: calibration_factor=%.2f, known_weight=%.2f\n",
           calibration_factor, known_weight);
    return 0;
}

static int hx711_init(void) {
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioWrite(SCK_PIN, 0);
    return 0;
}

static long hx711_read(void) {
    int timeout = HX711_TIMEOUT;
    while (gpioRead(DATA_PIN) == 1) {
        gpioDelay(1);
        if (--timeout <= 0) {
            fprintf(stderr, "Error: HX711 timeout waiting for data ready.\n");
            return -1;
        }
    }
    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(DATA_PIN)) {
            value++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);
    if (value & 0x800000) {
        value |= 0xFF000000;
    }
    return value;
}

static double hx711_get_weight(void) {
    long raw = hx711_read();
    if (raw == -1) return -1.0;
    return (double)raw / calibration_factor;
}

static int dispense_ingredient(double target_weight) {
    double actual_weight = hx711_get_weight();
    if (actual_weight < 0) {
        fprintf(stderr, "Error: Failed to read weight from HX711.\n");
        return -1;
    }
    double pulse_width = SERVO_MIN_PULSE +
        (target_weight / known_weight) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE);
    if (pulse_width < SERVO_MIN_PULSE) pulse_width = SERVO_MIN_PULSE;
    if (pulse_width > SERVO_MAX_PULSE) pulse_width = SERVO_MAX_PULSE;
    if (gpioServo(SERVO_PIN, (int)pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width.\n");
        return -1;
    }
    gpioDelay(STABILIZE_DELAY_US);
    actual_weight = hx711_get_weight();
    if (actual_weight < 0) {
        fprintf(stderr, "Error: Failed to read weight after dispensing.\n");
        return -1;
    }
    return (int)actual_weight;
}

static void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);
    fprintf(fp, "{\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error_message\":\"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message ? error_message : "");
    fclose(fp);
}

static void *handle_client(void *arg) {
    int client_socket = *(int *)arg;
    free(arg);
    char buffer[MAX_BUFFER];
    ssize_t bytes_received = recv(client_socket, buffer, MAX_BUFFER - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        double target_weight = atof(buffer);
        if (target_weight <= 0) {
            const char *err = "Invalid target weight (must be positive).";
            send(client_socket, err, strlen(err), 0);
            log_dispensing_event(target_weight, -1.0, err);
            return NULL;
        }
        int result = dispense_ingredient(target_weight);
        if (result >= 0) {
            char response[MAX_BUFFER];
            snprintf(response, sizeof(response), "Dispensed: %d grams", result);
            send(client_socket, response, strlen(response), 0);
            log_dispensing_event(target_weight, (double)result, NULL);
        } else {
            const char *err = "Dispensing failed.";
            send(client_socket, err, strlen(err), 0);
            log_dispensing_event(target_weight, -1.0, err);
        }
    } else if (bytes_received == 0) {
        printf("Client disconnected.\n");
    } else {
        fprintf(stderr, "Error receiving data: %s\n", strerror(errno));
    }
    close(client_socket);
    return NULL;
}

static int setup_server(void) {
    struct sockaddr_in address;
    int opt = 1;
    socklen_t addrlen = sizeof(address);
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket failed");
        return -1;
    }
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    printf("Server listening on 127.0.0.1:%d\n", PORT);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    hx711_init();
    read_config();
    if (setup_server() < 0) {
        gpioTerminate();
        return 1;
    }
    while (running) {
        int new_socket = accept(server_fd, NULL, NULL);
        if (new_socket < 0) {
            if (running) {
                perror("accept failed");
            }
            continue;
        }
        if (client_count < MAX_CLIENTS) {
            client_sockets[client_count++] = new_socket;
            int *new_sock = malloc(sizeof(int));
            if (!new_sock) {
                close(new_socket);
                continue;
            }
            *new_sock = new_socket;
            pthread_t thread_id;
            if (pthread_create(&thread_id, NULL, handle_client, (void *)new_sock) != 0) {
                perror("pthread_create failed");
                free(new_sock);
                close(new_socket);
            } else {
                pthread_detach(thread_id);
            }
        } else {
            const char *err = "Server full, try again later.";
            send(new_socket, err, strlen(err), 0);
            close(new_socket);
        }
    }
    for (int i = 0; i < MAX_CLIENTS; i++) {
        if (client_sockets[i] >= 0) {
            close(client_sockets[i]);
            client_sockets[i] = -1;
        }
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioTerminate();
    return 0;
}

