#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int relay_state = 0;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d to LOW\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_touch_sensor(void) {
    return gpioRead(TOUCH_SENSOR_GPIO);
}

static int toggle_relay(void) {
    relay_state = !relay_state;

    if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
        fprintf(stderr, "Error: failed to write relay GPIO %d\n", RELAY_GPIO);
        return -1;
    }

    log_relay_state(relay_state);
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce interval must be positive\n");
                    return EXIT_FAILURE;
                }
