    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d to LOW\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
