#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_PIN      18          /* BCM 18, physical pin 12 */
#define PWM_FREQUENCY  50          /* Hz  -> 20 ms period */
#define MIN_PULSE_US   500         /* SG90 minimum pulse width */
#define MAX_PULSE_US   2500        /* SG90 maximum pulse width */
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define STEP_ANGLE     10
#define INIT_ANGLE     90
#define INIT_PULSE_US  1500

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;
static int g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Terminal helpers                                                    */
/* ------------------------------------------------------------------ */
static int set_terminal_raw(int raw)
{
    struct termios tty;

    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }
    g_orig_termios = tty;

    if (raw) {
        tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);
        tty.c_iflag &= ~(IXON | IXOFF | IXANY);
        tty.c_oflag &= ~OPOST;
        tty.c_cc[VMIN]  = 1;
        tty.c_cc[VTIME] = 0;
    } else {
        tty.c_lflag |= (ICANON | ECHO | ECHOE | ECHONL | ISIG);
        tty.c_iflag |= (IXON | IXOFF | IXANY);
        tty.c_oflag |= OPOST;
        tty.c_cc[VMIN]  = 0;
        tty.c_cc[VTIME] = 0;
    }

    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int angle_to_pulse_us(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
}

static int set_servo_angle(int angle)
{
    int pulse_us = angle_to_pulse_us(angle);
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "gpioServo failed for pulse %d us: %s\n",
                pulse_us, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_initialized) {
        /* Stop sending PWM pulses to the servo pin */
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
    /* Restore terminal to canonical mode with echo */
    (void)set_terminal_raw(0);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int angle = INIT_ANGLE;
    int rc = EXIT_SUCCESS;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* --- Set up signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Put terminal in raw mode --- */
    if (set_terminal_raw(1) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Servo control on BCM GPIO%d (50 Hz PWM, %d-%d us pulse).\n",
           SERVO_PIN, MIN_PULSE_US, MAX_PULSE_US);
    printf("Angle: %d deg  |  keys: '+' (up), '-' (down), 'q' (quit)\n", angle);
    printf("Press 'q' or Ctrl-C to exit.\n");
    fflush(stdout);

    /* --- Main loop --- */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            /* Signal received while waiting for input */
            break;
        }

        switch (c) {
        case '+':
            angle += STEP_ANGLE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            break;
        case '-':
            angle -= STEP_ANGLE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            break;
        case 'q':
        case '\n':
        case '\r':
            goto exit_loop;
        default:
            continue;  /* ignore other characters */
        }

        if (set_servo_angle(angle) != 0) {
            rc = EXIT_FAILURE;
            goto exit_loop;
        }

        printf("Angle: %d deg\n", angle);
        fflush(stdout);
    }

exit_loop:
    cleanup();
    printf("\nExiting.\n");
    return rc;
}

