    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    struct timespec start_time, current_time;
    long pulse_count = 0;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events_flags(line, "motor_rpm",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_rising_edge_events_flags");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start_time) != 0) {
        perror("clock_gettime");
        goto cleanup;
    }

    printf("Monitoring motor RPM on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec debounce_start;
        int event_available;

        event_available = gpiod_line_event_wait(line, NULL);
        if (event_available < 0) {
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (event_available == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) != 0) {
            perror("gpiod_line_event_read");
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &debounce_start) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        while (program_running) {
            struct gpiod_line_event event2;
            if (gpiod_line_event_wait(line, &(struct timespec){0, 1000000}) != 0) {
                break;
            }
            if (gpiod_line_event_read(line, &event2) != 0) {
                break;
            }
            if (event2.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
                break;
            }
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
                perror("clock_gettime");
                goto cleanup;
            }
            long diff_ms = (current_time.tv_sec - debounce_start.tv_sec) * 1000L +
                           (current_time.tv_nsec - debounce_start.tv_nsec) / 1000000L;
            if (diff_ms > DEBOUNCE_MS) {
                break;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        double elapsed = (current_time.tv_sec - start_time.tv_sec) +
                         (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        if (elapsed >= SAMPLE_INTERVAL_S) {
            double rpm = calculate_rpm(pulse_count, elapsed);
            if (log_rpm(log_file, rpm) != 0) {
                goto cleanup;
            }
            printf("RPM: %.2f\n", rpm);
            fflush(stdout);
            pulse_count = 0;
            start_time = current_time;
        } else {
            pulse_count++;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return ret;
}

