#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000
#define MAX_TOUCH_DURATION_US 10000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        safe_write(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch_state = 0;
    uint32_t touch_start_tick = 0;
    uint32_t last_poll_tick = gpioTick();

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state != last_touch_state) {
            last_touch_state = touch_state;
            if (touch_state == 1) {
                relay_state = !relay_state;
                if (safe_write(RELAY_PIN, relay_state) != 0) {
                    break;
                }
                touch_start_tick = gpioTick();
                printf("Touch detected, relay toggled to %d\n", relay_state);
            } else {
                if (touch_start_tick != 0) {
                    uint32_t elapsed = gpioTick() - touch_start_tick;
                    if (elapsed > MAX_TOUCH_DURATION_US) {
                        printf("Touch duration exceeded, forcing relay OFF\n");
                        if (safe_write(RELAY_PIN, 0) != 0) {
                            break;
                        }
                        relay_state = 0;
                        touch_start_tick = 0;
                    }
                }
            }
        }

        last_poll_tick = gpioTick();
        usleep(POLL_DELAY_US);
    }

    safe_write(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

