#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_RANGE          255
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define FLOW_THRESHOLD     0.01    /* 100 ppm = 0.01 L/min */

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_flow_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_flow_count++;
}

static double calculate_flow_rate(void)
{
    static uint32_t last_count = 0;
    uint32_t current_count = g_flow_count;
    uint32_t delta = current_count - last_count;
    last_count = current_count;
    return (double)delta * FLOW_THRESHOLD;
}

static int set_valve_position(int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(VALVE_PWM_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", VALVE_PWM_PIN);
        return -1;
    }
    return 0;
}

static void log_data(double flow_rate, int valve_position)
{
    if (g_log_file == NULL) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s.%03ld,%.4f,%d\n",
            timestamp, ts.tv_nsec / 1000000, flow_rate, valve_position);
    fflush(g_log_file);
}

static void cleanup(void)
{
    set_valve_position(0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    double target_flow_rate = 0.0;

    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (optind != argc) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: target flow rate must be positive\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PWM pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for enable pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for PWM pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for PWM pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite failed to enable valve\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening flow_log.csv");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proportional valve control started. Target: %.2f L/min\n", target_flow_rate);

    while (g_running) {
        double flow_rate = calculate_flow_rate();
        int valve_position = set_valve_position((int)(target_flow_rate * 10.0));
        log_data(flow_rate, valve_position);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

