#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENA 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define TARGET_SPEED 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME 0.1
#define PWM_FREQ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ)
#define MAX_DUTY 255

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6];
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;
static int encoder1_count = 0;
static int encoder2_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int motor, int speed) {
    if (speed > MAX_DUTY) speed = MAX_DUTY;
    if (speed < -MAX_DUTY) speed = -MAX_DUTY;
    int ena, in1, in2;
    if (motor == 1) { ena = MOTOR1_ENA; in1 = MOTOR1_IN1; in2 = MOTOR1_IN2; }
    else { ena = MOTOR2_ENA; in1 = MOTOR2_IN3; in2 = MOTOR2_IN4; }
    if (gpiod_line_set_value(motor_lines[ena], 1) < 0) return -1;
    if (gpiod_line_set_value(motor_lines[in1], (speed > 0) ? 1 : 0) < 0) return -1;
    if (gpiod_line_set_value(motor_lines[in2], (speed < 0) ? 1 : 0) < 0) return -1;
    return 0;
}

static int read_encoder(int *count) {
    pthread_mutex_lock(&encoder_mutex);
    int val = gpiod_line_get_value(motor_lines[ENCODER1_A]);
    if (val < 0) { pthread_mutex_unlock(&encoder_mutex); return -1; }
    int b = gpiod_line_get_value(motor_lines[ENCODER1_B]);
    if (b < 0) { pthread_mutex_unlock(&encoder_mutex); return -1; }
    if (val == 1 && b == 0) encoder1_count++;
    else if (val == 0 && b == 1) encoder1_count--;
    else if (val == 1 && b == 1) encoder1_count--;
    else if (val == 0 && b == 0) encoder1_count++;
    *count = encoder1_count;
    pthread_mutex_unlock(&encoder_mutex);
    return 0;
}

static int read_encoder2(int *count) {
    pthread_mutex_lock(&encoder_mutex);
    int val = gpiod_line_get_value(motor_lines[ENCODER2_A]);
    if (val < 0) { pthread_mutex_unlock(&encoder_mutex); return -1; }
    int b = gpiod_line_get_value(motor_lines[ENCODER2_B]);
    if (b < 0) { pthread_mutex_unlock(&encoder_mutex); return -1; }
    if (val == 1 && b == 0) encoder2_count++;
    else if (val == 0 && b == 1) encoder2_count--;
    else if (val == 1 && b == 1) encoder2_count--;
    else if (val == 0 && b == 0) encoder2_count++;
    *count = encoder2_count;
    pthread_mutex_unlock(&encoder_mutex);
    return 0;
}

static double calculate_rpm(int count, double dt) {
    if (dt <= 0.0) return 0.0;
    return (double)count / dt * 60.0;
}

static double pid_control(double setpoint, double actual, double *integral, double *prev_error) {
    double error = setpoint - actual;
    *integral += error * SAMPLE_TIME;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    double derivative = (error - *prev_error) / SAMPLE_TIME;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    if (output > MAX_DUTY) output = MAX_DUTY;
    if (output < -MAX_DUTY) output = -MAX_DUTY;
    return output;
}

static void log_data(double rpm1, double rpm2, double p, double i, double d, double pid_out) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f\n", ts, rpm1, rpm2, p, i, d);
    fflush(log_file);
}

static void *encoder_thread1(void *arg) {
    (void)arg;
    while (running) {
        int count;
        if (read_encoder(&count) == 0) {
            double rpm = calculate_rpm(count, SAMPLE_TIME);
            printf("Motor 1 RPM: %.2f\n", rpm);
        }
        usleep(10000);
    }
    return NULL;
}

static void *encoder_thread2(void *arg) {
    (void)arg;
    while (running) {
        int count;
        if (read_encoder2(&count) == 0) {
            double rpm = calculate_rpm(count, SAMPLE_TIME);
            printf("Motor 2 RPM: %.2f\n", rpm);
        }
        usleep(10000);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENA, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", motor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %d: %s\n", motor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_input(motor_lines[encoder_pins[i]], "encoder_input") < 0) {
            fprintf(stderr, "Failed to request input on line %d: %s\n", encoder_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    if (gpiod_line_request_both_edges_events(motor_lines[ENCODER1_A], "encoder_events") < 0) {
        fprintf(stderr, "Failed to request events on Encoder1_A: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_both_edges_events(motor_lines[ENCODER2_A], "encoder_events") < 0) {
        fprintf(stderr, "Failed to request events on Encoder2_A: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P,I,Output\n");
    fflush(log_file);

    pthread_t t1, t2;
    if (pthread_create(&t1, NULL, encoder_thread1, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1: %s\n", strerror(errno));
        goto cleanup;
    }
    if (pthread_create(&t2, NULL, encoder_thread2, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2: %s\n", strerror(errno));
        pthread_cancel(t1);
        pthread_join(t1, NULL);
        goto cleanup;
    }

    double integral1 = 0.0, prev_error1 = 0.0;
    double integral2 = 0.0, prev_error2 = 0.0;

    while (running) {
        int count1, count2;
        if (read_encoder(&count1) == 0 && read_encoder2(&count2) == 0) {
            double rpm1 = calculate_rpm(count1, SAMPLE_TIME);
            double rpm2 = calculate_rpm(count2, SAMPLE_TIME);
            double pid_out1 = pid_control(TARGET_SPEED, rpm1, &integral1, &prev_error1);
            double pid_out2 = pid_control(TARGET_SPEED, rpm2, &integral2, &prev_error2);
            set_motor_speed(1, (int)pid_out1);
            set_motor_speed(2, (int)pid_out2);
            log_data(rpm1, rpm2, KP * (TARGET_SPEED - rpm1), KI * integral1, KD * (TARGET_SPEED - rpm1 - prev_error1), pid_out1);
            printf("Motor 1: RPM=%.2f, PID=%.2f\n", rpm1, pid_out1);
            printf("Motor 2: RPM=%.2f, PID=%.2f\n", rpm2, pid_out2);
        } else {
            fprintf(stderr, "Error reading encoder, stopping motors\n");
            set_motor_speed(1, 0);
            set_motor_speed(2, 0);
        }
        usleep(100000);
    }

    pthread_cancel(t1);
    pthread_cancel(t2);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

cleanup:
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    if (log_file) fclose(log_file);
    if (chip) gpiod_chip_close(chip);
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) gpiod_line_release(motor_lines[i]);
    }
    return 0;
}

