    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENA, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", motor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %d: %s\n", motor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_input(motor_lines[encoder_pins[i]], "encoder_input") < 0) {
            fprintf(stderr, "Failed to request input on line %d: %s\n", encoder_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    if (gpiod_line_request_both_edges_events(motor_lines[ENCODER1_A], "encoder_events") < 0) {
        fprintf(stderr, "Failed to request events on Encoder1_A: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_both_edges_events(motor_lines[ENCODER2_A], "encoder_events") < 0) {
        fprintf(stderr, "Failed to request events on Encoder2_A: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P,I,Output\n");
    fflush(log_file);

    pthread_t t1, t2;
    if (pthread_create(&t1, NULL, encoder_thread1, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1: %s\n", strerror(errno));
        goto cleanup;
    }
    if (pthread_create(&t2, NULL, encoder_thread2, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2: %s\n", strerror(errno));
        pthread_cancel(t1);
        pthread_join(t1, NULL);
        goto cleanup;
    }

    double integral1 = 0.0, prev_error1 = 0.0;
    double integral2 = 0.0, prev_error2 = 0.0;

    while (running) {
        int count1, count2;
        if (read_encoder(&count1) == 0 && read_encoder2(&count2) == 0) {
            double rpm1 = calculate_rpm(count1, SAMPLE_TIME);
            double rpm2 = calculate_rpm(count2, SAMPLE_TIME);
            double pid_out1 = pid_control(TARGET_SPEED, rpm1, &integral1, &prev_error1);
            double pid_out2 = pid_control(TARGET_SPEED, rpm2, &integral2, &prev_error2);
            set_motor_speed(1, (int)pid_out1);
            set_motor_speed(2, (int)pid_out2);
            log_data(rpm1, rpm2, KP * (TARGET_SPEED - rpm1), KI * integral1, KD * (TARGET_SPEED - rpm1 - prev_error1), pid_out1);
            printf("Motor 1: RPM=%.2f, PID=%.2f\n", rpm1, pid_out1);
            printf("Motor 2: RPM=%.2f, PID=%.2f\n", rpm2, pid_out2);
        } else {
            fprintf(stderr, "Error reading encoder, stopping motors\n");
            set_motor_speed(1, 0);
            set_motor_speed(2, 0);
        }
        usleep(100000);
    }

    pthread_cancel(t1);
    pthread_cancel(t2);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

cleanup:
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    if (log_file) fclose(log_file);
    if (chip) gpiod_chip_close(chip);
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) gpiod_line_release(motor_lines[i]);
    }
    return 0;
}

