#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18
#define VALVE_1_DURATION_MS 500
#define VALVE_2_DURATION_MS 1000
#define PAUSE_DURATION_S 5
#define PAUSE_DURATION_2_S 10
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_valve(int gpio, int duration_ms, const char *valve_id) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH for %s\n", gpio, valve_id);
        return -1;
    }
    if (log_event(valve_id) != 0) {
        fprintf(stderr, "Failed to log activation of %s\n", valve_id);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW for %s\n", gpio, valve_id);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(VALVE_1_GPIO, 0);
    gpioWrite(VALVE_2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d LOW\n", VALVE_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d LOW\n", VALVE_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (activate_valve(VALVE_1_GPIO, VALVE_1_DURATION_MS, "Valve 1") != 0) {
            break;
        }
        for (int i = 0; i < PAUSE_DURATION_S && running; i++) {
            gpioDelay(1000000);
        }
        if (!running) break;

        if (activate_valve(VALVE_2_GPIO, VALVE_2_DURATION_MS, "Valve 2") != 0) {
            break;
        }
        for (int i = 0; i < PAUSE_DURATION_2_S && running; i++) {
            gpioDelay(1000000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

