    int low = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

