#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type, int gpio_pin) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: %s - GPIO %d\n",
            time_buf, ts.tv_nsec / 1000000, event_type, gpio_pin);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to activate relay on GPIO %d\n", RELAY_GPIO);
        return;
    }
    log_event("Door Unlocked", RELAY_GPIO);
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate relay on GPIO %d\n", RELAY_GPIO);
    }
    log_event("Door Locked", RELAY_GPIO);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay to off on GPIO %d\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door strike controller started. Press Ctrl+C to exit.\n");
    log_event("Controller Started", PIR_GPIO);

    int last_pir_state = 0;
    uint32_t last_event_tick = 0;

    while (running) {
        int pir_state = gpioRead(PIR_GPIO);
        if (pir_state < 0) {
            fprintf(stderr, "Error: failed to read PIR sensor on GPIO %d\n", PIR_GPIO);
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            uint32_t now_tick = gpioTick();
            if (now_tick - last_event_tick >= RATE_LIMIT_MS * 1000) {
                unlock_door();
                last_event_tick = now_tick;
            } else {
                log_event("Rate Limit Exceeded", PIR_GPIO);
            }
        }
        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("Controller Stopped", PIR_GPIO);

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during cleanup\n");
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

