    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door strike controller started. Press Ctrl+C to exit.\n");
    log_event("Controller Started", PIR_GPIO);

    int last_pir_state = 0;
    uint32_t last_event_tick = 0;

    while (running) {
        int pir_state = gpioRead(PIR_GPIO);
        if (pir_state < 0) {
            fprintf(stderr, "Error: failed to read PIR sensor on GPIO %d\n", PIR_GPIO);
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            uint32_t now_tick = gpioTick();
            if (now_tick - last_event_tick >= RATE_LIMIT_MS * 1000) {
                unlock_door();
                last_event_tick = now_tick;
            } else {
                log_event("Rate Limit Exceeded", PIR_GPIO);
            }
        }
        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("Controller Stopped", PIR_GPIO);

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during cleanup\n");
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

