#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_PATTERN_STEPS 5
#define MAX_PATTERN_STEPS 15

typedef struct {
    int motor1_duty;
    int motor2_duty;
    int duration_ms;
} PatternStep;

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_1_GPIO, PI_OUTPUT) != 0) {
