        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", MOTOR_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", MOTOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static PatternStep *generate_pattern(int num_steps) {
    PatternStep *pattern = (PatternStep *)malloc(num_steps * sizeof(PatternStep));
    if (pattern == NULL) {
        fprintf(stderr, "Error: memory allocation failed for pattern\n");
        return NULL;
    }

    for (int i = 0; i < num_steps; i++) {
        pattern[i].motor1_duty = rand() % (PWM_RANGE + 1);
        pattern[i].motor2_duty = rand() % (PWM_RANGE + 1);
        pattern[i].duration_ms = MIN_STEP_DURATION_MS + (rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1));
    }

    return pattern;
}

