        if (pattern != NULL) {
            play_pattern(pattern, num_steps);
            free(pattern);
        }

        if (!shutdown_flag) {
            gpioDelay(500000);
        }
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

