#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define WEIGHT_THRESHOLD 10.0
#define READ_TIMEOUT_US 500000
#define SAMPLE_INTERVAL_US 500000
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start > READ_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data low\n");
            return -1;
        }
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        value = (value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    value ^= 0x800000;
    *out = value;
    return 0;
}

static double calculate_weight(int32_t raw, double scale, double offset) {
    return ((double)raw - offset) / scale;
}

static int load_calibration(double *scale, double *offset) {
    FILE *fp = fopen("calibration.txt", "r");
    if (!fp) {
        *scale = 1.0;
        *offset = 0.0;
        return -1;
    }
    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fclose(fp);
        *scale = 1.0;
        *offset = 0.0;
        return -1;
    }
    fclose(fp);
    return 0;
}

static int save_calibration(double scale, double offset) {
    FILE *fp = fopen("calibration.txt", "w");
    if (!fp) return -1;
    fprintf(fp, "%.6f %.6f\n", scale, offset);
    fclose(fp);
    return 0;
}

static int calibrate_hx711(double *scale, double *offset) {
    int32_t raw_sum = 0;
    int valid = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int32_t raw;
        if (read_hx711(&raw) == 0) {
            raw_sum += raw;
            valid++;
        }
        if (i < CALIBRATION_SAMPLES - 1) gpioDelay(CALIBRATION_DELAY_US);
    }
    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid readings\n");
        return -1;
    }
    double avg = (double)raw_sum / valid;
    *offset = avg;
    *scale = 1.0;
    return 0;
}

static void log_data(double weight, double scale, double offset) {
    FILE *fp = fopen("weight_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg, Scale: %.6f, Offset: %.6f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight, scale, offset);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    double scale = 1.0, offset = 0.0;
    if (load_calibration(&scale, &offset) != 0) {
        printf("Using default calibration: scale=%.6f, offset=%.6f\n", scale, offset);
    } else {
        printf("Loaded calibration: scale=%.6f, offset=%.6f\n", scale, offset);
    }

    if (calibrate_hx711(&scale, &offset) == 0) {
        printf("Calibration complete: scale=%.6f, offset=%.6f\n", scale, offset);
        if (save_calibration(scale, offset) != 0) {
            fprintf(stderr, "Warning: failed to save calibration\n");
        }
    }

    printf("Monitoring weight... Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw;
        if (read_hx711(&raw) != 0) {
            fprintf(stderr, "HX711 read error, skipping cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw, scale, offset);
        printf("Raw: %d, Weight: %.2f kg\n", raw, weight);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight threshold exceeded! Solenoid engaged.\n");
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        log_data(weight, scale, offset);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

