#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define RAIN_THRESHOLD 3
#define MOTOR_PWM_FREQ 1000
#define MOTOR_PWM_DUTY 150
#define MOTOR_RUN_TIME_S 5
#define SENSOR_CHECK_INTERVAL_S 60
#define POST_CLOSE_COOLDOWN_S 60

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
    syslog(LOG_INFO, "%s", message);
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int value = gpioRead(RAIN_SENSOR_PIN);
        if (value < 0) {
            log_event("Error reading rain sensor.");
            return -1;
        }
        if (value == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

static int control_motor(int direction) {
    int result = 0;
    if (direction == 1) {
        result = gpioWrite(MOTOR_IN1_PIN, 1);
        if (result < 0) { log_event("Error setting IN1 high."); return -1; }
        result = gpioWrite(MOTOR_IN2_PIN, 0);
        if (result < 0) { log_event("Error setting IN2 low."); return -1; }
        result = gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY);
        if (result < 0) { log_event("Error starting PWM."); return -1; }
    } else if (direction == 0) {
        result = gpioWrite(MOTOR_IN1_PIN, 0);
        if (result < 0) { log_event("Error setting IN1 low."); return -1; }
        result = gpioWrite(MOTOR_IN2_PIN, 0);
        if (result < 0) { log_event("Error setting IN2 low."); return -1; }
        result = gpioPWM(MOTOR_PWM_PIN, 0);
        if (result < 0) { log_event("Error stopping PWM."); return -1; }
    } else {
        log_event("Invalid motor direction.");
