#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define LOCK_DURATION_SEC 5
#define WEIGHT_THRESHOLD_G 100.0
#define HX711_TIMEOUT_US 1000000
#define LOG_FILE "stock_events.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static int hx711_init(void) {
    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioWrite(SCK_PIN, 0);
    return 0;
}

static long hx711_read(void) {
    if (gpioRead(DT_PIN) == 0) {
        gpioDelay(1);
    } else {
        log_event("HX711 data line stuck high; skipping read");
        return -1;
    }

    long count = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(DT_PIN)) {
            count++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    if (count & 0x800000) {
        count |= 0xFF000000;
    }
    return count;
}

static double raw_to_grams(long raw) {
    return (double)raw / 390.0;
}

static int lock_init(void) {
    gpioSetMode(LOCK_PIN, PI_OUTPUT);
    gpioWrite(LOCK_PIN, 0);
    return 0;
}

static void lock_activate(void) {
    gpioWrite(LOCK_PIN, 1);
    log_event("Lock activated");
}

static void lock_deactivate(void) {
    gpioWrite(LOCK_PIN, 0);
    log_event("Lock deactivated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (hx711_init() != 0) {
        log_event("HX711 initialization failed");
        gpioTerminate();
        return 1;
    }

    if (lock_init() != 0) {
        log_event("Lock initialization failed");
        gpioTerminate();
        return 1;
    }

    log_event("Stock monitoring started");

    while (running) {
        long raw = hx711_read();
        if (raw == -1) {
            gpioDelay(1000000);
            continue;
        }

        double weight = raw_to_grams(raw);
        char message[128];
        snprintf(message, sizeof(message), "Weight: %.2f g", weight);
        log_event(message);

        if (weight < WEIGHT_THRESHOLD_G) {
            log_event("Weight below threshold; activating lock");
            lock_activate();
            for (int i = 0; i < LOCK_DURATION_SEC && running; i++) {
                gpioDelay(1000000);
            }
            lock_deactivate();
        }

        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    lock_deactivate();
    log_event("Stock monitoring stopped");
    gpioTerminate();
    return 0;
}

