#define HX711_DATA_PIN  4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN    27

#define WEIGHT_THRESHOLD_KG 5.0f
#define SOLENOID_HOLD_SEC   5
#define CALIBRATION_FILE    "calibration.txt"
#define LOG_FILE            "security.log"
#define HX711_TIMEOUT_MS    100
#define HX711_SETTLE_US     1000
#define HX711_HALF_US       1
#define HX711_HALF_HALF_US  1

static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_data_line = NULL;
static struct gpiod_line *g_clock_line = NULL;
static struct gpiod_line *g_solenoid_line = NULL;
static float g_calibration_factor = 1.0f;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void sleep_us(unsigned us) {
    struct timespec ts = { us / 1000000, (long)(us % 1000000) * 1000L };
    nanosleep(&ts, NULL);
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    g_data_line = gpiod_chip_get_line(g_chip, HX711_DATA_PIN);
    g_clock_line = gpiod_chip_get_line(g_chip, HX711_CLOCK_PIN);
    g_solenoid_line = gpiod_chip_get_line(g_chip, SOLENOID_PIN);
    if (!g_data_line || !g_clock_line || !g_solenoid_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(g_data_line, "hx711_data") < 0) {
        fprintf(stderr, "Failed to request data line as input: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_clock_line, "hx711_clock", 0) < 0) {
        fprintf(stderr, "Failed to request clock line as output: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_solenoid_line, "solenoid", 0) < 0) {
        fprintf(stderr, "Failed to request solenoid line as output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void gpio_cleanup(void) {
    if (g_solenoid_line) {
        gpiod_line_set_value(g_solenoid_line, 0);
        gpiod_line_release(g_solenoid_line);
        g_solenoid_line = NULL;
    }
    if (g_clock_line) {
        gpiod_line_release(g_clock_line);
        g_clock_line = NULL;
    }
    if (g_data_line) {
        gpiod_line_release(g_data_line);
        g_data_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static int read_hx711(int32_t *out) {
    if (gpiod_line_set_value(g_clock_line, 0) < 0) return -1;
    msleep(1);

    int timeout = HX711_TIMEOUT_MS;
    while (gpiod_line_get_value(g_data_line) == 1) {
        if (--timeout <= 0) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
        sleep_us(1000);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(g_clock_line, 1) < 0) return -1;
        sleep_us(HX711_HALF_US);
        value = (value << 1) | (gpiod_line_get_value(g_data_line) & 1);
        if (gpiod_line_set_value(g_clock_line, 0) < 0) return -1;
        sleep_us(HX711_HALF_US);
    }

    if (gpiod_line_set_value(g_clock_line, 1) < 0) return -1;
    sleep_us(HX711_HALF_HALF_US);
    if (gpiod_line_set_value(g_clock_line, 0) < 0) return -1;
    sleep_us(HX711_HALF_HALF_US);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out = value;
    return 0;
}

static int calibrate_hx711(float known_weight_kg) {
    int32_t raw;
    if (read_hx711(&raw) < 0) {
        fprintf(stderr, "Calibration failed: HX711 read error\n");
        return -1;
    }

    if (raw == 0) {
        fprintf(stderr, "Calibration failed: HX711 returned 0\n");
        return -1;
    }

    g_calibration_factor = (float)raw / known_weight_kg;
    printf("Calibration factor: %.6f\n", g_calibration_factor);
    return 0;
}

static int save_calibration(float factor) {
    int fd = open(CALIBRATION_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", CALIBRATION_FILE, strerror(errno));
        return -1;
    }
    if (flock(fd, LOCK_EX) < 0) {
        fprintf(stderr, "Failed to lock %s: %s\n", CALIBRATION_FILE, strerror(errno));
        close(fd);
        return -1;
    }
    if (dprintf(fd, "%.6f\n", factor) < 0) {
        fprintf(stderr, "Failed to write calibration: %s\n", strerror(errno));
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }
    if (flock(fd, LOCK_UN) < 0) {
        fprintf(stderr, "Failed to unlock %s: %s\n", CALIBRATION_FILE, strerror(errno));
        close(fd);
        return -1;
    }
    if (close(fd) < 0) {
        fprintf(stderr, "Failed to close %s: %s\n", CALIBRATION_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int load_calibration(float *factor) {
    int fd = open(CALIBRATION_FILE, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "No calibration file found, using default 1.0\n");
        *factor = 1.0f;
        return 0;
    }
    if (flock(fd, LOCK_SH) < 0) {
        fprintf(stderr, "Failed to lock %s: %s\n", CALIBRATION_FILE, strerror(errno));
        close(fd);
        return -1;
    }
    char buf[64];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n < 0) {
        fprintf(stderr, "Failed to read %s: %s\n", CALIBRATION_FILE, strerror(errno));
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    if (flock(fd, LOCK_UN) < 0) {
        fprintf(stderr, "Failed to unlock %s: %s\n", CALIBRATION_FILE, strerror(errno));
        close(fd);
        return -1;
    }
    if (close(fd) < 0) {
        fprintf(stderr, "Failed to close %s: %s\n", CALIBRATION_FILE, strerror(errno));
        return -1;
    }
    *factor = (float)atof(buf);
    printf("Loaded calibration factor: %.6f\n", *factor);
    return 0;
}

static int open_log(void) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (flock(fd, LOCK_EX) < 0) {
        fprintf(stderr, "Failed to lock %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
