        }
    }
}

static void unlock_solenoid(void) {
    if (g_solenoid_line) {
        gpiod_line_set_value(g_solenoid_line, 0);
    }
}

static void lock_solenoid(void) {
    if (g_solenoid_line) {
        gpiod_line_set_value(g_solenoid_line, 1);
    }
}

