#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN 16
#define RELAY_PIN  20
#define LOG_FILE   "relay_events.log"
#define CONSUMER   "obstacle_relay"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(FILE *fp, const char *event) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s %s\n", ts, event) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *relay_line = NULL;
    FILE *log_fp = NULL;
    int relay_state = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, CONSUMER) != 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, CONSUMER, 0) != 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            log_event(log_fp, "ERROR: sensor_read_failed");
            sleep(1);
            continue;
        }

        if (val == 0) {
            relay_state = !relay_state;
            if (gpiod_line_set_value(relay_line, relay_state) != 0) {
                fprintf(stderr, "Error writing relay: %s\n", strerror(errno));
                log_event(log_fp, "ERROR: relay_write_failed");
            } else {
                const char *state_str = relay_state ? "ON" : "OFF";
                char event_msg[64];
                snprintf(event_msg, sizeof(event_msg), "Relay toggled to %s", state_str);
                if (log_event(log_fp, event_msg) != 0) {
                    fprintf(stderr, "Error logging event\n");
                }
                printf("Obstacle detected! Relay toggled to %s\n", state_str);
            }
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    printf("Obstacle detection stopped.\n");
    return ret;
}

