/*
 * Timed Watering System — Raspberry Pi 3 Model B+
 *
 * Valve : Parker Hannifin Series 9 miniature solenoid (12 V, 1.6 W)
 * Driver: external N-channel MOSFET / relay module
 * GPIO  : BCM 18 (physical pin 12)
 *
 * Build : gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP   "gpiochip0"
#define GPIO_LINE   18          /* BCM 18 */
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Parse duration=<seconds> from the config file.
 * Returns 0 on success and stores the value in *out_duration.
 * Returns -1 on error (file not found, empty, malformed, out of range).
 */
static int parse_duration(const char *path, int *out_duration)
{
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                path, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading config file '%s': %s\n",
                    path, strerror(errno));
        } else {
            fprintf(stderr, "Config file '%s' is empty.\n", path);
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing newline / whitespace */
    line[strcspn(line, "\r\n")] = '\0';

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Config file '%s' has no '=' (malformed).\n", path);
        return -1;
    }

    char *key = line;
    char *val = eq + 1;

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Config file '%s' has unexpected key '%s'.\n",
                path, key);
        return -1;
    }

    errno = 0;
    char *end = NULL;
    long val_l = strtol(val, &end, 10);
    if (errno != 0 || end == val) {
        fprintf(stderr, "Config file '%s' has invalid duration value '%s'.\n",
                path, val);
        return -1;
    }

    if (val_l < MIN_DURATION || val_l > MAX_DURATION) {
        fprintf(stderr, "Config file '%s' duration %ld out of range [%d, %d].\n",
                path, val_l, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *out_duration = (int)val_l;
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int duration = 0;
    if (parse_duration(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);
    fflush(stdout);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, default low (valve off). */
    if (gpiod_line_request_output(line, "watering-valve", 0) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve OFF (GPIO %d low)\n", GPIO_LINE);
    fflush(stdout);

    if (g_stop) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_SUCCESS;
    }

    /* Activate valve — active-high turns the MOSFET/relay on. */
    if (gpiod_line_set_value(line, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d high: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve ON (GPIO %d high)\n", GPIO_LINE);
    fflush(stdout);

    if (g_stop) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_SUCCESS;
    }

    /* Interruptible sleep: check g_stop every second. */
    for (int remaining = duration; remaining > 0 && !g_stop; remaining--) {
        sleep(1);
    }

    if (g_stop) {
        printf("Interrupt received — shutting down.\n");
    } else {
        printf("Watering complete.\n");
    }

    /* Ensure valve is off on every exit path. */
    if (gpiod_line_set_value(line, 0) != 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d low: %s\n",
                GPIO_LINE, strerror(errno));
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

