#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Sensor GPIO pins (BCM numbering) */
#define SENSOR_LEFT   4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT  27

/* Motor PWM GPIO pins (BCM numbering) */
#define MOTOR_LEFT   22
#define MOTOR_RIGHT  23
#define MOTOR_PWM    24
#define MOTOR_PWM2   25

/* PWM frequency (Hz) */
#define PWM_FREQUENCY 1000

/* Base motor speed (0-255) */
#define BASE_SPEED 150

/* Log file name */
#define LOG_FILE "trace_log.txt"

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_terminate = 0;

/* Log file pointer */
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static int motor_set_speed(int motor_pin, int speed)
{
    if (gpioPWM(motor_pin, speed) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d: %s\n",
                motor_pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int motors_stop(void)
{
    if (motor_set_speed(MOTOR_LEFT, 0) < 0) return -1;
    if (motor_set_speed(MOTOR_RIGHT, 0) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d: %s\n",
                pin, strerror(errno));
        return -1;
    }
    /* Keywish 3-Way IR sensor: active-low digital output */
    return (v == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Control logic                                                       */
/* ------------------------------------------------------------------ */
static void control_robot(int left, int middle, int right)
{
    int left_speed, right_speed;

    if (middle == 1) {
        /* Line center: drive straight */
        left_speed  = BASE_SPEED;
        right_speed = BASE_SPEED;
    } else if (left == 1 && right == 0) {
        /* Line on left: turn right */
        left_speed  = BASE_SPEED / 2;
        right_speed = BASE_SPEED;
    } else if (right == 1 && left == 0) {
        /* Line on right: turn left */
        left_speed  = BASE_SPEED;
        right_speed = BASE_SPEED / 2;
    } else {
        /* No line: stop */
        left_speed  = 0;
        right_speed = 0;
    }

    if (motor_set_speed(MOTOR_LEFT, left_speed) < 0) return;
    if (motor_set_speed(MOTOR_RIGHT, right_speed) < 0) return;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int left, int middle, int right, int left_speed,
                     int right_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%d,%d,%d,%d,%d\n",
                timestamp, left, middle, right, left_speed, right_speed) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motors_stop();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int left, middle, right;
    int rc;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    rc = gpioSetMode(SENSOR_LEFT, PI_INPUT);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for SENSOR_LEFT: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
