#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define MEASUREMENT_DELAY_US 180000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        log_message("Error: Failed to set BH1750 to one-time high-resolution mode.");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        log_message("Error: Failed to read BH1750 data.");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *lux = (float)raw / 1.2;
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0);
    int relay_state = 0;
    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);
            if (lux < LUX_THRESHOLD) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_message("Grow lamp ON");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_message("Grow lamp OFF");
                }
            }
        } else {
            log_message("Sensor read error, continuing...");
        }
        gpioDelay(5000000);
    }
    control_relay(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

