#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_LOCK_PULSE_WIDTH 1000
#define SERVO_UNLOCK_PULSE_WIDTH 2000

#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid angle %d (must be 0-180)\n", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_WIDTH +
        (int)((float)angle / 180.0f * (float)(SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set button pins as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            printf("Lock button pressed. Locking door.\n");
            if (set_servo_angle(0) == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        } else if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            printf("Unlock button pressed. Unlocking door.\n");
            if (set_servo_angle(180) == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

