/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 * Drives two Precision Microdrives 310-101 vibration motors
 * through an external driver circuit on GPIO17 and GPIO27.
 *
 * Motors: 3 V supply, 60 mA typical.  GPIO pins are NOT directly
 * connected to the motor coils; they drive an external driver
 * circuit (e.g., NPN transistor + flyback diode) to energize the
 * coils.  This is a safety-critical design pattern to protect the
 * Pi's GPIO pins from inductive spikes and excessive current.
 *
 * Build:  gcc -O2 -Wall -Wextra -o haptic haptic.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>

#define MOTOR1_PIN  17   /* BCM 17 */
#define MOTOR2_PIN  27   /* BCM 27 */
#define PULSE1_MS   200
#define PULSE2_MS   300
#define CONSUMER    "haptic"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("Haptic feedback running.  Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1, 1)");
            goto cleanup;
        }
        usleep(PULSE1_MS * 1000);

        if (!g_running)
            break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1, 0)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2, 1)");
            goto cleanup;
        }
        usleep(PULSE2_MS * 1000);

        if (!g_running)
            break;

        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2, 0)");
            goto cleanup;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure motors are stopped before releasing lines */
    if (line1)
        (void)gpiod_line_set_value(line1, 0);
    if (line2)
        (void)gpiod_line_set_value(line2, 0);

    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return rc;
}

