#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <zmq.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_US 1000000
#define ZMQ_PORT 5555
#define ZMQ_TOPIC "SOUND_ALERTS"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_gpio_line(struct gpio_chip *chip, unsigned int offset) {
    if (chip->line_config[offset].flags & GPIO_LINE_REQUEST_DIRECTION_OUTPUT) {
        return chip->line_config[offset].output_val;
    }
    if (chip->line_config[offset].flags & GPIO_LINE_REQUEST_DIRECTION_INPUT) {
        return chip->line_config[offset].input_val;
    }
    return -1;
}

static int write_gpio_line(struct gpio_chip *chip, unsigned int offset, int value) {
    if (chip->line_config[offset].flags & GPIO_LINE_REQUEST_DIRECTION_OUTPUT) {
        chip->line_config[offset].output_val = value;
        return 0;
    }
    return -1;
}

static int request_gpio_line(struct gpio_chip *chip, unsigned int offset, unsigned int flags) {
    if (offset >= chip->num_lines) {
        fprintf(stderr, "Invalid GPIO offset %u\n", offset);
        return -1;
    }
    if (chip->line_config[offset].flags & GPIO_LINE_REQUEST_DIRECTION_INPUT) {
        fprintf(stderr, "GPIO %u already requested as input\n", offset);
        return -1;
    }
    if (chip->line_config[offset].flags & GPIO_LINE_REQUEST_DIRECTION_OUTPUT) {
        fprintf(stderr, "GPIO %u already requested as output\n", offset);
        return -1;
    }
    chip->line_config[offset].flags = flags;
    if (flags & GPIO_LINE_REQUEST_DIRECTION_OUTPUT) {
        chip->line_config[offset].output_val = 0;
    }
    return 0;
}

static void release_gpio_line(struct gpio_chip *chip, unsigned int offset) {
    if (offset < chip->num_lines) {
        chip->line_config[offset].flags = 0;
        chip->line_config[offset].output_val = 0;
        chip->line_config[offset].input_val = 0;
    }
}

static int init_gpio_chip(struct gpio_chip *chip) {
    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd < 0) {
        perror("open(" GPIO_CHIP ")");
        return -1;
    }
    if (ioctl(fd, GPIO_GET_CHIP_NAME, chip->name) < 0) {
        perror("GPIO_GET_CHIP_NAME");
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_GET_LINE_COUNT, &chip->num_lines) < 0) {
        perror("GPIO_GET_LINE_COUNT");
        close(fd);
        return -1;
    }
    chip->fd = fd;
    memset(chip->line_config, 0, sizeof(chip->line_config));
    return 0;
}

static void cleanup_gpio_chip(struct gpio_chip *chip) {
    if (chip->fd >= 0) {
        for (int i = 0; i < chip->num_lines; i++) {
            release_gpio_line(chip, i);
        }
        close(chip->fd);
        chip->fd = -1;
    }
}

static int init_zmq_publisher(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        return -1;
    }
    void *socket = zmq_socket(context, ZMQ_PUB);
    if (!socket) {
        perror("zmq_socket(PUB)");
        zmq_ctx_destroy(context);
        return -1;
    }
    int linger = 0;
    if (zmq_setsockopt(socket, ZMQ_LINGER, &linger, sizeof(linger)) < 0) {
        perror("zmq_setsockopt(LINGER)");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }
    char endpoint[64];
    snprintf(endpoint, sizeof(endpoint), "tcp://*:%d", ZMQ_PORT);
    if (zmq_bind(socket, endpoint, 0) < 0) {
        perror("zmq_bind");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }
    printf("ZMQ publisher bound to %s\n", endpoint);
    return 0;
}

static void cleanup_zmq_publisher(void *socket, void *context) {
    if (socket) {
        zmq_close(socket);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
}

static int init_zmq_subscriber(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        return -1;
    }
    void *socket = zmq_socket(context, ZMQ_SUB);
    if (!socket) {
        perror("zmq_socket(SUB)");
        zmq_ctx_destroy(context);
        return -1;
    }
    if (zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
        perror("zmq_setsockopt(SUBSCRIBE)");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }
    char endpoint[64];
    snprintf(endpoint, sizeof(endpoint), "tcp://localhost:%d", ZMQ_PORT);
    if (zmq_connect(socket, endpoint) < 0) {
        perror("zmq_connect");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }
    printf("ZMQ subscriber connected to %s\n", endpoint);
    return 0;
}

static void cleanup_zmq_subscriber(void *socket, void *context) {
    if (socket) {
        zmq_close(socket);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    struct gpio_chip chip;
    memset(&chip, 0, sizeof(chip));
    chip.name = "gpiochip0";
    chip.num_lines = 18;
    chip.fd = -1;

    if (init_gpio_chip(&chip) < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (setup_signal_handlers() < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        cleanup_gpio_chip(&chip);
        return EXIT_FAILURE;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        if (request_gpio_line(&chip, SOUND_SENSOR_PIN, GPIO_LINE_REQUEST_DIRECTION_INPUT) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input\n", SOUND_SENSOR_PIN);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        if (request_gpio_line(&chip, ALARM_LED_PIN, GPIO_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", ALARM_LED_PIN);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }

        void *zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            perror("zmq_ctx_new");
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        void *zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
        if (!zmq_socket) {
            perror("zmq_socket(PUB)");
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        int linger = 0;
        if (zmq_setsockopt(zmq_socket, ZMQ_LINGER, &linger, sizeof(linger)) < 0) {
            perror("zmq_setsockopt(LINGER)");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        char endpoint[64];
        snprintf(endpoint, sizeof(endpoint), "tcp://*:%d", ZMQ_PORT);
        if (zmq_bind(zmq_socket, endpoint, 0) < 0) {
            perror("zmq_bind");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        printf("Sound sensor mode: listening on GPIO%d, publishing to %s\n", SOUND_SENSOR_PIN, endpoint);

        while (running) {
            int sound_detected = read_gpio_line(&chip, SOUND_SENSOR_PIN);
            if (sound_detected < 0) {
                fprintf(stderr, "Failed to read sound sensor GPIO\n");
                break;
            }
            if (sound_detected == 0) {
                printf("Sound detected!\n");
                if (zmq_send(zmq_socket, ZMQ_TOPIC, strlen(ZMQ_TOPIC), 0) < 0) {
                    perror("zmq_send");
                }
            }
            usleep(POLL_INTERVAL_US);
        }

        cleanup_zmq_publisher(zmq_socket, zmq_context);
        cleanup_gpio_chip(&chip);
    } else if (strcmp(mode, "alarm_node") == 0) {
        if (request_gpio_line(&chip, ALARM_LED_PIN, GPIO_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", ALARM_LED_PIN);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }

        void *zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            perror("zmq_ctx_new");
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        void *zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (!zmq_socket) {
            perror("zmq_socket(SUB)");
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        if (zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
            perror("zmq_setsockopt(SUBSCRIBE)");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        char endpoint[64];
        snprintf(endpoint, sizeof(endpoint), "tcp://localhost:%d", ZMQ_PORT);
        if (zmq_connect(zmq_socket, endpoint) < 0) {
            perror("zmq_connect");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        printf("Alarm node mode: subscribed to %s\n", endpoint);

        while (running) {
            zmq_msg_t msg;
            int rc = zmq_msg_init(&msg);
            if (rc == 0) {
                rc = zmq_msg_recv(&msg, zmq_socket, 0);
                if (rc > 0) {
                    char *topic = (char *)zmq_msg_data(&msg);
                    if (strcmp(topic, ZMQ_TOPIC) == 0) {
                        printf("Alert received!\n");
                        if (write_gpio_line(&chip, ALARM_LED_PIN, 1) < 0) {
                            fprintf(stderr, "Failed to set alarm LED high\n");
                        }
                        usleep(ALARM_DURATION_US);
                        if (write_gpio_line(&chip, ALARM_LED_PIN, 0) < 0) {
                            fprintf(stderr, "Failed to set alarm LED low\n");
                        }
                    }
                } else if (rc < 0) {
                    if (errno != EINTR) {
                        perror("zmq_msg_recv");
                    }
                }
                zmq_msg_close(&msg);
            }
        }

        cleanup_zmq_subscriber(zmq_socket, zmq_context);
        cleanup_gpio_chip(&chip);
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

