        zmq_ctx_destroy(context);
        return -1;
    }
    printf("ZMQ subscriber connected to %s\n", endpoint);
    return 0;
}

static void cleanup_zmq_subscriber(void *socket, void *context) {
    if (socket) {
        zmq_close(socket);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    struct gpio_chip chip;
    memset(&chip, 0, sizeof(chip));
    chip.name = "gpiochip0";
    chip.num_lines = 18;
    chip.fd = -1;

    if (init_gpio_chip(&chip) < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (setup_signal_handlers() < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        cleanup_gpio_chip(&chip);
        return EXIT_FAILURE;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        if (request_gpio_line(&chip, SOUND_SENSOR_PIN, GPIO_LINE_REQUEST_DIRECTION_INPUT) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input\n", SOUND_SENSOR_PIN);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        if (request_gpio_line(&chip, ALARM_LED_PIN, GPIO_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", ALARM_LED_PIN);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }

        void *zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            perror("zmq_ctx_new");
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        void *zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
        if (!zmq_socket) {
            perror("zmq_socket(PUB)");
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        int linger = 0;
        if (zmq_setsockopt(zmq_socket, ZMQ_LINGER, &linger, sizeof(linger)) < 0) {
            perror("zmq_setsockopt(LINGER)");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        char endpoint[64];
        snprintf(endpoint, sizeof(endpoint), "tcp://*:%d", ZMQ_PORT);
        if (zmq_bind(zmq_socket, endpoint, 0) < 0) {
            perror("zmq_bind");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        printf("Sound sensor mode: listening on GPIO%d, publishing to %s\n", SOUND_SENSOR_PIN, endpoint);

        while (running) {
            int sound_detected = read_gpio_line(&chip, SOUND_SENSOR_PIN);
            if (sound_detected < 0) {
                fprintf(stderr, "Failed to read sound sensor GPIO\n");
                break;
            }
            if (sound_detected == 0) {
                printf("Sound detected!\n");
                if (zmq_send(zmq_socket, ZMQ_TOPIC, strlen(ZMQ_TOPIC), 0) < 0) {
                    perror("zmq_send");
                }
            }
            usleep(POLL_INTERVAL_US);
        }

        cleanup_zmq_publisher(zmq_socket, zmq_context);
        cleanup_gpio_chip(&chip);
    } else if (strcmp(mode, "alarm_node") == 0) {
        if (request_gpio_line(&chip, ALARM_LED_PIN, GPIO_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", ALARM_LED_PIN);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }

        void *zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            perror("zmq_ctx_new");
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        void *zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (!zmq_socket) {
            perror("zmq_socket(SUB)");
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        if (zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
            perror("zmq_setsockopt(SUBSCRIBE)");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        char endpoint[64];
        snprintf(endpoint, sizeof(endpoint), "tcp://localhost:%d", ZMQ_PORT);
        if (zmq_connect(zmq_socket, endpoint) < 0) {
            perror("zmq_connect");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_gpio_chip(&chip);
            return EXIT_FAILURE;
        }
        printf("Alarm node mode: subscribed to %s\n", endpoint);

        while (running) {
            zmq_msg_t msg;
            int rc = zmq_msg_init(&msg);
            if (rc == 0) {
                rc = zmq_msg_recv(&msg, zmq_socket, 0);
                if (rc > 0) {
                    char *topic = (char *)zmq_msg_data(&msg);
                    if (strcmp(topic, ZMQ_TOPIC) == 0) {
                        printf("Alert received!\n");
                        if (write_gpio_line(&chip, ALARM_LED_PIN, 1) < 0) {
                            fprintf(stderr, "Failed to set alarm LED high\n");
                        }
                        usleep(ALARM_DURATION_US);
                        if (write_gpio_line(&chip, ALARM_LED_PIN, 0) < 0) {
                            fprintf(stderr, "Failed to set alarm LED low\n");
                        }
                    }
                } else if (rc < 0) {
                    if (errno != EINTR) {
                        perror("zmq_msg_recv");
                    }
                }
                zmq_msg_close(&msg);
            }
        }

        cleanup_zmq_subscriber(zmq_socket, zmq_context);
        cleanup_gpio_chip(&chip);
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

