static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_alert_cb(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        uint32_t dur = tick - pulse[MAX_PULSES - 1];
        if (pulse_idx < MAX_PULSES - 1) {
            pulse[pulse_idx++] = dur;
