#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_BASE 0x23
#define BH1750_CMD_CONT_HRES 0x10
#define BH1750_CONV_TIME_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux_out) {
    unsigned char cmd = BH1750_CMD_CONT_HRES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write: %s\n", strerror(errno));
        *lux_out = NAN;
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);
    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: expected 2 bytes, got %zd (%s)\n", n, n < 0 ? strerror(errno) : "short read");
        *lux_out = NAN;
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open(I2C_BUS, BH1750_ADDR_BASE + i);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to open I2C for sensor %d\n", i + 1);
            for (int j = 0; j < i; j++) close(i2c_fds[j]);
            return 1;
        }
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) close(i2c_fds[i]);
        return 1;
    }

    while (!terminate) {
        float lux[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            lux[i] = NAN;
            if (bh1750_read(i2c_fds[i], &lux[i]) < 0) {
                fprintf(stderr, "Sensor %d read failed\n", i + 1);
            }
        }

        char data[256];
        int idx = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            idx += snprintf(data + idx, sizeof(data) - idx, "%d,%.2f%s", i + 1, lux[i], (i < NUM_SENSORS - 1) ? ";" : "");
        }
        if (send_multicast(sockfd, data) < 0) {
            fprintf(stderr, "Multicast send failed\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++) close(i2c_fds[i]);
    close(sockfd);
    return 0;
}

