#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define READ_INTERVAL  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_i2c_device(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                AWM7300V_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read two bytes from the AWM7300V.
 * The sensor returns a 14-bit flow value in the first two bytes.
 * Bits [15:2] contain the 14-bit data; bits [1:0] are reserved.
 * The value is left-justified in the 16-bit word, so we right-shift by 2.
 */
static int read_airflow_rate(int fd, float *flow_rate)
{
    uint8_t buf[2] = {0};
    ssize_t bytes_read = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Zero-length write generates a start condition (no register select). */
        if (write(fd, buf, 0) < 0) {
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor not responding at address 0x%02X (attempt %d/%d)\n",
                        AWM7300V_ADDR, attempt + 1, MAX_RETRIES);
            } else if (errno == EIO) {
                fprintf(stderr, "I2C bus error on start condition (attempt %d/%d)\n",
                        attempt + 1, MAX_RETRIES);
            } else {
                fprintf(stderr, "I2C write error (attempt %d/%d): %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /* Read two bytes of flow data. */
        bytes_read = read(fd, buf, 2);
        if (bytes_read == 2) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            uint16_t flow_value = (raw >> 2) & 0x3FFF;
            *flow_rate = (float)flow_value / 100.0f;
            return 0;
        }

        if (bytes_read < 0) {
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor not responding (attempt %d/%d)\n",
                        attempt + 1, MAX_RETRIES);
            } else if (errno == EIO) {
                fprintf(stderr, "I2C bus error on read (attempt %d/%d)\n",
                        attempt + 1, MAX_RETRIES);
            } else {
                fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            }
        } else {
            fprintf(stderr, "Short read: %zd bytes (attempt %d/%d)\n",
                    bytes_read, attempt + 1, MAX_RETRIES);
        }

        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }

    return -1;
}

static int log_airflow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void)
{
    if (install_signal_handler() != 0)
        return EXIT_FAILURE;

    g_i2c_fd = open_i2c_device();
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        float flow_rate = 0.0f;

        if (read_airflow_rate(g_i2c_fd, &flow_rate) == 0) {
            if (log_airflow_rate(g_log_fp, flow_rate) != 0) {
                fprintf(stderr, "Failed to log airflow rate.\n");
            } else {
                printf("Flow Rate: %.2f SLPM\n", flow_rate);
            }
        } else {
            fprintf(stderr, "Failed to read airflow rate after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

