            fprintf(stderr, "Failed to read airflow rate after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

