#define AS7341_EXPECTED_ID     0x34

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an AS7341 register.                              */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int as7341_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an AS7341 register.                             */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int as7341_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (out == NULL) {
        fprintf(stderr, "as7341_read_reg: NULL output pointer\n");
        return -1;
    }

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read one byte back */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at reg.                             */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int as7341_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (buf == NULL || len == 0) {
        fprintf(stderr, "as7341_read_block: invalid arguments\n");
        return -1;
    }

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read len bytes */
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                    reg, strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read from reg 0x%02X: unexpected EOF\n", reg);
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the AS7341 sensor.                                      */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (as7341_read_reg(fd, AS7341_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read AS7341 ID register.\n");
        return -1;
    }
    if (id != AS7341_EXPECTED_ID) {
        fprintf(stderr,
                "AS7341 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id, AS7341_EXPECTED_ID);
        return -1;
    }
    printf("AS7341 detected (ID = 0x%02X).\n", id);

    /* Power on */
    if (as7341_write_reg(fd, AS7341_REG_ENABLE, 0x01) != 0) {
        fprintf(stderr, "Failed to power on AS7341.\n");
        return -1;
    }
    usleep(10000); /* 10 ms power-up delay */

    /* Configure measurement time (ATIME = 256 * 2.8 ms = 704 ms) */
    if (as7341_write_reg(fd, AS7341_REG_ATIME, 0x80) != 0) {
        fprintf(stderr, "Failed to set AS7341 ATIME.\n");
        return -1;
    }

    /* Configure spectral multiplexer (SMUX) via CFG6 */
    if (as7341_write_reg(fd, AS7341_REG_CFG6, 0x00) != 0) {
        fprintf(stderr, "Failed to set AS7341 CFG6.\n");
        return -1;
    }

    /* Enable spectral measurement (SP_EN bit) */
    if (as7341_write_reg(fd, AS7341_REG_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Failed to enable AS7341 spectral measurement.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all 10 spectral channels (F1-F8, Clear, NIR).                 */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int as7341_read_channels(int fd, uint16_t *ch0, uint16_t *ch1,
                                uint16_t *ch2, uint16_t *ch3, uint16_t *ch4,
                                uint16_t *ch5, uint16_t *ch6, uint16_t *ch7,
                                uint16_t *clear, uint16_t *nir)
{
    uint8_t buf[18];

    /* Read 18 bytes starting at register 0x10 (F1..F8, Clear, NIR) */
    if (as7341_read_block(fd, 0x10, buf, sizeof(buf)) != 0) {
        return -1;
    }

    *ch0 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *ch1 = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *ch2 = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    *ch3 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    *ch4 = (uint16_t)buf[8]  | ((uint16_t)buf[9] << 8);
    *ch5 = (uint16_t)buf[10] | ((uint16_t)buf[11] << 8);
    *ch6 = (uint16_t)buf[12] | ((uint16_t)buf[13] << 8);
    *ch7 = (uint16_t)buf[14] | ((uint16_t)buf[15] << 8);
    *clear = (uint16_t)buf[16] | ((uint16_t)buf[17] << 8);
    *nir = 0; /* NIR is not exposed via the standard 18-byte block */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute a simplified lux approximation from spectral channels.     */
/* ------------------------------------------------------------------ */
static float calculate_lux(uint16_t ch0, uint16_t ch1, uint16_t ch2,
                           uint16_t ch3, uint16_t ch4, uint16_t ch5,
                           uint16_t ch6, uint16_t ch7, uint16_t clear)
{
    /* Simplified linear approximation (weights from datasheet / typical
     * plant monitoring context).  Clear channel dominates visible lux.
     */
    float lux = 0.0f;
    lux += (float)ch0 * 0.01f;
    lux += (float)ch1 * 0.02f;
    lux += (float)ch2 * 0.03f;
    lux += (float)ch3 * 0.04f;
    lux += (float)ch4 * 0.05f;
    lux += (float)ch5 * 0.06f;
    lux += (float)ch6 * 0.07f;
    lux += (float)ch7 * 0.08f;
    lux += (float)clear * 1.0f;
    return lux;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped, comma-separated line to the log file.        */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t ch0, uint16_t ch1, uint16_t ch2,
                    uint16_t ch3, uint16_t ch4, uint16_t ch5,
                    uint16_t ch6, uint16_t ch7, uint16_t clear,
                    uint16_t nir, float lux)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                ts, ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7, clear, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("spectral_log.csv", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open spectral_log.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,ch0,ch1,ch2,ch3,ch4,ch5,ch6,ch7,clear,nir,lux\n");
        fflush(g_log_fp);
    }

    printf("Logging spectral data to spectral_log.csv every 5 s. "
           "Press Ctrl+C to stop.\n");

    /* ---- Main acquisition loop ---- */
    while (g_running) {
        uint16_t ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7, clear, nir;

        if (as7341_read_channels(g_i2c_fd, &ch0, &ch1, &ch2, &ch3, &ch4,
                                 &ch5, &ch6, &ch7, &clear, &nir) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            sleep(5);
            continue;
        }

        float lux = calculate_lux(ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7, clear);

        if (log_data(g_log_fp, ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7,
                     clear, nir, lux) != 0) {
            fprintf(stderr, "Logging error; continuing.\n");
        }

        printf("ch0=%u ch1=%u ch2=%u ch3=%u ch4=%u ch5=%u ch6=%u ch7=%u "
               "clear=%u nir=%u lux=%.2f\n",
               ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7, clear, nir, lux);

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 5 && g_running; i++) {
            sleep(1);
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power off the sensor */
        (void)as7341_write_reg(g_i2c_fd, AS7341_REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

