/*
 * seismic_logger.c — Raspberry Pi Zero W
 * Reads tri-axial acceleration data from an Omron D7S seismic sensor
 * over I2C and logs timestamped X/Y/Z values (in g) to a CSV file.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic_logger seismic_logger.c
 * Run:    ./seismic_logger [-a i2c_addr] [-i interval_s] [-f filename]
 *
 * Default I2C address: 0x28  (Omron D7S default)
 * Default interval:     1 second
 * Default output:       seismic_data.csv
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDR      0x28
#define DEFAULT_INTERVAL_SEC  1
#define DEFAULT_OUTPUT_FILE   "seismic_data.csv"
#define DEFAULT_ERROR_LOG     "seismic_error.log"
#define I2C_BUS              "/dev/i2c-1"
#define MAX_RETRIES           3
#define RETRY_DELAY_MS        10
#define READ_LEN              6   /* 3 bytes X, 3 bytes Y (D7S) */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;
static FILE *g_err   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(g_err, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
    fflush(g_err);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(uint8_t addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read 6 bytes from the D7S.
 * The D7S returns 3 bytes for X, then 3 bytes for Y (Z is not exposed
 * via the standard register map; if Z is needed the register offset
 * would be adjusted accordingly).
 * Each 2-byte pair is big-endian: [MSB, LSB].
 */
static int read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t buf[READ_LEN];
    int16_t raw_x, raw_y, raw_z;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = read(fd, buf, READ_LEN);
        if (n == READ_LEN) {
            raw_x = (int16_t)((buf[0] << 8) | buf[1]);
            raw_y = (int16_t)((buf[2] << 8) | buf[3]);
            raw_z = (int16_t)((buf[4] << 8) | buf[5]);

            /* Convert to g: raw / 1000 (per D7S datasheet) */
            *x = (float)raw_x / 1000.0f;
            *y = (float)raw_y / 1000.0f;
            *z = (float)raw_z / 1000.0f;
            return 0;
        }

        if (n < 0) {
            log_error("I2C read failed");
        } else {
            log_error("I2C read short read");
        }

        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int csv_open(const char *path)
{
    g_csv = fopen(path, "a");
    if (!g_csv) {
        log_error("fopen CSV");
        return -1;
    }

    /* Write header if file is empty */
    long pos = ftell(g_csv);
    if (pos == 0) {
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv);
    }
    return 0;
}

static void csv_write(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(g_csv, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(g_csv);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_err) {
        fflush(g_err);
        fclose(g_err);
        g_err = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    uint8_t  i2c_addr  = DEFAULT_I2C_ADDR;
    int      interval  = DEFAULT_INTERVAL_SEC;
    char     out_file[256] = DEFAULT_OUTPUT_FILE;
    char     err_file[256] = DEFAULT_ERROR_LOG;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
        case 'a':
            i2c_addr = (uint8_t)strtol(optarg, NULL, 0);
            if (i2c_addr == 0 || i2c_addr > 0x7F) {
                fprintf(stderr, "Invalid I2C address: 0x%02X\n", i2c_addr);
                return EXIT_FAILURE;
            }
            break;
        case 'i':
            interval = atoi(optarg);
            if (interval <= 0) {
                fprintf(stderr, "Interval must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'f':
            strncpy(out_file, optarg, sizeof(out_file) - 1);
            out_file[sizeof(out_file) - 1] = '\0';
            break;
        default:
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Open error log first so all errors go through it */
    g_err = fopen(err_file, "a");
    if (!g_err) {
        perror("fopen error log");
        return EXIT_FAILURE;
    }

    install_signal_handlers();

    g_i2c_fd = i2c_open(i2c_addr);
    if (g_i2c_fd < 0) {
        log_error("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (csv_open(out_file) < 0) {
        log_error("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging D7S seismic data to %s (addr=0x%02X, interval=%ds) — Ctrl+C to stop.\n",
           out_file, i2c_addr, interval);

    while (g_running) {
        float x, y, z;

        if (read_accel(g_i2c_fd, &x, &y, &z) == 0) {
            csv_write(x, y, z);
        } else {
            log_error("Failed to read acceleration data after retries");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int s = 0; s < interval * 10 && g_running; s++)
            usleep(100 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

