#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B921600
#define CSV_FILE "radar_data.csv"
#define MAX_BUFFER_SIZE 4096
#define MAGIC_WORD_SIZE 8
#define MAX_OBJECTS 100

#define MMWAVE_MAGIC_WORD_0 0x0201
#define MMWAVE_MAGIC_WORD_1 0x0304
#define MMWAVE_MAGIC_WORD_2 0x0506
#define MMWAVE_MAGIC_WORD_3 0x0708

#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_DOPPLER 2
#define TLV_TYPE_NOISE_PROFILE 3
#define TLV_TYPE_AZIMUT_HEAT_MAP 4
#define TLV_TYPE_RANGE_PROFILE 5
#define TLV_TYPE_STATS 6
#define TLV_TYPE_TARGET_TRACKING 7
#define TLV_TYPE_AZIMUT_HEAT_MAP_2 8
#define TLV_TYPE_RANGE_DOPPLER_2 9
#define TLV_TYPE_TARGET_TRACKING_2 10

#define MAX_FRAME_SIZE 8192

typedef struct {
    uint32_t magic_word[4];
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} __attribute__((packed)) mmw_frame_header_t;

typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) mmw_tlv_header_t;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} __attribute__((packed)) mmw_detected_point_t;

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int find_magic_word(const uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        uint32_t w0 = (uint32_t)buf[i];
        uint32_t w1 = (uint32_t)buf[i + 1];
        uint32_t w2 = (uint32_t)buf[i + 2];
        uint32_t w3 = (uint32_t)buf[i + 3];
        if (w0 == MMWAVE_MAGIC_WORD_0 && w1 == MMWAVE_MAGIC_WORD_1 &&
            w2 == MMWAVE_MAGIC_WORD_2 && w3 == MMWAVE_MAGIC_WORD_3) {
            return i;
        }
    }
    return -1;
}

static int process_frame(const uint8_t *frame, int frame_len) {
    if (frame_len < (int)sizeof(mmw_frame_header_t)) {
        fprintf(stderr, "Frame too short for header\n");
        return -1;
    }

    const mmw_frame_header_t *hdr = (const mmw_frame_header_t *)frame;
    if (hdr->total_packet_len > MAX_FRAME_SIZE) {
        fprintf(stderr, "Invalid total packet length: %u\n", hdr->total_packet_len);
        return -1;
    }

    if (frame_len < (int)hdr->total_packet_len) {
        fprintf(stderr, "Frame incomplete: have %d, need %u\n", frame_len, hdr->total_packet_len);
        return -1;
    }

    int offset = sizeof(mmw_frame_header_t);
    int remaining = hdr->total_packet_len - offset;
    int obj_count = 0;

    for (int i = 0; i < hdr->num_tlvs && remaining >= (int)sizeof(mmw_tlv_header_t); i++) {
        const mmw_tlv_header_t *tlv = (const mmw_tlv_header_t *)(frame + offset);
        offset += sizeof(mmw_tlv_header_t);

        if (tlv->length > remaining) {
            fprintf(stderr, "TLV length exceeds frame bounds\n");
            return -1;
        }

        if (tlv->type == TLV_TYPE_DETECTED_POINTS) {
            int num_points = tlv->length / sizeof(mmw_detected_point_t);
            for (int j = 0; j < num_points; j++) {
                const mmw_detected_point_t *pt = (const mmw_detected_point_t *)(frame + offset + j * sizeof(mmw_detected_point_t));
                float range = (float)pt->range_idx * 0.05f;
                float velocity = (float)pt->doppler_idx * 0.05f;
                time_t now = time(NULL);
                fprintf(csv_file, "%ld,%d,%.2f,%.2f\n", (long)now, obj_count, range, velocity);
                obj_count++;
            }
        }
        offset += tlv->length;
        remaining -= tlv->length;
    }

    fflush(csv_file);
    return obj_count;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("fopen CSV");
        close(uart_fd);
        return 1;
    }

    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    uint8_t *frame_buf = malloc(MAX_FRAME_SIZE);
    if (!frame_buf) {
        fprintf(stderr, "malloc failed\n");
        fclose(csv_file);
        close(uart_fd);
        return 1;
    }

    int frame_len = 0;
    int magic_pos = 0;

    while (running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval tv = {1, 0};
        int sel = select(uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        }
        if (sel == 0) continue;

        ssize_t n = read(uart_fd, frame_buf + frame_len, MAX_FRAME_SIZE - frame_len);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            break;
        }
        if (n == 0) {
            fprintf(stderr, "UART read returned 0 (device disconnected?)\n");
            break;
        }

        frame_len += (int)n;

        while (running) {
            if (frame_len < MAGIC_WORD_SIZE) break;

            int mw_idx = find_magic_word(frame_buf, frame_len);
            if (mw_idx < 0) {
                memmove(frame_buf, frame_buf + 1, frame_len - 1);
                frame_len--;
                continue;
            }

            if (mw_idx > 0) {
                memmove(frame_buf, frame_buf + mw_idx, frame_len - mw_idx);
                frame_len -= mw_idx;
            }

            if (frame_len < (int)sizeof(mmw_frame_header_t)) break;

            const mmw_frame_header_t *hdr = (const mmw_frame_header_t *)frame_buf;
            if (hdr->total_packet_len > MAX_FRAME_SIZE) {
                fprintf(stderr, "Invalid total packet length: %u\n", hdr->total_packet_len);
                memmove(frame_buf, frame_buf + 1, frame_len - 1);
                frame_len--;
                continue;
            }

            if (frame_len < (int)hdr->total_packet_len) break;

            int obj_count = process_frame(frame_buf, hdr->total_packet_len);
            if (obj_count < 0) {
                fprintf(stderr, "Frame processing error\n");
            }

            int consumed = hdr->total_packet_len;
            memmove(frame_buf, frame_buf + consumed, frame_len - consumed);
            frame_len -= consumed;
        }
    }

    free(frame_buf);
    if (csv_file) fclose(csv_file);
    if (uart_fd >= 0) close(uart_fd);
    return 0;
}

