#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 512
#define READ_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0.5
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int parse_line(const char *line, char *timestamp_str, char *range_str) {
    char *saveptr = NULL;
    char *token = strtok_r(line, ",", &saveptr);
    if (token == NULL) return -1;

    strncpy(timestamp_str, token, 20);
    timestamp_str[20] = '\0';

    token = strtok_r(NULL, "\n", &saveptr);
    if (token == NULL) return -1;

    strncpy(range_str, token, 10);
    range_str[10] = '\0';
    return 0;
}

static void log_detection(const char *timestamp, const char *range) {
    printf("Timestamp: %s, Range: %s meters\n", timestamp, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char *timestamp_str = malloc(21);
    char *range_str = malloc(11);
    if (timestamp_str == NULL || range_str == NULL) {
        fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
        free(timestamp_str);
        free(range_str);
        close(g_uart_fd);
        return 1;
    }

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int retval = select(g_uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (retval < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            break;
        }
        if (retval == 0) {
            fprintf(stderr, "UART read timeout (sensor absent or bus error)\n");
            break;
        }

        char ch;
        ssize_t n = read(g_uart_fd, &ch, 1);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed by peer\n");
            break;
        }

        if (ch == '\n') {
            line_buf[line_len] = '\0';
            if (line_len > 0) {
                if (parse_line(line_buf, timestamp_str, range_str) == 0) {
                    time_t rawtime = (time_t)strtol(timestamp_str, NULL, 10);
                    struct tm *timeinfo = localtime(&rawtime);
                    char time_str[20];
                    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
                    log_detection(time_str, range_str);
                } else {
                    fprintf(stderr, "Error parsing line: %s\n", line_buf);
                }
            }
            line_len = 0;
        } else if (line_len < LINE_BUF_SIZE - 1) {
            line_buf[line_len++] = ch;
        } else {
            fprintf(stderr, "Line buffer overflow, discarding\n");
            line_len = 0;
        }
    }

    free(timestamp_str);
    free(range_str);
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
    }
    return 0;
}

