#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN  4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE      "/dev/ttyAMA0"
#define BAUD_RATE        B115200
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static int uart_fd = -1;

static void cleanup_resources(void) {
    if (left_line)  gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line)  gpiod_line_release(right_line);
    if (chip)        gpiod_chip_close(chip);
    if (uart_fd >= 0) close(uart_fd);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    left_line  = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input_flags(left_line, "ky033-left",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(middle_line, "ky033-middle",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(right_line, "ky033-right",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static int init_uart(void) {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        fprintf(stderr, "Failed to open UART %s: %s\n", UART_DEVICE, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(uart_fd);
        uart_fd = -1;
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP |
                     INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(uart_fd);
        uart_fd = -1;
        return -1;
    }
    return 0;
}

static int read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n",
           timestamp, left, middle, right);
    fflush(stdout);
}

static int send_emergency_stop(void) {
    const char *msg = "EMERGENCY STOP!\n";
    size_t len = strlen(msg);
    ssize_t written = write(uart_fd, msg, len);
    if (written < 0) {
        fprintf(stderr, "UART write error: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)written != len) {
        fprintf(stderr, "UART partial write: %zd of %zu bytes\n", written, len);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup_resources();
        return 1;
    }

    if (init_uart() != 0) {
        cleanup_resources();
        return 1;
    }

    printf("KY-033 obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int left   = read_sensor(left_line);
        int middle = read_sensor(middle_line);
        int right  = read_sensor(right_line);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            log_sensor_data(left, middle, right);

            if (left == 0 && middle == 0 && right == 0) {
                if (send_emergency_stop() != 0) {
                    fprintf(stderr, "Failed to send emergency stop signal.\n");
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup_resources();
    return 0;
}

